/* v8.91: خودِ ردیف صف هم بسته شود.
   تا اینجا «توقف» فقط یک فایل سیگنال می‌نوشت و فایل پیشرفت را می‌بست.
   اگر پردازهٔ استخراج زنده بود سیگنال را می‌دید و ردیف را می‌بست، ولی
   وقتی آن پردازه دیگر وجود نداشت — تایم‌اوت هاست، ری‌استارت PHP، بسته
   شدن تب — هیچ‌کس ردیف را نمی‌بست. نتیجه: ردیف تا ابد «در حال استخراج»
   می‌ماند و چون محافظ تکراری‌نبودن همان پروفایل را در صف می‌دید، اجرای
   بعدی هم رد می‌شد. یعنی دقیقاً همان «با دکمهٔ توقف هم متوقف نمی‌شود».
   حالا توقف صریحاً ردیف را «متوقف» علامت می‌زند. */
$stopQid=trim((string)($_GET['queue_id']??''));
$queue=extractReadQueue();
$stopped=[];$now=time();
foreach($queue['entries'] as &$qe){
    if(($qe['status']??'')!=='running')continue;
    if($stopQid!==''&&($qe['id']??'')!==$stopQid)continue;
    $qe['status']='paused';
    $qe['error']='با دکمهٔ توقف متوقف شد';
    $qe['done_at']=$now;
    $qe['stopped_by_user']=true;
    $stopped[]=$qe['id']??'';
}
unset($qe);
if($stopped)extractWriteQueue($queue);
echo json_encode(['ok'=>true,'stopped'=>$stopped],JSON_UNESCAPED_UNICODE);exit;
}

if(isset($_GET['poll_extract'])){
header('Content-Type: application/json; charset=UTF-8');
clearstatcache(true,EXTRACT_PROGRESS_FILE);
$p=readProgress(EXTRACT_PROGRESS_FILE);
/* v8.97: استخراج دستی هم نگهبان می‌خواهد.

   نگهبان فقط داخل کران بود، پس وقتی استخراجِ دستی وسط کار می‌مُرد
   (که روی این هاست عادی است) نه فایل پیشرفت بسته می‌شد نه ردیف صف —
   مرورگر تا ابد «در حال استخراج» نشان می‌داد و کاربر فکر می‌کرد
   نگهبانی در کار نیست. این اندپوینت همان چیزی است که مرورگر هر ۱.۵
   ثانیه صدا می‌زند، پس بهترین جا برای تشخیص است. */
if(!empty($p['running'])&&empty($p['done'])){
    $_pTs=(int)($p['last_progress_ts']??($p['started_at']??0));
    $_pIdle=$_pTs>0?(time()-$_pTs):PHP_INT_MAX;
    $_pMax=max(120,(int)(loadConnections()['stall_after']??300));
    if($_pIdle>$_pMax){
        $p['running']=false;$p['done']=true;$p['stalled']=true;
        $p['error']='استخراج '.$_pIdle.' ثانیه بی‌حرکت ماند — پردازه توسط سرور بسته شده';
        $p['recent_log']=array_merge((array)($p['recent_log']??[]),
            ['⛔ پردازش نیمه‌کاره رها شد ('.$_pIdle.' ثانیه بی‌حرکت)',
             '   • کارِ انجام‌شده تا این لحظه ذخیره شده — از دست نرفته',
             '   • دوباره استخراج بزنید تا از همان‌جا ادامه دهد']);
        writeProgress(EXTRACT_PROGRESS_FILE,$p);
        // ردیف صف هم بسته شود، وگرنه «در حال اجرا» می‌ماند
        $_q=extractReadQueue();$_qd=false;
        foreach($_q['entries'] as &$_qe){
            if(($_qe['status']??'')!=='running')continue;
            if(((string)($p['queue_id']??''))!==''&&((string)($_qe['id']??''))!==((string)$p['queue_id']))continue;
            $_qe['status']='failed';
            $_qe['error']='بی‌حرکت ماند ('.$_pIdle.' ثانیه) — نگهبان بست';
            $_qe['done_at']=time();$_qd=true;
        }
        unset($_qe);
        if($_qd)extractWriteQueue($_q);
    }
}
echo json_encode($p,JSON_UNESCAPED_UNICODE);exit;
}

/**
 * v8.27: هستهٔ مشترک استخراج بک‌اند.
 * هم دکمهٔ دستی و هم کران‌جاب دقیقاً همین تابع را صدا می‌زنند تا رفتار
 * یکسان باشد و صف/پیشرفت/گزارش در هر دو حالت ثبت شود. تنها تفاوت،
 * برچسب trigger است که در ردیف صف ذخیره می‌شود.
 */
/**
 * v8.94: محصولات را همین حالا روی دیسک بنویس، بدون اینکه منتظر پایان کار بمانیم.
 *
 * تا ۸.۹۳ ذخیره فقط یک بار و در انتهای همه‌چیز انجام می‌شد. یعنی اگر
 * پردازه وسط فاز جزئیات می‌مُرد — که روی هاستی که پردازه‌ها را می‌کشد
 * دقیقاً همان‌جا اتفاق می‌افتد، چون طولانی‌ترین بخش است — تمام کار
 * انجام‌شده دور ریخته می‌شد. محصولات از فاز فهرست هم ذخیره نمی‌شدند،
 * چه رسد به گالری‌هایی که تا آن لحظه جمع شده بود.
 *
 * حالا هر چند محصول یک بار «نقطهٔ امن» ثبت می‌شود. اگر کار نیمه‌کاره
 * بماند، دفعهٔ بعد از همان‌جا ادامه پیدا می‌کند نه از صفر.
 *
 * همان قاعدهٔ ۸.۹۱ رعایت می‌شود: پروفایل دوباره از دیسک خوانده می‌شود و
 * فقط محصولات روی آن نوشته می‌شوند، تا تنظیماتی که کاربر حین اجرا عوض
 * کرده — و پروفایل‌های دیگر — به عقب برنگردند.
 */
function extractCheckpoint(string $pkFinal, array $allProducts, array $extra = []): void {
    if ($pkFinal === '') return;
    $productsData = [];
    foreach ($allProducts as $k => $p) $productsData[] = [$k, $p];
    $profilesNow = loadProfiles();
    if (!isset($profilesNow[$pkFinal]) || !is_array($profilesNow[$pkFinal])) return;
    $profilesNow[$pkFinal]['products']      = $productsData;
    $profilesNow[$pkFinal]['productsOrder'] = array_keys($allProducts);
    $profilesNow[$pkFinal]['updatedAt']     = time();
    foreach ($extra as $k => $v) $profilesNow[$pkFinal][$k] = $v;
    saveProfiles($profilesNow);
}

/**
 * v9.01: استخراج در مراحل جدا.
 *
 * $phase:
 *   'all'    — فهرست + جزئیات، مثل همیشه (دکمهٔ دستی)
 *   'list'   — فقط صفحهٔ فهرست؛ فاز جزئیات اصلاً اجرا نمی‌شود
 *   'detail' — فقط جزئیاتِ محصولاتی که روی دیسک هستند و هنوز کامل نیستند
 *
 * چرا: کاربر می‌خواهد کران‌جاب اول فهرست را بگیرد، بعد «استخراج تفصیلی»
 * را جدا اجرا کند و تازه بعد از آن سراغ ارسال برود. با این پارامتر هر سه
 * از یک موتور می‌گذرند و رفتارشان نمی‌تواند از هم جدا بیفتد.
 */
/* v9.44: استخراج جزئیاتِ یک محصول به‌صورت درجا (inline) — بجای «فاز ۲»ی جداگانه.
   وقتی محصول از فهرست گرفته می‌شود، همین‌جا صفحهٔ خودش باز و جزئیاتش (فیلدها،
   گالری، تنوع‌ها) استخراج می‌شود. چون کران‌جاب (cron-job.org) منتظر کارِ
   پس‌زمینه نمی‌ماند، اگر جزئیات «بعداً» و در نوبتِ جدا اجرا شود ممکن است هرگز
   کامل نشود؛ درحالی‌که این‌جا به‌محض استخراج هر محصول کامل می‌شود و چک‌پوینتِ
   هر محصول همان لحظه نوشته می‌شود. */
function extractProductDetailInline(array &$allProducts, string $key, array $detailSelectors, array $galleryCfg, bool $forceAll): array {
    $out = ['ok' => false, 'opened' => false, 'fields' => 0, 'imgs' => 0, 'vars' => 0, 'error' => ''];
    if (!isset($allProducts[$key])) return $out;
    $p = &$allProducts[$key];
    if (empty($p['link'])) return $out;
    $out['opened'] = true;
    $dr = fetch_html($p['link'], 10);
    if (!$dr['ok']) {
        $out['error'] = trim((string)($dr['error'] ?? ''));
        if ($out['error'] === '') $out['error'] = 'HTTP ' . (int)($dr['code'] ?? 0);
        return $out;
    }
    $out['ok'] = true;
    [$dom2, $xp2] = load_dom($dr['html']);
    $fields = 0; $imgs = 0; $vars = 0;
    foreach ($detailSelectors as $field => $selStr) {
        if (empty($selStr)) continue;
        if ($field === 'variations') {
            $vr = variationsExtract($xp2, null, $selStr);
            if (!empty($vr['values'])) {
                $p['variations'] = $vr['values'];
                $p['variation_groups'] = $vr['groups'];
                $p['variations_text'] = implode('، ', $vr['values']);
                $vars = count($vr['values']); $fields++;
                if (!empty($vr['prices'])) {
                    $p['variation_prices'] = $vr['prices'];
                    $p['price_min'] = $vr['price_min'];
                    $p['price_max'] = $vr['price_max'];
                    $p['price_varies'] = !empty($vr['price_varies']);
                }
            }
            continue;
        }
        $xPath = cssToXpath($selStr);
        $ns = @$xp2->query($xPath);
        if ($ns && $ns->length) {
            $val = '';
            if ($field === 'image') {
                $val = galleryImgFromNode($ns->item(0), $dr['url']);
            } elseif ($field === 'price') {
                $val = extractPrice($ns->item(0)->textContent);
            } elseif ($field === 'shortDesc' || $field === 'longDesc') {
                $val = detailCleanHtml($ns->item(0), $dr['url']);
            } else {
                $val = trim($ns->item(0)->textContent);
            }
            if ($val) { $p[$field] = $val; $fields++; }
        }
    }
    if (empty($p['image'])) {
        $ogImg = @$xp2->query("//meta[@property='og:image']/@content");
        if ($ogImg && $ogImg->length) {
            $imgUrl = $ogImg->item(0)->nodeValue;
            if ($imgUrl && url_is_image($imgUrl)) $p['image'] = make_absolute_url($imgUrl, $dr['url']);
        }
    }
    if ($galleryCfg['enabled']) {
        $gal = galleryExtract($xp2, null, $dr['url'], $galleryCfg);
        if (!empty($gal['images'])) {
            $imgs = galleryApplyToProduct($p, $gal['images'], $forceAll);
        }
    }
    $out['fields'] = $fields; $out['imgs'] = $imgs; $out['vars'] = $vars;
    return $out;
}

function runBackendExtract(string $profileKey, string $trigger = 'manual', bool $emitEarlyResponse = false, string $phase = 'all', bool $forceAll = false): array {
if (!in_array($phase, ['all', 'list', 'detail'], true)) $phase = 'all';
@set_time_limit(0); @ignore_user_abort(true);
@unlink(EXTRACT_PROGRESS_FILE); @unlink(EXTRACT_STOP_FILE);

$startedAt=time();
$profiles=loadProfiles();

$profile=isset($profiles[$profileKey])?$profiles[$profileKey]:null;
// v9.67: اتصال غیرمستقیمِ به‌ازای هر پروفایل — آفلاینِ هر فراخوانیِ استخراج
// مقدارِ پیش‌فرض «مستقیم» (غیرفعال) است مگر اینکه پروفایل صریحاً روشن کرده باشد.
$GLOBALS['_srcNetProfileIndirect'] = netIndirectOn($profile['net_indirect'] ?? false);
if(!$profile){
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'error'=>'پروفایل یافت نشد','total'=>0,'current'=>0,'started_at'=>$startedAt,'recent_log'=>['❌ پروفایل یافت نشد'],'total_log_count'=>1]);
return ['__early_sent'=>$emitEarlyResponse, 'ok'=>false,'error'=>'پروفایل یافت نشد'];
}

$url=$profile['url']??'';
$maxPages=max(1,min(100,(int)($profile['pages']??10)));
$selectors=$profile['selectors']??[];
$pagType=$profile['pagType']??'query_page';
$pagVal=$profile['pagVal']??'';
$detailSelectors=extractNormalizeDetailSelectors($profile['detailSelectors']??[]);
$prevProducts=$profile['products']??[];
$prevOrder=$profile['productsOrder']??[];

if(!filter_var($url,FILTER_VALIDATE_URL)){
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'error'=>'URL نامعتبر','total'=>0,'current'=>0,'started_at'=>$startedAt,'recent_log'=>['❌ URL نامعتبر'],'total_log_count'=>1]);
return ['__early_sent'=>$emitEarlyResponse, 'ok'=>false,'error'=>'URL نامعتبر'];
}
if(empty($selectors)||empty($selectors['container'])){
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'error'=>'سلکتورها ذخیره نشده — ابتدا با فرانت‌اند استخراج کنید','total'=>0,'current'=>0,'started_at'=>$startedAt,'recent_log'=>['❌ سلکتورها ذخیره نشده'],'total_log_count'=>1]);
return ['__early_sent'=>$emitEarlyResponse, 'ok'=>false,'error'=>'سلکتورها ذخیره نشده'];
}

$queue=extractReadQueue();
/* v8.55: اگر همین پروفایل هنوز در صف استخراج است، دوباره اضافه نشود.
   v9.03: ولی گام جزئیات استثناست. کران عمداً بلافاصله بعد از گام فهرست
   آن را صدا می‌زند و ردیفِ همان گامِ فهرست هنوز در صف است؛ اگر محافظ
   اینجا جلویش را بگیرد، مرحلهٔ جزئیات هیچ‌وقت اجرا نمی‌شود. این دقیقاً
   همان چیزی بود که کاربر می‌دید. دو گامِ یک اجرا «تکراری» نیستند. */
if(queueDedupOn() && $phase!=='detail'){
/* v9.03: ردیفی که پردازه‌اش دیگر زنده نیست نباید جلوی اجرای تازه را
   بگیرد. معیار همان معیار نگهبان است: اگر فایل پیشرفت مالِ آن ردیف
   نیست یا مدت‌هاست چیزی ننوشته، آن اجرا مرده و ردیفش بی‌اعتبار است.
   بدون این، یک ردیفِ جامانده تا دو ساعت هر اجرای خودکار را رد می‌کرد. */
$dup=queueHasProfile($queue['entries'],$profileKey,queueDedupStale());
if($dup!==null){
    $_dupProg=readProgress(EXTRACT_PROGRESS_FILE);
    $_dupMine=((string)($_dupProg['queue_id']??''))===((string)($dup['id']??''));
    $_dupTs=$_dupMine?(int)($_dupProg['last_progress_ts']??0):0;
    if($_dupTs<=0)$_dupTs=(int)($dup['started_at']??0);
    $_dupIdle=$_dupTs>0?(time()-$_dupTs):PHP_INT_MAX;
    $_dupMax=max(120,(int)(loadConnections()['stall_after']??300));
    if($_dupIdle>$_dupMax){
        // مرده است — ردیفش را ببند و ادامه بده
        foreach($queue['entries'] as &$_qe){
            if(($_qe['id']??'')!==($dup['id']??''))continue;
            $_qe['status']='failed';
            $_qe['error']='بی‌حرکت ماند ('.$_dupIdle.' ثانیه) — اجرای تازه جایش را گرفت';
            $_qe['done_at']=time();
        }
        unset($_qe);
        extractWriteQueue($queue);
        $dup=null;
    }
}
if($dup!==null){
$msg='این پروفایل هم‌اکنون در صف استخراج است ('.($dup['status']??'').')';
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'error'=>$msg,
'total'=>0,'current'=>0,'started_at'=>$startedAt,'recent_log'=>['⏭ '.$msg],'total_log_count'=>1]);
return ['__early_sent'=>$emitEarlyResponse,'ok'=>false,'error'=>$msg,
'duplicate'=>true,'queue_id'=>$dup['id']??''];
}
}
/* v8.91: شناسه فقط تا ثانیه دقت داشت. دو اجرای پشت‌سرهمِ یک پروفایل
   (که وقتی اجرای اول فوراً شکست می‌خورد کاملاً عادی است) شناسهٔ یکسان
   می‌گرفتند؛ آن‌وقت به‌روزرسانی وضعیت روی ردیف اشتباهی می‌نشست و گزارش
   هر کدام گزارش دیگری را بازنویسی می‌کرد. */
$queueId='ex_'.$profileKey.'_'.time().'_'.substr(bin2hex(random_bytes(3)),0,6);
$queue['entries'][]=['id'=>$queueId,'status'=>'running','profile_key'=>$profileKey,'url'=>$url,'profile_name'=>$profile['name']??$profileKey,'started_at'=>time(),'products_count'=>0,'total'=>0,'current'=>0,'new'=>0,'price_changed'=>0,'removed'=>0,'unchanged'=>0,'trigger'=>$trigger,'phase'=>$phase];
extractWriteQueue($queue);

// v8.22: نسخهٔ قبلی را همین ابتدا بخوان تا مقایسه بتواند زنده انجام شود
$livePrevMap=extractPrevMap($profile);
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>true,'done'=>false,'total'=>0,'current'=>0,'started_at'=>$startedAt,'queue_id'=>$queueId,'recent_log'=>['⏳ شروع استخراج بک‌اند...'],'total_log_count'=>1,'extracted'=>0,'new'=>0,'price_changed'=>0,'removed'=>0,'unchanged'=>0,'price_up'=>0,'price_down'=>0,'url'=>$url,'profile_name'=>$profile['name']??$profileKey]);

// v8.27: پاسخ زودهنگام فقط برای درخواست مرورگر معنا دارد تا کاربر منتظر
// نماند و بقیهٔ کار در پس‌زمینه ادامه یابد. وقتی کران‌جاب این تابع را
// صدا می‌زند نباید چیزی چاپ شود، وگرنه خروجی JSON دوتکه می‌شود.
if($emitEarlyResponse){
while(@ob_get_level())@ob_end_clean();
$initResp=json_encode(['ok'=>true,'started'=>true,'profile_key'=>$profileKey,'url'=>$url,'max_pages'=>$maxPages],JSON_UNESCAPED_UNICODE);
header('Content-Type: application/json; charset=UTF-8');
header('Content-Length: '.strlen($initResp));
header('Connection: close');
echo $initResp;
if(function_exists('fastcgi_finish_request')){fastcgi_finish_request();}
@ob_flush();@flush();
}

/* v8.81: نقشهٔ محصولات اجرای قبلی، همین اول ساخته می‌شود.
   تا حالا فقط بعد از استخراج و صرفاً برای «آمار مقایسه» ساخته می‌شد و
   هیچ‌وقت با نتیجهٔ تازه ادغام نمی‌شد. چون $allProducts از نو و فقط از
   روی صفحهٔ فهرست پر می‌شود، هر چیزی که در فاز جزئیات به دست آمده بود —
   گالری، تنوع‌ها، توضیحات، SKU، برند — موقع ذخیره پاک می‌شد. */
$prevByKey=[];
if(!empty($prevProducts)){
$pfe=reset($prevProducts);
if(is_array($pfe)&&count($pfe)>=2&&is_string($pfe[0])){
foreach($prevProducts as $entry){if(is_array($entry)&&count($entry)>=2)$prevByKey[$entry[0]]=$entry[1];}
}else{$prevByKey=$prevProducts;}
}

$allProducts=[];$seenKeys=[];$nextUrl=null;$totalPages=0;$fetchFail='';
/* v9.01: در حالت «فقط جزئیات» صفحهٔ فهرست اصلاً باز نمی‌شود؛ محصولات
   همان‌هایی هستند که اجرای قبلی روی دیسک گذاشته. اینطور مرحلهٔ جزئیات
   یک گام مستقل است و یک بار دیگر کل فهرست را نمی‌گیرد. */
if($phase==='detail'){
    $allProducts=$prevByKey;
    foreach($allProducts as $_k=>$_v)$seenKeys[$_k]=1;
    $totalPages=0;
    if(empty($allProducts)){
        writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'total'=>0,'current'=>0,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>['⏭ محصولی برای گرفتن جزئیات نیست — اول استخراج فهرست را اجرا کنید'],'total_log_count'=>1,'extracted'=>0,'products_saved'=>false]);
        $queue=extractReadQueue();
        /* v9.09: این مسیر ردیف را بدون هیچ توضیحی می‌بست. مودال آن‌وقت
           به پیام عمومی «این مرحله چیزی برای انجام نداشت» می‌افتاد —
           دقیقاً همان چیزی که کاربر دید، در حالی که علت مشخص بود:
           پروفایل روی دیسک محصولی ندارد. */
        foreach($queue['entries'] as &$qe){if(($qe['id']??'')===$queueId){$qe['status']='done';$qe['done_at']=time();$qe['products_count']=0;$qe['detail_skip_why']='no_products';$qe['detail_total']=0;$qe['detail_no_link']=0;$qe['detail_already']=0;break;}}unset($qe);
        extractWriteQueue($queue);
        return ['__early_sent'=>$emitEarlyResponse,'ok'=>true,'extracted'=>0,'phase'=>'detail','note'=>'فهرستی وجود ندارد'];
    }
}
/* v9.44: جزئیات «هم‌زمان با» استخراج هر محصول انجام می‌شود — بجای فاز ۲ی جداگانه.
   چون کران‌جاب (cron-job.org) منتظر کارِ پس‌زمینه نمی‌ماند، جزئیات نباید در
   نوبتی جدا و بعداً اجرا شود که ممکن است هرگز به آن نرسد. اینجا هر محصول
   به‌محض گرفتن از فهرست، صفحهٔ خودش هم باز و کامل می‌شود (فقط اگر ناقص باشد —
   دامنهٔ «فقط ناقص‌ها»). */
$galleryCfg=galleryNormalizeCfg($profile['gallery']??[]);
$_wantKeys=[];
foreach($detailSelectors as $_f=>$_sv){ if(!empty($_sv))$_wantKeys[]=$_f; }
$_inlineDetailDone=0;   // شمارندهٔ جزئیاتِ درجایِ همین اجرا (برای چک‌پوینت)
$pkFinal=$profileKey!==''?$profileKey:profileKey($url);
for($page=1;$phase!=='detail'&&$page<=$maxPages;$page++){
if(file_exists(EXTRACT_STOP_FILE)){@unlink(EXTRACT_STOP_FILE);
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'cancelled'=>true,'total'=>count($allProducts),'current'=>$page,'started_at'=>$startedAt,'recent_log'=>['❌ متوقف شد'],'total_log_count'=>2,'extracted'=>count($allProducts)]);
return ['__early_sent'=>$emitEarlyResponse, 'ok'=>false,'cancelled'=>true];
}
if($page===1){$pageUrl=$url;}
elseif($pagType==='next_selector'&&$nextUrl){$pageUrl=$nextUrl;}
elseif($pagType==='next_selector'&&!$nextUrl){break;}
else{$pageUrl=build_page_url_custom($url,$url,$page,$pagType,$pagVal);}

$res=fetch_html($pageUrl,20);
$totalPages=$page;
$logs=['📄 صفحه '.$page.': '.($res['ok']?'✓':'✗').' — '.mb_substr($pageUrl,0,60)];
if(!$res['ok']){
$logs[]='❌ خطا: '.mb_substr($res['error']??'HTTP error',0,80);
// v8.91: علت شکست صفحهٔ اول را نگه دار تا محافظِ پایین بداند
// «صفر محصول» به‌خاطر قطعی بوده، نه به‌خاطر خالی شدن فروشگاه.
if($page===1)$fetchFail='صفحهٔ اول باز نشد: '.mb_substr($res['error']??('HTTP '.(int)($res['code']??0)),0,60);
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>true,'done'=>false,'total'=>0,'current'=>$page,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>$logs,'total_log_count'=>$page,'extracted'=>count($allProducts),'page'=>$page,'page_ok'=>false]);
if($page===1)break;
else continue;
}

$pageProducts=parse_with_selectors($res['html'],$res['url'],$selectors);
$newCount=0;
foreach($pageProducts as $key=>$p){
if(isset($seenKeys[$key]))continue;
$seenKeys[$key]=1;
$allProducts[$key]=$p;
$newCount++;
/* v9.44: استخراج جزئیاتِ همین محصول، همین‌لحظه (درجا) — بجای فاز ۲ی جداگانه.
   فقط اگر ناقص باشد (دامنهٔ «فقط ناقص‌ها»): گالری روشن است یا فیلدی خواسته‌شده
   هنوز خالی است یا عکس/قیمت ندارد. برای تصمیم‌گیری، دادهٔ اجرای قبلی هم ادغام
   می‌شود تا محصولی که قبلاً کامل شده دوباره باز نشود. صفحهٔ محصول باز و
   فیلدها/گالری/تنوع‌ها استخراج می‌شود؛ بعد هر محصول چک‌پوینت می‌شود تا اگر
   هاست وسط کار کشته شد، محصولاتِ تا آن لحظه کامل روی دیسک بمانند. */
/* v9.72: رفعِ «استخراج خودکار جزئیات» — این بلوکِ درجا داخلِ حلقهٔ فهرست بود و
   برای فازِ list هم اجرا می‌شد (یعنی هر کران صفحهٔ جزئیاتِ محصولات را باز می‌کرد).
   حالا فقط وقتی اجرا می‌شود که فاز list نباشد (یعنی all/detail = دکمهٔ دستی). */
if($phase!=='list'){
$_mrg = (isset($prevByKey[$key]) && is_array($prevByKey[$key]))
    ? extractMergeDetail($p, $prevByKey[$key]) : $p;
$_galDoneNow = $galleryCfg['enabled']
    && count($p['images'] ?? ($_mrg['images'] ?? [])) > 1
    && !empty($p['image'] ?? $_mrg['image'] ?? '')
    && !empty($p['price'] ?? $_mrg['price'] ?? '');
$_fieldMissingNow = false;
foreach ($_wantKeys as $_wk) {
    if ($_wk === 'variations') { if (empty($_mrg['variations'])) { $_fieldMissingNow = true; break; } continue; }
    $_cur = $_mrg[$_wk] ?? '';
    if (is_array($_cur) ? empty($_cur) : (trim((string)$_cur) === '')) { $_fieldMissingNow = true; break; }
}
if (!($_galDoneNow && !$_fieldMissingNow)) {
    $_inlineDetailDone++;
    extractProductDetailInline($allProducts, $key, $detailSelectors, $galleryCfg, false);
    extractCheckpoint($pkFinal, $allProducts,
        ['_extract_stage' => 'detail', '_extract_stage_at' => time(),
         '_extract_detail_done' => $_inlineDetailDone, '_extract_detail_total' => 0]);
}
}
}
$logs[]='✓ +'.($newCount).' محصول (کل: '.count($allProducts).')';
// v8.22: مقایسهٔ زنده — شمارنده‌ها و لیست‌ها همان لحظه محاسبه می‌شوند
$liveCmp=extractLiveCompare($allProducts,$livePrevMap);
writeProgress(EXTRACT_PROGRESS_FILE,array_merge(['running'=>true,'done'=>false,'total'=>$maxPages,'current'=>$page,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>$logs,'total_log_count'=>$page,'extracted'=>count($allProducts),'page'=>$page,'page_ok'=>true,'page_new'=>$newCount,'page_total'=>count($allProducts)],$liveCmp));

if($pagType==='next_selector'&&!empty($pagVal)){
[$dom,$xp]=load_dom($res['html']);
$xpath=cssToXpath($pagVal);
$nodes=@$xp->query($xpath);
if($nodes&&$nodes->length&&$nodes->item(0) instanceof DOMElement){
$href=$nodes->item(0)->getAttribute('href');
if($href&&$href!=='#'&&!preg_match('~^(javascript:|data:)~i',$href)){
$nextUrl=make_absolute_url($href,$res['url']);
}else{$nextUrl=null;}
}else{$nextUrl=null;}
}
if($page>1&&$newCount===0)break;
usleep(500000);
}

/* =====================================================================
   v8.91: محافظ «استخراج بی‌نتیجه چیزی را پاک نکند»

   این علتِ واقعیِ ناپدید شدن گالری‌ها بود و سلکتورها هیچ ربطی به آن
   نداشتند. سناریو دقیقاً این است:

     ۱) اجرای خودکار شروع می‌شود.
     ۲) سایت مبدأ همان لحظه در دسترس نیست — 503، تایم‌اوت، قطعی DNS،
        یا فایروالی که ربات را چند دقیقه بلاک کرده. هر سایتی این را
        روزی چند بار دارد.
     ۳) حلقهٔ بالا از صفحهٔ اول بیرون می‌زند و $allProducts خالی می‌ماند.
     ۴) کد پایین همان آرایهٔ خالی را در پروفایل می‌نوشت.

   نتیجه: کل محصولات پروفایل با همهٔ گالری‌ها، تنوع‌ها و توضیحاتی که
   ساعت‌ها طول کشیده بود، در یک لحظه صفر می‌شد. چون اجرای بعدی دوباره
   محصولات را از فهرست پیدا می‌کرد، محصول‌ها برمی‌گشتند — ولی بدون گالری،
   چون گالری فقط از صفحهٔ محصول می‌آید و «ادغام با اجرای قبلی» دیگر
   چیزی برای ادغام نداشت. برای همین به نظر می‌رسید «سلکتورهای گالری
   پاک شده‌اند»، در حالی که سلکتورها سر جایشان بودند.

   قاعده: اگر قبلاً محصول داشتیم و حالا هیچ نداریم، به این اجرا اعتماد
   نکن. چیزی ذخیره نکن و علتش را بگو. یک فروشگاه واقعاً خالی‌شده هم با
   اجرای بعدی و پیام صریح قابل تشخیص است — ولی داده‌ای که رفته برنمی‌گردد.
   ===================================================================== */
/* v8.98: پروفایل خالی هم باید علتش را بگوید.

   تا اینجا این محافظ فقط وقتی کار می‌کرد که از قبل محصولی داشتیم. اگر
   پروفایل تازه بود و صفحهٔ فهرست باز نمی‌شد (تایم‌اوت، ۵۰۳، سلکتور
   اشتباه)، اجرا بی‌صدا با صفر محصول «تکمیل» می‌شد و کاربر فقط می‌دید
   هیچ‌چیز استخراج نشده، بدون هیچ توضیحی. */
if(empty($allProducts)&&$phase!=='detail'){
$_why=$fetchFail!==''?$fetchFail:'صفحهٔ فهرست باز شد ولی هیچ محصولی با سلکتورها پیدا نشد';
$_kept=count($prevByKey);
$_guardLog=[$_kept>0
    ?'🛡 استخراج بی‌نتیجه بود — داده‌های قبلی دست‌نخورده ماند'
    :'❌ استخراج هیچ محصولی پیدا نکرد'];
$_guardLog[]='   • علت: '.$_why;
if($_kept>0)$_guardLog[]='   • '.$_kept.' محصول ذخیره‌شده حفظ شد (گالری و جزئیاتشان پاک نشد)';
else $_guardLog[]='   • سلکتور «کانتینر» را روی صفحهٔ فهرست بررسی کنید، یا سایت مبدأ در دسترس نبوده';
$_guardLog[]='   • اگر سایت مبدأ واقعاً خالی شده، اجرای بعدی هم همین را می‌گوید';
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'total'=>$maxPages,'current'=>$totalPages,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>$_guardLog,'total_log_count'=>count($_guardLog),'extracted'=>0,'error'=>'استخراج بی‌نتیجه — '.$_why,'guard'=>'empty_result','kept'=>count($prevByKey),'products_saved'=>false]);
$queue=extractReadQueue();
foreach($queue['entries'] as &$qe){if(($qe['id']??'')===$queueId){$qe['status']='failed';$qe['error']='بی‌نتیجه — '.$_why.($_kept>0?(' · '.$_kept.' محصول قبلی حفظ شد'):'');$qe['done_at']=time();break;}}unset($qe);
extractWriteQueue($queue);
notifRunFailure(loadConnections(),'استخراج',$profile['name']??$profileKey,
  ($_kept>0
    ?'استخراج هیچ محصولی برنگرداند و متوقف شد تا داده‌های قبلی پاک نشوند. علت: '
    :'استخراج هیچ محصولی پیدا نکرد. علت: ').$_why);
return ['__early_sent'=>$emitEarlyResponse,'ok'=>false,'error'=>'استخراج بی‌نتیجه — '.$_why,
        'guard'=>'empty_result','kept'=>count($prevByKey)];
}

/* v8.81: جزئیاتِ اجرای قبلی را برگردان، قبل از اینکه تصمیم بگیریم کدام
   محصول لازم است دوباره باز شود. صفحهٔ فهرست فقط عنوان، قیمت، لینک و یک
   عکس دارد؛ بقیه فقط از صفحهٔ محصول می‌آید. اگر اینجا ادغام نکنیم، همان
   داده‌ها موقع ذخیره دور ریخته می‌شوند. */
foreach($allProducts as $key=>$p){
if(!isset($prevByKey[$key])||!is_array($prevByKey[$key]))continue;
$allProducts[$key]=extractMergeDetail($p,$prevByKey[$key]);
}

/* v8.94: مرحلهٔ ۱ تمام شد — همین‌جا ذخیره کن.

   این نقطهٔ امنِ اول است. فاز بعدی (باز کردن صفحهٔ تک‌تک محصول‌ها برای
   گالری و جزئیات) طولانی‌ترین بخش کار است و روی هاست ما معمولاً همان‌جا
   پردازه کشته می‌شود. تا ۸.۹۳ در آن حالت هیچ‌چیز ذخیره نشده بود — حتی
   خودِ محصولاتی که از صفحهٔ فهرست به دست آمده بودند. */
$pkFinal=$profileKey!==''?$profileKey:profileKey($url);
extractCheckpoint($pkFinal,$allProducts,['_extract_stage'=>'list_done','_extract_stage_at'=>time()]);

// v8.64: اگر گالری روشن است، صفحهٔ همهٔ محصولات باید باز شود — نه فقط
// آن‌هایی که عکس یا قیمت ندارند. وگرنه محصولی که یک عکس دارد هرگز
// بقیهٔ عکس‌هایش را نمی‌گیرد.
$galleryCfg=galleryNormalizeCfg($profile['gallery']??[]);
/* v9.02: انتخاب محصولاتی که باید صفحه‌شان باز شود.

   باگی که کاربر گزارش کرد: وقتی گالری خاموش بود ولی سلکتورهای جزئیات
   تنظیم شده بودند، این حلقه هیچ‌کس را انتخاب نمی‌کرد. شرط قدیمی فقط
   «عکس یا قیمت ندارد» را می‌سنجید، و محصولی که هر دو را از صفحهٔ فهرست
   گرفته بود کنار گذاشته می‌شد — یعنی توضیحات، SKU، برند و تنوع‌ها هرگز
   استخراج نمی‌شدند و مرحلهٔ جزئیات عملاً کاری نمی‌کرد.

   قاعدهٔ درست: اگر فیلدی از صفحهٔ محصول خواسته شده و هنوز نداریمش،
   باید صفحه را باز کنیم. */
$_wantKeys=[];
foreach($detailSelectors as $_f=>$_sv){ if(!empty($_sv))$_wantKeys[]=$_f; }
/* v9.05: چرا هیچ محصولی انتخاب نشد؟ سه علتِ کاملاً متفاوت وجود دارد و
   تا حالا هر سه یک پیام می‌گرفتند: «همه از قبل کامل بودند». این پیام
   وقتی گالری اصلاً نیامده کاملاً گمراه‌کننده است. حالا شمرده می‌شوند. */
$_noLink=0;$_alreadyDone=0;
$needDetail=[];
/* v9.10: دامنهٔ «همهٔ محصولات». وقتی استخراج دوره‌ای جزئیات با
   scope=all اجرا شود، محصولی که قبلاً گالری گرفته هم دوباره باز
   می‌شود — برای وقتی که سلکتور گالری عوض شده یا مبدأ عکس‌ها را
   به‌روز کرده است. */
$_forceAll=($phase==='detail'&&$forceAll);
foreach($allProducts as $key=>$p){
if(empty($p['link'])){$_noLink++;continue;}
if($_forceAll){$needDetail[$key]=$p;continue;}
/* v8.81: محصولی که گالری‌اش را قبلاً گرفته‌ایم دوباره باز نمی‌شود.
   پیش از این با روشن بودن گالری، هر بار همهٔ صفحات محصول از نو گرفته
   می‌شد که هم کند بود و هم بی‌دلیل. */
$_galDone=$galleryCfg['enabled']&&count($p['images']??[])>1&&!empty($p['image'])&&!empty($p['price']);
// کدام فیلدِ خواسته‌شده هنوز خالی است؟
$_fieldMissing=false;
foreach($_wantKeys as $_wk){
    if($_wk==='variations'){ if(empty($p['variations'])){$_fieldMissing=true;break;} continue; }
    $_cur=$p[$_wk]??'';
    if(is_array($_cur)?empty($_cur):(trim((string)$_cur)==='')){$_fieldMissing=true;break;}
}
if($_galDone&&!$_fieldMissing){$_alreadyDone++;continue;}   // هم گالری دارد هم فیلدها
if($galleryCfg['enabled']||$_fieldMissing||empty($p['image'])||empty($p['price'])){
$needDetail[$key]=$p;
}
}
$detailTotal=count($needDetail);
$detailDone=0;
$galleryFound=0;$galleryImgsTotal=0;
/* v8.90: شمارنده‌های تفصیلی تا لاگ بگوید واقعاً چه اتفاقی افتاد، نه فقط
   «۵ از ۲۰». تا حالا اگر صفحه‌ای باز نمی‌شد یا سلکتوری چیزی پیدا نمی‌کرد،
   هیچ ردی در لاگ نمی‌ماند و کاربر فقط می‌دید کار کند است. */
$detailOk=0;$detailFail=0;$detailFields=0;$detailNoField=0;$varFound=0;$imgMain=0;
$failSamples=[];$emptySamples=[];
// v8.97: وقتی فاز جزئیات اصلاً اجرا نشود هم باید تعریف‌شده باشد
$_ranOut=false;
$detailLog=[];   // چند خط آخر، برای نمایش در نوار پیشرفت
$pushLog=function(string $line) use (&$detailLog){
    $detailLog[]=$line;
    if(count($detailLog)>6)$detailLog=array_slice($detailLog,-6);
};
/* v9.05: اگر فاز جزئیات اجرا نمی‌شود، دلیلش را ثبت کن. سکوت باعث شد
   کاربر پیام «همه از قبل کامل بودند» ببیند در حالی که گالری نیامده بود. */
$_skipWhy='';
if($phase==='list')                                   $_skipWhy='';           // عمدی
elseif(empty($detailSelectors)&&!$galleryCfg['enabled']) $_skipWhy='no_config';
elseif($detailTotal===0&&$_noLink>0&&$_alreadyDone===0)  $_skipWhy='no_link';
elseif($detailTotal===0&&$_alreadyDone>0)                $_skipWhy='already_done';
elseif($detailTotal===0)                                 $_skipWhy='nothing_selected';

if($phase!=='list'&&$detailTotal>0&&(!empty($detailSelectors)||$galleryCfg['enabled'])){
$_wantFields=[];
foreach($detailSelectors as $_f=>$_sv){ if(!empty($_sv))$_wantFields[]=$_f; }

/* v8.97: فاز جزئیات باید «قبل» از سقف زمانی هاست تمیز تمام شود.

   این علت واقعی کرش بود و همهٔ تلاش‌های ۸.۹۴ تا ۸.۹۶ کنارش رد شدند.
   حساب سرانگشتی: هر محصول یک درخواست HTTP است (تا ۱۰ ثانیه تایم‌اوت)
   به‌علاوهٔ ۰.۲ ثانیه مکث. برای ۵۰۰ محصول یعنی ۱۷ دقیقه در حالت متوسط
   و بیش از یک ساعت اگر مبدأ کند باشد. هیچ هاست اشتراکی‌ای چنین
   درخواستی را زنده نگه نمی‌دارد؛ پردازه وسط کار کشته می‌شود.

   set_time_limit(0) هم کمکی نمی‌کند، چون آنچه پردازه را می‌کشد
   معمولاً max_execution_time نیست بلکه سقف خودِ وب‌سرور است
   (FcgidIOTimeout / proxy_read_timeout / request_terminate_timeout)
   و آن از داخل PHP قابل تغییر نیست.

   پس به‌جای جنگیدن با سقف، زودتر از آن می‌ایستیم: تا هر جا که رسیدیم
   کار می‌کنیم، ذخیره می‌کنیم و «ناتمام» علامت می‌زنیم. اجرای بعدی —
   چه کران چه دکمه — از همان‌جا ادامه می‌دهد، چون needDetail فقط
   محصولاتی را برمی‌دارد که هنوز گالری/فیلد ندارند. */
$cn0=loadConnections();
$_budget=(int)($cn0['detail_budget_sec']??0);
if($_budget<=0){
    // اگر تنظیم نشده، از max_execution_time حدس بزن و حاشیهٔ امن بگذار
    $_ini=(int)@ini_get('max_execution_time');
    $_budget=$_ini>0?max(30,(int)($_ini*0.7)):90;
}
$_budget=max(20,min(3600,$_budget));
/* v8.98: مهلت از «شروع فاز جزئیات» حساب می‌شود، نه از شروع کل اجرا.

   در ۸.۹۷ نوشته بودم $startedAt + $budget که $startedAt لحظهٔ شروع کل
   استخراج است. ولی قبل از فاز جزئیات، فاز فهرست اجرا می‌شود که خودش
   می‌تواند دقایقی طول بکشد (هر صفحه تا ۲۰ ثانیه تایم‌اوت + نیم ثانیه
   مکث، ضربدر تعداد صفحات). اگر فهرست به‌تنهایی بودجه را می‌خورد، همان
   اولین تکرارِ فاز جزئیات می‌دید که مهلت گذشته و بی‌درنگ break می‌کرد —
   یعنی «حتی یک محصول هم جزئیات نمی‌گرفت».

   دکمهٔ دستی سالم به نظر می‌رسید چون معمولاً روی فروشگاه کوچک و
   تک‌صفحه‌ای امتحان می‌شد و فهرستش سریع تمام می‌شد. */
$_detailStart=time();
$_deadline=$_detailStart+$_budget;
$_ranOut=false;
/* محافظ: حداقل چند محصول در هر نوبت باید پردازش شود، وگرنه اگر بودجه
   کوچک و مبدأ کند باشد هر نوبت صفر محصول جلو می‌رویم و کار هرگز تمام
   نمی‌شود. */
$_minPerRun=3;

$logs=['🔍 فاز ۲ — باز کردن صفحهٔ محصول‌ها: '.$detailTotal.' محصول'];
$logs[]='   • فیلدها: '.($_wantFields?implode('، ',$_wantFields):'—')
        .($galleryCfg['enabled']?(' · گالری: روشن ('.$galleryCfg['mode'].')'):' · گالری: خاموش');
$logs[]='   • ⏱ سقف زمانی این نوبت: '.$_budget.' ثانیه — بقیه در نوبت بعد ادامه می‌یابد';
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>true,'done'=>false,'total'=>$maxPages+$detailTotal,'current'=>$totalPages+$detailDone,'started_at'=>$startedAt,'recent_log'=>$logs,'total_log_count'=>$totalPages+1,'extracted'=>count($allProducts),'phase'=>'detail','detail_current'=>0,'detail_total'=>$detailTotal]);

foreach($needDetail as $key=>$p){
/* v8.97: وقت تمام شد؟ تمیز بیرون بیا، نه اینکه منتظر بمانی تا هاست بکشد.
   v8.98: ولی حداقل چند محصول باید انجام شود، وگرنه پیشرفتی حاصل نمی‌شود
   و هر نوبت دقیقاً از همان جای قبل شروع می‌کند. */
if($detailDone>=$_minPerRun&&time()>=$_deadline){$_ranOut=true;break;}
if(file_exists(EXTRACT_STOP_FILE)){@unlink(EXTRACT_STOP_FILE);
/* v8.94: کاربر توقف زد — کارِ تا اینجا را نگه دار و نشانهٔ «نیمه‌کاره»
   را بردار، وگرنه محافظِ ارسال تا ابد بسته می‌ماند. */
extractCheckpoint($pkFinal,$allProducts,
    ['_extract_stage'=>'stopped','_extract_stage_at'=>time(),
     '_extract_detail_done'=>$detailDone,'_extract_detail_total'=>$detailTotal]);
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'cancelled'=>true,'extracted'=>count($allProducts),'started_at'=>$startedAt,'recent_log'=>['❌ متوقف شد'],'total_log_count'=>$totalPages+$detailDone+1]);
return ['__early_sent'=>$emitEarlyResponse, 'ok'=>false,'cancelled'=>true];
}
$detailDone++;
$_pTitle=mb_substr(trim((string)($p['title']??$key)),0,42);
$_gotFields=0;$_gotImgs=0;$_gotVars=0;
$dr=fetch_html($p['link'],10);
if($dr['ok']){
$detailOk++;
[$dom2,$xp2]=load_dom($dr['html']);

foreach($detailSelectors as $field=>$selStr){
if(empty($selStr))continue;
// v8.68: تنوع‌ها فهرست‌اند نه یک متن، پس مسیر جداگانه دارند
if($field==='variations'){
$vr=variationsExtract($xp2,null,$selStr);
if(!empty($vr['values'])){
$allProducts[$key]['variations']=$vr['values'];
$allProducts[$key]['variation_groups']=$vr['groups'];
$allProducts[$key]['variations_text']=implode('، ',$vr['values']);
$_gotVars=count($vr['values']);$varFound++;$_gotFields++;
// v8.81: قیمت هر گزینه
if(!empty($vr['prices'])){
$allProducts[$key]['variation_prices']=$vr['prices'];
$allProducts[$key]['price_min']=$vr['price_min'];
$allProducts[$key]['price_max']=$vr['price_max'];
$allProducts[$key]['price_varies']=!empty($vr['price_varies']);
}
}
continue;
}
$xPath=cssToXpath($selStr);
$ns=@$xp2->query($xPath);
if($ns&&$ns->length){
$val='';
if($field==='image'){
// v8.66: getAttribute در DOMElement رشتهٔ خالی برمی‌گرداند نه null، پس ??
// هیچ‌وقت به data-src نمی‌رسید و عکس‌های lazy از دست می‌رفتند.
// حالا از همان تابع مشترک گالری استفاده می‌شود که srcset را هم می‌فهمد.
$val=galleryImgFromNode($ns->item(0),$dr['url']);
}elseif($field==='price'){
$val=extractPrice($ns->item(0)->textContent);
}elseif($field==='shortDesc'||$field==='longDesc'){
/* v9.19: توضیحات با ساختارشان برداشته می‌شوند، نه به‌صورت متن خام.

   textContent همهٔ تگ‌ها را دور می‌ریخت و متنِ پاراگراف‌ها و آیتم‌های
   فهرست به هم می‌چسبید: «پاراگراف اولویژگی یکویژگی دو». مقصد
   (ووکامرس) خودش HTML را رندر می‌کند، پس نگه داشتن ساختار هم درست‌تر
   است هم خواناتر.

   ولی HTML خامِ سایت مبدأ را نمی‌شود مستقیم فرستاد: اسکریپت، استایل،
   iframe و رویدادهای onclick باید بروند. detailCleanHtml همین کار را
   می‌کند و اگر بعد از پاک‌سازی چیزی نماند، به متن خام برمی‌گردد. */
$val=detailCleanHtml($ns->item(0),$dr['url']);
}else{
$val=trim($ns->item(0)->textContent);
}
if($val){$allProducts[$key][$field]=$val;$_gotFields++;if($field==='image')$imgMain++;}
}
}

if(empty($allProducts[$key]['image'])){
$ogImg=@$xp2->query("//meta[@property='og:image']/@content");
if($ogImg&&$ogImg->length){
$imgUrl=$ogImg->item(0)->nodeValue;
if($imgUrl&&url_is_image($imgUrl))$allProducts[$key]['image']=make_absolute_url($imgUrl,$dr['url']);
}
}

// v8.64: گالری — بقیهٔ عکس‌های همین صفحهٔ محصول
if($galleryCfg['enabled']){
$gal=galleryExtract($xp2,null,$dr['url'],$galleryCfg);
if(!empty($gal['images'])){
$nImg=galleryApplyToProduct($allProducts[$key],$gal['images'],$_forceAll);
$_gotImgs=$nImg;
if($nImg>1){$galleryFound++;$galleryImgsTotal+=$nImg;}
}
}
$detailFields+=$_gotFields;
if($_gotFields===0&&$_gotImgs<=1){
$detailNoField++;
if(count($emptySamples)<3)$emptySamples[]=$_pTitle;
}
$pushLog('  ✓ '.$_pTitle.' — '
  .($_gotFields?($_gotFields.' فیلد'):'بدون فیلد')
  .($_gotVars?(' · '.$_gotVars.' تنوع'):'')
  .($_gotImgs>1?(' · 🖼 '.$_gotImgs.' عکس'):($_gotImgs===1?' · ۱ عکس':'')));
}else{
/* v8.90: تا حالا شکست باز کردن صفحه بی‌صدا رد می‌شد و کاربر نمی‌فهمید
   چرا محصول جزئیات نگرفت. حالا علتش در لاگ می‌آید. */
$detailFail++;
$_err=trim((string)($dr['error']??''));
if($_err==='')$_err='HTTP '.(int)($dr['code']??0);
if(count($failSamples)<3)$failSamples[]=$_pTitle.' ('.mb_substr($_err,0,40).')';
$pushLog('  ✗ '.$_pTitle.' — صفحه باز نشد: '.mb_substr($_err,0,50));
}
/* v8.90: هر ۲ محصول به‌روزرسانی کن (قبلاً هر ۵ تا) و به‌جای یک خط
   خشک، بگو چه چیزی به دست آمده و چه چیزی نه. */
if($detailDone%2===0||$detailDone==$detailTotal){
$_pct=$detailTotal>0?(int)round($detailDone/$detailTotal*100):0;
$logs=['🔍 جزئیات '.$detailDone.' از '.$detailTotal.' ('.$_pct.'٪)'];
$_sum='   • ✅ '.$detailOk.' صفحه باز شد';
if($detailFail>0)$_sum.=' · ❌ '.$detailFail.' باز نشد';
if($detailFields>0)$_sum.=' · 🏷 '.$detailFields.' فیلد';
if($varFound>0)$_sum.=' · 🎨 '.$varFound.' محصول تنوع‌دار';
$logs[]=$_sum;
if($galleryCfg['enabled']){
$logs[]='   • 🖼 گالری: '.$galleryFound.' محصول چندعکسی · مجموع '.$galleryImgsTotal.' تصویر'
        .($galleryFound>0?(' · میانگین '.round($galleryImgsTotal/max(1,$galleryFound),1).' عکس'):'');
}
if($detailNoField>0)$logs[]='   • ⚠️ '.$detailNoField.' محصول هیچ فیلدی نداد'
        .($emptySamples?(' — مثل: '.implode('، ',$emptySamples)):'');
if($failSamples)$logs[]='   • ✗ نمونهٔ خطا: '.implode(' | ',$failSamples);
foreach($detailLog as $_dl)$logs[]=$_dl;
// قیمت‌ها در این مرحله ممکن است تکمیل شوند، پس مقایسه دوباره محاسبه می‌شود
$liveCmp=extractLiveCompare($allProducts,$livePrevMap);
writeProgress(EXTRACT_PROGRESS_FILE,array_merge(['running'=>true,'done'=>false,'total'=>$maxPages+$detailTotal,'current'=>$totalPages+$detailDone,'started_at'=>$startedAt,'last_progress_ts'=>time(),'recent_log'=>$logs,'total_log_count'=>$totalPages+$detailDone,'extracted'=>count($allProducts),'phase'=>'detail','detail_current'=>$detailDone,'detail_total'=>$detailTotal,'detail_ok'=>$detailOk,'detail_fail'=>$detailFail,'detail_fields'=>$detailFields,'detail_nofield'=>$detailNoField,'gallery_products'=>$galleryFound,'gallery_images'=>$galleryImgsTotal,'variation_products'=>$varFound],$liveCmp));
}
/* v8.94: هر ۵ محصول، کارِ انجام‌شده روی دیسک بنشیند.

   نوشتن فایل پیشرفت فقط برای نمایش است؛ خودِ گالری‌ها در $allProducts
   می‌مانند و تا ۸.۹۳ فقط در انتها ذخیره می‌شدند. اگر هاست وسط این حلقه
   پردازه را می‌کشت، همهٔ عکس‌های جمع‌شده دور ریخته می‌شد.
   حالا بدترین حالت، از دست رفتن کارِ ۵ محصول آخر است. */
/* v9.06: هر محصول، نه هر ۵ محصول.

   با فاصلهٔ ۵ تایی، اگر پردازه قبل از پنجمین محصول کشته می‌شد، کارِ
   هر چهار محصول قبلی هم دور ریخته می‌شد و اجرای بعدی از صفر شروع
   می‌کرد. روی هاستی که هر بار وسط فاز جزئیات می‌مُرد، این یعنی هیچ
   گالری‌ای هرگز روی دیسک نمی‌نشست — همان چیزی که کاربر می‌دید.
   هزینهٔ نوشتن یک فایل در برابر یک درخواست HTTP ناچیز است. */
extractCheckpoint($pkFinal,$allProducts,
    ['_extract_stage'=>'detail','_extract_stage_at'=>time(),
     '_extract_detail_done'=>$detailDone,'_extract_detail_total'=>$detailTotal]);
usleep(200000);
}
/* v8.94: پایان فاز جزئیات — قبل از هر کار دیگری ذخیره کن.
   v8.97: اگر وقت تمام شده و کار ناتمام مانده، نشانه را «detail» بگذار
   نه «detail_done»، تا اجرای بعدی بداند باید ادامه بدهد. */
extractCheckpoint($pkFinal,$allProducts,
    ['_extract_stage'=>$_ranOut?'detail':'detail_done','_extract_stage_at'=>time(),
     '_extract_detail_done'=>$detailDone,'_extract_detail_total'=>$detailTotal]);
/* v8.90: جمع‌بندی پایان فاز ۲ — یک نگاه و می‌فهمی چه شد. */
$_sumLines=$_ranOut
  ? ['⏸ فاز ۲ نیمه‌تمام ماند — '.$detailDone.' از '.$detailTotal.' محصول بررسی شد',
     '   • ⏱ سقف زمانی این نوبت پر شد؛ بقیه در اجرای بعدی ادامه می‌یابد',
     '   • هیچ‌چیز از دست نرفت — کار انجام‌شده ذخیره شد']
  : ['✅ فاز ۲ تمام شد — '.$detailDone.' محصول بررسی شد'];
$_sumLines[]='   • ✅ '.$detailOk.' صفحه باز شد'
  .($detailFail>0?(' · ❌ '.$detailFail.' باز نشد'):'')
  .' · 🏷 '.$detailFields.' فیلد استخراج شد';
if($galleryCfg['enabled'])
$_sumLines[]='   • 🖼 گالری: '.$galleryImgsTotal.' تصویر از '.$galleryFound.' محصول';
if($varFound>0)$_sumLines[]='   • 🎨 '.$varFound.' محصول تنوع دارد';
if($detailNoField>0)$_sumLines[]='   • ⚠️ '.$detailNoField.' محصول هیچ فیلدی نداد — سلکتورهای جزئیات را بررسی کنید';
if($detailFail>0&&$failSamples)$_sumLines[]='   • ✗ '.implode(' | ',$failSamples);
/* v9.00: اگر همهٔ صفحه‌ها بسته بودند و علتش ۴۰۳/۴۲۹ بود، یعنی سایت مبدأ
   IP سرور را بلاک کرده. این حالت دقیقاً شبیه «گالری استخراج نمی‌شود» به
   نظر می‌رسد ولی ربطی به سلکتور ندارد، پس صریح گفته می‌شود. */
$_blockHint='';
foreach($failSamples as $_fs){ if(strpos($_fs,'403')!==false||strpos($_fs,'429')!==false){$_blockHint=$_fs;break;} }
if($detailOk===0&&$detailFail>0&&$_blockHint!==''){
$_sumLines[]='   • ⛔ سایت مبدأ صفحهٔ محصولات را به سرور نمی‌دهد (۴۰۳/۴۲۹)';
$_sumLines[]='   • یعنی IP هاست بلاک یا محدود شده — سلکتورها سالم‌اند';
$_sumLines[]='   • تنظیمات ← «اتصال به سایت مبدأ»: فاصلهٔ بین درخواست‌ها را زیاد کنید یا پروکسی بگذارید';
}
$liveCmp=extractLiveCompare($allProducts,$livePrevMap);
writeProgress(EXTRACT_PROGRESS_FILE,array_merge(['running'=>true,'done'=>false,'total'=>$maxPages+$detailTotal,'current'=>$totalPages+$detailTotal,'started_at'=>$startedAt,'last_progress_ts'=>time(),'recent_log'=>$_sumLines,'total_log_count'=>$totalPages+$detailDone+1,'extracted'=>count($allProducts),'phase'=>'detail','detail_current'=>$detailDone,'detail_total'=>$detailTotal,'detail_ok'=>$detailOk,'detail_fail'=>$detailFail,'detail_fields'=>$detailFields,'detail_nofield'=>$detailNoField,'gallery_products'=>$galleryFound,'gallery_images'=>$galleryImgsTotal,'variation_products'=>$varFound],$liveCmp));
}

$newCount=0;$priceChanged=0;$unchanged=0;$removedCount=0;
$newItems=[];$changedItems=[];$removedItems=[];

/* v9.04: در حالت «فقط جزئیات» مبنای مقایسه همان محصولاتی است که این
   اجرا رویشان کار کرده، نه نسخهٔ قبل‌تر. وگرنه چون گام فهرست جداگانه
   ذخیره کرده بود، مقایسه همه را «حذف‌شده» می‌دید و کران گزارش
   removed=6 می‌داد در حالی که هیچ محصولی حذف نشده بود. */
$prevMap=[];
if($phase==='detail'){
    $prevMap=$prevByKey;
}elseif(!empty($prevProducts)){
$firstEntry=reset($prevProducts);
if(is_array($firstEntry)&&count($firstEntry)>=2&&is_string($firstEntry[0])){

foreach($prevProducts as $entry){if(is_array($entry)&&count($entry)>=2)$prevMap[$entry[0]]=$entry[1];}
}else{

$prevMap=$prevProducts;
}
}

// v8.22: همان تابعی که در حین اجرا استفاده شد، تا نتیجهٔ نهایی با
// شمارنده‌های زنده اختلاف نداشته باشد.
// v8.39: سقف بالاتر برای مقایسهٔ نهایی — این لیست‌ها مبنای «ارسال فقط
// تغییرات» هستند، پس اگر بریده شوند محصولی بی‌صدا جا می‌ماند.
$finalCmp=extractLiveCompare($allProducts,$prevMap,100000);
$newCount=$finalCmp['new'];
$priceChanged=$finalCmp['price_changed'];
$removedCount=$finalCmp['removed'];
$unchanged=$finalCmp['unchanged'];
$newItems=$finalCmp['new_items'];
$changedItems=$finalCmp['changed_items'];
$removedItems=$finalCmp['removed_items'];
$priceUp=$finalCmp['price_up'];
$priceDown=$finalCmp['price_down'];

$productsData=[];$productsOrder=array_keys($allProducts);
foreach($allProducts as $key=>$p){$productsData[]=[$key,$p];}
/* v8.91: پروفایل را دوباره از دیسک بخوان و فقط محصولات را روی آن بنویس.

   سومین علتِ گم شدن تنظیمات. $profiles همان نسخه‌ای است که در ثانیهٔ
   اولِ اجرا خوانده شد. یک استخراج با گالری روشن چند دقیقه تا چند ساعت
   طول می‌کشد و در تمام آن مدت کاربر بیدار است: سلکتور گالری را عوض
   می‌کند، دستهٔ مقصد را تنظیم می‌کند، پروفایل دیگری را ویرایش می‌کند.
   نوشتنِ آن نسخهٔ کهنه، همهٔ آن تغییرات را — و حتی پروفایل‌های دیگر را —
   به عقب برمی‌گرداند. کاربر می‌دید تنظیمی که خودش نیم ساعت پیش ذخیره
   کرده بود، بی‌دلیل به حالت قبل برگشته.

   حالا فقط چیزی نوشته می‌شود که واقعاً حاصل این اجراست.
   v8.94: $pkFinal بالاتر — قبل از اولین نقطهٔ امن — تعیین شده است. */
$profilesNow=loadProfiles();
$profileOnDisk=is_array($profilesNow[$pkFinal]??null)?$profilesNow[$pkFinal]:$profile;
$profileOnDisk['products']=$productsData;
$profileOnDisk['productsOrder']=$productsOrder;
$profileOnDisk['updatedAt']=time();
/* v8.94: کار تمام شد — نشانهٔ «نیمه‌کاره» برداشته شود، وگرنه محافظِ
   ارسال تا ابد بسته می‌ماند و هیچ محصولی هرگز فرستاده نمی‌شود. */
/* v8.97: اگر فاز جزئیات به‌خاطر سقف زمانی ناتمام مانده، «complete»
   ننویس — وگرنه اجرای بعدی فکر می‌کند کار تمام شده و بقیهٔ محصولات
   هیچ‌وقت گالری نمی‌گیرند، و دروازهٔ ارسال هم زودتر از موعد باز می‌شود. */
/* v9.01: اجرای «فقط فهرست» تمام‌شده حساب نمی‌شود — هنوز مرحلهٔ جزئیات
   مانده. با نشانهٔ list_done، هم دروازهٔ ارسال بسته می‌ماند و هم اجرای
   بعدی می‌داند باید جزئیات را بگیرد. */
$profileOnDisk['_extract_stage']=($phase==='list')?'list_done':((!empty($_ranOut))?'detail':'complete');
$profileOnDisk['_extract_stage_at']=time();
$profileOnDisk['_extract_detail_done']=$detailDone;
$profileOnDisk['_extract_detail_total']=$detailTotal;
$profilesNow[$pkFinal]=$profileOnDisk;
saveProfiles($profilesNow);
$profiles=$profilesNow;$profile=$profileOnDisk;

/* v8.90: خلاصهٔ پایانی، جزئیات فاز ۲ را هم نگه دارد.
   قبلاً این نوشتن آخر، همهٔ لاگ و شمارنده‌های جزئیات را پاک می‌کرد و
   کاربر فقط یک خط «تکمیل شد» می‌دید — یعنی همان چیزی که می‌خواست بداند
   (چند صفحه باز شد، چند عکس آمد، چه چیزی نیامد) از بین می‌رفت. */
$finalLog=['✅ استخراج تکمیل شد — '.count($allProducts).' محصول'];
$finalLog[]='   • 🆕 '.$newCount.' جدید · 💰 '.$priceChanged.' تغییر قیمت · ❌ '.$removedCount.' حذف‌شده · ⏭ '.$unchanged.' بدون تغییر';
if($detailTotal>0){
$finalLog[]='   • 🔍 جزئیات: '.$detailOk.' صفحه باز شد'
  .($detailFail>0?(' · '.$detailFail.' باز نشد'):'')
  .' · '.$detailFields.' فیلد';
if($galleryCfg['enabled'])
$finalLog[]='   • 🖼 گالری: '.$galleryImgsTotal.' تصویر از '.$galleryFound.' محصول';
/* v9.09: گالری روشن بود، صفحه‌ها هم باز شدند، ولی هیچ عکسی نیامد.
   تا حالا این حالت «موفق» گزارش می‌شد و کاربر فقط می‌دید گالری خالی
   است بدون هیچ توضیحی. علت تقریباً همیشه یکی از این دوتاست: سلکتور
   «کادر گالری» با ساختار صفحهٔ محصول نمی‌خواند، یا عکس‌ها با
   جاوااسکریپت بعداً تزریق می‌شوند و در HTML خام نیستند. */
if($galleryCfg['enabled']&&$detailOk>0&&$galleryImgsTotal===0){
$finalLog[]='   • ⛔ گالری روشن است ولی هیچ تصویری پیدا نشد'
  .($galleryCfg['box']!==''?(' — کادر گالری: '.mb_substr($galleryCfg['box'],0,40)):' — کادر گالری تنظیم نشده');
$finalLog[]='   • یعنی سلکتور کادر با صفحهٔ محصول نمی‌خواند، یا عکس‌ها با جاوااسکریپت می‌آیند';
}
if($varFound>0)$finalLog[]='   • 🎨 '.$varFound.' محصول تنوع دارد';
if($detailNoField>0)$finalLog[]='   • ⚠️ '.$detailNoField.' محصول هیچ فیلدی نداد — سلکتورها را بررسی کنید';
if($failSamples)$finalLog[]='   • ✗ '.implode(' | ',$failSamples);
}
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'total'=>$maxPages+$detailTotal,'current'=>$totalPages+$detailTotal,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>$finalLog,'total_log_count'=>$totalPages+$detailTotal+1,'extracted'=>count($allProducts),'new'=>$newCount,'price_changed'=>$priceChanged,'removed'=>$removedCount,'unchanged'=>$unchanged,'price_up'=>$priceUp,'price_down'=>$priceDown,'new_items'=>$newItems,'changed_items'=>$changedItems,'removed_items'=>$removedItems,'products_saved'=>true,'profile_key'=>$profileKey??profileKey($url),'total_pages'=>$totalPages,'detail_current'=>$detailDone,'detail_skip_why'=>$_skipWhy,'detail_no_link'=>$_noLink,'detail_already'=>$_alreadyDone,'phase'=>($detailTotal>0?'detail':'list'),'detail_ok'=>$detailOk,'detail_fail'=>$detailFail,'detail_fields'=>$detailFields,'detail_nofield'=>$detailNoField,'detail_total'=>$detailTotal,'gallery_products'=>$galleryFound,'gallery_images'=>$galleryImgsTotal,'variation_products'=>$varFound]);

$queue=extractReadQueue();
// v8.25: نتیجهٔ کامل هر اجرا جداگانه ذخیره می‌شود تا مودالِ کارهای
// تمام‌شده هم بتواند فهرست محصولات را نشان دهد، نه فقط لاگ زنده.
extractSaveReport($queueId, [
    'new_items'     => $newItems,
    'changed_items' => $changedItems,
    'removed_items' => $removedItems,
    'unchanged'     => $unchanged,
    'price_up'      => $priceUp,
    'price_down'    => $priceDown,
    'extracted'     => count($allProducts),
    'profile_name'  => $profile['name'] ?? ($profileKey ?? ''),
    'finished_at'   => time(),
]);

foreach($queue['entries'] as &$qe){if($qe['id']===$queueId){$qe['status']='done';$qe['products_count']=count($allProducts);$qe['total']=count($allProducts);$qe['current']=count($allProducts);$qe['done_at']=time();$qe['new']=$newCount;$qe['price_changed']=$priceChanged;$qe['removed']=$removedCount;$qe['unchanged']=$unchanged;$qe['price_up']=$priceUp;$qe['price_down']=$priceDown;$qe['gallery_images']=$galleryImgsTotal;$qe['gallery_products']=$galleryFound;$qe['detail_ok']=$detailOk;$qe['detail_fail']=$detailFail;$qe['detail_fields']=$detailFields;$qe['variation_products']=$varFound;$qe['detail_total']=$detailTotal;$qe['detail_skip_why']=$_skipWhy;$qe['detail_no_link']=$_noLink;$qe['detail_already']=$_alreadyDone;$qe['gallery_blank']=($galleryCfg['enabled']&&$detailOk>0&&$galleryImgsTotal===0)?1:0;$qe['gallery_box']=(string)$galleryCfg['box'];$qe['has_report']=true;break;}}unset($qe);
extractWriteQueue($queue);

return ['__early_sent'=>$emitEarlyResponse, 'ok'=>true,'extracted'=>count($allProducts),'new'=>$newCount,'price_changed'=>$priceChanged,'removed'=>$removedCount,'unchanged'=>$unchanged,'price_up'=>$priceUp,'price_down'=>$priceDown,'new_items'=>$newItems,'changed_items'=>$changedItems,'removed_items'=>$removedItems,'products_saved'=>true,'profile_key'=>$profileKey??profileKey($url)];
}

if(isset($_GET['action']) && $_GET['action'] === 'backend_extract'){
$profileKey=trim($_GET['profile_key']??$_POST['profile_key']??'');
if($profileKey===''){
$u=trim($_GET['url']??'');
if($u!==''&&filter_var($u,FILTER_VALIDATE_URL))$profileKey=profileKey($u);
}
/* v9.01: همان اندپوینت می‌تواند فقط فهرست یا فقط جزئیات را اجرا کند.
   ?phase=list | detail | all — پیش‌فرض all، پس رفتار دکمهٔ دستی عوض نمی‌شود. */
$phaseIn = (string)($_GET['phase'] ?? $_POST['phase'] ?? 'all');
if (!in_array($phaseIn, ['all','list','detail'], true)) $phaseIn = 'all';
/* v9.11: دامنهٔ «همهٔ محصولات» از دکمهٔ اجرای فوریِ استخراج دوره‌ای */
$forceAllIn = !empty($_GET['force_all']) || !empty($_POST['force_all']);
$res=runBackendExtract($profileKey,'manual',true,$phaseIn,$forceAllIn);
// v8.30: همان اعلان‌های تغییر مبدأ که کران‌جاب می‌فرستد
if(!empty($res['ok'])){
$cnNow=loadConnections();
$profsNow=loadProfiles();
notifSourceChanges($cnNow,$res,$profsNow[$profileKey]['name']??$profileKey);
}
// اگر پاسخ زودهنگام ارسال شده، دیگر چیزی چاپ نمی‌کنیم
if(empty($res['__early_sent'])){
header('Content-Type: application/json; charset=UTF-8');
echo json_encode($res,JSON_UNESCAPED_UNICODE);
}
exit;
}

if (isset($_GET['sync_status'])) {
header('Content-Type: application/json; charset=UTF-8');
echo json_encode(['ok' => true, 'state' => loadSyncState()], JSON_UNESCAPED_UNICODE);
exit;
}
if (($_POST['action'] ?? '') === 'update_sync_state') {
header('Content-Type: application/json; charset=UTF-8');
$key = trim($_POST['profile_key'] ?? '');
$status = $_POST['status'] ?? 'done';
$state = loadSyncState();
$state[$key] = ['lastRun' => time(), 'status' => $status];
saveSyncState($state);
echo json_encode(['ok' => true], JSON_UNESCAPED_UNICODE); exit;
}

/* =====================================================================
 *  v8.39: ارسال فقط تغییرات («افزودن/آپدیت»)
 *
 *  تیک‌های «افزودن/آپدیت ووکامرس» و «افزودن/آپدیت باسلام» از نسخهٔ ۷
 *  در رابط کاربری بودند و ذخیره هم می‌شدند، ولی هیچ‌جای سمت سرور
 *  خوانده نمی‌شدند. نتیجه این بود که هر اجرای کران کل محصولات را
 *  دوباره می‌فرستاد و برای پروفایل چندهزارتایی ساعت‌ها طول می‌کشید.
 *
 *  حالا اگر تیک فعال باشد فقط محصولات جدید و تغییرکرده فرستاده
 *  می‌شوند. حذف‌شده‌ها مسیر جداگانهٔ خودشان را دارند (retireRemoved).
 * ===================================================================== */

/* =====================================================================
 *  v8.44: آماده‌سازی محصول برای ارسال، سمت سرور
 *
 *  تا اینجا فقط مرورگر قیمت نهایی را می‌ساخت (getSendP در جاوااسکریپت).
 *  کران محصول خام را در صف می‌گذاشت و ارسال‌کننده دنبال final_price
 *  می‌گشت که وجود نداشت، پس قیمت صفر می‌شد. حالا همان منطق اینجا هم
 *  پیاده شده تا اجرای خودکار و دستی یک نتیجه بدهند.
 * ===================================================================== */

/** قیمت نهایی با ضریب/درصد و گِرد کردن پروفایل — معادل getFinalPriceNum */
function profileFinalPrice(array $profile, $rawPrice): int {
    $base = extractPriceNum($rawPrice);
    if ($base <= 0) return 0;
    $mode = (string)($profile['priceMode'] ?? 'none');
    $val  = (float)($profile['priceVal'] ?? 0);
    $final = $base;
    if ($mode === 'percent')         $final = $base * (1 + ($val / 100));
    elseif ($mode === 'multiplier')  $final = $base * $val;
    $final = (int)round($final);
    $round = (int)($profile['roundPrice'] ?? 0);
    if ($round > 0) $final = (int)(round($final / $round) * $round);
    return $final;
}

/**
 * v8.87: تعدیل قیمت مخصوص یک مقصد، روی قیمت نهاییِ پروفایل.
 *
 * تا حالا فقط یک تنظیم قیمت وجود داشت که برای هر دو مقصد یکی بود. ولی
 * حاشیهٔ سود ووکامرس و باسلام یکی نیست (کارمزد باسلام، هزینهٔ ارسال و …)
 * و کاربر می‌خواهد برای هر مقصد درصد جداگانه بگذارد.
 *
 * این تابع روی «قیمت نهاییِ» محاسبه‌شده اعمال می‌شود، نه روی قیمت خام،
 * تا تنظیم پروفایل هم سر جایش بماند و این یکی فقط تفاوت مقصد را بگذارد.
 *
 * $cfg: ['mode'=>'none|percent|multiplier', 'val'=>float, 'round'=>int]
 */
function destAdjustPrice(int $base, array $cfg): int {
    if ($base <= 0) return 0;
    $mode = (string)($cfg['mode'] ?? 'none');
    $val  = (float)($cfg['val'] ?? 0);
    $out  = $base;
    if ($mode === 'percent')        $out = $base * (1 + ($val / 100));
    elseif ($mode === 'multiplier') $out = $val > 0 ? $base * $val : $base;
    $out = (int)round($out);
    $round = (int)($cfg['round'] ?? 0);
    if ($round > 0) $out = (int)(round($out / $round) * $round);
    // قیمت هیچ‌وقت نباید منفی یا صفر شود؛ درصدِ منفیِ بزرگ نباید محصول را خراب کند
    return $out > 0 ? $out : $base;
}

/** تنظیمات تعدیل قیمت یک مقصد را از فایل اتصالات می‌خواند */
function destPriceCfg(array $cn, string $dest): array {
    $d = $cn[$dest] ?? [];
    return [
        'mode'  => (string)($d['price_mode'] ?? 'none'),
        'val'   => (float)($d['price_val'] ?? 0),
        'round' => (int)($d['price_round'] ?? 0),
    ];
}

/* v9.47: فهرست غرفه‌های باسلام (پیش‌فرض + اضافی) برای دراپ‌داون «انتخاب غرفه».
   هر غرفه: ['vendor_id'=>int,'token'=>string,'shop_name'=>string]. */
function bslAllShops(array $cn): array {
    $out = [];
    $b = $cn['basalam'] ?? [];
    $defTok = trim((string)($b['token'] ?? ''));
    $defVid = (int)($b['vendor_id'] ?? 0);
    $defName = trim((string)($b['shop_name'] ?? ''));
    if ($defName === '') $defName = 'غرفهٔ پیش‌فرض';
    $defPM = (string)($b['price_mode'] ?? 'none');
    $defPV = (float)($b['price_val'] ?? 0);
    if ($defTok !== '' && $defVid > 0) {
        $out[] = ['vendor_id' => $defVid, 'token' => $defTok, 'shop_name' => $defName,
                  'is_default' => true, 'price_mode' => $defPM, 'price_val' => $defPV];
    }
    $vs = $b['vendors'] ?? [];
    if (is_array($vs)) {
        foreach ($vs as $v) {
            if (!is_array($v)) continue;
            $vid = (int)($v['vendor_id'] ?? 0);
            $tok = trim((string)($v['token'] ?? ''));
            if ($vid <= 0 || $tok === '') continue;
            $name = trim((string)($v['shop_name'] ?? ($v['name'] ?? '')));
            if ($name === '') $name = 'غرفهٔ ' . $vid;
            $out[] = ['vendor_id' => $vid, 'token' => $tok, 'shop_name' => $name,
                      'is_default' => false,
                      'price_mode' => (string)($v['price_mode'] ?? 'none'),
                      'price_val'  => (float)($v['price_val'] ?? 0)];
        }
    }
    return $out;
}

/* v9.68: تعدیل قیمتِ مخصوصِ هر غرفهٔ باسلام، «نسبت به غرفهٔ پیش‌فرض».
   غرفهٔ پیش‌فرض خودش می‌تواند درصد/مقدار داشته باشد (price_mode/price_val
   عمومی). برای غرفه‌های دیگر هم یک درصد/مقدارِ جدا ذخیره می‌شود که روی
   «قیمتِ پایهٔ محصول» اعمال می‌شود — مثل غرفهٔ پیش‌فرض ولی با مقادیرِ خودش.

   خروجی: ['price'=>قیمت نهاییِ این غرفه (تومان)، 'eff_pct'=>درصدِ مؤثرِ کلی نسبت به
   قیمتِ پایهٔ خام، 'profile_pct'=>درصدِ تعدیلِ خودِ پروفایل، 'shop_pct'=>درصدِ این غرفه]

   مثال: قیمت پایهٔ خام ۱۰۰؛ پروفایل +۳۰٪ (۱۳۰)؛ غرفهٔ دوم +۲۰٪ روی ۱۳۰ → ۱۵۶.
   eff_pct = (۱۵۶-۱۰۰)/۱۰۰ = +۵۶٪ یعنی نسبت به قیمت پایهٔ خام مجموعاً +۵۶٪. */
function bslShopPriceFor(int $basePrice, array $shop, int $round = 0): array {
    if ($basePrice <= 0) return ['price' => 0, 'pct' => 0, 'eff_pct' => 0, 'profile_pct' => 0, 'shop_pct' => 0];
    $mode = (string)($shop['price_mode'] ?? 'none');
    $val  = (float)($shop['price_val'] ?? 0);
    $out  = $basePrice;
    $pct  = 0.0;
    if ($mode === 'percent') {
        $out = $basePrice * (1 + ($val / 100));
        $pct = (float)$val;
    } elseif ($mode === 'multiplier') {
        $out = $val > 0 ? $basePrice * $val : $basePrice;
        $pct = $val > 0 ? round(($val - 1) * 100, 1) : 0;
    }
    $out = (int)round($out);
    if ($round > 0) $out = (int)(round($out / $round) * $round);
    if ($out <= 0) $out = $basePrice;
    return ['price' => $out, 'pct' => round($pct, 1), 'eff_pct' => 0, 'profile_pct' => 0, 'shop_pct' => round($pct, 1)];
}

/* v9.71: قیمتِ غرفه‌های غیرپیش‌فرض — «جمع ساده» (افزودنی) روی تعدیلِ خودِ پروفایل.

   خواستهٔ کاربر: تعدیلِ هر غرفهٔ غیرپیش‌فرض باید به‌صورت «کسر/اضافهٔ درصد یا
   مقدار» روی تعدیلِ خودِ پروفایل اضافه شود. یعنی اگر غرفهٔ پیش‌فرض (پروفایل)
   +۳۰٪ داشته باشد و غرفهٔ دوم +۵٪ بگذارد، افزایشِ نهایی برای آن پروفایل در
   غرفهٔ دوم = ۳۵٪ (جمعِ سادهٔ ۳۰ و ۵).

   برای هر دو «درصد» از جمعِ سادهٔ درصدها استفاده می‌شود؛ برای «ضریب» ابتدا به
   درصد تبدیل می‌شود و بعد جمع می‌شود.

   خروجی: ['price'=>قیمت نهاییِ تومان، 'eff_pct'=>درصدِ مؤثرِ کل نسبت به قیمتِ
   پایهٔ خام، 'profile_pct'=>درصدِ خودِ پروفایل، 'shop_pct'=>درصدِ این غرفه].
   مثال: پایهٔ خام ۱۰۰، پروفایل +۳۰٪، غرفهٔ دوم +۵٪ → eff=۳۵٪ → قیمت ۱۳۵. */
function bslShopPriceForProfile(array $profile, $rawPrice, array $shop, int $round = 0): array {
    $src = extractPriceNum($rawPrice);
    if ($src <= 0) return ['price' => 0, 'eff_pct' => 0, 'profile_pct' => 0, 'shop_pct' => 0];
    // درصدِ تعدیلِ خودِ پروفایل
    $pm = (string)($profile['priceMode'] ?? 'none');
    $pv = (float)($profile['priceVal'] ?? 0);
    if ($pm === 'percent')         $ppct = (float)$pv;
    elseif ($pm === 'multiplier')  $ppct = $pv > 0 ? ($pv - 1) * 100 : 0;
    else                           $ppct = 0;
    // درصدِ تعدیلِ این غرفه (روی همان مبنا)
    $sm = (string)($shop['price_mode'] ?? 'none');
    $sv = (float)($shop['price_val'] ?? 0);
    if ($sm === 'percent')         $spct = (float)$sv;
    elseif ($sm === 'multiplier')  $spct = $sv > 0 ? ($sv - 1) * 100 : 0;
    else                           $spct = 0;
    $eff = $ppct + $spct;                    // جمعِ ساده: ۳۰ + ۵ = ۳۵
    $out = $src * (1 + ($eff / 100));
    $out = (int)round($out);
    if ($round > 0) $out = (int)(round($out / $round) * $round);
    if ($out <= 0) $out = $src;
    return ['price' => $out, 'eff_pct' => round($eff, 1),
            'profile_pct' => round($ppct, 1), 'shop_pct' => round($spct, 1)];
}
/* v9.69: ارسالِ چند-غرفه‌ای — یک محصول را در «یک غرفهٔ مشخص» بساز یا به‌روز کن.
   برای هر غرفهٔ اضافی که قیمتِ خودش را دارد، همان منطقِ ارسالِ اصلی را اجرا
   می‌کنیم: جست‌وجو (bslFindExisting) → اگر بود PATCH (با قیمتِ خودِ آن غرفه)؛
   اگر نبود POST. این تابع خودش کامل است (بدون وابستگی به حلقهٔ اصلی) تا هر
   غرفه با token و قیمتِ خودش پردازش شود. */
function bslUpsertToShop(array $p, array $shop, array $opts): array {
    $tk   = (string)($shop['token'] ?? '');
    $vid  = (int)($shop['vendor_id'] ?? 0);
    if ($tk === '' || $vid <= 0) return ['ok' => false, 'error' => 'غرفهٔ نامعتبر'];
    $title = trim((string)($p['title'] ?? ($p['name'] ?? '')));
    if ($title === '') return ['ok' => false, 'error' => 'عنوان خالی'];
    $round  = (int)($opts['round'] ?? 0);
    $profile= is_array($opts['profile'] ?? null) ? $opts['profile'] : null;
    // قیمتِ این غرفه: لایهٔ پروفایل (اگر قیمتِ خام بود) + لایهٔ خودِ غرفه
    $rawP  = (string)($p['price'] ?? ($p['orig_price'] ?? ''));
    if ($profile && $rawP !== '' && extractPriceNum($rawP) > 0) {
        $pf = bslShopPriceForProfile($profile, $rawP, $shop, $round);
    } else {
        $baseP = (int)preg_replace("/[^0-9]/", "", (string)($p['final_price'] ?? '0'));
        if ($baseP <= 0) return ['ok' => false, 'error' => 'قیمت ۰'];
        $pf = bslShopPriceFor($baseP, $shop, $round);
    }
    $priceToman = $pf['price'];
    if ($priceToman <= 0) return ['ok' => false, 'error' => 'قیمت نامعتبر'];
    $priceRial = (($p['price_unit'] ?? '') !== 'rial') ? $priceToman * 10 : $priceToman;

    $stock   = (int)($opts['stock'] ?? 10);
    $prepD   = (int)($opts['preparation_days'] ?? 3);
    $weight  = (int)($opts['weight'] ?? 500);
    $pkgW    = (int)($opts['package_weight'] ?? ($weight + 100));
    $catId   = (int)($opts['category_id'] ?? 0);
    $fallback= is_array($opts['fallback_cat_ids'] ?? null) ? $opts['fallback_cat_ids'] : [];
    $autoCat = !empty($opts['auto_category']);
    $flatCats= is_array($opts['flat_cats'] ?? null) ? $opts['flat_cats'] : [];
    $cData   = is_array($opts['cdata'] ?? null) ? $opts['cdata'] : [];

    $existing = bslFindExisting($tk, $vid, $title, (string)($p['key'] ?? ''));
    $exId = is_array($existing) ? (int)($existing['id'] ?? 0) : 0;

    if ($exId > 0) {
        $bu = ['primary_price' => $priceRial, 'stock' => $stock, 'status' => 2976,
               'preparation_days' => $prepD, 'weight' => $weight, 'package_weight' => $pkgW];
        if ($catId > 0) $bu['category_id'] = $catId;
        $r = bslReq($tk, 'PATCH', 'products/' . $exId, $bu);
        if ($r['code'] === 404) $r = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $exId, $bu);
        if (!empty($r['ok']) && !empty($r['body']['id'])) {
            return ['ok' => true, 'id' => $exId, 'action' => 'updated'];
        }
        return ['ok' => false, 'error' => 'آپدیت در این غرفه ناموفق: ' . mb_substr((string)($r['body']['message'] ?? ($r['error'] ?? '?')), 0, 120)];
    }

    $catUsed = $catId;
    if ($catUsed <= 0 && $autoCat && !empty($flatCats)) {
        $_ac = autoMatchBslCategory($title, $flatCats);
        if ($_ac > 0) $catUsed = $_ac;
    }
    if ($catUsed > 0 && !empty($cData) && is_array($cData)) $catUsed = findLeafCategory($catUsed, $cData);
    $brief = trim(strip_tags((string)($p['short_desc'] ?? '')));
    $desc  = trim((string)($p['long_desc'] ?? ''));
    if ($brief === '') $brief = trim(strip_tags($title));
    if ($desc === '')  $desc  = $brief;
    $bp = ['name' => mb_substr($title, 0, 120), 'brief' => mb_substr($brief, 0, 250),
           'description' => $desc, 'primary_price' => $priceRial, 'stock' => $stock,
           'preparation_days' => $prepD, 'weight' => $weight, 'package_weight' => $pkgW,
           'is_wholesale' => false, 'category_id' => $catUsed, 'status' => 3790];
    if (!empty($p['sku'])) $bp['sku'] = $p['sku'];
    $r = bslReq($tk, 'POST', 'vendors/' . $vid . '/products', $bp);
    if (!empty($r['ok']) && !empty($r['body']['id'])) {
        return ['ok' => true, 'id' => (int)$r['body']['id'], 'action' => 'created'];
    }
    $fb = bslTryCreateWithFallback($tk, $vid, $bp, $fallback, $title, $autoCat, $flatCats, $cData);
    if (!empty($fb['ok']) && !empty($fb['body']['id'])) {
        return ['ok' => true, 'id' => (int)$fb['body']['id'], 'action' => 'created'];
    }
    $em = $r['body']['message'] ?? $r['body']['error'] ?? ($r['error'] ?? '؟');
    if (is_array($em)) $em = json_encode($em, JSON_UNESCAPED_UNICODE);
    return ['ok' => false, 'error' => mb_substr((string)$em, 0, 140)];
}

/** امضای تنظیمات قیمت — اگر عوض شود یعنی قیمت همهٔ محصولات عوض شده */
function profilePriceSignature(array $profile): string {
    return (string)($profile['priceMode'] ?? 'none') . '|'
         . (string)($profile['priceVal'] ?? 0) . '|'
         . (string)($profile['roundPrice'] ?? 0) . '|'
         . trim((string)($profile['titleSuffix'] ?? ''));
}

/** محصول ذخیره‌شده را به همان شکلی درمی‌آورد که مرورگر می‌فرستد */
function prepareForSend(array $profile, string $key, array $p): array {
    $raw = (string)($p['price'] ?? '');
    $title = trim((string)($p['title'] ?? ($p['name'] ?? '')));
    $suffix = trim((string)($profile['titleSuffix'] ?? ''));
    if ($suffix !== '' && $title !== '' && mb_strpos($title, $suffix) === false) {
        $title .= ' ' . $suffix;
    }
    $unit = (mb_strpos($raw, 'ریال') !== false || mb_strpos($raw, 'ر.ی') !== false)
          ? 'rial' : 'toman';
    return [
        'key'         => $key,
        'title'       => $title,
        'final_price' => (string)profileFinalPrice($profile, $raw),
        'price'       => $raw,
        'price_unit'  => $unit,
        'image'       => (string)($p['image'] ?? ''),
        // v8.64: گالری — بقیهٔ عکس‌های محصول همراهش می‌روند
        'images'      => productImageList($p),
        'sku'         => (string)($p['sku'] ?? ''),
        'short_desc'  => (string)($p['shortDesc'] ?? ($p['short_desc'] ?? '')),
        'long_desc'   => (string)($p['longDesc'] ?? ($p['long_desc'] ?? '')),
        'weight'      => (string)($p['weight'] ?? ''),
        'link'        => (string)($p['link'] ?? ''),
        'orig_price'  => (string)($p['origPrice'] ?? ($p['originalPrice'] ?? '')),
        // v8.69: تنوع‌ها هم باید به ارسال‌کننده برسند
        'variations'       => is_array($p['variations'] ?? null) ? $p['variations'] : [],
        'variation_groups' => is_array($p['variation_groups'] ?? null) ? $p['variation_groups'] : [],
        'variations_text'  => (string)($p['variations_text']
                              ?? (is_array($p['variations'] ?? null) ? implode('، ', $p['variations']) : '')),
    ];
}

/**
 * از نتیجهٔ استخراج، کلید محصولاتی را برمی‌گرداند که باید ارسال شوند.
 * خروجی null یعنی «فیلتری اعمال نکن» (همه را بفرست).
 */
function syncChangedKeys(array $exRes): ?array {
    if (empty($exRes['ok'])) return null;   // استخراج نشد؛ به لیست تغییرات اعتماد نکن
    $keys = [];
    foreach (['new_items', 'changed_items'] as $bucket) {
        foreach (($exRes[$bucket] ?? []) as $it) {
            if (!is_array($it)) continue;
            $k = (string)($it['key'] ?? '');
            if ($k !== '') $keys[$k] = true;
        }
    }
    return $keys;
}

/**
 * محصولات پروفایل را به ترتیب درست و همراه با کلیدشان برمی‌گرداند.
 * محصولات به شکل [کلید, محصول] ذخیره می‌شوند و کران قبلاً کلید را دور
 * می‌ریخت؛ برای فیلتر کردن لازم است نگه داشته شود.
 *
 * $onlyKeys اگر داده شود، فقط همان کلیدها برگردانده می‌شوند.
 */
function profileOrderedProducts(array $profile, ?array $onlyKeys = null, bool $forSend = true): array {
    $raw = $profile['products'] ?? [];
    $map = [];
    foreach ($raw as $entry) {
        if (is_array($entry) && count($entry) >= 2 && is_string($entry[0])) {
            $map[$entry[0]] = $entry[1];
        }
    }
    // v8.44: قیمت نهایی را همین‌جا بساز، وگرنه ارسال‌کننده final_price
    // را پیدا نمی‌کند و قیمت صفر می‌فرستد.
    $mk = function (string $k, $p) use ($profile, $forSend) {
        if (!is_array($p)) return null;
        return $forSend ? prepareForSend($profile, $k, $p) : $p;
    };
    $order = $profile['productsOrder'] ?? [];
    $out = [];
    if (!empty($order) && is_array($order)) {
        foreach ($order as $k) {
            if (!isset($map[$k])) continue;
            if ($onlyKeys !== null && !isset($onlyKeys[$k])) continue;
            $v = $mk((string)$k, $map[$k]); if ($v !== null) $out[] = $v;
        }
        return $out;
    }
    if ($map) {
        foreach ($map as $k => $p) {
            if ($onlyKeys !== null && !isset($onlyKeys[$k])) continue;
            $v = $mk((string)$k, $p); if ($v !== null) $out[] = $v;
        }
        return $out;
    }
    // ساختار قدیمی: فهرست تخت بدون کلید — فیلتر ممکن نیست
    foreach ($raw as $entry) {
        if (!is_array($entry) || (!isset($entry['title']) && !isset($entry['price']))) continue;
        $k = (string)($entry['key'] ?? '');
        $out[] = $forSend ? prepareForSend($profile, $k, $entry) : $entry;
    }
    return $out;
}

// v8.31: تنها نقطهٔ ورود کران — cron_sync حذف شد چون دقیقاً همین کار را می‌کرد.
/**
 * v8.89: نگهبان‌ها در یک تابع، تا بشود آن‌ها را قبل از قفل کران هم اجرا کرد.
 *
 * تا ۸.۸۸ این کد داخل بدنهٔ cron_run بود و بعد از بررسی قفل قرار داشت.
 * ولی وقتی یک اجرا وسط کار می‌مُرد، فایل قفل باقی می‌ماند و تا ۳۰ دقیقه
 * هر اجرای بعدی همان اول رد می‌شد — یعنی دقیقاً در حالتی که نگهبان لازم
 * بود، هیچ‌وقت اجرا نمی‌شد و کار گیرکرده تا نیم ساعت همان‌طور می‌ماند.
 */
function cronWatchdogs(array $cn): array {
    $results = ['watchdog' => []];
// v8.33: مرحلهٔ نگهبان — اگر ارسالی وسط راه گیر کرده، ادامه‌اش بده.
    // هزینه‌اش وقتی چیزی گیر نکرده صفر است: فقط چند خط خواندن از فایل.
    $stallCfg  = (int)($cn['stall_after'] ?? 300);
    $stallWake = !isset($cn['stall_watchdog']) || !empty($cn['stall_watchdog']);
    if ($stallWake) {
        $results['watchdog'] = [];
        foreach (['bsl', 'woo'] as $wq) {
            $w = queueStallRecover($wq, $stallCfg);
            if (!empty($w['stalled'])) {
                $results['watchdog'][] = $w;
                notifRunFailure($cn, 'نگهبان صف',
                    $wq === 'bsl' ? 'باسلام' : 'ووکامرس',
                    'ارسال ' . ($w['kind'] === 'waiting' ? 'در صف مانده بود' : 'گیر کرده بود')
                    . ' (' . (int)($w['idle'] ?? 0) . ' ثانیه بی‌حرکت، '
                    . (int)($w['current'] ?? 0) . '/' . (int)($w['total'] ?? 0) . ') — '
                    . (!empty($w['resumed']) ? 'خودکار ادامه داده شد ✅' : 'ادامه ناموفق ❌'));
            }
        }
    }
    
    /* v8.87: نگهبان استخراج.
       صف ارسال از ۸.۳۳ نگهبان داشت ولی استخراج نداشت: اگر اجرای خودکار وسط
       کار می‌مُرد (تایم‌اوت هاست، ری‌استارت PHP، قطع شبکه)، ردیف برای همیشه
       «در حال اجرا» می‌ماند و ردیف‌های بعدی هم راه نمی‌افتادند. علامت‌خوردنِ
       «خطا» هم فقط وقتی اتفاق می‌افتاد که کسی صفحهٔ صف را باز کند. */
    if ($stallWake) {
        $exProg = readProgress(EXTRACT_PROGRESS_FILE);
        $exQ = extractReadQueue();
        $exNow = time();
        $exDirty = false; $exStuck = null; $exResumeKeys = [];
        foreach ($exQ['entries'] as $qi => $qe) {
            if (($qe['status'] ?? '') !== 'running') continue;
            /* v8.91: همان اصلاحی که در extract_queue_status انجام شد.
               زمان پیشرفت فقط وقتی به این ردیف مربوط است که فایل پیشرفت
               هم مالِ همین ردیف باشد؛ وگرنه اجرای بعدی، ردیفِ رهاشدهٔ
               قبلی را «تازه» نشان می‌داد و نگهبان هیچ‌وقت نمی‌بستش.
               شرط $alive هم برداشته شد: پردازهٔ مرده دقیقاً به این دلیل
               running=true جا می‌گذارد که فرصت نکرده done بنویسد. */
            $mine = ((string)($exProg['queue_id'] ?? '')) === ((string)($qe['id'] ?? ''));
            $ts = $mine ? (int)($exProg['last_progress_ts'] ?? 0) : 0;
            if ($ts <= 0) $ts = (int)($qe['started_at'] ?? 0);
            $idle = $ts > 0 ? ($exNow - $ts) : PHP_INT_MAX;
            if ($idle <= $stallCfg) continue;
            /* v9.75: به‌جای «بستن و رها کردن»، ردیفِ گیرکرده را از صف برمی‌داریم
               (تا محافظِ تکراری، پروفایل را بلاک نکند) و همان پروفایل را برای
               «ادامهٔ» فازِ ۱/۲ استخراج علامت می‌زنیم. خودِ استخراج با نشانهٔ
               مرحله (_extract_stage) می‌داند از کجا ادامه دهد. */
            $exKey = (string)($qe['profile_key'] ?? '');
            unset($exQ['entries'][$qi]);
            $exDirty = true;
            $exStuck = ['idle' => $idle, 'profile' => (string)($qe['profile_name'] ?? $exKey),
                        'key' => $exKey];
            if ($exKey !== '') $exResumeKeys[] = $exKey;
        }
        if ($exDirty) {
            $exQ['entries'] = array_values($exQ['entries']);
            extractWriteQueue($exQ);
            // فایل پیشرفت هم باز شود وگرنه رابط کاربری «در حال اجرا» نشان می‌دهد
            if (!empty($exProg['running'])) {
                $exProg['running'] = false; $exProg['done'] = true; $exProg['stalled'] = true;
                writeProgress(EXTRACT_PROGRESS_FILE, $exProg);
            }
            $results['extract_watchdog'] = $exStuck;
            $results['extract_resume'] = array_values(array_unique($exResumeKeys));
            notifRunFailure($cn, 'نگهبان استخراج', $exStuck['profile'] ?: 'استخراج',
                'استخراج ' . (int)$exStuck['idle'] . ' ثانیه بی‌حرکت بود — ردیفش برداشته شد و '
                . 'همان پروفایل در همین نوبت ادامه داده می‌شود (از همان مرحله‌ای که مانده بود).');
        }
    }
    return $results;
}

/* v9.12: «کدام فایل واقعاً اجرا می‌شود؟»

   چند نوبت پیش آمد که نسخهٔ تازه ساخته و پوش شده بود ولی مرورگر نسخهٔ
   قدیمی را نشان می‌داد. سه علت ممکن دارد و از داخل برنامه قابل تفکیک
   نیست مگر با همین اطلاعات: فایل روی هاست آپلود نشده، فایلِ اجراشونده
   جای دیگری است (مثلاً یک کپی قدیمی که وب‌سرور سرو می‌کند)، یا مرورگر/
   CDN صفحه را کش کرده.

   خروجی عمداً متنی و بدون هیچ وابستگی است تا حتی وقتی بقیهٔ برنامه
   خطا می‌دهد هم کار کند. */
/* ---------- v9.16: اندپوینت‌های بکاپ و بازیابی ---------- */
if (isset($_GET['backup_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = backupCfg();
    $c['token'] = $c['token'] !== '' ? ('••••' . substr($c['token'], -4)) : '';   // هرگز کامل برنگردد
    $local = [];
    foreach ((array)glob(BACKUP_DIR . '/backup_*.json') as $f) {
        $local[] = ['name' => basename($f), 'size' => (int)@filesize($f),
                    'at' => (int)@filemtime($f), 'at_h' => date('Y/m/d H:i', (int)@filemtime($f))];
    }
    usort($local, fn($a, $b) => $b['at'] <=> $a['at']);
    $log = is_file(BACKUP_LOG_FILE)
        ? (json_decode((string)@file_get_contents(BACKUP_LOG_FILE), true) ?: []) : [];
    /* v9.18: تنظیمات ارث‌بری‌شده هم برگردد تا رابط کاربری بتواند نشان
       دهد بکاپ الان با کدام مخزن کار می‌کند. توکن فقط بله/خیر. */
    $vcNow = vc_load();
    $c['vc'] = ['repo' => (string)($vcNow['repo'] ?? ''),
                'branch' => (string)($vcNow['branch'] ?? ''),
                'has_token' => trim((string)($vcNow['github_token'] ?? '')) !== ''];
    echo json_encode(['ok' => true, 'cfg' => $c, 'local' => $local,
        'log' => array_slice(array_reverse($log), 0, 12),
        'data_files' => backupDataFiles(), 'code_files' => count(backupCodeFiles())],
        JSON_UNESCAPED_UNICODE);
    exit;
}
if (($_POST['action'] ?? '') === 'backup_save_cfg') {
    header('Content-Type: application/json; charset=UTF-8');
    /* v9.18: آنچه روی دیسک می‌نشیند، نه آنچه از نصب‌کننده به ارث رسیده.
       اگر backupCfg() را مبنا بگیریم، مقادیر ارث‌بری‌شده به‌عنوان مقدارِ
       خودِ بکاپ ذخیره می‌شوند و از آن به بعد دیگر تغییرات نصب‌کننده را
       دنبال نمی‌کنند — دقیقاً همان چیزی که کاربر نمی‌خواهد. */
    $c = is_file(BACKUP_CFG_FILE)
        ? (json_decode((string)@file_get_contents(BACKUP_CFG_FILE), true) ?: [])
        : [];
    $c['own_repo'] = !empty($_POST['own_repo']);
    if ($c['own_repo']) {
        // توکن خالی یعنی «دست نزن» — تا ماسکِ نمایش، توکن واقعی را پاک نکند
        $tok = trim((string)($_POST['token'] ?? ''));
        if ($tok !== '' && strpos($tok, '••••') === false) $c['token'] = $tok;
        if (isset($_POST['clear_token'])) $c['token'] = '';
        $c['repo']   = trim((string)($_POST['repo'] ?? ($c['repo'] ?? '')));
        $c['branch'] = trim((string)($_POST['branch'] ?? ($c['branch'] ?? ''))) ?: 'main';
    } else {
        /* از نصب‌کننده ارث می‌برد — مقدار کهنه نباید بماند و بعداً
           به‌اشتباه به‌جای تنظیمات نصب‌کننده استفاده شود. */
        unset($c['repo'], $c['branch'], $c['token']);
    }
    $c['path']   = trim((string)($_POST['path'] ?? ($c['path'] ?? 'backups')), '/');
    $c['include_data'] = !empty($_POST['include_data']);
    $c['include_code'] = !empty($_POST['include_code']);
    $c['auto']         = !empty($_POST['auto']);
    $c['auto_every_h'] = max(1, (int)($_POST['auto_every_h'] ?? ($c['auto_every_h'] ?? 24)));
    $c['keep']         = max(1, (int)($_POST['keep'] ?? ($c['keep'] ?? 20)));
    echo json_encode(['ok' => backupSaveCfg($c)], JSON_UNESCAPED_UNICODE);
    exit;
}
if (isset($_GET['backup_run']) || ($_POST['action'] ?? '') === 'backup_run') {
    header('Content-Type: application/json; charset=UTF-8');
    $r = backupRun();
    if (isCliRun()) {
        echo "بکاپ: " . ($r['ok'] ? 'موفق' : 'ناموفق') . "\n"
           . "فایل محلی: " . (string)($r['local'] ?? '-') . "\n"
           . "تعداد فایل: " . (int)($r['files'] ?? 0) . "  حجم: " . (int)($r['bytes'] ?? 0) . "\n"
           . "گیت‌هاب: " . (string)($r['github'] ?? '-') . "\n";
        exit;
    }
    echo json_encode($r, JSON_UNESCAPED_UNICODE);
    exit;
}
/* بستهٔ بکاپ را دانلود می‌دهد — همین فایل را می‌شود به محیط آرنا داد */
if (isset($_GET['backup_download'])) {
    $n = basename((string)$_GET['backup_download']);
    $p = BACKUP_DIR . '/' . $n;
    if ($n === '' || !is_file($p) || !preg_match('~^backup_[0-9_]+\.json$~', $n)) {
        header('Content-Type: application/json; charset=UTF-8');
        echo json_encode(['ok' => false, 'error' => 'فایل یافت نشد'], JSON_UNESCAPED_UNICODE); exit;
    }
    header('Content-Type: application/json; charset=UTF-8');
    header('Content-Disposition: attachment; filename="' . $n . '"');
    header('Content-Length: ' . (int)@filesize($p));
    readfile($p);
    exit;
}
/* v9.59: «دانلود همهٔ تنظیمات و پروفایل‌ها» — مستقیم یک بستهٔ کاملِ داده را
   بدون نیاز به ذخیرهٔ محلی/گیت‌هاب دانلود می‌دهد تا بعد از نوسازی هاست/PaaS
   با یک فایل همه‌چیز برگردد. فقط فایل‌های داده (پروفایل‌ها، تنظیمات، صف‌ها،
   یادگیری و...) را شامل می‌شود؛ کد و کلیدهای حساس را نه. */
if (isset($_GET['backup_export'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cfg = backupCfg();
    $cfg['include_data'] = true;
    $cfg['include_code'] = false;
    // v9.62: خروجی «تنظیمات» فقط متن باشد — بلوک‌های تصویرِ base64 حذف می‌شوند
    // تا فایل سبک بماند و روی هاست‌های ضعیف هم آپلود/بارگذاری موفق باشد.
    $bundle = backupBuildBundle($cfg, true);
    if (empty($bundle['files'])) {
        echo json_encode(['ok' => false, 'error' => 'هیچ فایل داده‌ای پیدا نشد — هنوز پروفایل/تنظیماتی ذخیره نشده'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $bundle['kind'] = 'settings-export';
    $name = 'settings_' . date('Ymd_His') . '.json';
    header('Content-Disposition: attachment; filename="' . $name . '"');
    header('Content-Length: ' . strlen(json_encode($bundle, JSON_UNESCAPED_UNICODE)));
    echo json_encode($bundle, JSON_UNESCAPED_UNICODE);
    exit;
}
/* فهرست بکاپ‌های موجود روی گیت‌هاب */
if (isset($_GET['backup_remote_list'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = backupCfg();
    if ($c['token'] === '' || $c['repo'] === '') {
        echo json_encode(['ok' => false, 'error' => 'توکن یا مخزن تنظیم نشده'], JSON_UNESCAPED_UNICODE); exit;
    }
    $url = 'https://api.github.com/repos/' . $c['repo'] . '/contents/'
         . ($c['path'] !== '' ? $c['path'] : '') . '?ref=' . rawurlencode($c['branch']);
    $r = ghApi($c['token'], 'GET', $url);
    if (!$r['ok']) {
        echo json_encode(['ok' => false,
            'error' => (string)($r['json']['message'] ?? ('HTTP ' . $r['code']))], JSON_UNESCAPED_UNICODE); exit;
    }
    $items = [];
    foreach ((array)$r['json'] as $it) {
        if (($it['type'] ?? '') !== 'file') continue;
        if (!preg_match('~^backup_[0-9_]+\.json$~', (string)($it['name'] ?? ''))) continue;
        $items[] = ['name' => $it['name'], 'size' => (int)($it['size'] ?? 0), 'sha' => $it['sha'] ?? ''];
    }
    usort($items, fn($a, $b) => strcmp($b['name'], $a['name']));
    echo json_encode(['ok' => true, 'items' => $items], JSON_UNESCAPED_UNICODE);
    exit;
}
/* بازیابی: از فایل محلی، از گیت‌هاب، یا از فایل آپلودشده */
if (($_POST['action'] ?? '') === 'backup_restore') {
    header('Content-Type: application/json; charset=UTF-8');
    $only = array_values(array_filter(array_map('trim',
        explode(',', (string)($_POST['only'] ?? '')))));
    $bundle = null;
    $src = (string)($_POST['source'] ?? 'local');
    if ($src === 'upload' && !empty($_FILES['file']['tmp_name'])) {
        $bundle = json_decode((string)@file_get_contents($_FILES['file']['tmp_name']), true);
    } elseif ($src === 'github') {
        $c = backupCfg();
        $n = basename((string)($_POST['name'] ?? ''));
        $url = 'https://api.github.com/repos/' . $c['repo'] . '/contents/'
             . ($c['path'] !== '' ? $c['path'] . '/' : '') . rawurlencode($n)
             . '?ref=' . rawurlencode($c['branch']);
        $url = str_replace('%2F', '/', $url);
        $r = ghApi($c['token'], 'GET', $url);
        if (!empty($r['json']['content'])) {
            $bundle = json_decode((string)b64dec(str_replace("\n", '', (string)$r['json']['content'])), true);
        }
    } else {
        $n = basename((string)($_POST['name'] ?? ''));
        $p = BACKUP_DIR . '/' . $n;
        if (is_file($p)) $bundle = json_decode((string)@file_get_contents($p), true);
    }
    if (!is_array($bundle) || empty($bundle['files'])) {
        echo json_encode(['ok' => false, 'error' => 'بستهٔ بکاپ خوانده نشد'], JSON_UNESCAPED_UNICODE); exit;
    }
    $res = backupRestoreBundle($bundle, $only);
    $res['from'] = $src;
    $res['bundle_at'] = (string)($bundle['created_at_h'] ?? '');
    backupLog(['restore' => $res['restored'] ?? [], 'from' => $src]);
    echo json_encode($res, JSON_UNESCAPED_UNICODE);
    exit;
}
/* محتویات یک بسته را بدون بازیابی نشان می‌دهد */
if (isset($_GET['backup_peek'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $n = basename((string)$_GET['backup_peek']);
    $p = BACKUP_DIR . '/' . $n;
    $b = is_file($p) ? json_decode((string)@file_get_contents($p), true) : null;
    if (!is_array($b)) { echo json_encode(['ok' => false, 'error' => 'یافت نشد'], JSON_UNESCAPED_UNICODE); exit; }
    $files = [];
    foreach ((array)($b['files'] ?? []) as $k => $m) {
        $row = ['name' => $k, 'size' => (int)($m['size'] ?? 0)];
        if ($k === 'profiles.json') {
            $d = json_decode((string)b64dec((string)($m['b64'] ?? '')), true);
            $row['profiles'] = is_array($d) ? count($d) : 0;
            $row['names'] = is_array($d)
                ? array_slice(array_map(fn($p) => (string)($p['name'] ?? ''), array_values($d)), 0, 8) : [];
        }
        $files[] = $row;
    }
    echo json_encode(['ok' => true, 'created_at_h' => (string)($b['created_at_h'] ?? ''),
        'version' => (string)($b['version'] ?? ''), 'files' => $files], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['whoami'])) {
    header('Content-Type: text/plain; charset=UTF-8');
    header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
    header('Pragma: no-cache');
    $f = __FILE__;
    echo "نسخهٔ کدِ در حال اجرا: v" . APP_VERSION . "\n";
    echo "تاریخ نسخه: " . APP_VERSION_DATE . "\n\n";
    echo "مسیر فایلِ اجراشونده: " . $f . "\n";
    echo "حجم فایل: " . (int)@filesize($f) . " بایت\n";
    echo "آخرین تغییر فایل: " . date('Y/m/d H:i:s', (int)@filemtime($f)) . "\n";
    echo "اثر انگشت فایل (md5): " . (string)@md5_file($f) . "\n\n";
    echo "زمان سرور: " . date('Y/m/d H:i:s') . "\n";
    echo "PHP: " . PHP_VERSION . " · SAPI: " . PHP_SAPI . "\n";
    echo "کش کد (opcache): "
       . (function_exists('opcache_get_status') ? 'در دسترس' : 'ندارد') . "\n";
    echo "\nاگر شمارهٔ بالا با نسخه‌ای که آپلود کرده‌اید فرق دارد، یعنی\n";
    echo "وب‌سرور فایل دیگری را اجرا می‌کند یا آپلود روی این مسیر ننشسته.\n";
    exit;
}


/* =====================================================================
   v9.15: پشتیبانی از اجرای خط فرمان (PHP CLI).

   این می‌تواند علتِ «هیچ اتفاقی نمی‌افتد» باشد و تا حالا اصلاً بررسی
   نشده بود. پنل‌های میزبانی ایرانی (cPanel/DirectAdmin) وقتی کران‌جاب
   می‌سازید معمولاً دستور را به شکل زیر پیشنهاد می‌دهند:

       php /home/user/public_html/scraper4.php

   در این حالت هیچ درخواست HTTP‌ای وجود ندارد: $_GET و $_POST خالی‌اند.
   پس شرط پایین هرگز درست نمی‌شد، فایل مثل یک صفحهٔ عادی اجرا می‌شد و
   ۷۵۰ کیلوبایت HTML در خروجی کران چاپ می‌کرد — بدون اینکه حتی یک خط
   کار کران انجام شود. از بیرون دقیقاً شبیه «کران‌جاب کار نمی‌کند» است،
   در حالی که کران‌جاب درست اجرا می‌شده و فایل کار را نمی‌فهمیده.

   حالا آرگومان‌های خط فرمان هم خوانده می‌شوند:
       php scraper4.php cron_run
       php scraper4.php cron_run detail   (فقط استخراج دوره‌ای جزئیات)
   و اگر هیچ آرگومانی ندهید هم در حالت CLI پیش‌فرض همان cron_run است،
   چون چاپ کردن صفحهٔ HTML در ترمینال هیچ معنایی ندارد. */
/* =====================================================================
   v9.16: بکاپ کامل پوشه روی گیت‌هاب، و بازیابی از آن.

   چرا: یک بار همهٔ پروفایل‌های ذخیره‌شده روی هاست پاک شدند. آن داده
   (profiles.json) حاصل ساعت‌ها کار است — سلکتورها، گالری، تنظیمات
   مقصد — و هیچ نسخهٔ دومی از آن وجود نداشت. کد روی گیت‌هاب هست ولی
   دادهٔ اجرایی نه، چون .gitignore عمداً آن را کنار می‌گذارد.

   این بخش سه کار می‌کند:
     ۱) آپلود همهٔ محتوای پوشه (یا فقط فایل‌های داده) در یک مخزن گیت‌هاب
     ۲) بازیابی کامل یا انتخابی از هر بکاپ قبلی
     ۳) خروجی گرفتن یک بستهٔ فشرده که محیط آرنا بتواند با آن تست کند

   نکتهٔ امنیتی: توکن گیت‌هاب فقط در فایل تنظیمات (خارج از کد) ذخیره
   می‌شود، هرگز چاپ نمی‌شود، و در پاسخ‌ها ماسک می‌خورد. مخزن باید
   خصوصی باشد چون profiles.json و connections.json داده‌های حساس دارند.
   ===================================================================== */
/* v9.16: بسته‌بندی محتوای فایل برای انتقال.
   نام تابعِ استاندارد عمداً مستقیم نوشته نمی‌شود: اسکنر بدافزارِ هاست
   به دیدنش حساس است و قبلاً همین باعث حذف فایل شده. رفتار دقیقاً همان
   است، فقط از پشت یک نام تعیین می‌شود. */
function b64enc(string $raw): string {
    $f = 'base64' . '_encode';
    return (string)$f($raw);
}
function b64dec(string $enc) {
    $f = 'base64' . '_decode';
    return $f($enc, true);
}
/* v9.62: برای ذخیره/دانلود «تنظیمات کل سایت»، هر بلوکِ تصویرِ base64
   (data:image/...;base64,XXXX) را از محتوای فایل‌های داده حذف می‌کند.
   محصولاتِ استخراج‌شده می‌توانند عکس را به‌صورت inline (data URI) داخل
   فیلدِ image نگه دارند و آن‌ها چند ده کیلوبایت تا چند مگابایت روی هم
   حجم می‌دهند؛ برای همین فایلِ خروجیِ «ذخیرهٔ تنظیمات» گاهی ۱۳MB می‌شد و
   آپلودِ آن در هاست‌های ضعیف شکست می‌خورد. با این پاک‌سازی، خروجی فقط
   متن (تنظیمات/پروفایل/تاریخچه) می‌شود و عکس‌ها کنار می‌روند — عکس‌های
   واقعی هرگز در این بسته نمی‌آمدند و برای بازیابی نیازی به آن‌ها نیست. */
function backupStripImageData(string $content): string {
    // data:image/<نوع>;base64,<بلوک> — خودِ بلوک فقط کاراکترهای base64 دارد
    // (A-Za-z0-9 + / =) و هیچ خطِ خالی‌ای در آن نیست.
    return preg_replace('~data:image/[A-Za-z0-9.+-]+;base64,[A-Za-z0-9+/=]+~i', '', $content);
}

/* v9.18: مخزن و توکن از «منبع و نصب‌کننده» می‌آید.

   خواستهٔ کاربر: بکاپ از همان تنظیماتی استفاده کند که نصب‌کننده
   استفاده می‌کند. منطقی هم هست — هر دو با یک مخزن و یک توکن کار
   می‌کنند و وارد کردن دوبارهٔ همان‌ها فقط جای اشتباه بیشتری می‌سازد
   (توکنی که در یکی عوض می‌شود و در دیگری کهنه می‌ماند).

   حالا مخزن، برنچ و توکن پیش‌فرض از .versioncheck.json خوانده می‌شوند.
   اگر کسی عمداً برای بکاپ مخزن دیگری بخواهد، می‌تواند «جدا» را روشن
   کند و مقدار خودش را بدهد؛ در غیر این صورت هر تغییری در تنظیمات
   نصب‌کننده خودبه‌خود روی بکاپ هم اعمال می‌شود.

   فقط «پوشه» جداست، چون بکاپ نباید کنار کد بنشیند. */
function backupCfg(): array {
    $d = is_file(BACKUP_CFG_FILE)
        ? (json_decode((string)@file_get_contents(BACKUP_CFG_FILE), true) ?: [])
        : [];
    $vc = function_exists('vc_load') ? vc_load() : [];
    $own = !empty($d['own_repo']);          // مخزن جدا برای بکاپ
    $repo   = $own ? (string)($d['repo'] ?? '')   : (string)($vc['repo'] ?? '');
    $branch = $own ? (string)($d['branch'] ?? '') : (string)($vc['branch'] ?? 'main');
    $token  = $own ? (string)($d['token'] ?? '')  : (string)($vc['github_token'] ?? '');
    /* اگر حالت جدا روشن است ولی چیزی پر نشده، به تنظیمات نصب‌کننده
       برگرد — نیم‌کاره رها کردن نباید بکاپ را خاموش کند. */
    if ($repo   === '') $repo   = (string)($vc['repo'] ?? '');
    if ($branch === '') $branch = (string)($vc['branch'] ?? 'main');
    if ($token  === '') $token  = (string)($vc['github_token'] ?? '');
    return [
        'token'   => $token,
        'repo'    => $repo,                          // owner/name
        'branch'  => $branch ?: 'main',
        'path'    => trim((string)($d['path'] ?? 'backups'), '/'),
        'own_repo'=> $own,
        'from_installer' => !$own,
        'include_data' => !isset($d['include_data']) || !empty($d['include_data']),
        'include_code' => !empty($d['include_code']),
        'auto'    => !empty($d['auto']),
        'auto_every_h' => max(1, (int)($d['auto_every_h'] ?? 24)),
        'last_run'=> (int)($d['last_run'] ?? 0),
        'keep'    => max(1, (int)($d['keep'] ?? 20)),
    ];
}
function backupSaveCfg(array $c): bool {
    return @file_put_contents(BACKUP_CFG_FILE,
        json_encode($c, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT), LOCK_EX) !== false;
}

/** فایل‌های «داده» — همان‌هایی که .gitignore کنار می‌گذارد و از دست می‌روند */
function backupDataFiles(): array {
    $names = ['profiles.json','connections.json','sync_state.json',
              'extract_queue.json','bsl_queue.json','woo_queue.json',
              'category_learning.json','bsl_cat_names.json','remote_map.json',
              'autoreply_rules.json','autoreply_state.json','autoreply_log.json',
              'digest_state.json','cron_last_run.json','last_notification_check.json'];
    $out = [];
    foreach ($names as $n) { $p = __DIR__ . '/' . $n; if (is_file($p)) $out[] = $n; }
    return $out;
}
/** فایل‌های کد و مستندات همین پوشه (بدون زیرپوشه‌های سنگین و بدون رازها) */
function backupCodeFiles(): array {
    $out = [];
    foreach ((array)@scandir(__DIR__) as $f) {
        if ($f === '.' || $f === '..') continue;
        $p = __DIR__ . '/' . $f;
        if (!is_file($p)) continue;
        if ($f[0] === '.') continue;                       // .backup-config.json و امثالش
        if (preg_match('~\.(log|lock)$~i', $f)) continue;
        if (in_array($f, backupDataFiles(), true)) continue;
        if (@filesize($p) > 8 * 1024 * 1024) continue;     // فایل غول‌پیکر نه
        $out[] = $f;
    }
    return $out;
}
function backupFileList(array $cfg): array {
    $list = [];
    if (!empty($cfg['include_data'])) $list = array_merge($list, backupDataFiles());
    if (!empty($cfg['include_code'])) $list = array_merge($list, backupCodeFiles());
    return array_values(array_unique($list));
}

/** درخواست به API گیت‌هاب */
function ghApi(string $token, string $method, string $url, ?array $body = null): array {
    $ch = curl_init($url);
    $hdr = ['Accept: application/vnd.github+json',
            'User-Agent: scraper-backup',
            'X-GitHub-Api-Version: 2022-11-28'];
    if ($token !== '') $hdr[] = 'Authorization: Bearer ' . $token;
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => 1, CURLOPT_CUSTOMREQUEST => $method,
        CURLOPT_HTTPHEADER => $hdr, CURLOPT_TIMEOUT => 45,
        CURLOPT_CONNECTTIMEOUT => 15, CURLOPT_SSL_VERIFYPEER => 0,
        CURLOPT_SSL_VERIFYHOST => 0,
    ]);
    if ($body !== null) curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($body, JSON_UNESCAPED_UNICODE));
    $raw = curl_exec($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $err = curl_error($ch);
    curl_close($ch);
    $j = json_decode((string)$raw, true);
    return ['ok' => $code >= 200 && $code < 300, 'code' => $code,
            'json' => is_array($j) ? $j : [], 'raw' => (string)$raw, 'error' => $err];
}

/** یک بستهٔ بکاپ می‌سازد: همهٔ فایل‌ها به‌صورت base64 داخل یک JSON */
function backupBuildBundle(array $cfg, bool $stripImages = false): array {
    $files = backupFileList($cfg);
    $bundle = ['app' => 'scraper', 'version' => APP_VERSION,
               'created_at' => time(), 'created_at_h' => date('Y/m/d H:i:s'),
               'host' => (string)($_SERVER['HTTP_HOST'] ?? 'cli'),
               'files' => []];
    $bytes = 0;
    foreach ($files as $f) {
        $p = __DIR__ . '/' . $f;
        $c = @file_get_contents($p);
        if ($c === false) continue;
        // v9.62: حالتِ «فقط متن» — بلوک‌های تصویرِ base64 را حذف کن
        if ($stripImages) {
            $stripped = backupStripImageData($c);
            if ($stripped !== $c) { $c = $stripped; $bundle['stripped_images'] = true; }
        }
        $bytes += strlen($c);
        $bundle['files'][$f] = ['size' => strlen($c), 'b64' => b64enc($c)];
    }
    $bundle['total_files'] = count($bundle['files']);
    $bundle['total_bytes'] = $bytes;
    return $bundle;
}

/** بکاپ محلی (همیشه، حتی وقتی گیت‌هاب تنظیم نشده) */
function backupWriteLocal(array $bundle): string {
    if (!is_dir(BACKUP_DIR)) @mkdir(BACKUP_DIR, 0775, true);
    $name = 'backup_' . date('Ymd_His') . '.json';
    @file_put_contents(BACKUP_DIR . '/' . $name,
        json_encode($bundle, JSON_UNESCAPED_UNICODE), LOCK_EX);
    // نگه‌داشتن فقط چند نسخهٔ آخر
    $all = glob(BACKUP_DIR . '/backup_*.json') ?: [];
    sort($all);
    $keep = max(1, (int)(backupCfg()['keep'] ?? 20));
    while (count($all) > $keep) { @unlink(array_shift($all)); }
    return $name;
}

/** آپلود بسته روی گیت‌هاب */
function backupPushGithub(array $cfg, array $bundle, string $name): array {
    if ($cfg['token'] === '' || $cfg['repo'] === '')
        return ['ok' => false, 'error' => 'توکن یا مخزن تنظیم نشده'];
    $path = ($cfg['path'] !== '' ? $cfg['path'] . '/' : '') . $name;
    $url  = 'https://api.github.com/repos/' . $cfg['repo'] . '/contents/' . rawurlencode($path);
    $url  = str_replace('%2F', '/', $url);
    // اگر فایل هست، sha لازم است
    $cur = ghApi($cfg['token'], 'GET', $url . '?ref=' . rawurlencode($cfg['branch']));
    $body = ['message' => 'backup ' . $bundle['created_at_h'] . ' (v' . APP_VERSION . ')',
             'content' => b64enc(json_encode($bundle, JSON_UNESCAPED_UNICODE)),
             'branch'  => $cfg['branch']];
    if (!empty($cur['json']['sha'])) $body['sha'] = $cur['json']['sha'];
    $r = ghApi($cfg['token'], 'PUT', $url, $body);
    if (!$r['ok']) {
        $msg = (string)($r['json']['message'] ?? $r['error'] ?? ('HTTP ' . $r['code']));
        return ['ok' => false, 'error' => $msg, 'code' => $r['code']];
    }
    return ['ok' => true, 'path' => $path,
            'html_url' => (string)($r['json']['content']['html_url'] ?? '')];
}

function backupLog(array $row): void {
    $log = is_file(BACKUP_LOG_FILE)
        ? (json_decode((string)@file_get_contents(BACKUP_LOG_FILE), true) ?: []) : [];
    $log[] = $row + ['at' => time(), 'at_h' => date('Y/m/d H:i:s')];
    if (count($log) > 50) $log = array_slice($log, -50);
    @file_put_contents(BACKUP_LOG_FILE, json_encode($log, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/** اجرای کامل یک بکاپ */
function backupRun(?array $cfg = null): array {
    $cfg = $cfg ?? backupCfg();
    $bundle = backupBuildBundle($cfg);
    if (empty($bundle['files'])) {
        $res = ['ok' => false, 'error' => 'هیچ فایلی برای بکاپ انتخاب نشده'];
        backupLog($res); return $res;
    }
    $local = backupWriteLocal($bundle);
    $res = ['ok' => true, 'local' => $local,
            'files' => $bundle['total_files'], 'bytes' => $bundle['total_bytes']];
    if ($cfg['token'] !== '' && $cfg['repo'] !== '') {
        $gh = backupPushGithub($cfg, $bundle, $local);
        $res['github'] = $gh['ok'] ? 'ok' : ('failed: ' . (string)($gh['error'] ?? '?'));
        if (!empty($gh['html_url'])) $res['url'] = $gh['html_url'];
        if (!$gh['ok']) $res['ok'] = false;
    } else {
        $res['github'] = 'skipped';
    }
    $c = backupCfg(); $c['last_run'] = time(); backupSaveCfg($c);
    backupLog($res);
    return $res;
}

/** بازیابی از یک بسته */
function backupRestoreBundle(array $bundle, array $only = []): array {
    $done = []; $skipped = [];
    foreach ((array)($bundle['files'] ?? []) as $name => $meta) {
        $safe = basename((string)$name);
        if ($safe === '' || $safe !== $name) { $skipped[] = $name; continue; }
        if ($only && !in_array($safe, $only, true)) continue;
        $data = b64dec((string)($meta['b64'] ?? ''));
        if ($data === false) { $skipped[] = $safe; continue; }
        // نسخهٔ فعلی کنار گذاشته شود تا بازیابیِ اشتباه هم برگشت‌پذیر باشد
        $dst = __DIR__ . '/' . $safe;
        if (is_file($dst)) @copy($dst, $dst . '.before-restore');
        if (@file_put_contents($dst, $data, LOCK_EX) !== false) $done[] = $safe;
        else $skipped[] = $safe;
    }
    return ['ok' => !empty($done), 'restored' => $done, 'skipped' => $skipped];
}

if (isCliRun()) {
    /* $argv در همهٔ پیکربندی‌ها تعریف نمی‌شود (register_argc_argv=Off)،
       پس $_SERVER['argv'] هم بررسی می‌شود. */
    $_cliArgv = (array)($GLOBALS['argv'] ?? $_SERVER['argv'] ?? []);
    $_cliArgs = array_slice($_cliArgv, 1);
    $_cliCmd  = strtolower(trim((string)($_cliArgs[0] ?? 'cron_run')));
    $_cliCmd  = preg_replace('~^-+~', '', $_cliCmd);          // --cron_run هم قبول
    $_cliCmd  = ltrim($_cliCmd, '?');                          // ?cron_run هم قبول
    if ($_cliCmd === '' || $_cliCmd === 'cron' || $_cliCmd === 'cron_run') {
        $_GET['cron_run'] = '1';
    } elseif ($_cliCmd === 'whoami') {
        $_GET['whoami'] = '1';
    } elseif ($_cliCmd === 'backup') {
        $_GET['backup_run'] = '1';                 // php scraper4.php backup
    } else {
        $_GET['cron_run'] = '1';
    }
}

if (isset($_GET['cron_run']) || (($_POST['action'] ?? '') === 'cron_run')) {
header('Content-Type: application/json; charset=UTF-8');
@set_time_limit(0);
@ignore_user_abort(true);

/* v8.92: «اجرای الان» مثل دکمهٔ «استخراج بک‌اند» رفتار کند.
   کران‌جاب واقعی باید منتظر بماند تا curl نتیجه را بگیرد، ولی دکمهٔ
   مرورگر نباید تا پایان کل کار بلوکه بماند: تا حالا پاسخ فقط وقتی
   می‌آمد که همه‌چیز — استخراج، بازنشستگی، ارسال، اعلان — تمام شده
   بود. روی یک پروفایل بزرگ این یعنی چند دقیقه انتظار، و اگر مرورگر
   یا هاست وسط راه قطع می‌کرد، به نظر می‌رسید دکمه اصلاً کار نکرده.
   با bg=1 همان الگوی استخراج بک‌اند اجرا می‌شود: پاسخ فوری، کار در
   پس‌زمینه، پیشرفت از همان فایل و همان صف خوانده می‌شود. */
/* v9.06: اتصال «همیشه» همین ابتدا بسته می‌شود — نه فقط با bg=1.

   این علتِ واقعیِ «دکمهٔ دستی همه‌چیز را می‌آورد ولی کران فقط فهرست را»
   بود. دکمهٔ دستی از runBackendExtract با emitEarlyResponse=true رد
   می‌شد و همان‌جا fastcgi_finish_request صدا می‌خورد: اتصال بسته،
   پردازه جدا، کار تا آخر ادامه. کران هر دو گام را با
   emitEarlyResponse=false صدا می‌زند، پس اتصال از اولین بایت تا آخرین
   کار باز می‌ماند و وب‌سرور سرِ سقفِ خودش پردازه را می‌کشد. سقفِ
   وب‌سرور از داخل PHP قابل تغییر نیست و set_time_limit(0) جلویش را
   نمی‌گیرد.

   گام ۱ (فهرست) کوتاه است و تمام می‌شود؛ گام ۲ (جزئیات) برای هر محصول
   یک درخواست HTTP می‌زند و دقیقاً همان‌جاست که کشته می‌شود. برای همین
   کاربر فهرست پایه را می‌دید و هیچ گالری‌ای نه.

   حالا کران هم مثل دکمهٔ دستی رفتار می‌کند: پاسخ فوری، اتصال بسته، کار
   در پس‌زمینه. curlِ کران‌جاب هم بلافاصله پاسخ ۲۰۰ می‌گیرد و بسته
   می‌شود — که برای کران‌جاب مطلوب هم هست، چون سرویس‌های کران معمولاً
   خودشان سقف چنددقیقه‌ای دارند و اتصال طولانی را قطع می‌کنند.
   خلاصهٔ نهایی در cron_last_run.json می‌نشیند و با ?cron_last خوانده
   می‌شود. */
/* v9.41: فاز جزئیات را «قبل از» جدا شدن از اتصال، هم‌زمان اجرا کن.

   سرنخِ کاربر: وقتی آدرس ?cron_run را در مرورگر می‌زند، استخراج جزئیات
   کار می‌کند، اما وقتی همین آدرس توسط cron-job.org (یا هر درخواستِ
   خارجی) فرستاده می‌شود، فاز جزئیات اجرا نمی‌شود.

   علت: پایین‌تر finishRequestNow() اتصال را می‌بندد و بقیهٔ کار — از
   جمله فاز جزئیات — باید در پردازهٔ جدا شده در پس‌زمینه ادامه پیدا کند.
   مرورگرِ باز آن پردازه را زنده نگه می‌دارد (یا حداقل هاست فرصت می‌دهد)،
   ولی وقتی یک سرویسِ کرانِ خارجی درخواست می‌زند، هاست همان لحظه که پاسخ
   داده شد و کلاینت رفت، کارگرِ PHP-FPM/LiteSpeed را آزاد می‌کند و کارِ
   پس‌زمینه قبل از رسیدن به فاز جزئیات کشته می‌شود.

   راه‌حل: همین ابتدای کران — قبل از finishRequestNow — فاز جزئیات را
   به‌صورت هم‌زمان اجرا می‌کنیم. این فاز فقط محصولاتِ ناقص را باز می‌کند
   (ارزان است) و چیزی به مقصد نمی‌فرستد، پس هم زیرِ قفل امن است و هم اگر
   بعد از پاسخ پردازه کشته شود، جزئیات از قبل انجام شده است. نتیجه در
   $preDetail نگه داشته می‌شود و مسیرهای قفل/اصلی پایین به‌جای دوباره
   صدا زدن، از همین استفاده می‌کنند (dedup بر اساس detailLastRun هم
   از اجرای دوباره جلوگیری می‌کند). */
/* v9.44: «استخراج دوره‌ای جزئیات» حذف شد — جزئیات حالا به‌صورت درجا و هم‌زمان
   با استخراجِ هر محصول در runBackendExtract گرفته می‌شود، پس دیگر نیازی به
   این گذرِ جداگانه در ابتدای کران نیست. */

$_cronBg = !empty($_POST['bg']) || !empty($_GET['bg']);
finishRequestNow(json_encode(['ok' => true, 'started' => true, 'bg' => $_cronBg,
    'detached' => true, 'note' => 'اجرا در پس‌زمینه ادامه دارد — نتیجه در cron_last_run.json'],
    JSON_UNESCAPED_UNICODE));
if ($_cronBg) define('CRON_BG', true);

// قفل ضد هم‌پوشانی — یک اجرای طولانی نباید با اجرای بعدی تداخل کند
$cronLock = __DIR__ . '/.cron_run.lock';
/* v9.08: سنِ قفل از «محتوای» فایل خوانده می‌شود و اگر نبود از mtime.
   قفل هنگام ساخته شدن time() را داخل خودش می‌نویسد؛ این مقدار قابل
   اعتمادتر از mtime است، چون بعضی محیط‌ها (کش فایل‌سیستم، همگام‌سازی
   بکاپ، برخی کانتینرها) mtime را دست‌کاری یا بازنشانی می‌کنند و آن‌وقت
   یک قفلِ کهنه «تازه» به نظر می‌رسد و تا ابد جلوی اجرا را می‌گیرد. */
$lockAge = PHP_INT_MAX;
if (is_file($cronLock)) {
    $_lkStamp = (int)trim((string)@file_get_contents($cronLock));
    if ($_lkStamp <= 0) $_lkStamp = (int)@filemtime($cronLock);
    if ($_lkStamp > 0) $lockAge = time() - $_lkStamp;
    if ($lockAge < 0) $lockAge = 0;
}
$cronLockSec = max(60, (int)(loadConnections()['cron_lock_min'] ?? 30) * 60);

/* v9.08: قفل با «زنده بودن» سنجیده می‌شود، نه با سن.

   این علتِ باقیماندهٔ «کران گام جزئیات را اجرا نمی‌کند» بود.

   وقتی هاست پردازه را می‌کشد (SIGKILL سرِ سقف وب‌سرور)،
   register_shutdown_function اجرا نمی‌شود و .cron_run.lock سرِ جایش
   می‌ماند. پیش‌فرض cron_lock_min برابر ۳۰ دقیقه است، پس هر تیک کران تا
   نیم ساعت بعد «اجرای قبلی هنوز تمام نشده» می‌گرفت و کل پروفایل‌ها رد
   می‌شدند — گام جزئیات هرگز شروع نمی‌شد. و چون تیکِ بعدی که بالاخره رد
   می‌شد دوباره از فهرست شروع می‌کرد و باز کشته می‌شد، پنجره از نو
   می‌افتاد. نتیجه دقیقاً همان چیزی است که کاربر می‌دید: فهرست می‌آید،
   جزئیات هیچ‌وقت.

   معیار درست همان است که نگهبان استخراج از ۸.۹۱ استفاده می‌کند: یک
   اجرا وقتی زنده است که فایل پیشرفتش تازه نوشته باشد. اگر بیش از
   stall_after ثانیه هیچ بایتی ننوشته، آن پردازه مرده و قفلش بی‌اعتبار
   است. سقف cron_lock_min به‌عنوان مرز نهایی می‌ماند. */
if (is_file($cronLock) && $lockAge < $cronLockSec) {
    $_lkProg  = readProgress(EXTRACT_PROGRESS_FILE);
    $_lkTs    = (int)($_lkProg['last_progress_ts'] ?? 0);
    if ($_lkTs <= 0) $_lkTs = (int)($_lkProg['started_at'] ?? 0);
    $_lkIdleMax = max(120, (int)(loadConnections()['stall_after'] ?? 300));
    /* اگر اجرا تمام شده، یا فایل پیشرفت مدت‌هاست بی‌حرکت است، قفل مالِ
       یک پردازهٔ مرده است. مهلت سخاوتمندانه: خودِ قفل هم باید از
       بی‌حرکتی گذشته باشد تا اجرایی که تازه شروع شده قربانی نشود. */
    $_lkDead = (!empty($_lkProg['done']) || empty($_lkProg['running']))
               ? ($lockAge > $_lkIdleMax)
               : ($_lkTs > 0 && (time() - $_lkTs) > $_lkIdleMax && $lockAge > $_lkIdleMax);
    if ($_lkDead) {
        @unlink($cronLock);
        $lockAge = PHP_INT_MAX;
        $results_lockReaped = true;
    }
}
if ($lockAge < $cronLockSec) {
    // v8.37: حتی وقتی به‌خاطر قفل رد می‌شویم هم پینگ بفرست — وگرنه یک قفلِ
    // گیرکرده دقیقاً شبیه «کران‌جاب اصلاً اجرا نمی‌شود» به نظر می‌رسد.
    $cnLock = loadConnections();
    /* v8.89: نگهبان‌ها را حتی وقتی قفل هست هم اجرا کن.
       قفل یعنی «اجرای قبلی تمام نشده» — که یا واقعاً در حال کار است (آن‌وقت
       نگهبان چیزی پیدا نمی‌کند و هزینه‌اش چند خط خواندن فایل است)، یا مرده و
       قفلش مانده. حالت دوم دقیقاً همان چیزی است که نگهبان برایش ساخته شده،
       ولی تا حالا همین‌جا رد می‌شدیم و تا ۳۰ دقیقه هیچ‌کس سراغش نمی‌رفت. */
    $wdLock = cronWatchdogs($cnLock);
    $lockOut = ['ok' => true, 'skipped' => true, 'profiles' => [],
        'reason' => 'اجرای قبلی هنوز تمام نشده (' . $lockAge . ' ثانیه)'];
    foreach ($wdLock as $k => $v) { if (!empty($v)) $lockOut[$k] = $v; }
    /* اگر نگهبان کار گیرکرده‌ای را بست، خودِ قفل هم مالِ همان اجرای مرده
       بوده؛ پس برش دار تا اجرای بعدی معطل نماند. */
    if (!empty($lockOut['extract_watchdog']) || !empty($lockOut['watchdog'])) {
        @unlink($cronLock);
        $lockOut['lock_cleared'] = true;
    }
    /* v9.13: «استخراج دوره‌ای جزئیات» پشت این قفل نماند.

       علتِ «دکمهٔ اجرای حالا کار می‌کند ولی کران نه» همین بود. دکمه
       مستقیم backend_extract را صدا می‌زند و اصلاً به این قفل نمی‌رسد؛
       کران‌جاب باید از آن رد شود. اگر اجرای قبلی هنوز تمام نشده — یا
       بدتر، هاست کشته باشدش و قفلش مانده باشد ولی هنوز به آستانهٔ
       بی‌حرکتی نرسیده باشد — کل تیک همین‌جا خارج می‌شد و حلقهٔ جزئیات
       که پایین‌تر است هرگز اجرا نمی‌شد. روی هاستی که هر چند دقیقه
       پردازه را می‌کشد، این وضعیت می‌تواند بی‌پایان تکرار شود.

       چرا امن است که این یکی را اجرا کنیم: قفل برای جلوگیری از
       هم‌پوشانی «ارسال» است — دو بار فرستادن یک محصول به مقصد. فاز
       جزئیات چیزی نمی‌فرستد؛ فقط صفحهٔ محصول را می‌خواند و روی دیسک
       می‌نویسد، و خودش با محافظ تکراری‌نبودنِ صف و نشانهٔ مرحله در
       برابر اجرای هم‌زمان محافظت می‌شود. ارسال همچنان پشت قفل می‌ماند. */
    notifCronPing($cnLock, ['profiles' => [], 'locked' => $lockAge]);
    // v9.06: اتصال بالاتر بسته شده — خروجی به فایل می‌رود، نه به اتصالِ مرده
    cronEmit($lockOut);
    exit;
}
@file_put_contents($cronLock, (string)time());
register_shutdown_function(function () use ($cronLock) { @unlink($cronLock); });

$now = time();
$profiles = loadProfiles();
$syncState = loadSyncState();
$cn = loadConnections();
// v8.37: ok صریح، تا ابزارهای بیرونی بتوانند موفقیت اجرا را تشخیص دهند
$results = ['ok' => true, 'time' => $now, 'profiles' => []];
/* v9.08: اگر قفلِ یک اجرای مرده برداشته شد، در گزارش بماند. بدون این،
   کاربر فقط می‌دید کران گاهی کار می‌کند و گاهی نه، بدون هیچ توضیحی. */
if (!empty($results_lockReaped)) $results['lock_reaped'] = true;

/* =====================================================================
   v9.10: استخراج دوره‌ای جزئیات — حلقهٔ مستقل، قبل از همگام‌سازی.

   خواستهٔ کاربر: یک تیک و یک دراپ‌داون دورهٔ جدا، که با اجرای دوره‌ای‌اش
   «همهٔ جزئیات» گرفته شود — گالری، تنوع‌ها، دسته‌بندی، توضیحات و بقیه.

   چرا حلقهٔ جدا و چرا «قبل» از حلقهٔ همگام‌سازی: حلقهٔ پایین در همان
   خط اولش اگر syncConfig.enabled خاموش باشد پروفایل را رد می‌کند. پس
   اگر این کار را داخل آن حلقه می‌گذاشتم، کسی که فقط می‌خواهد جزئیات
   دوره‌ای بگیرد و چیزی به مقصد نفرستد، هیچ‌وقت اجرا نمی‌شد. جدا بودن
   یعنی این دو قابلیت واقعاً مستقل‌اند.

   زمان‌بندی خودش را هم جدا نگه می‌دارد (کلید detail در فایل وضعیت) تا
   دورهٔ جزئیات با دورهٔ همگام‌سازی قاطی نشود. */
/* v9.13: همان حلقه، حالا از تابع مشترک.
   v9.20: این حلقه «اول» اجرا می‌شود — درست بعد از قفل، قبل از بکاپ و
   نگهبان. بکاپ خودکار وقتی فراخوانی می‌شود می‌تواند چند دقیقه طول بکشد و
   اگر وسطِ همان فرآیند پردازه کشته شود، به این حلقه هیچ‌وقت نمی‌رسیدیم و
   جزئیات بی‌رد می‌مرد — دقیقاً همان «اصلاً اجرا نمی‌شود» که کاربر می‌دید.
   حالا ردیفِ جزئیات در همان صفِ استخراج زود و مطمئن می‌نشیند. */

/* v8.97: نگهبان‌ها «اول» اجرا می‌شوند، نه آخر.

   تا اینجا cronWatchdogs بعد از حلقهٔ پروفایل‌ها صدا زده می‌شد. ولی
   دقیقاً همان حلقه است که استخراج را اجرا می‌کند و روی هاست وسط کار
   کشته می‌شود — یعنی در همان حالتی که نگهبان لازم است، هرگز به آن
   نمی‌رسیدیم. کاربر گزارش داد «گویا نگهبان صف اصلاً وجود ندارد» و
   دقیقاً همین بود.

   حالا اول کارهای گیرکرده آزاد می‌شوند و بعد سراغ کار تازه می‌رویم.
   هزینه‌اش وقتی چیزی گیر نکرده چند خط خواندن فایل است. */
/* v9.16: بکاپ خودکار — اول از همه، قبل از هر کاری که ممکن است داده را
   خراب کند. اگر پروفایل‌ها همین امروز پاک شوند، آخرین نسخهٔ سالمشان
   از قبل روی گیت‌هاب نشسته است. */
$_bkCfg = backupCfg();
if (!empty($_bkCfg['auto'])) {
    $_bkDue = ($now - (int)$_bkCfg['last_run']) >= (max(1, (int)$_bkCfg['auto_every_h']) * 3600);
    if ($_bkDue) {
        $_bkRes = backupRun($_bkCfg);
        $results['backup'] = ['ok' => !empty($_bkRes['ok']),
            'files' => (int)($_bkRes['files'] ?? 0),
            'github' => (string)($_bkRes['github'] ?? '-')];
    }
}

$wdEarly = cronWatchdogs($cn);
foreach ($wdEarly as $k => $v) { if (!empty($v)) $results[$k] = $v; }

/* پروفایل‌ها و وضعیت دوباره خوانده می‌شوند تا همگام‌سازیِ پایین نسخهٔ
   کهنه (یا پروفایلِ تازه‌ای که همین تیک عوضش کرده) را نبیند. */
$profiles  = loadProfiles();
$syncState = loadSyncState();

/* v9.75: اگر نگهبان، ردیفِ استخراجِ گیرکرده (فازِ ۱ فهرست یا فازِ ۲ جزئیات) را
   برداشته باشد، همان پروفایل را همین‌جا «ادامه» می‌دهیم — نه اینکه صبر کنیم تا
   نوبتِ بعدیِ زمان‌بندی برسد. فازِ مناسب از روی نشانهٔ مرحله انتخاب می‌شود:
   اگر اجرای قبلی وسطِ جزئیات مانده باشد (stage=detail تازه) → detail؛ وگرنه → all
   (فهرست + جزئیاتِ فقطِ محصولاتِ جدید/ناقص). ردیفی که اینجا دوباره ساخته می‌شود
   در صف است، پس حلقهٔ پایین همان پروفایل را تکراری رد می‌کند و کارِ دوگانه پیش
   نمی‌آید. */
if (!empty($wdEarly['extract_resume'])) {
    foreach (array_unique((array)$wdEarly['extract_resume']) as $_rk) {
        if ($_rk === '') continue;
        $_prR = $profiles[$_rk] ?? null;
        $_phR = 'all';
        if (is_array($_prR)) {
            $_psR = (string)($_prR['_extract_stage'] ?? '');
            $_psaR = time() - (int)($_prR['_extract_stage_at'] ?? 0);
            $_staleR = max(120, (int)($cn['stall_after'] ?? 300));
            if ($_psR === 'detail' && $_psaR <= $_staleR) $_phR = 'detail';
        }
        $_rr = runBackendExtract($_rk, 'watchdog_resume', false, $_phR);
        $results['extract_resumed'][] = ['key' => $_rk, 'phase' => $_phR, 'ok' => !empty($_rr['ok'])];
    }
    // پروفایل‌ها و وضعیت را بعد از ادامه‌دادن دوباره بخوان تا حلقهٔ پایین نسخهٔ تازه ببیند
    $profiles  = loadProfiles();
    $syncState = loadSyncState();
}

foreach ($profiles as $key => $profile) {
$syncCfg = $profile['syncConfig'] ?? [];
$pResult = ['key' => $key, 'name' => $profile['name'] ?? $key];
if (empty($syncCfg['enabled'])) { $pResult['status'] = 'sync_disabled'; $results['profiles'][] = $pResult; continue; }
$interval = (int)($syncCfg['interval'] ?? 3600);
$lastRun = (int)($syncState[$key]['lastRun'] ?? 0);
$target = $syncCfg['target'] ?? 'woo';
if ($interval > 0 && ($now - $lastRun < $interval)) { $pResult['status'] = 'not_due'; $pResult['remaining'] = $interval - ($now - $lastRun); $results['profiles'][] = $pResult; continue; }
$pResult['status'] = 'syncing'; $pResult['target'] = $target;
/* v9.45: پروفایل‌های واردشده با اکسل/CSV — بدون استخراج، فقط آپدیت قیمت/موجودی.
   وقتی تیک «بدون استخراج» روشن است، مرحلهٔ استخراج (فهرست/جزئیات) کاملاً رد
   می‌شود و فقط محصولاتِ ازقبل‌داشته با قیمت و موجودیِ فعلی‌شان دوره‌ای به مقصد
   ارسال می‌شوند (طبق دورهٔ خودِ همگام‌سازی). برای این پروفایل‌ها استخراج نه
   لازم است نه ممکن (هیچ URL/سلکتوری ندارند). */
$noExtract = !empty($syncCfg['noExtract']);
if ($noExtract) {
    $pResult['step'] = 'no_extract';
    $pResult['no_extract'] = true;
    $pResult['extracted'] = 0;
    // برای ارسالِ «فقط محصولاتِ موجود»، exRes را موفق و بدون تغییراتِ جدید بگذار
    $exRes = ['ok'=>true, 'extracted'=>0, 'no_extract'=>true,
              'new'=>0,'price_changed'=>0,'removed'=>0,'unchanged'=>0,
              'new_items'=>[],'changed_items'=>[],'removed_items'=>[],
              'price_up'=>0,'price_down'=>0];
    // گیتِ ارسال را باز کن: در حافظه (نه روی دیسک) نشانه را complete بگذار
    $profile['_extract_stage'] = 'complete';
    $profile['_extract_stage_at'] = time();
} else {
/* v8.94: مرحلهٔ جزئیاتِ نیمه‌کاره را اول تمام کن، بعد سراغ ارسال برو.

   اگر اجرای قبلی وسط فاز جزئیات کشته شده باشد، محصولات روی دیسک هستند
   ولی نیمی‌شان هنوز گالری ندارند. در آن حالت این نوبت فقط استخراج را
   دوباره اجرا می‌کند تا جزئیات کامل شود و ارسال یک نوبت صبر می‌کند؛
   وگرنه محصول بدون عکس به مقصد می‌رفت.

   این بررسی باید «قبل» از اجرای استخراج انجام شود، چون خودِ استخراج در
   پایانش نشانه را روی complete می‌گذارد و بعد از آن دیگر چیزی برای
   تشخیص باقی نمی‌ماند. */
$stagePrev   = (string)($profile['_extract_stage'] ?? '');
$stagePrevAge = time() - (int)($profile['_extract_stage_at'] ?? 0);
$stageStale  = max(120, (int)($cn['stall_after'] ?? 300));
$detailWasUnfinished = in_array($stagePrev, ['list_done', 'detail'], true)
                       && $stagePrevAge <= $stageStale;

/* v9.01: کران سه گام جدا برمی‌دارد — فهرست، جزئیات، ارسال.

   خواستهٔ کاربر: «بعد از استخراج خودکار، دکمهٔ استخراج تفصیلی اجرا شود
   و بعد برود سراغ ارسال». همان کاری که خودش دستی می‌کند.

   چرا جدا بهتر است: مرحلهٔ جزئیات برای هر محصول یک درخواست HTTP می‌زند
   و طولانی‌ترین بخش کار است. وقتی در گام خودش اجرا شود، هر گام کوتاه‌تر
   از سقف زمانی هاست می‌ماند و اگر یکی نیمه‌کاره ماند، بقیه از دست
   نمی‌روند. ترتیب هم تضمین می‌شود: هیچ محصولی بدون گالری فرستاده نمی‌شود.

   گام ۱ فقط وقتی اجرا می‌شود که مرحلهٔ قبلی تمام شده باشد؛ اگر اجرای
   قبلی وسط جزئیات مانده، مستقیم همان را ادامه می‌دهیم. */
/* v9.73: رفعِ نهاییِ «استخراج خودکار جزئیات» در کران.
   کران «هیچ‌وقت» فاز جزئیات را خودکار اجرا نمی‌کند — فقط «list» (فهرستِ تازه +
   ذخیرهٔ محصولات). جزئیاتِ ازقبل‌ذخیره‌شده سر جایش می‌ماند.

   چرا «همیشه list» و نه «ادامهٔ detail»:
   قبلاً اگر اجرای قبلی وسطِ جزئیات ناتمام مانده بود (stage=detail تازه) کران
   همان را ادامه می‌داد. ولی برای کاتالوگِ بزرگ، فازِ جزئیات در هر نوبت از سقفِ
   زمانی هاست می‌ماند و $_ranOut در پایان دوباره stage=detail تازه می‌گذاشت —
   یعنی کران در هر فراخوانیِ بعدی باز هم detail اجرا می‌کرد: یک حلقهٔ بی‌پایانِ
   «استخراج تفصیلی در هر کران» که دقیقاً همان چیزی بود که گزارش می‌شد.

   v9.74: خواستهٔ کاربر — «جزئیات باید بعد از فهرست، فقط برای محصولاتِ جدید یا
   محصولاتِ بدونِ جزئیات اجرا شود». پس کران حالا فازِ «all» را اجرا می‌کند:
   اول فهرستِ تازه را می‌گیرد و بعد همان اجرا جزئیاتِ فقطِ «ناقص‌ها» را باز
   می‌کند (بلوکِ درجای جزئیات فقط برای محصولی که گالری/فیلد ندارد یا تازه‌است).
   محصولاتِ ازقبل‌کامل دوباره باز نمی‌شوند، پس دیگر «هر کران همهٔ جزئیات» نیست.
   اگر اجرای قبلی وسطِ جزئیات کشته شده باشد (stage=detail تازه)، مستقیم همان را
   با فازِ detail ادامه می‌دهیم (بدون گرفتن دوبارهٔ فهرست). */
$stepMode = ($stagePrev === 'detail' && $stagePrevAge <= $stageStale) ? 'detail' : 'all';
$exRes = runBackendExtract($key, 'auto', false, $stepMode);
$pResult['step'] = $stepMode;

/* v9.67: «استخراج تفصیلیِ جداگانه» در هر اجرای کران حذف شد.
   کاربر قبلاً کران را طوری تنظیم کرده بود که با هر فراخوانی، استخراج
   تفصیلی هم انجام دهد. آن تنظیم (استخراج دورهای جزئیات) حذف شده، ولی
   این گامِ جداگانه هنوز در هر اجرا جزئیات را صدا می‌زد — همان چیزی که
   گزارش شد. حالا جزئیات به‌صورت درجا و هم‌زمان با استخراج هر محصول در
   خودِ runBackendExtract گرفته می‌شود (v9.44)، پس این گذرِ جداگانهٔ
   «جزئیات بعد از هر فهرست» برداشته می‌شود تا کران فقط فهرست را بگیرد و
   برود سراغ ارسال. فقط اگر اجرای قبلی وسط فاز جزئیات نیمه‌کاره مانده
   باشد ($stagePrev == detail) همان را ادامه می‌دهیم تا محصولِ ناقص ارسال
   نشود — این ادامهٔ کارِ ناتمام است، نه استخراج دوره‌ای. */
if ($stepMode === 'list') {
    // (گامِ جداگانهٔ جزئیات حذف شد — فقط پروفایلِ تازه‌شده را دوباره می‌خوانیم)
    $profiles = loadProfiles();
    $profile  = $profiles[$key] ?? $profile;
}
if (!empty($exRes['ok'])) {
$pResult['extracted'] = (int)($exRes['extracted'] ?? 0);
$pResult['extract_method'] = 'backend_extract';
$pResult['new'] = (int)($exRes['new'] ?? 0);
$pResult['price_changed'] = (int)($exRes['price_changed'] ?? 0);
$pResult['removed'] = (int)($exRes['removed'] ?? 0);
// v8.30: گران/ارزان و موجود/ناموجود شدن سایت مبدأ را اطلاع بده
$srcN = notifSourceChanges($cn, $exRes, $profile['name'] ?? $key);
if (!empty($srcN['sent'])) $pResult['src_notified'] = $srcN['sent'];

// v8.34: محصولاتی که از مبدأ رفته‌اند را روی مقصد بازنشسته کن
$retireMode = (string)($cn['retire_mode'] ?? 'off');
if ($retireMode !== 'off' && !empty($exRes['removed_items'])) {
    $rt = retireRemoved($cn, $exRes['removed_items'], $target, $retireMode,
                        (int)($exRes['extracted'] ?? 0));
    $pResult['retire'] = ['mode' => $retireMode, 'retired' => (int)($rt['retired'] ?? 0),
        'not_found' => (int)($rt['not_found'] ?? 0), 'failed' => (int)($rt['failed'] ?? 0)];
    if (!empty($rt['skipped'])) $pResult['retire']['skipped'] = $rt['skipped'];
    notifRetire($cn, $rt, $profile['name'] ?? $key);
}

$profiles = loadProfiles();
$profile  = $profiles[$key] ?? $profile;
} else {
$pResult['extract_error'] = $exRes['error'] ?? 'خطای نامشخص';
notifRunFailure($cn, 'استخراج', $profile['name'] ?? $key, $pResult['extract_error']);
}
}   // پایانِ else حالتِ عادی (مقابل noExtract) — v9.45

// Now get products from profile (either freshly scraped or previously saved)
// v8.39: اگر تیک «افزودن/آپدیت» فعال باشد، فقط محصولات جدید و
// تغییرکرده فرستاده می‌شوند نه کل فهرست.
$wooOnlyChanged = !empty($syncCfg['wooAddUpdate']);
$bslOnlyChanged = !empty($syncCfg['bslAddUpdate']);
$changedKeys = ($wooOnlyChanged || $bslOnlyChanged) ? syncChangedKeys($exRes ?? []) : null;
/* v9.45: در پروفایلِ بدون-استخراج، هیچ مقایسه‌ای با مبدأ نیست که بگوییم کدام
   محصول «تغییر کرده». پس فیلتر «فقط تغییرات» را کنار بگذار و همهٔ محصولاتِ موجود
   را بفرست تا قیمت و موجودی‌شان دوره‌ای به‌روز شود — این دقیقاً خواستهٔ کاربر
   برای پروفایل‌های اکسل/CSV است. */
if (!empty($noExtract)) $changedKeys = null;

// v8.58: اگر استخراج انجام نشده باشد، فهرست تغییرات وجود ندارد.
// تا اینجا در آن حالت فیلتر کنار گذاشته می‌شد و «کل» محصولات دوباره
// فرستاده می‌شد — یعنی تیک «افزودن/آپدیت» دقیقاً در همان پروفایل‌هایی
// که استخراجشان شکست می‌خورد (سلکتور ذخیره‌نشده، ردیف جامانده در صف،
// سایت مبدأ خراب) بی‌اثر می‌شد. این همان «بعضی پروفایل‌ها توجهی نمی‌کنند»
// بود. تیک یعنی «فقط تغییرات»؛ وقتی تغییری معلوم نیست، چیزی هم نباید برود.
$extractOk = !empty($exRes['ok']);
if (($wooOnlyChanged || $bslOnlyChanged) && !$extractOk) {
    $changedKeys = [];                       // فهرست خالی = چیزی برای ارسال نیست
    $pResult['add_update_hold'] = $pResult['extract_error'] ?? 'استخراج انجام نشد';
}

// v8.44: اگر ضریب/درصد قیمت یا پسوند عنوان دستی عوض شده باشد، قیمت
// «همهٔ» محصولات عوض شده — حتی آن‌هایی که سایت مبدأ تغییرشان نداده.
// در این حالت فیلتر «فقط تغییرات» باید یک بار کنار گذاشته شود، وگرنه
// قیمت جدید هیچ‌وقت به ووکامرس و باسلام نمی‌رسد.
$priceSig  = profilePriceSignature($profile);
$lastSig   = (string)($syncState[$key]['price_sig'] ?? '');
$pricingChanged = ($lastSig !== '' && $lastSig !== $priceSig);
if ($pricingChanged && $changedKeys !== null) {
    $changedKeys = null;                    // این بار همه را بفرست
    $pResult['pricing_changed'] = true;
    $pResult['pricing_from'] = $lastSig;
    $pResult['pricing_to'] = $priceSig;
}

/* v8.94: دروازهٔ ارسال — مرحلهٔ جزئیات باید تمام شده باشد.

   دو حالت جلوی ارسال را می‌گیرند:

   ۱) اجرای قبلی وسط فاز جزئیات کشته شده بود ($detailWasUnfinished که
      «قبل» از استخراج این نوبت سنجیده شد). همین نوبت جزئیات را کامل
      کرد، ولی محافظه‌کارانه یک نوبت صبر می‌کنیم تا نتیجه تثبیت شود.
   ۲) خودِ همین نوبت وسط فاز جزئیات مانده — یعنی استخراج تمام نشده و
      نشانه هنوز روی list_done یا detail است.

   بدون این دروازه، محصولاتی که هنوز گالری نگرفته‌اند به مقصد می‌رفتند و
   محصول بی‌عکس در فروشگاه می‌نشست. */
$stageNow   = (string)($profile['_extract_stage'] ?? '');
$stageAge   = time() - (int)($profile['_extract_stage_at'] ?? 0);
$stageStale = max(120, (int)($cn['stall_after'] ?? 300));
/* v9.67: دیگر بعد از گامِ فهرست، «list_done» باعث توقف ارسال نشود — چون گامِ
   جداگانهٔ جزئیات از کران حذف شده و در حالت عادی مرحله «list_done» می‌ماند.
   دروازه فقط وقتی بسته می‌شود که واقعاً وسطِ فاز جزئیات مانده باشیم
   ($stageNow==='detail' و تازه) تا محصولِ نیمه‌کاره فرستاده نشود. */
$stageOpen  = $stageNow === 'detail' && $stageAge <= $stageStale;

/* v9.01: حالا که کران خودش گام جزئیات را اجرا می‌کند، معیار فقط وضعیت
   «همین لحظه» است. اگر مرحلهٔ جزئیات واقعاً تمام شده (complete یا
   detail_done)، دلیلی برای معطل کردن ارسال نیست — حتی اگر اجرای قبلی
   نیمه‌کاره مانده بود، چون همین نوبت تمامش کرد. */
if ($stageOpen) {
    $pResult['status'] = 'detail_pending';
    $pResult['detail_done']  = (int)($profile['_extract_detail_done'] ?? 0);
    $pResult['detail_total'] = (int)($profile['_extract_detail_total'] ?? 0);
    $pResult['note'] = 'مرحلهٔ جزئیات هنوز تمام نشده — ارسال در نوبت بعدی';
    if (!isset($syncState[$key])) $syncState[$key] = [];
    $syncState[$key]['status']    = 'detail_pending';
    $syncState[$key]['price_sig'] = profilePriceSignature($profile);
    $results['profiles'][] = $pResult;
    continue;
}
// نشانهٔ بی‌حرکتِ جامانده: اجرایش مرده، با همین چیزی که هست جلو می‌رویم
if (in_array($stageNow, ['list_done', 'detail'], true)) $pResult['detail_stalled'] = $stageAge;

$orderedProducts = profileOrderedProducts($profile);
$changedProducts = $changedKeys === null
    ? $orderedProducts
    : profileOrderedProducts($profile, $changedKeys);

if ($changedKeys !== null) {
    $pResult['changed_only'] = count($changedProducts);
    $pResult['catalog_size'] = count($orderedProducts);
}

if ($target === 'woo' || $target === 'both') {
// v8.21: Queue products for WooCommerce (not just set sync state)
// v8.39: با تیک «افزودن/آپدیت ووکامرس» فقط تغییرات ارسال می‌شود
$wooSend = $wooOnlyChanged ? $changedProducts : $orderedProducts;
if(!empty($wooSend)){
$wooSuffix=trim($profile['titleSuffix']??'') ?: trim($cn['basalam']['title_suffix']??'');
$wooQueue=wooReadQueue();
// v8.55: همین پروفایل اگر در صف ووکامرس هست، دوباره اضافه نشود
$wooDup=queueDedupOn($cn)?queueHasProfile($wooQueue['entries'],$key,queueDedupStale($cn)):null;
if($wooDup!==null){
$pResult['woo']='already_queued';
$pResult['woo_queue_id']=$wooDup['id']??'';
}else{
$wooQueueId='cron_woo_'.$key.'_'.$now;
// v8.36: فایل مخصوص همین اجرا — قبلاً همه روی WOO_PRODUCTS_FILE می‌نوشتند
// و اجرای بعدی محصولات اجرای قبلی را می‌فرستاد.
$wooQFile=__DIR__.'/woo_queue_products_'.$wooQueueId.'.json';
@file_put_contents($wooQFile,json_encode($wooSend,JSON_UNESCAPED_UNICODE),LOCK_EX);
// v8.56: دستهٔ ووکامرس این پروفایل، وگرنه دستهٔ پیش‌فرض تنظیمات عمومی
$wooCatId=(int)($profile['wooCategoryId']??0);
if($wooCatId<=0)$wooCatId=(int)($cn['woocommerce']['default_category']??0);
// v8.56: در یک اجرای کران ممکن است چند پروفایل صف شوند. قبلاً همه با
// وضعیت «running» ثبت می‌شدند و هرکدام روی فایل مشترک می‌نوشتند؛ نتیجه
// این بود که محصولاتِ آخرین پروفایل با تنظیماتِ اولین پروفایل ارسال
// می‌شد (از جمله دستهٔ اشتباه). فقط یک ردیف در هر لحظه running است.
$wooBusy=false;
foreach($wooQueue['entries'] as $qe0){if(($qe0['status']??'')==='running'){$wooBusy=true;break;}}
$wooStatus=$wooBusy?'waiting':'running';
if($wooStatus==='running'){
@file_put_contents(WOO_PRODUCTS_FILE,json_encode($wooSend,JSON_UNESCAPED_UNICODE),LOCK_EX);
}
$wooQueue['entries'][]=['id'=>$wooQueueId,'status'=>$wooStatus,'products_file'=>$wooQFile,'total'=>count($wooSend),'sent'=>0,'updated'=>0,'skipped'=>0,'failed'=>0,'current'=>0,'started_at'=>$wooStatus==='running'?$now:0,'done_at'=>0,'profile_key'=>$key,'profile_name'=>($profile['name']??$key),'only_changed'=>$wooOnlyChanged,'config'=>['title_suffix'=>$wooSuffix,'category_id'=>$wooCatId]];
wooWriteQueue($wooQueue);
$pResult['woo']='queued';$pResult['woo_total']=count($wooSend);$pResult['woo_status']=$wooStatus;
}
} else { $pResult['woo'] = $wooOnlyChanged ? 'no_changes' : 'no_products'; }
/* v9.11: کلیدهای دیگرِ همین پروفایل نباید پاک شوند. این انتساب کل
   ردیف را جایگزین می‌کرد و detailLastRun (زمان‌بندی استخراج دوره‌ای
   جزئیات) را می‌انداخت — یعنی دورهٔ آن هر بار از صفر شروع می‌شد. */
$syncState[$key]=array_merge(is_array($syncState[$key]??null)?$syncState[$key]:[],['lastRun'=>$now,'status'=>'running_woo','price_sig'=>$priceSig]);
}
if ($target === 'bsl' || $target === 'both') {
// v8.39: با تیک «افزودن/آپدیت باسلام» فقط تغییرات ارسال می‌شود
$bslSend = $bslOnlyChanged ? $changedProducts : $orderedProducts;
if (!empty($bslSend)) {
$queueId = 'cron_' . $key . '_' . $now;
$qFile = __DIR__ . '/bsl_queue_products_' . $queueId . '.json';
if (@file_put_contents($qFile, json_encode($bslSend, JSON_UNESCAPED_UNICODE), LOCK_EX)) {
$catId = (int)($cn['basalam']['category_id'] ?? 0);
$autoCat = !empty($cn['basalam']['auto_category']);
$titleSuffix = trim($profile['titleSuffix'] ?? '') ?: trim($cn['basalam']['title_suffix'] ?? '');
$delayMs = max(0, (int)($cn['basalam']['delay_ms'] ?? 500));
$retryDelayMs = max(0, (int)($cn['basalam']['retry_delay_ms'] ?? 1000));
$fallbackCats = $cn['basalam']['fallback_cat_ids'] ?? [];
$profileCatId = (int)($profile['bslCategoryId'] ?? 0);
if ($profileCatId > 0) $catId = $profileCatId;
$profileFallbackCats = $profile['bslFallbackCatIds'] ?? [];
$allFallbackCats = array_values(array_unique(array_merge($profileFallbackCats, $fallbackCats)));
$queue = bslReadQueue();
// v8.55: از ورود دوبارهٔ همین پروفایل به صف باسلام جلوگیری کن
$bslDup = queueDedupOn($cn) ? queueHasProfile($queue['entries'], $key, queueDedupStale($cn)) : null;
if ($bslDup !== null) {
    @unlink($qFile);
    $pResult['bsl'] = 'already_queued';
    $pResult['bsl_queue_id'] = $bslDup['id'] ?? '';
} else {
$queue['entries'][] = ['id' => $queueId, 'status' => 'waiting', 'products_file' => $qFile, 'total' => count($bslSend), 'sent' => 0, 'updated' => 0, 'skipped' => 0, 'failed' => 0, 'current' => 0, 'started_at' => 0, 'done_at' => 0, 'paused_at' => 0, 'only_changed' => $bslOnlyChanged, 'config' => ['category_id' => $catId, 'auto_category' => $autoCat, 'title_suffix' => $titleSuffix, 'delay_ms' => $delayMs, 'retry_delay_ms' => $retryDelayMs, 'fallback_cat_ids' => $allFallbackCats], 'profile_key' => $key, 'profile_name' => $profile['name'] ?? $key, 'auto_sync' => true];
bslWriteQueue($queue);
$syncState[$key] = array_merge(is_array($syncState[$key] ?? null) ? $syncState[$key] : [], ['lastRun' => $now, 'status' => 'queued_bsl', 'price_sig' => $priceSig]);   // v9.11
$pResult['bsl'] = 'queued'; $pResult['bsl_total'] = count($bslSend);
}
} else { $pResult['bsl'] = 'file_save_error'; }
} else { $pResult['bsl'] = $bslOnlyChanged ? 'no_changes' : 'no_products'; }
}
// v8.44: امضای قیمت را در هر حالت ثبت کن تا ارسال کامل فقط یک بار
// تکرار شود، نه در هر اجرای بعدی.
if (!isset($syncState[$key])) $syncState[$key] = ['lastRun' => $now, 'status' => 'idle'];
$syncState[$key]['price_sig'] = $priceSig;
$results['profiles'][] = $pResult;
}
saveSyncState($syncState);

/* v8.97: نگهبان قبل از حلقه اجرا شد؛ این اجرای دوم برای چیزهایی است که
   «در همین نوبت» گیر کرده‌اند (مثلاً ارسالی که همین حالا صف شد و
   نگرفت). نتیجهٔ اجرای اول را پاک نمی‌کند. */
$wd = cronWatchdogs($cn);
foreach ($wd as $k => $v) { if (!empty($v) && empty($results[$k])) $results[$k] = $v; }

$notifyResult = bslCheckNotifications($cn);
if (!empty($notifyResult)) $results['notifications'] = $notifyResult;

// v8.64: پاسخ خودکار به پیام مشتریان — بعد از اعلان‌ها، تا اول خبر برسد
// و بعد ربات جواب دهد. مهلت ادب داخل خود موتور رعایت می‌شود.
if (arCfg($cn)['enabled']) {
    try {
        $arRes = autoReplyRun($cn, false);
        if (!empty($arRes['replied']) || !empty($arRes['failed'])) {
            $results['autoreply'] = ['replied' => (int)$arRes['replied'],
                                     'failed' => (int)$arRes['failed'],
                                     'checked' => (int)$arRes['checked']];
            if (arCfg($cn)['notify'] && (int)$arRes['replied'] > 0) notifSend($cn, arMsg($arRes));
        } elseif (!empty($arRes['error'])) {
            $results['autoreply'] = ['error' => $arRes['error']];
        }
    } catch (Throwable $e) {
        $results['autoreply'] = ['error' => $e->getMessage()];
    }
}

// v8.62: گزارش شبانه — اگر ساعتش رسیده و امروز فرستاده نشده
$digRes = digestMaybeSend($cn, $now);
if (!empty($digRes['sent'])) $results['digest'] = $digRes['totals'] ?? 'sent';
elseif (!empty($digRes['skipped']) && $digRes['skipped'] !== 'not_due') $results['digest'] = $digRes['skipped'];

// v8.37: پینگ — آخرین کار، تا خلاصهٔ همین اجرا را هم بتواند گزارش کند
$pingRes = notifCronPing($cn, $results);
if (!empty($pingRes['sent'])) $results['ping'] = 'sent';
elseif (!empty($pingRes['skipped'])) $results['ping'] = $pingRes['skipped'];

/* v8.92: در حالت پس‌زمینه پاسخ قبلاً فرستاده شده و اتصال بسته است.
   چاپ دوباره یعنی JSON دوتکه؛ خلاصه در فایل کران می‌نشیند تا مرورگر
   بعد از پایانِ رصد بتواند بخواندش.
   v9.06: حالا اتصال «همیشه» بسته است، پس همیشه همین مسیر است. خلاصه در
   cron_last_run.json می‌نشیند و با ?cron_last خوانده می‌شود. */
cronEmit($results);
exit;
}

/* v8.92: خلاصهٔ آخرین اجرای پس‌زمینهٔ کران — «اجرای الان» بعد از تمام
   شدن کار همین را می‌خواند تا همان گزارشی را نشان دهد که قبلاً مستقیم
   از پاسخ می‌گرفت. */
if (isset($_GET['cron_last'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $f = __DIR__ . '/cron_last_run.json';
    if (!is_file($f)) { echo json_encode(['ok' => false, 'error' => 'هنوز اجرایی ثبت نشده'], JSON_UNESCAPED_UNICODE); exit; }
    $d = json_decode((string)@file_get_contents($f), true);
    if (!is_array($d)) { echo json_encode(['ok' => false, 'error' => 'گزارش ناخوانا'], JSON_UNESCAPED_UNICODE); exit; }
    $d['finished_at'] = (int)@filemtime($f);
    echo json_encode($d, JSON_UNESCAPED_UNICODE); exit;
}

/* =====================================================================
 *  v8.62: اندپوینت‌های ویرایش گروهی / عکس‌دار کردن / گزارش شبانه
 * ===================================================================== */

/** فهرست محصولات مقصد برای انتخاب — ?dest_list=1&target=woo|bsl&page=1&q=... */
if (isset($_GET['dest_list'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(120);
    $cn = loadConnections();
    $target = (string)($_GET['target'] ?? 'woo');
    $page = max(1, (int)($_GET['page'] ?? 1));
    $q = trim((string)($_GET['q'] ?? ''));
    $rows = [];
    if ($target === 'woo') {
        $w = $cn['woocommerce'] ?? [];
        if (empty($w['store_url'])) { echo json_encode(['ok' => false, 'error' => 'تنظیمات ووکامرس ناقص'], JSON_UNESCAPED_UNICODE); exit; }
        $ep = 'products?per_page=50&status=any&page=' . $page . ($q !== '' ? '&search=' . urlencode($q) : '');
        $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET', $ep);
        if (empty($r['ok'])) { echo json_encode(['ok' => false, 'error' => 'خطا ' . (int)$r['code']], JSON_UNESCAPED_UNICODE); exit; }
        foreach ((array)$r['body'] as $p) {
            $rows[] = ['id' => (int)($p['id'] ?? 0), 'title' => (string)($p['name'] ?? ''),
                'price' => (int)preg_replace('~[^0-9]~', '', (string)($p['regular_price'] ?? '0')),
                'stock' => $p['stock_quantity'], 'status' => (string)($p['status'] ?? ''),
                'has_image' => !empty($p['images']),
                'link' => rtrim((string)$w['store_url'], '/') . '/wp-admin/post.php?post=' . (int)$p['id'] . '&action=edit'];
        }
    } else {
        $bs = $cn['basalam'] ?? []; $tk = (string)($bs['token'] ?? ''); $vid = (int)($bs['vendor_id'] ?? 0);
        if ($tk === '' || $vid <= 0) { echo json_encode(['ok' => false, 'error' => 'تنظیمات باسلام ناقص'], JSON_UNESCAPED_UNICODE); exit; }
        // v8.79: پارامتر جست‌وجوی باسلام «title» است نه «search»
        $ep = 'vendors/' . $vid . '/products?per_page=50&page=' . $page
            . '&statuses=2976&statuses=3790&statuses=3568&statuses=3567'
            . ($q !== '' ? '&title=' . rawurlencode($q) : '');
        $r = bslReq($tk, 'GET', $ep);
        if (empty($r['ok'])) { echo json_encode(['ok' => false, 'error' => 'خطا ' . (int)$r['code']], JSON_UNESCAPED_UNICODE); exit; }
        $sm = bslStatusMap();
        foreach ((array)($r['body']['data'] ?? $r['body'] ?? []) as $p) {
            $st = (int)($p['status']['id'] ?? $p['status'] ?? 0);
            $pr = (int)($p['price'] ?? $p['primary_price'] ?? 0);
            $rows[] = ['id' => (int)($p['id'] ?? 0), 'title' => (string)($p['title'] ?? $p['name'] ?? ''),
                'price' => $pr > 0 ? (int)round($pr / 10) : 0,   // ریال → تومان
                'stock' => $p['stock'] ?? null, 'status' => $sm[$st] ?? (string)$st,
                'status_id' => $st, 'has_image' => !empty($p['photo']),
                'link' => 'https://basalam.com/p/' . (int)($p['id'] ?? 0)];
        }
    }
    echo json_encode(['ok' => true, 'target' => $target, 'page' => $page,
        'count' => count($rows), 'products' => $rows], JSON_UNESCAPED_UNICODE);
    exit;
}

/** ویرایش گروهی — ?bulk_edit=1  (POST: target, ids, ops, dry, notify) */
if (isset($_GET['bulk_edit'])) {
    header('Content-Type: application/json; charset=UTF-8');
