/** گزارش شبانه — ?digest=1 پیش‌نمایش · &send=1 ارسال فوری */
// v8.66: این نگهبان باید «فقط» وقتی بگیرد که خودِ digest درخواست شده باشد.
// باگ: bsl_notify_selected هم پارامتر digest می‌فرستد (۰ یا ۱) و چون isset
// در هر دو حالت درست است، دکمهٔ «ارسال انتخاب‌شده‌ها به پیام‌رسان» همیشه
// اینجا می‌افتاد و به‌جای ارسال، گزارش شبانه را برمی‌گرداند.
if (isset($_GET['digest']) && !isset($_GET['bsl_notify_selected'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(120);
    $cn = loadConnections();
    $hours = max(1, min(168, (int)($_GET['hours'] ?? ($cn['digest_hours'] ?? 24))));
    $d = digestBuild($cn, $hours);
    $msg = digestMsg($d);
    $out = ['ok' => true, 'data' => $d, 'message' => $msg,
            'state' => digestLoadState(),
            'enabled' => !empty($cn['digest_enabled']),
            'hour' => (int)($cn['digest_hour'] ?? 23)];
    if (!empty($_GET['send'])) {
        $why = notifPrereq($cn);
        if ($why !== null) { $out['sent'] = false; $out['error'] = $why; }
        else {
            $out['delivery'] = notifSend($cn, $msg);
            $out['sent'] = true;
            $st = digestLoadState();
            $st['last_date'] = date('Y-m-d'); $st['last_at'] = time();
            digestSaveState($st);
        }
    }
    echo json_encode($out, JSON_UNESCAPED_UNICODE); exit;
}

/**
 * v8.34: بازنشستگی دستی — پیش‌نمایش یا اجرا.
 * ?retire_run=1&profile=<key>&mode=draft&dry=1
 * بدون dry=1 واقعاً روی ووکامرس/باسلام اعمال می‌شود.
 */
if (isset($_GET['retire_run'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cn  = loadConnections();
    $key = (string)($_GET['profile'] ?? '');
    $dry = !isset($_GET['dry']) || $_GET['dry'] !== '0';   // پیش‌فرض: فقط پیش‌نمایش
    $profiles = loadProfiles();
    if ($key === '' || !isset($profiles[$key])) {
        echo json_encode(['ok' => false, 'error' => 'پروفایل نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    $profile = $profiles[$key];
    $mode = (string)($_GET['mode'] ?? ($cn['retire_mode'] ?? 'draft'));
    if (!isset(retireModes()[$mode]) || $mode === 'off') $mode = 'draft';
    $target = (string)($_GET['target'] ?? ($profile['syncConfig']['target'] ?? 'woo'));

    // آخرین گزارش استخراج این پروفایل را پیدا کن
    $rep = null; $newest = 0;
    foreach (glob(__DIR__ . '/extract_report_*.json') ?: [] as $f) {
        $d = json_decode((string)@file_get_contents($f), true);
        if (!is_array($d)) continue;
        if (($d['profile_key'] ?? '') !== $key) continue;
        $ts = (int)@filemtime($f);
        if ($ts >= $newest) { $newest = $ts; $rep = $d; }
    }
    if ($rep === null) {
        echo json_encode(['ok' => false,
            'error' => 'گزارش استخراجی برای این پروفایل نیست — اول یک استخراج اجرا کنید'],
            JSON_UNESCAPED_UNICODE); exit;
    }
    $items = $rep['removed_items'] ?? [];
    $res = retireRemoved($cn, $items, $target, $mode, (int)($rep['extracted'] ?? 0), $dry);
    $res['ok'] = true; $res['profile'] = $profile['name'] ?? $key;
    $res['report_time'] = $newest;
    echo json_encode($res, JSON_UNESCAPED_UNICODE);
    exit;
}

/**
 * v8.47: مغایرت‌گیری مقصد با پروفایل‌ها.
 * ?recon=1&target=woo|bsl            → فقط گزارش (پیش‌فرض، امن)
 * &apply=1                           → اعمال تغییرات
 * &mode=off|draft|outofstock|delete  → با موارد اضافی چه شود
 * &fix_price=0                       → قیمت‌ها دست نخورند
 */
/**
 * v8.49: مغایرت‌گیری سمت سرور با گزارش زنده.
 * ?recon=1&target=woo|bsl[&apply=1&mode=...&fix_price=0]  → شروع در پس‌زمینه
 * ?recon_status=1                                          → وضعیت زنده
 * ?recon_result=1                                          → نتیجهٔ کامل
 */
if (isset($_GET['recon'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $target = (string)($_GET['target'] ?? '');
    if ($target !== 'woo' && $target !== 'bsl') {
        echo json_encode(['ok' => false, 'error' => 'مقصد نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    // قفل، تا دو مغایرت‌گیری هم‌زمان اجرا نشوند
    $lockFile = __DIR__ . '/recon.lock';
    $fp = fopen($lockFile, 'c');
    if (!$fp || !flock($fp, LOCK_EX | LOCK_NB)) {
        if ($fp) fclose($fp);
        echo json_encode(['ok' => false, 'error' => 'یک مغایرت‌گیری در حال اجراست',
            'running' => true], JSON_UNESCAPED_UNICODE); exit;
    }
    @set_time_limit(0); @ignore_user_abort(true);

    $apply = !empty($_GET['apply']);
    $cn = loadConnections();
    $mode = (string)($_GET['mode'] ?? ($cn['retire_mode'] ?? 'off'));
    if (!isset(retireModes()[$mode])) $mode = 'off';
    $fixPrice = !isset($_GET['fix_price']) || $_GET['fix_price'] !== '0';
    // v8.64: همهٔ پروفایل‌ها، نه فقط آن‌هایی که همگام‌سازی دوره‌ای دارند
    $allProf = !empty($_GET['all_profiles']);

    @unlink(RECON_PROGRESS_FILE);
    reconProgress(['running' => true, 'done' => false, 'target' => $target,
        'apply' => $apply, 'mode' => $mode, 'all_profiles' => $allProf,
        'started_at' => time(), 'phase' => 'start',
        'log_add' => [($apply ? '🚀 شروع اعمال تغییرات' : '🔍 شروع بررسی') . ' — '
            . ($target === 'woo' ? 'ووکامرس' : 'باسلام')
            . ($allProf ? ' · همهٔ پروفایل‌ها' : ' · فقط پروفایل‌های همگام‌شونده')]]);

    // پاسخ فوری، بعد ادامهٔ کار در پس‌زمینه
    $early = json_encode(['ok' => true, 'started' => true, 'target' => $target],
        JSON_UNESCAPED_UNICODE);
    header('Connection: close');
    header('Content-Length: ' . strlen($early));
    echo $early;
    @ob_flush(); @flush();
    if (function_exists('fastcgi_finish_request')) fastcgi_finish_request();

    register_shutdown_function(function () use ($fp, $lockFile) {
        @flock($fp, LOCK_UN); @fclose($fp); @unlink($lockFile);
    });

    try {
        $res = reconRun($cn, $target, $apply, $mode, $fixPrice, $allProf);
    } catch (Throwable $e) {
        reconProgress(['running' => false, 'done' => true, 'error' => $e->getMessage(),
            'log_add' => ['❌ خطا: ' . $e->getMessage()]]);
        exit;
    }
    foreach (['extra', 'price_diff', 'matched_items'] as $k) {
        $res[$k . '_total'] = count($res[$k] ?? []);
        if (isset($res[$k]) && count($res[$k]) > 300) $res[$k] = array_slice($res[$k], 0, 300);
    }
    @file_put_contents(__DIR__ . '/recon_result.json',
        json_encode($res, JSON_UNESCAPED_UNICODE), LOCK_EX);
    reconProgress(['running' => false, 'done' => true, 'phase' => 'done',
        'extra' => (int)$res['extra_total'], 'diff' => (int)$res['price_diff_total'],
        'matched' => (int)($res['matched'] ?? 0), 'repriced' => (int)($res['repriced'] ?? 0),
        'deleted' => (int)($res['deleted'] ?? 0), 'failed' => (int)($res['failed'] ?? 0),
        'result_ok' => !empty($res['ok']), 'error' => $res['error'] ?? '',
        'log_add' => [empty($res['ok']) ? ('❌ ' . ($res['error'] ?? 'ناموفق')) : '✅ پایان']]);
    exit;
}

/**
 * v8.51: پیشنهاد دستهٔ آموخته‌شده برای چند عنوان یک‌جا.
 * ?catlearn_bulk=1&titles=<json آرایه‌ای از {id,title}>
 * فقط پیشنهاد می‌دهد؛ چیزی را تغییر نمی‌دهد.
 */
if (isset($_GET['catlearn_bulk'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $raw = (string)($_POST['titles'] ?? $_GET['titles'] ?? '[]');
    $rows = json_decode($raw, true);
    if (!is_array($rows)) $rows = [];
    $learned = catLearnLoad();
    $out = [];
    foreach ($rows as $r) {
        if (!is_array($r)) continue;
        $t = trim((string)($r['title'] ?? ''));
        if ($t === '') continue;
        $cid = catLearnLookup($t, $learned);
        if ($cid > 0) {
            // v8.60: کلیدی که واقعاً جواب داد را گزارش کن، نه همیشه یک کلمه
            $usedKey = catFirstWord($t);
            for ($i = catLearnWordCount(); $i >= 1; $i--) {
                $k = catFirstWords($t, $i);
                if (catLearnBestFor($k, $learned) === $cid) { $usedKey = $k; break; }
            }
            $out[] = ['id' => (int)($r['id'] ?? 0), 'title' => $t,
                      'word' => $usedKey, 'cat_id' => $cid];
        }
    }
    echo json_encode(['ok' => true, 'matches' => $out, 'count' => count($out)],
        JSON_UNESCAPED_UNICODE);
    exit;
}

