    $esc = fn($s) => htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8');
    echo '<!DOCTYPE html><html dir="rtl" lang="fa"><head><meta charset="UTF-8">'
       . '<meta name="viewport" content="width=device-width,initial-scale=1">'
       . '<title>خودآزمون v' . APP_VERSION . '</title><style>'
       . 'body{font-family:Tahoma,system-ui,sans-serif;background:#0f172a;color:#e2e8f0;padding:16px;line-height:1.7}'
       . '.wrap{max-width:760px;margin:0 auto}h1{font-size:18px;margin:0 0 4px}'
       . '.big{font-size:34px;font-weight:700;font-family:ui-monospace,monospace}'
       . '.card{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:14px;margin-bottom:14px}'
       . 'table{width:100%;border-collapse:collapse;font-size:13px}'
       . 'td{padding:7px 6px;border-bottom:1px solid #334155}'
       . '.v{color:#64748b;font-family:ui-monospace,monospace;font-size:11px;white-space:nowrap}'
       . '.ok{color:#4ade80}.no{color:#f87171}.d{color:#64748b;font-size:11px}'
       . '.hero{border-radius:12px;padding:16px;text-align:center;margin-bottom:14px}'
       . '</style></head><body><div class="wrap">';
    echo '<div class="hero" style="background:' . ($allOk ? '#14532d' : '#7f1d1d')
       . ';border:1px solid ' . ($allOk ? '#22c55e' : '#ef4444') . '">'
       . '<div class="big">v' . $esc(APP_VERSION) . '</div>'
       . '<div style="font-size:14px;margin-top:4px">'
       . ($allOk ? '✅ همهٔ قابلیت‌ها روی این سرور فعال‌اند' : '⚠️ نصب ناقص است — فایل قدیمی روی سرور مانده')
       . '</div><div class="d" style="margin-top:4px">' . $okCount . ' از ' . count($checks) . ' بررسی موفق</div></div>';

    if (!$allOk) {
        echo '<div class="card" style="border-color:#f59e0b">'
           . '<b style="color:#fbbf24">چه باید کرد؟</b><br>'
           . 'یعنی فایل روی هاست قدیمی است. با <code>deploy.php</code> نسخهٔ تازه را نصب کنید '
           . 'و بعد این صفحه را دوباره باز کنید.</div>';
    }

    echo '<div class="card"><b>وضعیت فعلی</b><table>';
    foreach ($cfgNow as $k => $v) {
        echo '<tr><td style="width:45%">' . $esc($k) . '</td><td><b>' . $esc($v) . '</b></td></tr>';
    }
    echo '</table></div><div class="card"><b>بررسی قابلیت‌ها</b><table>';
    foreach ($checks as $c) {
        echo '<tr><td class="v">v' . $esc($c['ver']) . '</td><td>' . $esc($c['name'])
           . ($c['detail'] !== '' ? ' <span class="d">' . $esc($c['detail']) . '</span>' : '')
           . '</td><td style="width:34px;text-align:center" class="' . ($c['ok'] ? 'ok' : 'no') . '">'
           . ($c['ok'] ? '✓' : '✗') . '</td></tr>';
    }
    echo '</table></div>';
    echo '<div class="d">این صفحه فقط می‌خواند و چیزی را تغییر نمی‌دهد. '
       . 'برای خروجی ماشینی: <code>?selftest=1&amp;json=1</code></div>';
    echo '</div></body></html>';
    exit;
}

// v8.19: Re-scrape a profile using its manual selectors. Returns updated products array.
// If selectors are empty, returns null (caller should use saved products).
/* =====================================================================
 *  v8.29: اعلان‌های باسلام
 *  به سه بررسی مستقل تقسیم شده تا هرکدام دکمهٔ تست جدا داشته باشند و
 *  در کران‌جاب هم به ترتیب اولویت اجرا شوند.
 * ===================================================================== */


function notifLoadState(): array {
    if (!is_file(NOTIF_STATE_FILE)) return [];
    $d = json_decode((string)@file_get_contents(NOTIF_STATE_FILE), true);
    return is_array($d) ? $d : [];
}

function notifSaveState(array $st): void {
    @file_put_contents(NOTIF_STATE_FILE, json_encode($st, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/* =====================================================================
 *  v8.38: پیگیری تک‌تک موارد + یادآوری
 *
 *  تا نسخهٔ ۸.۳۷ فقط یک «زمان آخرین بررسی» ذخیره می‌شد. یعنی هر مورد
 *  دقیقاً یک بار اعلان می‌شد و بعد برای همیشه ساکت می‌ماند — حتی اگر
 *  پیام مشتری بی‌جواب مانده بود.
 *
 *  حالا وضعیت هر مورد جداگانه نگه داشته می‌شود:
 *    • مورد تازه            → اعلان
 *    • وضعیتش عوض شده       → اعلان (رویداد تازه است)
 *    • بی‌تغییر ولی بی‌جواب  → بعد از فاصلهٔ تعیین‌شده، یادآوری
 *    • جواب داده شده        → دیگر یادآوری نمی‌شود
 * ===================================================================== */

/** تنظیمات یادآوری: فاصله (ثانیه) و سقف تعداد */
function notifRemindCfg(array $cn): array {
    $after = $cn['notif_remind_after'] ?? 30;      // دقیقه
    $after = (int)$after;
    if ($after < 0) $after = 0;                    // ۰ = یادآوری خاموش
    $max = (int)($cn['notif_remind_max'] ?? 0);    // ۰ = بی‌نهایت
    return ['after' => $after * 60, 'max' => max(0, $max)];
}

/**
 * تصمیم می‌گیرد برای یک مورد اعلان بفرستیم یا نه.
 *
 * $sig امضای وضعیت است؛ اگر عوض شود یعنی اتفاق تازه‌ای افتاده.
 * $pending یعنی هنوز کاری برایش لازم است (پیام بی‌جواب، سفارش ارسال‌نشده).
 *
 * خروجی: '' یعنی نفرست · 'new' · 'changed' · 'remind'
 */
function notifDecide(array &$st, string $key, string $sig, bool $pending,
                     array $cfg, int $now): string {
    if (!isset($st['items']) || !is_array($st['items'])) $st['items'] = [];
    $prev = $st['items'][$key] ?? null;

    if (!is_array($prev)) {
        $st['items'][$key] = ['sig' => $sig, 'first' => $now, 'last' => $now,
                              'n' => 1, 'pending' => $pending];
        return 'new';
    }
    if ((string)($prev['sig'] ?? '') !== $sig) {
        // امضا عوض شده — مثلاً پیام تازه رسیده یا وضعیت سفارش تغییر کرده
        $st['items'][$key] = ['sig' => $sig, 'first' => (int)($prev['first'] ?? $now),
                              'last' => $now, 'n' => 1, 'pending' => $pending];
        return 'changed';
    }
    // همان وضعیت قبلی
    if (!$pending) { $st['items'][$key]['pending'] = false; return ''; }
    if ($cfg['after'] <= 0) return '';
    if ($now - (int)($prev['last'] ?? 0) < $cfg['after']) return '';
    $n = (int)($prev['n'] ?? 1);
    if ($cfg['max'] > 0 && $n > $cfg['max']) return '';   // سقف یادآوری پر شده
    $st['items'][$key]['last'] = $now;
    $st['items'][$key]['n'] = $n + 1;
    $st['items'][$key]['pending'] = true;
    return 'remind';
}

/**
 * موارد قدیمی و تمام‌شده را پاک می‌کند تا فایل وضعیت بی‌نهایت بزرگ نشود.
 * موارد بی‌جواب نگه داشته می‌شوند چون هنوز باید یادآوری شوند.
 */
function notifPrune(array &$st, int $now, int $maxAge = 604800): void {
    if (empty($st['items']) || !is_array($st['items'])) return;
    foreach ($st['items'] as $k => $v) {
        if (!is_array($v)) { unset($st['items'][$k]); continue; }
        $age = $now - (int)($v['last'] ?? 0);
        if (empty($v['pending']) && $age > 86400)   { unset($st['items'][$k]); continue; }
        if ($age > $maxAge)                          { unset($st['items'][$k]); }
    }
    // سقف سخت، برای وقتی غرفه خیلی شلوغ است
    if (count($st['items']) > 500) {
        uasort($st['items'], fn($a, $b) => (int)($b['last'] ?? 0) <=> (int)($a['last'] ?? 0));
        $st['items'] = array_slice($st['items'], 0, 500, true);
    }
}

/**
 * هنگام ارتقا از نسخه‌های قبلی، موارد قدیمی را بی‌صدا ثبت می‌کند.
 * بدون این کار، اولین اجرا هر ۱۰ مورد موجود را «تازه» می‌دید و یک‌جا
 * ۱۰ پیام می‌فرستاد.
 */
function notifSeedIfNeeded(array &$st, string $kind, array $seen, int $watermark): bool {
    $flag = 'seeded_' . $kind;
    if (!empty($st[$flag])) return false;
    if (!isset($st['items']) || !is_array($st['items'])) $st['items'] = [];
    if ($watermark > 0) {
        foreach ($seen as $s) {
            // فقط مواردی که قبلاً هم بوده‌اند؛ موارد تازه‌تر باید اعلان شوند
            if ((int)$s['ts'] > 0 && (int)$s['ts'] <= $watermark) {
                $st['items'][$s['key']] = ['sig' => $s['sig'], 'first' => (int)$s['ts'],
                    'last' => $watermark, 'n' => 1, 'pending' => !empty($s['pending'])];
            }
        }
    }
    $st[$flag] = time();
    return true;
}

/** سرتیتر پیام بر اساس نوع رویداد */
function notifHead(string $why, string $base, int $n = 0): string {
    if ($why !== 'remind') return $base;
    $tag = '🔁 یادآوری' . ($n > 1 ? ' (' . $n . ')' : '');
    return $base === '' ? $tag : $tag . ' — ' . $base;
}

/** ارسال یک پیام به همهٔ پیام‌رسان‌های فعال */
function notifSend(array $cn, string $msg): array {
    $out = [];
    $bt = $cn['baleh']['token'] ?? '';  $bc = $cn['baleh']['chat_id'] ?? '';
    $rt = $cn['rubika']['token'] ?? ''; $rc = $cn['rubika']['chat_id'] ?? '';
    if ($bt !== '' && $bc !== '')  $out['baleh']  = bslSendToBaleh($bt, $bc, $msg) ? 'sent' : 'fail';
    if ($rt !== '' && $rc !== '')  $out['rubika'] = bslSendToRubika($rt, $rc, $msg) ? 'sent' : 'fail';
    if (!$out) $out['none'] = 'no_messenger';
    return $out;
}

/**
 * v8.37: پیام «پینگ» برای اثبات اینکه خودِ کران‌جاب اجرا می‌شود.
 *
 * فرق این با «خطای اجرای خودکار»: آن وقتی می‌آید که کاری شکست بخورد،
 * ولی اگر کران‌جاب اصلاً اجرا نشود هیچ پیامی نمی‌آید و سکوت گمراه‌کننده
 * است. پینگ دقیقاً همین حالت را آشکار می‌کند.
 *
 * ⚠️ چون کران معمولاً هر ۵ دقیقه اجرا می‌شود، ارسال پیام در هر اجرا
 * روزی ۲۸۸ پیام می‌شود. برای همین یک فاصلهٔ زمانی (پیش‌فرض ۶ ساعت)
 * رعایت می‌شود؛ با ping_every=0 می‌توان هر اجرا را فرستاد.
 */
function notifCronPing(array $cn, array $results, bool $force = false): array {
    if (!$force && empty($cn['notif_events']['cron_ping'])) return ['ok' => true, 'skipped' => 'disabled'];
    if (notifPrereq($cn) !== null) return ['ok' => false, 'error' => notifPrereq($cn)];

    $everyMin = (int)($cn['ping_every'] ?? 360);   // دقیقه
    $st  = notifLoadState();
    $last = (int)($st['last_cron_ping'] ?? 0);
    $now  = time();
    if (!$force && $everyMin > 0 && $last > 0 && ($now - $last) < $everyMin * 60) {
        return ['ok' => true, 'skipped' => 'throttled',
                'next_in' => $everyMin * 60 - ($now - $last)];
    }

    // خلاصهٔ کاری که همین اجرا انجام داد تا پینگ فقط «زنده‌ام» نباشد
    $profiles = is_array($results['profiles'] ?? null) ? $results['profiles'] : [];
    $ran = 0; $notDue = 0; $errs = 0; $extracted = 0;
    foreach ($profiles as $p) {
        $stt = $p['status'] ?? '';
        if ($stt === 'not_due') { $notDue++; continue; }
        if ($stt === 'sync_disabled') continue;
        $ran++;
        $extracted += (int)($p['extracted'] ?? 0);
        if (!empty($p['extract_error'])) $errs++;
    }
    $sinceTxt = $last > 0 ? gmdate('H:i', min(359999, $now - $last)) : '—';

    $msg = "📡 کران‌جاب اجرا شد"
         . "\nزمان سرور: " . date('Y-m-d H:i:s')
         . "\nنسخه: " . APP_VERSION
         . "\nپروفایل‌های اجراشده: " . $ran
         . ($notDue > 0 ? " · نوبتشان نبود: " . $notDue : '')
         . ($extracted > 0 ? "\nمحصولات استخراج‌شده: " . $extracted : '')
         . ($errs > 0 ? "\n⚠️ خطا در " . $errs . " پروفایل" : '')
         . ($last > 0 ? "\nفاصله از پینگ قبلی: " . $sinceTxt : '')
         . ($force ? "\n(پینگ آزمایشی)" : '');

    $delivery = notifSend($cn, $msg);
    if (!$force) { $st['last_cron_ping'] = $now; notifSaveState($st); }
    return ['ok' => true, 'sent' => true, 'delivery' => $delivery, 'message' => $msg];
}

/** پیش‌نیازها را بررسی می‌کند و در صورت نبود، علت را برمی‌گرداند */
function notifPrereq(array $cn): ?string {
    if (trim((string)($cn['basalam']['token'] ?? '')) === '') return 'توکن باسلام تنظیم نشده';
    if ((int)($cn['basalam']['vendor_id'] ?? 0) <= 0)         return 'شناسهٔ غرفه تنظیم نشده';
    $hasMsgr = (!empty($cn['baleh']['token']) && !empty($cn['baleh']['chat_id']))
            || (!empty($cn['rubika']['token']) && !empty($cn['rubika']['chat_id']));
    if (!$hasMsgr) return 'هیچ پیام‌رسانی تنظیم نشده (بله یا روبیکا)';
    return null;
}

/**
 * v8.31: پیام خطای گویا برای پاسخ‌های ناموفق باسلام.
 * ۴۰۴ معمولاً یعنی مسیر عوض شده (باسلام به API Gateway مهاجرت کرده) و
 * ۴۰۳ یعنی توکن اسکوپ لازم را ندارد — این دو را نباید یکی گزارش کرد.
 */
function bslApiError(array $r, string $what, string $endpoint, string $scope = ''): string {
    $c = (int)($r['code'] ?? 0);
    if ($c === 404) return $what . ' — مسیر یافت نشد (۴۰۴): ' . $endpoint;
    if ($c === 401) return $what . ' — توکن نامعتبر یا منقضی (۴۰۱)';
    if ($c === 403) return $what . ' — توکن دسترسی لازم را ندارد (۴۰۳)'
                         . ($scope !== '' ? ' · اسکوپ موردنیاز: ' . $scope : '');
    if ($c === 429) return $what . ' — تعداد درخواست بیش از حد (۴۲۹)، کمی بعد تلاش کنید';
    // v8.33: ۴۲۲ یعنی پارامتر ورودی نامعتبر است — جزئیات را از پاسخ بیرون می‌کشیم
    if ($c === 422) {
        $det = [];
        foreach ((array)($r['body']['detail'] ?? []) as $d) {
            if (!is_array($d)) continue;
            $loc = is_array($d['loc'] ?? null) ? end($d['loc']) : '';
            $m   = (string)($d['msg'] ?? '');
            if ($loc !== '' || $m !== '') $det[] = trim($loc . ' ' . $m);
        }
        return $what . ' — پارامتر نامعتبر (۴۲۲)'
             . ($det ? ': ' . mb_substr(implode(' · ', $det), 0, 160) : ' در ' . $endpoint);
    }
    if ($c === 0)   return $what . ' — ارتباط با باسلام برقرار نشد';
    return $what . ' — خطای HTTP ' . $c;
}

/* =====================================================================
 *  v8.32: وضعیت سفارش‌های غرفه‌دار و نرمال‌سازی پاسخ باسلام
 *  کدها از مستندات رسمی order_processing گرفته شده‌اند (پارامتر statuses).
 * ===================================================================== */

/** کد وضعیت سفارش → نام فارسی */
function bslParcelStatuses(): array {
    return [
        3739 => 'جدید',              3237 => 'در حال آماده‌سازی',
        3238 => 'ارسال شده',          5017 => 'اطلاعات ارسال نادرست',
        3572 => 'نرسیده',             3740 => 'ثبت مشکل شده',
        4633 => 'درخواست لغو مشتری',  5075 => 'درخواست توافق تأخیر',
        3195 => 'رضایت',              3233 => 'عودت وجه کامل',
        3067 => 'لغو',                6440 => 'درخواست لغو غرفه‌دار',
    ];
}

/** سفارش‌هایی که هنوز ارسال نشده‌اند و غرفه‌دار باید کاری برایشان بکند */
function bslUnsentStatuses(): array { return [3739, 3237]; }

/**
 * v8.32: نام مشتری را از ساختار درست بیرون می‌کشد.
 * طبق مستندات، customer سه کلید دارد: recipient / city / user — و
 * «name» مستقیم زیر customer وجود ندارد. نسخهٔ ۸.۳۱ اشتباه می‌خواند و
 * همیشه «نامشخص» می‌داد.
 */
function bslParcelCustomerName(array $o): string {
    $c = $o['order']['customer'] ?? ($o['customer'] ?? []);
    if (!is_array($c)) return 'نامشخص';
    foreach ([['recipient', 'name'], ['user', 'name']] as $p) {
        $v = trim((string)($c[$p[0]][$p[1]] ?? ''));
        if ($v !== '') return $v;
    }
    $v = trim((string)($c['name'] ?? ''));
    return $v !== '' ? $v : 'نامشخص';
}

/** یک ردیف vendor-parcels را به ساختار ساده و یک‌دست تبدیل می‌کند */
function bslNormalizeParcel(array $o): array {
    $stId  = (int)($o['status']['id'] ?? 0);
    $names = bslParcelStatuses();
    $stTxt = trim((string)($o['status']['title'] ?? ''));
    if ($stTxt === '') $stTxt = $names[$stId] ?? '—';
    $items = [];
    foreach (($o['items'] ?? []) as $it) {
        if (!is_array($it)) continue;
        $items[] = ['title' => (string)($it['title'] ?? ''), 'qty' => (int)($it['quantity'] ?? 1)];
    }
    return [
        'parcel_id'   => (int)($o['id'] ?? 0),
        'order_id'    => (int)($o['order']['id'] ?? 0),
        'customer'    => bslParcelCustomerName($o),
        'amount'      => (int)($o['total_items_price'] ?? 0),
        'status_id'   => $stId,
        'status'      => $stTxt,
        'unsent'      => in_array($stId, bslUnsentStatuses(), true),
        'created_at'  => (string)($o['created_at'] ?? ''),
        'send_before' => (string)($o['estimate_send_at'] ?? ''),
        'items'       => $items,
        'items_count' => count($items),
    ];
}

/**
 * v8.32: یک ردیف chats را نرمال می‌کند.
 * طبق مستندات، متن پیام زیر last_message.content.text است نه
 * last_message.text — نسخهٔ ۸.۳۱ اشتباه می‌خواند و همیشه «...» می‌فرستاد.
 */
function bslNormalizeChat(array $c): array {
    $lm = is_array($c['last_message'] ?? null) ? $c['last_message'] : [];
    $txt = '';
    foreach ([$lm['content']['text'] ?? null, $lm['text'] ?? null] as $cand) {
        if (is_string($cand) && trim($cand) !== '') { $txt = trim($cand); break; }
    }
    $ct = $c['contact'] ?? [];
    $who = '';
    if (is_array($ct)) {
        foreach (['name', 'title', 'username', 'hash_id'] as $k) {
            $v = trim((string)($ct[$k] ?? ''));
            if ($v !== '') { $who = $v; break; }
        }
    } elseif (is_string($ct)) { $who = trim($ct); }
    if ($who === '') $who = trim((string)($lm['sender']['name'] ?? ''));
    if ($who === '') $who = 'مشتری';
    $type = (string)($lm['message_type'] ?? '');
    if ($txt === '') $txt = $type !== '' && $type !== 'text' ? '[' . $type . ']' : '—';
    return [
        'chat_id'    => (int)($c['id'] ?? 0),
        'who'        => $who,
        'text'       => $txt,
        'unseen'     => (int)($c['unseen_message_count'] ?? 0),
        'updated_at' => (string)($c['updated_at'] ?? ($c['created_at'] ?? '')),
        'chat_type'  => (string)($c['chat_type'] ?? ''),
        'sender'     => trim((string)($lm['sender']['name'] ?? '')),
    ];
}

/** متن پیام‌رسان برای یک سفارش */
function bslParcelMsg(array $n, string $head = '🛒 سفارش باسلام'): string {
    $s = $head . "\nشماره: #" . ($n['order_id'] ?: $n['parcel_id'])
       . "\nمشتری: " . $n['customer']
       . "\nمبلغ: " . number_format($n['amount']) . ' تومان'
       . "\nوضعیت: " . $n['status'];
    if (!empty($n['items'])) {
        $lines = [];
        foreach (array_slice($n['items'], 0, 3) as $it) {
            $lines[] = '• ' . mb_substr($it['title'], 0, 45) . ' ×' . $it['qty'];
        }
        $more = count($n['items']) - count($lines);
        if ($more > 0) $lines[] = '• و ' . $more . ' قلم دیگر';
        $s .= "\n" . implode("\n", $lines);
    }
    return $s;
}

/**
 * v8.33: متن پیام‌های خوانده‌نشدهٔ یک گفتگو را می‌گیرد.
 * فقط پیام‌های طرف مقابل برگردانده می‌شود، به ترتیب قدیم به جدید،
 * تا در پیام‌رسان همان چیزی دیده شود که مشتری نوشته است.
 */
function bslMyUserId(string $tk): int {
    static $cache = [];
    $k = substr(md5($tk), 0, 12);
    if (isset($cache[$k])) return $cache[$k];
    $r = bslReq($tk, 'GET', 'users/me');
    $id = 0;
    if (!empty($r['ok'])) $id = (int)($r['body']['id'] ?? ($r['body']['user_id'] ?? 0));
    return $cache[$k] = $id;
}

function bslFetchChatMessages(string $tk, int $chatId, int $limit = 10, int $myUserId = -1): array {
    if ($chatId <= 0) return [];
    // v8.33: پیش‌فرض یعنی «خودت پیدا کن» تا پاسخ‌های خود غرفه‌دار فیلتر شوند
    if ($myUserId < 0) $myUserId = bslMyUserId($tk);
    $lim = max(1, min(50, $limit));
    $r = bslReq($tk, 'GET', 'chats/' . $chatId . '/messages?limit=' . $lim . '&order=desc');
    if (!$r['ok']) return [];
    $rows = $r['body']['data']['messages'] ?? ($r['body']['data'] ?? []);
    if (!is_array($rows)) return [];
    $out = [];
    foreach ($rows as $m) {
        if (!is_array($m)) continue;
        $sid = (int)($m['sender']['id'] ?? 0);
        if ($myUserId > 0 && $sid === $myUserId) continue;   // پیام‌های خودمان را نشان نده
        $txt = $m['content']['text'] ?? null;
        if (!is_string($txt) || trim($txt) === '') {
            $mt = (string)($m['message_type'] ?? '');
            $txt = $mt !== '' && $mt !== 'text' ? '[' . $mt . ']' : '';
        }
        $txt = trim((string)$txt);
        if ($txt === '') continue;
        $out[] = ['text' => $txt, 'at' => (string)($m['created_at'] ?? ''),
                  'sender' => trim((string)($m['sender']['name'] ?? ''))];
    }
    return array_reverse($out);   // قدیمی‌ترین اول، مثل خود گفتگو
}

/**
 * متن پیام‌رسان برای یک گفتگو.
 * v8.33: اگر متن پیام‌ها داده شود، همه را می‌فرستد نه فقط آخری.
 */
function bslChatMsg(array $n, string $head = '💬 پیام مشتری باسلام', array $msgs = []): string {
    $s = $head . "\nمشتری: " . $n['who']
       . ($n['unseen'] > 0 ? ' (' . $n['unseen'] . ' خوانده‌نشده)' : '');
    if ($msgs) {
        $s .= "\n━━━━━━━━━━";
        $budget = 3000;   // سقف امن برای بله/روبیکا
        foreach ($msgs as $m) {
            $line = "\n▸ " . mb_substr($m['text'], 0, 700);
            if (mb_strlen($line) > $budget) { $s .= "\n… (بقیه در باسلام)"; break; }
            $s .= $line; $budget -= mb_strlen($line);
        }
        return $s;
    }
    return $s . "\nپیام: " . mb_substr($n['text'], 0, 700);
}

/* =====================================================================
 *  v8.64: پاسخ خودکار به پیام مشتریان باسلام
 *
 *  هر قاعده یک «محرک» دارد (چند کلمه یا عبارت) و یک «پاسخ». وقتی پیام
 *  خوانده‌نشدهٔ مشتری با یکی از محرک‌ها بخورد، همان پاسخ برایش فرستاده
 *  می‌شود. مهم‌ترین تصمیم‌های طراحی:
 *
 *   • تأخیر ادب (grace) — پیش‌فرض چند دقیقه صبر می‌کند تا اگر خودِ
 *     غرفه‌دار جواب داد، ربات وسط حرف نپرد. با ۰ دقیقه فوری جواب می‌دهد.
 *   • هر گفتگو در یک بازهٔ زمانی فقط یک بار پاسخ خودکار می‌گیرد، و هر
 *     قاعده هم سقف روزانه دارد — تا حلقهٔ پاسخ‌به‌پاسخ راه نیفتد.
 *   • ساعت کاری — می‌شود گفت فقط بیرون ساعت کاری جواب بده (وقتی آدم
 *     نیست)، یا همیشه.
 *   • قاعدهٔ «پیش‌فرض» (بدون محرک) برای وقتی هیچ‌کدام نخورد.
 *   • حالت آزمایشی: هیچ پیامی فرستاده نمی‌شود، فقط می‌گوید چه می‌کرد.
 *
 *  ⚠️ تنها فرستندهٔ واقعی bslSendChatMessage است و فقط از یک نقطه صدا
 *  زده می‌شود، تا «پیش‌نمایش» هیچ‌وقت به‌اشتباه ارسال نکند.
 * ===================================================================== */

/** متن را برای تطبیق ساده می‌کند: بدون اعراب، بدون ی/ک عربی، بدون علائم */
function arNormText(string $t): string {
    $t = persianToEnglish($t);
    // ي ك عربی → ی ک فارسی، حذف اعراب و نیم‌فاصله
    $t = str_replace(['ي', 'ك', 'ة', 'ۀ', 'أ', 'إ', 'آ', 'ؤ'],
                     ['ی', 'ک', 'ه', 'ه', 'ا', 'ا', 'ا', 'و'], $t);
    $t = preg_replace('~[\x{064B}-\x{065F}\x{0670}\x{200c}\x{200f}\x{200e}]~u', '', $t);
    $t = preg_replace('~[^\p{L}\p{N}\s]~u', ' ', $t);
    $t = preg_replace('~\s+~u', ' ', $t);
    return trim(mb_strtolower($t, 'UTF-8'));
}

/** قواعد پیش‌فرض — فقط وقتی هنوز چیزی ذخیره نشده */
function arDefaultRules(): array {
    return [
        ['id' => 'greet', 'on' => true, 'match' => 'contains',
         'triggers' => "سلام\nدرود\nوقت بخیر\nروز بخیر",
         'reply' => 'سلام و وقت بخیر 🌷 در خدمتم، بفرمایید.', 'priority' => 10, 'daily_max' => 100],
        ['id' => 'thanks', 'on' => true, 'match' => 'contains',
         'triggers' => "ممنون\nمرسی\nسپاس\nتشکر\nلطف کردید\nدمت گرم",
         'reply' => 'خواهش می‌کنم 🙏 خوشحالم که راضی بودید.', 'priority' => 10, 'daily_max' => 100],
        ['id' => 'price', 'on' => false, 'match' => 'contains',
         'triggers' => "قیمت\nچند\nهزینه\nتخفیف",
         'reply' => 'قیمت همان است که روی صفحهٔ محصول نوشته شده. اگر محصول خاصی مدنظرتان است، لینکش را بفرستید.',
         'priority' => 20, 'daily_max' => 50],
        ['id' => 'send', 'on' => false, 'match' => 'contains',
         'triggers' => "ارسال\nپست\nکی می‌رسه\nچند روزه\nتیپاکس",
         'reply' => 'سفارش‌ها معمولاً ۱ تا ۳ روز کاری بعد از ثبت ارسال می‌شوند و کد رهگیری برایتان می‌آید.',
         'priority' => 20, 'daily_max' => 50],
        ['id' => 'bye', 'on' => false, 'match' => 'contains',
         'triggers' => "خداحافظ\nخدانگهدار\nفعلا",
         'reply' => 'خدانگهدار 🌹 هر وقت سؤالی داشتید در خدمتم.', 'priority' => 30, 'daily_max' => 100],
        ['id' => 'fallback', 'on' => false, 'match' => 'always',
         'triggers' => '',
         'reply' => 'پیام شما رسید 🙏 در اولین فرصت پاسخ می‌دهم.', 'priority' => 99, 'daily_max' => 30],
    ];
}

/** تنظیمات پاسخ خودکار با پیش‌فرض‌ها */
function arCfg(?array $cn = null): array {
    if ($cn === null) $cn = loadConnections();
    $a = (array)($cn['autoreply'] ?? []);
    return [
        'enabled'      => !empty($a['enabled']),
        'grace_min'    => max(0, min(1440, (int)($a['grace_min'] ?? 10))),
        'per_chat_min' => max(0, min(10080, (int)($a['per_chat_min'] ?? 180))),
        'max_per_run'  => max(1, min(50, (int)($a['max_per_run'] ?? 5))),
        'only_offhours'=> !empty($a['only_offhours']),
        'work_from'    => max(0, min(23, (int)($a['work_from'] ?? 9))),
        'work_to'      => max(0, min(23, (int)($a['work_to'] ?? 21))),
        'sign'         => trim((string)($a['sign'] ?? '')),
        'notify'       => !empty($a['notify']),
        'scan_limit'   => max(5, min(50, (int)($a['scan_limit'] ?? 20))),
        // v9.33: حالت جایگزین وقتی قاعده‌ای نخورد.
        // سازگاری با نسخهٔ قبل: اگر fallback تنظیم نشده ولی ai_reply روشن بود،
        // یعنی کاربر قبلاً «پاسخ با هوش مصنوعی» را انتخاب کرده بود.
        'fallback'     => (function () use ($a) {
            $f = (string)($a['fallback'] ?? '');
            if (in_array($f, ['none','premade','ai'], true)) return $f;
            return !empty($a['ai_reply']) ? 'ai' : 'none';
        })(),
        'fallback_text'=> trim((string)($a['fallback_text'] ?? '')),
        // v9.37: پیام سیستمیِ هوش مصنوعی
        'ai_system_mode' => in_array((string)($a['ai_system_mode'] ?? 'default'), ['default','custom'], true) ? $a['ai_system_mode'] : 'default',
        'ai_system_text' => trim((string)($a['ai_system_text'] ?? '')),
        // v9.38: ترتیب اولویت پاسخ‌دهی بین قواعد آماده و هوش مصنوعی
        'reply_order'   => in_array((string)($a['reply_order'] ?? 'rules_first'), ['rules_first','ai_first','rules_only','ai_only'], true) ? $a['reply_order'] : 'rules_first',
    ];
}

function arLoadRules(): array {
    if (!is_file(AUTOREPLY_RULES_FILE)) return arDefaultRules();
    $d = json_decode((string)@file_get_contents(AUTOREPLY_RULES_FILE), true);
    if (!is_array($d) || !isset($d['rules']) || !is_array($d['rules'])) return arDefaultRules();
    return $d['rules'];
}

function arSaveRules(array $rules): bool {
    $clean = [];
    foreach ($rules as $r) {
        if (!is_array($r)) continue;
        $m = (string)($r['match'] ?? 'contains');
        if (!in_array($m, ['contains', 'exact', 'starts', 'regex', 'always'], true)) $m = 'contains';
        $id = preg_replace('~[^A-Za-z0-9_-]~', '', (string)($r['id'] ?? ''));
        if ($id === '') $id = 'r' . substr(md5(json_encode($r) . mt_rand()), 0, 8);
        $clean[] = [
            'id'        => $id,
            'on'        => !empty($r['on']),
            'match'     => $m,
            'triggers'  => trim((string)($r['triggers'] ?? '')),
            'reply'     => trim((string)($r['reply'] ?? '')),
            'priority'  => max(1, min(999, (int)($r['priority'] ?? 50))),
            'daily_max' => max(0, min(1000, (int)($r['daily_max'] ?? 50))),
        ];
    }
    return @file_put_contents(AUTOREPLY_RULES_FILE,
        json_encode(['rules' => $clean, 'saved_at' => time()], JSON_UNESCAPED_UNICODE),
        LOCK_EX) !== false;
}

function arLoadState(): array {
    if (!is_file(AUTOREPLY_STATE_FILE)) return ['chats' => [], 'daily' => [], 'day' => ''];
    $d = json_decode((string)@file_get_contents(AUTOREPLY_STATE_FILE), true);
    if (!is_array($d)) return ['chats' => [], 'daily' => [], 'day' => ''];
    $d['chats'] = is_array($d['chats'] ?? null) ? $d['chats'] : [];
    $d['daily'] = is_array($d['daily'] ?? null) ? $d['daily'] : [];
    return $d;
}

function arSaveState(array $st): void {
    // گفتگوهای قدیمی‌تر از ۳۰ روز لازم نیستند
    $cut = time() - 30 * 86400;
    foreach ($st['chats'] as $k => $v) {
        if ((int)($v['at'] ?? 0) < $cut) unset($st['chats'][$k]);
    }
    @file_put_contents(AUTOREPLY_STATE_FILE, json_encode($st, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/**
 * v9.21: تولید پاسخ با هوش مصنوعی (مدل فعال، با بک‌آپ مدل رایگان Bonsai).
 * وقتی هیچ قاعدهٔ دستی‌ای به پیام مشتری نمی‌خورد و «پاسخ هوش مصنوعی»
 * روشن باشد، یک پاسخ کوتاه و مؤدبانهٔ فارسی از ارائه‌دهندهٔ فعال می‌گیریم.
 * خروجی ['ok'=>bool, 'text'=>string, 'error'=>string]
 */
function arAiReplyText(string $text, ?int $timeoutSec = null): array {
    $text = trim((string)$text);
    if ($text === '') return ['ok' => false, 'text' => '', 'error' => 'پیام خالی'];
    // v9.37: پیام سیستمیِ هوش مصنوعی — پیش‌فرض یا سفارشی از تنظیمات
    $arCfg = arCfg();
    if ((string)($arCfg['ai_system_mode'] ?? 'default') === 'custom' && trim((string)($arCfg['ai_system_text'] ?? '')) !== '') {
        $system = trim((string)$arCfg['ai_system_text']);
    } else {
        $system = 'تو دستیار پاسخ‌گویی یک فروشگاه اینترنتی هستی و به پیام‌های مشتریان به زبان فارسی پاسخ می‌دهی. '
                . 'پاسخ‌ها باید کوتاه، مؤدبانه و حرفه‌ای باشند (حداکثر ۲-۳ جمله). '
                . 'اگر پاسخ سؤال را نمی‌دانی، بگو همکاران به‌زودی پاسخ می‌دهند. '
                . 'چیزی خارج از نقش پشتیبانی ننویس.';
    }
    $prompt = "مشتری این پیام را فرستاده:\n\"{$text}\"\n\n"
            . "با توجه به دستورالعمل‌ات، همین حالا پاسخ مناسب را بده.";
    $net = aiNetCfg();
    // v9.35: اگر مهلت داده شد (مثلاً برای دکمهٔ آزمایش که نباید کاربر را معطل
    // کند)، همان مهلتِ کوتاه روی همهٔ تلاش‌ها اعمال می‌شود تا حداکثر در
    // (timeout × روش‌ها) ثانیه جواب برگردد و دکمه هرگز «کار نمی‌کند» نشود.
    if ($timeoutSec !== null && $timeoutSec > 0) $net['timeout'] = max(5, min(30, (int)$timeoutSec));
    $r = aiActiveChat(['messages' => [
        ['role' => 'system', 'content' => $system],
        ['role' => 'user', 'content' => $prompt],
    ], 'temperature' => 0.5, 'max_tokens' => 160], $net);
    if (empty($r['ok'])) return ['ok' => false, 'text' => '', 'error' => mb_substr((string)($r['error'] ?? 'خطا'), 0, 120), 'model' => ''];
    $body = $r['body'] ?? [];
    $reply = trim((string)($body['choices'][0]['message']['content'] ?? ''));
    if ($reply === '') return ['ok' => false, 'text' => '', 'error' => 'پاسخ خالی از مدل', 'model' => ''];
    $reply = preg_replace('/\s+/u', ' ', $reply);
    $modelName = (string)($body['model'] ?? ($r['model'] ?? ($r['backup']['model'] ?? '')));
    return ['ok' => true, 'text' => mb_substr($reply, 0, 500), 'error' => '', 'model' => $modelName];
}

/** شمارندهٔ روزانهٔ هر قاعده — با عوض شدن روز صفر می‌شود */
function arDailyCount(array &$st, string $ruleId, int $now): int {
    $today = date('Y-m-d', $now);
    if (($st['day'] ?? '') !== $today) { $st['day'] = $today; $st['daily'] = []; }
    return (int)($st['daily'][$ruleId] ?? 0);
}

function arDailyBump(array &$st, string $ruleId, int $now): void {
    $today = date('Y-m-d', $now);
    if (($st['day'] ?? '') !== $today) { $st['day'] = $today; $st['daily'] = []; }
    $st['daily'][$ruleId] = (int)($st['daily'][$ruleId] ?? 0) + 1;
}

/** آیا این لحظه «بیرون ساعت کاری» است؟ */
function arIsOffHours(array $cfg, int $now): bool {
    $h = (int)date('G', $now);
    $f = $cfg['work_from']; $t = $cfg['work_to'];
    if ($f === $t) return false;                       // ۲۴ ساعته
    if ($f < $t)  return !($h >= $f && $h < $t);       // مثلاً ۹ تا ۲۱
    return !($h >= $f || $h < $t);                     // شیفت شب، مثلاً ۲۲ تا ۶
}

/** آیا متن با این قاعده می‌خورد؟ */
function arRuleMatches(array $rule, string $text): bool {
    $m = (string)($rule['match'] ?? 'contains');
    if ($m === 'always') return true;
    $norm = arNormText($text);
    if ($norm === '') return false;
    foreach (preg_split('~[\r\n|]+~u', (string)($rule['triggers'] ?? '')) as $trig) {
        $trig = trim((string)$trig);
        if ($trig === '') continue;
        if ($m === 'regex') {
            if (@preg_match('~' . str_replace('~', '\~', $trig) . '~ui', $text)) return true;
            continue;
        }
        $tn = arNormText($trig);
        if ($tn === '') continue;
        if ($m === 'exact'  && $norm === $tn) return true;
        if ($m === 'starts' && mb_strpos($norm, $tn) === 0) return true;
        if ($m === 'contains') {
            // مرز کلمه، تا «چند» داخل «چندین» بی‌خود نخورد
            if (preg_match('~(^|\s)' . preg_quote($tn, '~') . '(\s|$)~u', $norm)) return true;
            // عبارت‌های چندکلمه‌ای بدون مرز هم پذیرفته‌اند
            if (mb_strpos($tn, ' ') !== false && mb_strpos($norm, $tn) !== false) return true;
        }
    }
    return false;
}

/** اولین قاعده‌ای که می‌خورد، به ترتیب اولویت */
function arPickRule(array $rules, string $text): ?array {
    $on = array_values(array_filter($rules, fn($r) => !empty($r['on']) && trim((string)($r['reply'] ?? '')) !== ''));
    usort($on, fn($a, $b) => ((int)($a['priority'] ?? 50)) <=> ((int)($b['priority'] ?? 50)));
    foreach ($on as $r) if (arRuleMatches($r, $text)) return $r;
    return null;
}

/** ارسال واقعی یک پیام به گفتگوی باسلام */
function bslSendChatMessage(string $tk, int $chatId, string $text): array {
    if ($chatId <= 0 || trim($text) === '') return ['ok' => false, 'error' => 'ورودی نامعتبر'];
    // طبق openapi چت باسلام: content.text + message_type
    $body = ['content' => ['text' => mb_substr($text, 0, 3000)], 'message_type' => 'text'];
    $r = bslReq($tk, 'POST', 'chats/' . $chatId . '/messages', $body);
    return ['ok' => !empty($r['ok']), 'code' => (int)($r['code'] ?? 0),
            'error' => bslApiError($r, 'ارسال پیام ناموفق', 'chats/{id}/messages', 'customer.chat.write'),
            'body' => $r['body'] ?? null];
}

/** آخرین ۲۰ پاسخ خودکار، برای نمایش در رابط کاربری */
function arLogAdd(array $row): void {
    $log = [];
    if (is_file(AUTOREPLY_LOG_FILE)) {
        $d = json_decode((string)@file_get_contents(AUTOREPLY_LOG_FILE), true);
        if (is_array($d)) $log = $d;
    }
    $row['at'] = time();
    $log[] = $row;
    if (count($log) > 60) $log = array_slice($log, -60);
    @file_put_contents(AUTOREPLY_LOG_FILE, json_encode($log, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

function arLogRead(): array {
    if (!is_file(AUTOREPLY_LOG_FILE)) return [];
    $d = json_decode((string)@file_get_contents(AUTOREPLY_LOG_FILE), true);
    return is_array($d) ? array_reverse($d) : [];
}

/**
 * موتور پاسخ خودکار.
 *
 * $dry=true یعنی هیچ چیزی فرستاده و ذخیره نمی‌شود — فقط گزارش می‌دهد که
 * چه اتفاقی می‌افتاد. همان مسیر و همان تصمیم‌ها، فقط بدون ارسال.
 */
function autoReplyRun(array $cn, bool $dry = false, bool $ignoreGrace = false): array {
    $now = time();
    $cfg = arCfg($cn);
    $out = ['ok' => true, 'dry' => $dry, 'checked' => 0, 'replied' => 0, 'skipped' => 0,
            'failed' => 0, 'items' => [], 'at' => $now];

    if (!$cfg['enabled'] && !$dry) { $out['ok'] = false; $out['error'] = 'پاسخ خودکار خاموش است'; return $out; }
    $tk = (string)($cn['basalam']['token'] ?? '');
    if ($tk === '') { $out['ok'] = false; $out['error'] = 'توکن باسلام تنظیم نشده'; return $out; }

    $rules = arLoadRules();
    if (!array_filter($rules, fn($r) => !empty($r['on']))) {
        $out['ok'] = false; $out['error'] = 'هیچ قاعدهٔ فعالی وجود ندارد'; return $out;
    }
    if ($cfg['only_offhours'] && !arIsOffHours($cfg, $now)) {
        $out['skipped_all'] = 'داخل ساعت کاری — پاسخ خودکار فقط بیرون ساعت کاری فعال است';
        return $out;
    }

    $r = bslReq($tk, 'GET', 'chats?limit=' . $cfg['scan_limit'] . '&order_by=updated_at');
    if (empty($r['ok'])) {
        $out['ok'] = false;
        $out['error'] = bslApiError($r, 'دریافت گفتگوها ناموفق', 'chats', 'customer.chat.read');
        return $out;
    }
    $rows = $r['body']['data']['chats'] ?? ($r['body']['data'] ?? []);
    if (!is_array($rows)) $rows = [];

    $st = arLoadState();
    $myId = bslMyUserId($tk);

    foreach ($rows as $c) {
        if (!is_array($c)) continue;
        if ($out['replied'] >= $cfg['max_per_run']) break;
        $nc = bslNormalizeChat($c);
        $chatId = (int)$nc['chat_id'];
        if ($chatId <= 0) continue;
        $out['checked']++;
        $row = ['chat_id' => $chatId, 'who' => $nc['who'], 'text' => mb_substr($nc['text'], 0, 90)];

        // فقط گفتگویی که پیام خوانده‌نشده دارد
        if ((int)$nc['unseen'] <= 0) { $out['skipped']++; continue; }

        $lm = is_array($c['last_message'] ?? null) ? $c['last_message'] : [];
        // اگر آخرین پیام مال خودمان است یعنی جواب داده‌ایم
        if ($myId > 0 && (int)($lm['sender']['id'] ?? 0) === $myId) {
            $out['skipped']++; continue;
        }
        // فقط پیام متنی — عکس و فاکتور و سفارش را دست نمی‌زنیم
        $mt = (string)($lm['message_type'] ?? 'text');
        if ($mt !== '' && $mt !== 'text') {
            $row['skip'] = 'پیام متنی نیست (' . $mt . ')'; $out['items'][] = $row; $out['skipped']++; continue;
        }

        // تأخیر ادب — به ادمین فرصت بده خودش جواب دهد
        $msgAt = strtotime((string)($lm['created_at'] ?? ($nc['updated_at'] ?: ''))) ?: 0;
        if (!$ignoreGrace && $cfg['grace_min'] > 0 && $msgAt > 0
            && ($now - $msgAt) < $cfg['grace_min'] * 60) {
            $row['skip'] = 'هنوز در مهلت ' . $cfg['grace_min'] . ' دقیقه‌ای ادمین';
            $out['items'][] = $row; $out['skipped']++; continue;
        }

        // یک گفتگو در بازهٔ تعیین‌شده فقط یک پاسخ خودکار می‌گیرد
        $prev = $st['chats']['c' . $chatId] ?? null;
        if ($prev && $cfg['per_chat_min'] > 0
            && ($now - (int)($prev['at'] ?? 0)) < $cfg['per_chat_min'] * 60) {
            $row['skip'] = 'به‌تازگی پاسخ خودکار گرفته';
            $out['items'][] = $row; $out['skipped']++; continue;
        }
        // همان پیام قبلی، دوباره جواب نده
        $lastId = (int)($lm['id'] ?? 0);
        if ($prev && $lastId > 0 && (int)($prev['msg_id'] ?? 0) === $lastId) {
            $row['skip'] = 'برای همین پیام قبلاً پاسخ رفته';
            $out['items'][] = $row; $out['skipped']++; continue;
        }

        $text = (string)($lm['content']['text'] ?? $nc['text']);
        /* v9.38: ترتیب اولویت پاسخ‌دهی بین قواعد آماده و هوش مصنوعی.
           در تنظیمات می‌توان از بین این حالت‌ها انتخاب کرد:
             rules_first → اول قواعد؛ اگر هیچ قاعده‌ای نخورد هوش مصنوعی
             ai_first    → اول هوش مصنوعی؛ اگر خطا داد قواعد
             rules_only  → فقط قواعد آماده (هوش مصنوعی صدا زده نمی‌شود)
             ai_only     → فقط هوش مصنوعی (قواعد نادیده گرفته می‌شوند)
           پیش‌فرض rules_first است: «سلام» و سؤال‌های ساده را همان قواعدِ
           آماده جواب می‌دهند (سریع و مطمئن) و سؤال‌های پیچیده‌تر که هیچ
           قاعده‌ای به آن‌ها نمی‌خورد را هوش مصنوعی پاسخ می‌دهد. */
        $order = (string)($cfg['reply_order'] ?? 'rules_first');
        $aiMode = false;             // true = پاسخ از هوش مصنوعی
        $rid = ''; $dmax = 0;
        $reply = '';
        $aiError = '';
        $rule = null;

        if ($order === 'ai_first') {
            $aiRes = arAiReplyText($text);
            if (!empty($aiRes['ok'])) {
                $reply = $aiRes['text'];
                $rid = 'ai';
                $aiMode = true;
            } else {
                $aiError = (string)($aiRes['error'] ?? 'خطا');
                $rule = arPickRule($rules, $text);
                if ($rule !== null) {
                    $rid = (string)$rule['id'];
                    $dmax = (int)($rule['daily_max'] ?? 0);
                    $reply = (string)$rule['reply'];
                }
            }
        } elseif ($order === 'ai_only') {
            $aiRes = arAiReplyText($text);
            if (!empty($aiRes['ok'])) {
                $reply = $aiRes['text'];
                $rid = 'ai';
                $aiMode = true;
            } else {
                $aiError = (string)($aiRes['error'] ?? 'خطا');
            }
        } elseif ($order === 'rules_only') {
            $rule = arPickRule($rules, $text);
            if ($rule !== null) {
                $rid = (string)$rule['id'];
                $dmax = (int)($rule['daily_max'] ?? 0);
                $reply = (string)$rule['reply'];
            }
        } else { // rules_first (پیش‌فرض)
            $rule = arPickRule($rules, $text);
            if ($rule !== null) {
                $rid = (string)$rule['id'];
                $dmax = (int)($rule['daily_max'] ?? 0);
                $reply = (string)$rule['reply'];
            } else {
                $aiRes = arAiReplyText($text);
                if (!empty($aiRes['ok'])) {
                    $reply = $aiRes['text'];
                    $rid = 'ai';
                    $aiMode = true;
                } else {
                    $aiError = (string)($aiRes['error'] ?? 'خطا');
                }
            }
        }

        // تصمیم نهایی — اگر هیچ منبعی پاسخ نداد، این گفتگو رد می‌شود
        if ($reply === '') {
            if ($order === 'rules_only')      $row['skip'] = 'هیچ قاعده‌ای نخورد';
            elseif ($order === 'ai_only')     $row['skip'] = 'هوش مصنوعی پاسخ نداد';
            else                              $row['skip'] = 'هیچ قاعده‌ای نخورد و هوش مصنوعی هم پاسخ نداد';
            $out['items'][] = $row; $out['skipped']++;
            continue;
        }
        if (!$aiMode && $dmax > 0 && arDailyCount($st, $rid, $now) >= $dmax) {
            $row['skip'] = 'سقف روزانهٔ قاعدهٔ «' . $rid . '» پر شده';
            $out['items'][] = $row; $out['skipped']++; continue;
        }
        if ($cfg['sign'] !== '') $reply .= "\n" . $cfg['sign'];
        $row['rule'] = $rid;
        $row['reply'] = mb_substr($reply, 0, 160);
        if ($aiError !== '') $row['ai_error'] = $aiError;

        if ($dry) {
            $row['status'] = 'ارسال می‌شد';
            $out['items'][] = $row; $out['replied']++;
            continue;
        }

        $send = bslSendChatMessage($tk, $chatId, $reply);
        if (!empty($send['ok'])) {
            $out['replied']++;
            $row['status'] = '✅ ارسال شد';
            $st['chats']['c' . $chatId] = ['at' => $now, 'msg_id' => $lastId, 'rule' => $rid];
            if ($aiMode) {
                arLogAdd(['chat_id' => $chatId, 'who' => $nc['who'], 'rule' => 'ai',
                          'in' => mb_substr($text, 0, 120), 'out' => mb_substr($reply, 0, 160)]);
            } else {
                arDailyBump($st, $rid, $now);
                arLogAdd(['chat_id' => $chatId, 'who' => $nc['who'], 'rule' => $rid,
                          'in' => mb_substr($text, 0, 120), 'out' => mb_substr($reply, 0, 160)]);
            }
        } else {
            $out['failed']++;
            $row['status'] = '❌ ' . mb_substr((string)($send['error'] ?? 'خطا'), 0, 90);
        }
        $out['items'][] = $row;
        usleep(400000);
    }

    if (!$dry) { $st['last_run'] = $now; arSaveState($st); }
    return $out;
}

/** خلاصهٔ پاسخ‌های خودکار برای پیام‌رسان */
function arMsg(array $r): string {
    $m = "🤖 پاسخ خودکار به پیام مشتریان\n";
    if (!empty($r['dry'])) $m .= "(پیش‌نمایش — چیزی ارسال نشد)\n";
    $m .= "───────────────\n";
    $m .= 'بررسی‌شده: ' . (int)$r['checked'] . "\n";
    $m .= '✅ پاسخ داده شد: ' . (int)$r['replied'] . "\n";
    if ((int)$r['skipped'] > 0) $m .= '⏭ رد شد: ' . (int)$r['skipped'] . "\n";
    if ((int)$r['failed'] > 0)  $m .= '❌ ناموفق: ' . (int)$r['failed'] . "\n";
    foreach (array_slice($r['items'] ?? [], 0, 6) as $it) {
        if (empty($it['rule'])) continue;
        $m .= '• ' . ($it['who'] ?? '') . ' → «' . ($it['rule'] ?? '') . '»' . "\n";
    }
    return $m;
}

/**
 * بررسی سفارش‌های جدید.
 * $test=true یعنی حالت آزمایشی: وضعیت ذخیره نمی‌شود تا اجرای بعدی هم
 * همان نتیجه را بدهد، و اگر چیزی نبود یک پیام نمونه فرستاده می‌شود.
 */
function notifCheckOrders(array $cn, bool $test = false, bool $send = true): array {
    $tk = $cn['basalam']['token'] ?? ''; $vid = (int)($cn['basalam']['vendor_id'] ?? 0);
    $st = notifLoadState(); $since = (int)($st['last_order_check'] ?? 0);
    // v8.31: مسیر درست طبق مستندات رسمی — سفارش‌های غرفه‌دار
    $r = bslReq($tk, 'GET', 'vendor-parcels?items.vendor_ids=' . $vid . '&per_page=10');
    if (!$r['ok']) return ['ok' => false, 'code' => (int)($r['code'] ?? 0), 'found' => 0,
            'error' => bslApiError($r, 'دریافت سفارش‌ها ناموفق', 'vendor-parcels', 'vendor.parcel.read')];

    $rows = $r['body']['data'] ?? [];
    $now = time(); $cfg = notifRemindCfg($cn);

    // v8.38: امضا = وضعیت سفارش. «بی‌جواب» یعنی هنوز ارسال نشده،
    // پس تا وقتی غرفه‌دار کاری نکند یادآوری می‌شود.
    $norm = [];
    foreach ($rows as $o) {
        if (!is_array($o)) continue;
        $np = bslNormalizeParcel($o);
        if ($np['parcel_id'] <= 0) continue;
        $norm[] = ['np' => $np, 'key' => 'order:' . $np['parcel_id'],
                   'sig' => (string)$np['status_id'],
                   'ts' => strtotime($np['created_at'] ?: 'now') ?: $now,
                   'pending' => !empty($np['unsent'])];
    }

    if ($test) {
        $sentTo = [];
        $sample = $norm ? bslParcelMsg($norm[0]['np'], '🛒 سفارش جدید باسلام') : '';
        if ($send) {
            $msg = $sample ? ("🧪 تست سفارش‌ها\n" . $sample) : "🧪 تست سفارش‌ها\nهیچ سفارشی در ۱۰ مورد اخیر نبود، اما ارتباط برقرار است ✅";
            $sentTo = notifSend($cn, $msg);
        }
        return ['ok' => true, 'found' => count($norm), 'total_seen' => count($rows),
                'sent' => $sentTo, 'sample' => $sample];
    }

    notifSeedIfNeeded($st, 'orders', $norm, $since);

    $found = 0; $reminded = 0; $sentTo = []; $samples = [];
    foreach ($norm as $f) {
        $why = notifDecide($st, $f['key'], $f['sig'], $f['pending'], $cfg, $now);
        if ($why === '') continue;
        $n = (int)($st['items'][$f['key']]['n'] ?? 1);
        $base = $why === 'changed' ? '📦 تغییر وضعیت سفارش باسلام' : '🛒 سفارش جدید باسلام';
        $msg = bslParcelMsg($f['np'], notifHead($why, $base, $n - 1));
        $samples[] = $msg;
        if ($why === 'remind') $reminded++; else $found++;
        if ($send) $sentTo = notifSend($cn, $msg);
    }
    $st['last_order_check'] = $now;
    notifPrune($st, $now);
    notifSaveState($st);
    return ['ok' => true, 'found' => $found, 'reminded' => $reminded,
            'total_seen' => count($rows), 'sent' => $sentTo, 'sample' => $samples[0] ?? ''];
}

/** بررسی پیام‌های جدید مشتری */
function notifCheckChats(array $cn, bool $test = false, bool $send = true): array {
    $tk = $cn['basalam']['token'] ?? ''; $vid = (int)($cn['basalam']['vendor_id'] ?? 0);
    $st = notifLoadState(); $since = (int)($st['last_chat_check'] ?? 0);
    // v8.31: مسیر درست — گفتگوها زیر ریشه است، نه زیر vendors
    $r = bslReq($tk, 'GET', 'chats?limit=10&order_by=updated_at');
    if (!$r['ok']) return ['ok' => false, 'code' => (int)($r['code'] ?? 0), 'found' => 0,
            'error' => bslApiError($r, 'دریافت گفتگوها ناموفق', 'chats', 'customer.chat.read')];

    // v8.31: پاسخ chats به شکل data.chats است، نه data
    $rows = $r['body']['data']['chats'] ?? ($r['body']['data'] ?? []);
    $now = time(); $cfg = notifRemindCfg($cn);

    // v8.38: امضای هر گفتگو = شناسهٔ آخرین پیام + تعداد خوانده‌نشده.
    // «بی‌جواب» یعنی هنوز پیام خوانده‌نشده دارد.
    $norm = [];
    foreach ($rows as $c) {
        if (!is_array($c)) continue;
        $nc = bslNormalizeChat($c);
        if ($nc['chat_id'] <= 0) continue;
        $lastId = (int)($c['last_message']['id'] ?? 0);
        // v8.38: امضا فقط شناسهٔ آخرین پیام است. اگر تعداد خوانده‌نشده را هم
        // در امضا بیاوریم، جواب دادن مشتری (۲ → ۰) مثل «رویداد تازه» دیده
        // می‌شود و یک اعلان بی‌مورد می‌فرستد.
        $norm[] = ['nc' => $nc, 'key' => 'chat:' . $nc['chat_id'],
                   'sig' => (string)$lastId,
                   'ts' => strtotime($nc['updated_at'] ?: 'now') ?: $now,
                   'pending' => $nc['unseen'] > 0];
    }

    if ($test) {
        $sentTo = []; $sample = '';
        if ($norm) {
            $f = $norm[0];
            $body = $f['pending'] ? bslFetchChatMessages($tk, $f['nc']['chat_id'], min(10, $f['nc']['unseen'])) : [];
            $sample = bslChatMsg($f['nc'], '💬 پیام مشتری باسلام', $body);
        }
        if ($send) {
            $msg = $sample ? ("🧪 تست پیام‌ها\n" . $sample) : "🧪 تست پیام‌ها\nهیچ پیامی در ۱۰ مورد اخیر نبود، اما ارتباط برقرار است ✅";
            $sentTo = notifSend($cn, $msg);
        }
        return ['ok' => true, 'found' => count($norm), 'total_seen' => count($rows),
                'sent' => $sentTo, 'sample' => $sample];
    }

    notifSeedIfNeeded($st, 'chats', $norm, $since);

    $found = 0; $reminded = 0; $sentTo = []; $samples = [];
    foreach ($norm as $f) {
        $why = notifDecide($st, $f['key'], $f['sig'], $f['pending'], $cfg, $now);
        if ($why === '') continue;
        $n = (int)($st['items'][$f['key']]['n'] ?? 1);
        $body = $f['pending'] ? bslFetchChatMessages($tk, $f['nc']['chat_id'], min(10, $f['nc']['unseen'])) : [];
        $msg = bslChatMsg($f['nc'], notifHead($why, '💬 پیام مشتری باسلام', $n - 1), $body);
        $samples[] = $msg;
        if ($why === 'remind') $reminded++; else $found++;
        if ($send) $sentTo = notifSend($cn, $msg);
    }
    $st['last_chat_check'] = $now;
    notifPrune($st, $now);
    notifSaveState($st);
    return ['ok' => true, 'found' => $found, 'reminded' => $reminded,
            'total_seen' => count($rows), 'sent' => $sentTo, 'sample' => $samples[0] ?? ''];
}

/** بررسی تغییر وضعیت یا افزوده شدن محصول */
function notifCheckProducts(array $cn, bool $test = false, bool $send = true): array {
    $tk = $cn['basalam']['token'] ?? ''; $vid = (int)($cn['basalam']['vendor_id'] ?? 0);
    $st = notifLoadState(); $since = (int)($st['last_product_check'] ?? 0);
    $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?per_page=10&statuses=2976&statuses=3790&statuses=3567');
    if (!$r['ok']) return ['ok' => false, 'code' => (int)($r['code'] ?? 0), 'found' => 0,
            'error' => bslApiError($r, 'دریافت محصولات ناموفق', 'vendors/{id}/products', 'vendor.product.read')];

    $rows = $r['body']['data'] ?? [];
    $now = time(); $cfg = notifRemindCfg($cn);

    // v8.38: امضا = وضعیت محصول. «تأیید نشده» نیاز به اقدام دارد، پس
    // تا وقتی درست نشود یادآوری می‌شود؛ محصول فعال یادآوری ندارد.
    $norm = [];
    foreach ($rows as $p) {
        if (!is_array($p)) continue;
        $pid = (int)($p['id'] ?? 0);
        if ($pid <= 0) continue;
        $ps = $p['status'] ?? [];
        $val = is_array($ps) ? (int)($ps['value'] ?? 0) : (int)$ps;
        $title = mb_substr((string)($p['title'] ?? ($p['name'] ?? 'محصول')), 0, 60);
        if ($val === 3567)      { $txt = "📋 تغییر وضعیت محصول باسلام\nمحصول: " . $title . "\nوضعیت جدید: تأیید نشده ❌"; $pend = true; }
        elseif ($val === 4184)  { $txt = "📋 تغییر وضعیت محصول باسلام\nمحصول: " . $title . "\nوضعیت جدید: بایگانی 🗑️"; $pend = false; }
        elseif ($val === 2976)  { $txt = "➕ محصول جدید باسلام\nمحصول: " . $title . "\nوضعیت: فعال ✅"; $pend = false; }
        else continue;
        $norm[] = ['key' => 'prod:' . $pid, 'sig' => (string)$val, 'text' => $txt,
                   'ts' => strtotime($p['created_at'] ?? 'now') ?: $now, 'pending' => $pend];
    }

    if ($test) {
        $sentTo = [];
        $sample = $norm ? $norm[0]['text'] : '';
        if ($send) {
            $msg = $sample ? ("🧪 تست محصولات\n" . $sample) : "🧪 تست محصولات\nتغییری در ۱۰ محصول اخیر نبود، اما ارتباط برقرار است ✅";
            $sentTo = notifSend($cn, $msg);
        }
        return ['ok' => true, 'found' => count($norm), 'total_seen' => count($rows),
                'sent' => $sentTo, 'sample' => $sample];
    }

    notifSeedIfNeeded($st, 'products', $norm, $since);

    $found = 0; $reminded = 0; $sentTo = []; $samples = [];
    foreach ($norm as $f) {
        $why = notifDecide($st, $f['key'], $f['sig'], $f['pending'], $cfg, $now);
        if ($why === '') continue;
        $n = (int)($st['items'][$f['key']]['n'] ?? 1);
        $msg = $why === 'remind'
             ? notifHead($why, '', $n - 1) . "\n" . $f['text']
             : $f['text'];
        $samples[] = $msg;
        if ($why === 'remind') $reminded++; else $found++;
        if ($send) $sentTo = notifSend($cn, $msg);
    }
    $st['last_product_check'] = $now;
    notifPrune($st, $now);
    notifSaveState($st);
    return ['ok' => true, 'found' => $found, 'reminded' => $reminded,
            'total_seen' => count($rows), 'sent' => $sentTo, 'sample' => $samples[0] ?? ''];
}

/* =====================================================================
 *  v8.33: نگهبان صف — تشخیص گیر کردن ارسال و ادامهٔ خودکار
 *
 *  چرا امن است: قفل‌های bsl_backend/woo_backend با flock گرفته می‌شوند.
 *  اگر پردازه واقعاً زنده باشد قفل در اختیار اوست و درخواست تازه فوراً
 *  «already running» می‌گیرد و برمی‌گردد. اگر پردازه مرده باشد، سیستم‌عامل
 *  قفل را آزاد کرده و کار ادامه پیدا می‌کند. پس نگهبان هیچ‌وقت دو پردازش
 *  موازی نمی‌سازد و روی سرعت ارسال اثری ندارد — فقط یک درخواست HTTP سبک
 *  است که وقتی چیزی گیر نکرده باشد اصلاً فرستاده نمی‌شود.
 * ===================================================================== */

/** آدرس خود اسکریپت برای فراخوانی داخلی */
function selfBaseUrl(): string {
    $host = $_SERVER['HTTP_HOST'] ?? '';
    if ($host === '') return '';
    $https = isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off';
    return ($https ? 'https' : 'http') . '://' . $host . ($_SERVER['SCRIPT_NAME'] ?? '');
}

/** یک فراخوانی «شلیک کن و فراموش کن» به خود اسکریپت */
function fireAndForget(string $qs, int $timeoutMs = 1200, ?array $post = null): bool {
    $base = selfBaseUrl();
    if ($base === '') return false;
    $ch = curl_init($base . '?' . ltrim($qs, '?'));
    $opt = [CURLOPT_RETURNTRANSFER => 1, CURLOPT_NOSIGNAL => 1,
        CURLOPT_TIMEOUT_MS => $timeoutMs, CURLOPT_CONNECTTIMEOUT => 3,
        CURLOPT_SSL_VERIFYPEER => 0, CURLOPT_SSL_VERIFYHOST => 0];
    // v8.45: پردازنده‌ها پارامترها را از POST می‌خوانند. نگهبان قبلاً فقط
    // GET می‌فرستاد، پس from_file و queue_id و start_index خالی می‌ماندند
    // و بازیابی از محصول اول شروع می‌شد — کار تکراری و گاهی ارسال دوباره.
    if ($post !== null) {
        $opt[CURLOPT_POST] = true;
        $opt[CURLOPT_POSTFIELDS] = http_build_query($post);
    }
    curl_setopt_array($ch, $opt);
    curl_exec($ch);
    $err = curl_errno($ch);
    curl_close($ch);
    // مهلت تمام‌شدن یعنی کار شروع شده و پس‌زمینه ادامه می‌دهد — خطا نیست
    return $err === 0 || $err === CURLE_OPERATION_TIMEDOUT;
}

/**
 * بررسی می‌کند صف ارسال گیر کرده یا نه.
 * گیر کرده = ردیفی در حال اجراست ولی از آخرین پیشرفتش بیش از
 * $staleAfter ثانیه گذشته، یا ردیفی در انتظار مانده و هیچ‌کس نمی‌بردش.
 */
function queueStallCheck(string $which, int $staleAfter = 300): array {
    $isBsl = $which === 'bsl';
    $qFile = $isBsl ? BSL_QUEUE_FILE : WOO_QUEUE_FILE;
    $pFile = $isBsl ? BSL_PROGRESS_FILE : WOO_PROGRESS_FILE;
    $lock  = __DIR__ . ($isBsl ? '/bsl_backend.lock' : '/woo_backend.lock');

    $q = json_decode((string)@file_get_contents($qFile), true);
    $entries = is_array($q['entries'] ?? null) ? $q['entries'] : [];
    $running = null; $waiting = null;
    foreach ($entries as $e) {
        $st = $e['status'] ?? '';
        if ($st === 'running' && $running === null) $running = $e;
        if ($st === 'waiting' && $waiting === null) $waiting = $e;
    }
    if ($running === null && $waiting === null) {
        return ['stalled' => false, 'reason' => 'صفی در جریان نیست'];
    }

    // v8.45: ردیفی که کارش تمام شده ولی وضعیتش «running» مانده، جلوی
    // شروع ردیف بعدی را می‌گیرد. اول این را ببند تا صف راه بیفتد.
    if ($running !== null) {
        $pg = readProgress($pFile);
        $sameRow = ((string)($pg['queue_id'] ?? '') === (string)($running['id'] ?? ''))
                   || ((string)($pg['queue_id'] ?? '') === '');
        $tot = (int)($running['total'] ?? 0);
        $cur = max((int)($running['current'] ?? 0), (int)($pg['current'] ?? 0));
        $finished = !empty($pg['done']) || ($tot > 0 && $cur >= $tot);
        if ($sameRow && $finished) {
            foreach ($entries as $i => $e) {
                if (($e['id'] ?? '') === ($running['id'] ?? '')) {
                    $entries[$i]['status'] = 'done';
                    $entries[$i]['done_at'] = time();
                    $entries[$i]['current'] = $cur;
                    break;
                }
            }
            $q['entries'] = $entries;
            @file_put_contents($qFile, json_encode($q, JSON_UNESCAPED_UNICODE), LOCK_EX);
            $running = null;
            foreach ($entries as $e) {
                if (($e['status'] ?? '') === 'waiting') { $waiting = $e; break; }
            }
            if ($waiting === null) {
                return ['stalled' => false, 'reason' => 'ردیف تمام‌شده بسته شد'];
            }
        }
    }

    $prog = readProgress($pFile);
    $now  = time();
    // پردازهٔ زنده قفل را در دست دارد؛ اگر قفل باز شود یعنی پردازه رفته
    $lockFresh = false;
    if (is_file($lock)) {
        $fp = @fopen($lock, 'c');
        if ($fp) {
            $lockFresh = !@flock($fp, LOCK_EX | LOCK_NB);   // نشد ⇒ کسی گرفته ⇒ زنده
            if (!$lockFresh) @flock($fp, LOCK_UN);
            @fclose($fp);
        }
    }

    if ($running !== null) {
        $ts = (int)($prog['last_progress_ts'] ?? 0);
        if ($ts <= 0) $ts = (int)($running['started_at'] ?? 0);
        $idle = $ts > 0 ? ($now - $ts) : PHP_INT_MAX;
        if ($lockFresh && $idle <= $staleAfter) {
            return ['stalled' => false, 'reason' => 'در حال اجرا', 'idle' => $idle];
        }
        if ($idle > $staleAfter) {
            return ['stalled' => true, 'kind' => 'running', 'idle' => $idle,
                'queue_id' => $running['id'] ?? '', 'lock_held' => $lockFresh,
                'current' => (int)($running['current'] ?? 0),
                'total' => (int)($running['total'] ?? 0)];
        }
        return ['stalled' => false, 'reason' => 'تازه شروع شده', 'idle' => $idle];
    }

    // فقط ردیف در انتظار — اگر پردازنده‌ای زنده نیست باید راهش انداخت
    if ($lockFresh) return ['stalled' => false, 'reason' => 'پردازنده فعال است'];
    return ['stalled' => true, 'kind' => 'waiting', 'idle' => 0,
        'queue_id' => $waiting['id'] ?? '', 'lock_held' => false,
        'current' => 0, 'total' => (int)($waiting['total'] ?? 0)];
}

/** اگر صف گیر کرده باشد، پردازش را دوباره راه می‌اندازد */
/**
 * v8.45: بازیابی صف گیرکرده — با ادامه از همان جایی که مانده بود.
 *
 * قبلاً فقط یک GET خالی فرستاده می‌شد. چون پردازنده پارامترها را از POST
 * می‌خواند، هر بازیابی از محصول اول شروع می‌کرد؛ یعنی صدها محصول دوباره
 * بررسی می‌شدند و در بدترین حالت دوباره ارسال. حالا شمارهٔ محصول جاری،
 * شناسهٔ صف و پرچم from_file فرستاده می‌شوند.
 */
function queueStallRecover(string $which, int $staleAfter = 300, bool $dryRun = false): array {
    $chk = queueStallCheck($which, $staleAfter);
    $chk['which'] = $which;
    if (empty($chk['stalled']) || $dryRun) { $chk['resumed'] = false; return $chk; }

    $qid   = (string)($chk['queue_id'] ?? '');
    $start = max(0, (int)($chk['current'] ?? 0));

    // قفلِ رهاشدهٔ پردازهٔ مرده را پاک کن، وگرنه تلاش بعدی «در حال اجرا» می‌بیند
    if (empty($chk['lock_held'])) {
        @unlink(__DIR__ . ($which === 'bsl' ? '/bsl_backend.lock' : '/woo_backend.lock'));
    }
    // سیگنال توقفِ جامانده هم باید برود، وگرنه ادامه بلافاصله متوقف می‌شود
    if ($which === 'bsl' && defined('BSL_STOP_FILE') && is_file(BSL_STOP_FILE)) @unlink(BSL_STOP_FILE);

    $action = $which === 'bsl' ? 'bsl_backend' : 'woo_backend';
    $post = ['from_file' => '1', 'start_index' => (string)$start];
    if ($qid !== '') $post['queue_id'] = $qid;

    $chk['resume_from'] = $start;
    $chk['resumed'] = fireAndForget('action=' . $action, 1500, $post);
    if ($chk['resumed']) {
        // شمارندهٔ تلاش را نگه دار تا اگر بارها گیر کرد بتوان تشخیص داد
        $st = notifLoadState();
        $k  = 'stall_' . $which;
        $st[$k] = ['at' => time(), 'n' => (int)($st[$k]['n'] ?? 0) + 1,
                   'queue_id' => $qid, 'from' => $start];
        notifSaveState($st);
        $chk['attempt'] = $st[$k]['n'];
    }
    return $chk;
}

/* =====================================================================
 *  v8.34: بازنشستگی خودکار محصولاتی که از مبدأ رفته‌اند
 *
 *  وقتی محصولی در سایت مبدأ ناموجود یا حذف می‌شود، تا امروز فقط گزارش
 *  می‌شد و روی ووکامرس/باسلام دست‌نخورده می‌ماند. حالا می‌توان خودکار
 *  آن را از دسترس خارج کرد.
 *
 *  پیش‌فرض عمداً «پیش‌نویس/غیرفعال» است نه حذف، چون برگشت‌پذیر است و
 *  نظرات و تاریخچهٔ محصول از بین نمی‌رود.
 *
 *  ⚠️ محافظ ایمنی: اگر سایت مبدأ یک بار خراب شود و چیزی برنگرداند،
 *  همهٔ محصولات «حذف‌شده» به نظر می‌رسند. برای همین اگر نسبت حذف‌ها از
 *  یک آستانه بگذرد، هیچ کاری انجام نمی‌شود و فقط هشدار می‌رود.
 * ===================================================================== */

/** حالت‌های مجاز بازنشستگی */
function retireModes(): array {
    return ['off' => 'کاری نکن', 'draft' => 'پیش‌نویس/غیرفعال', 'outofstock' => 'ناموجود کن', 'delete' => 'حذف کامل'];
}

/**
 * تصمیم می‌گیرد که آیا بازنشستگی مجاز است یا محافظ باید جلویش را بگیرد.
 * $removed تعداد رفته‌ها، $total کل محصولات دیده‌شده در این اجرا.
 */
function retireGuard(int $removed, int $total, array $cfg): array {
    $maxPct   = (float)($cfg['retire_max_pct'] ?? 30);   // درصد
    $maxCount = (int)($cfg['retire_max_count'] ?? 50);   // سقف مطلق
    if ($removed <= 0) return ['allow' => false, 'reason' => 'موردی برای بازنشستگی نیست'];
    // اگر استخراج تقریباً هیچ محصولی نداده، یعنی مبدأ خراب بوده — دست نزن
    if ($total <= 0) return ['allow' => false, 'blocked' => true,
        'reason' => 'استخراج هیچ محصولی برنگرداند — احتمال خرابی سایت مبدأ'];
    $pct = $total > 0 ? ($removed / max(1, $total + $removed)) * 100 : 100;
    if ($pct > $maxPct) return ['allow' => false, 'blocked' => true, 'pct' => round($pct, 1),
        'reason' => 'نسبت حذف‌ها (' . round($pct, 1) . '٪) از آستانهٔ ' . $maxPct . '٪ بیشتر است'];
    if ($removed > $maxCount) return ['allow' => false, 'blocked' => true, 'pct' => round($pct, 1),
        'reason' => 'تعداد حذف‌ها (' . $removed . ') از سقف ' . $maxCount . ' بیشتر است'];
    return ['allow' => true, 'pct' => round($pct, 1)];
}

/** یک محصول ووکامرس را با عنوان پیدا می‌کند */
/* =====================================================================
 *  v8.62: ویرایش مستقیم محصولات روی مقصد (ووکامرس و باسلام)
 *
 *  ⚠️ نکتهٔ مهم دربارهٔ «حذف» در باسلام:
 *  در OpenAPI رسمی باسلام هیچ متد DELETE برای محصول وجود ندارد؛ فقط
 *  PATCH /v1/products/{id} و PATCH /v1/vendors/{vid}/products/batch-updates.
 *  یعنی حذف همیشگی ذاتاً در API نیست. کاری که واقعاً می‌شود کرد، عوض
 *  کردن وضعیت است:
 *      2976 فعال · 3790 غیرفعال · 4184 بایگانی
 *  «بایگانی» نزدیک‌ترین چیز به حذف است و محصول را از غرفه برمی‌دارد.
 *  فراخوانی‌های DELETE قبلی روی اندپوینتی می‌رفتند که وجود ندارد و
 *  فقط ۴۰۴ می‌گرفتند — یعنی حذف باسلام هیچ‌وقت کار نمی‌کرده است.
 * ===================================================================== */

/** وضعیت‌های محصول باسلام */
function bslStatusMap(): array {
    return [2976 => 'فعال', 3567 => 'تأیید نشده', 3568 => 'در انتظار',
            3790 => 'غیرفعال', 4184 => 'بایگانی'];
}

/**
 * یک محصول باسلام را ویرایش می‌کند.
 * $fields می‌تواند شامل primary_price، stock، status، name، description،
 * brief، preparation_days، weight و ... باشد.
 */
function bslEditProduct(string $tk, int $vid, int $pid, array $fields): array {
    if ($pid <= 0 || empty($fields)) return ['ok' => false, 'code' => 0, 'error' => 'ورودی ناقص'];
    $r = bslReq($tk, 'PATCH', 'products/' . $pid, $fields);
    // بعضی نصب‌ها فقط مسیر زیر غرفه را قبول می‌کنند
    if ((int)($r['code'] ?? 0) === 404 && $vid > 0) {
        $r = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $pid, $fields);
    }
    return $r;
}

/**
 * «حذف» محصول باسلام = بایگانی کردن (4184).
 * چون API حذف واقعی ندارد، این تنها راه برداشتن محصول از غرفه است.
 */
function bslArchiveProduct(string $tk, int $vid, int $pid): array {
    $r = bslEditProduct($tk, $vid, $pid, ['status' => 4184]);
    if (!empty($r['ok'])) $r['archived'] = true;
    return $r;
}

/**
 * ویرایش گروهی باسلام با اندپوینت رسمی batch-updates.
 * هر آیتم باید id داشته باشد؛ بقیهٔ فیلدها اختیاری‌اند.
 * در دسته‌های ۵۰تایی فرستاده می‌شود تا درخواست خیلی بزرگ نشود.
 */
function bslBatchUpdate(string $tk, int $vid, array $items): array {
    $items = array_values(array_filter($items, fn($i) => (int)($i['id'] ?? 0) > 0));
    if (empty($items) || $vid <= 0) return ['ok' => false, 'done' => 0, 'error' => 'ورودی خالی'];
    $done = 0; $failed = 0; $errors = [];
    foreach (array_chunk($items, 50) as $chunk) {
        $r = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/batch-updates', ['data' => $chunk]);
        if (!empty($r['ok'])) { $done += count($chunk); }
        else {
            // اگر گروهی نشد، تک‌تک امتحان کن تا یک محصول خراب کل دسته را نبرد
            foreach ($chunk as $one) {
                $id = (int)$one['id']; unset($one['id']);
                $r2 = bslEditProduct($tk, $vid, $id, $one);
                if (!empty($r2['ok'])) $done++;
                else { $failed++; if (count($errors) < 10) $errors[] = '#' . $id . ' → ' . (int)($r2['code'] ?? 0); }
            }
        }
        usleep(200000);
    }
    return ['ok' => $failed === 0, 'done' => $done, 'failed' => $failed, 'errors' => $errors];
}

/** یک محصول ووکامرس را ویرایش می‌کند */
function wooEditProduct(array $w, int $pid, array $fields): array {
    if ($pid <= 0 || empty($fields)) return ['ok' => false, 'code' => 0, 'error' => 'ورودی ناقص'];
    return wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                  'PUT', 'products/' . $pid, $fields);
}

/**
 * حذف محصول ووکامرس.
 * $force=false یعنی به زباله‌دان (برگشت‌پذیر)، true یعنی نابودی همیشگی.
 * برخلاف باسلام، ووکامرس واقعاً حذف دائمی دارد.
 */
function wooDeleteProduct(array $w, int $pid, bool $force = false): array {
    if ($pid <= 0) return ['ok' => false, 'code' => 0, 'error' => 'شناسه نامعتبر'];
    return wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                  'DELETE', 'products/' . $pid . '?force=' . ($force ? 'true' : 'false'));
}

/**
 * قیمت تازه را از روی دستور کاربر می‌سازد.
 *   set:12000   → همین عدد
 *   inc:10%     → ۱۰٪ گران‌تر     ·  dec:10%  → ۱۰٪ ارزان‌تر
 *   inc:5000    → ۵۰۰۰ اضافه      ·  dec:5000 → ۵۰۰۰ کم
 * خروجی null یعنی دستور نامفهوم بود و نباید چیزی نوشته شود.
 */
function editApplyPrice(string $op, string $val, int $current): ?int {
    $val = trim(persianToEnglish($val));
    $isPct = substr($val, -1) === '%';
    $num = (float)preg_replace('~[^0-9.\-]~', '', $val);
    if ($op === 'set') return $num > 0 ? (int)round($num) : null;
    if ($current <= 0) return null;
    $delta = $isPct ? ($current * $num / 100) : $num;
    if ($op === 'inc') return max(0, (int)round($current + $delta));
    if ($op === 'dec') return max(0, (int)round($current - $delta));
    return null;
}

function wooFindByTitle(array $w, string $title): ?array {
    if ($title === '') return null;
    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET',
        'products?search=' . urlencode($title) . '&status=any&per_page=10');
    if (empty($r['ok']) || !is_array($r['body'] ?? null)) return null;
    foreach ($r['body'] as $ep) {
        if (trim((string)($ep['name'] ?? '')) === $title) return $ep;
    }
    return null;
}

/** یک محصول باسلام را با عنوان پیدا می‌کند */
function bslFindByTitle(string $tk, int $vid, string $title): ?array {
    if ($title === '' || $vid <= 0) return null;
    $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?per_page=20&title=' . rawurlencode($title));
    if (empty($r['ok'])) return null;
    foreach (($r['body']['data'] ?? []) as $p) {
        if (!is_array($p)) continue;
        if (trim((string)($p['title'] ?? ($p['name'] ?? ''))) === $title) return $p;
    }
    return null;
}

/**
 * محصولات رفته از مبدأ را روی مقصد بازنشسته می‌کند.
 * $items همان removed_items استخراج است.
 */
function retireRemoved(array $cn, array $items, string $target, string $mode,
                       int $extracted, bool $dryRun = false): array {
    $out = ['mode' => $mode, 'target' => $target, 'checked' => 0,
            'retired' => 0, 'not_found' => 0, 'failed' => 0, 'items' => [], 'dry_run' => $dryRun];
    if ($mode === 'off' || !$items) { $out['skipped'] = 'غیرفعال'; return $out; }

    $guard = retireGuard(count($items), $extracted, $cn);
    $out['guard'] = $guard;
    if (empty($guard['allow'])) { $out['skipped'] = $guard['reason']; return $out; }

    $w   = $cn['woocommerce'] ?? [];
    $tk  = (string)($cn['basalam']['token'] ?? '');
    $vid = (int)($cn['basalam']['vendor_id'] ?? 0);
    $suffix = trim((string)($w['title_suffix'] ?? ''));

    foreach ($items as $it) {
        $title = trim((string)($it['title'] ?? ''));
        if ($title === '') continue;
        $out['checked']++;
        $row = ['title' => mb_substr($title, 0, 60), 'reason' => $it['reason'] ?? ''];

        if ($target === 'woo' || $target === 'both') {
            $t = $suffix !== '' && mb_strpos($title, $suffix) === false ? $title . $suffix : $title;
            $ex = wooFindByTitle($w, $t) ?: wooFindByTitle($w, $title);
            if (!$ex) { $out['not_found']++; $row['woo'] = 'یافت نشد'; }
            elseif ($dryRun) { $row['woo'] = 'آماده: #' . $ex['id']; }
            else {
                $id = (int)$ex['id'];
                if ($mode === 'delete') {
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'DELETE', 'products/' . $id . '?force=false');   // به زباله‌دان، نه نابودی
                } elseif ($mode === 'outofstock') {
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'PUT', 'products/' . $id, ['stock_status' => 'outofstock', 'stock_quantity' => 0]);
                } else {
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'PUT', 'products/' . $id, ['status' => 'draft']);
                }
                if (!empty($r['ok'])) { $out['retired']++; $row['woo'] = 'انجام شد #' . $id; }
                else { $out['failed']++; $row['woo'] = 'خطا ' . (int)($r['code'] ?? 0); }
            }
        }

        if (($target === 'bsl' || $target === 'both') && $tk !== '' && $vid > 0) {
            $ex = bslFindByTitle($tk, $vid, $title);
            if (!$ex) { $out['not_found']++; $row['bsl'] = 'یافت نشد'; }
            elseif ($dryRun) { $row['bsl'] = 'آماده: #' . $ex['id']; }
            else {
                $id = (int)$ex['id'];
                if ($mode === 'delete') {
                    // v8.62: باسلام حذف واقعی ندارد — بایگانی نزدیک‌ترین معادل است.
                    // قبلاً DELETE به اندپوینتی می‌رفت که وجود ندارد و همیشه ۴۰۴ می‌شد.
                    $r = bslArchiveProduct($tk, $vid, $id);
                } elseif ($mode === 'outofstock') {
                    $r = bslEditProduct($tk, $vid, $id, ['stock' => 0]);
                } else {
                    $r = bslEditProduct($tk, $vid, $id, ['status' => 3790]);   // غیرفعال
                }
                if (!empty($r['ok'])) {
                    $out['retired']++;
                    $row['bsl'] = ($mode === 'delete' ? 'بایگانی شد #' : 'انجام شد #') . $id;
                }
                else { $out['failed']++; $row['bsl'] = 'خطا ' . (int)($r['code'] ?? 0); }
            }
        }
        if (count($out['items']) < 50) $out['items'][] = $row;
    }
    return $out;
}

/* =====================================================================
 *  v8.47: مغایرت‌گیری — مقایسهٔ مقصد با نتایج پروفایل‌ها
 *
 *  همهٔ پروفایل‌هایی که همگام‌سازی دوره‌ای‌شان روشن است را می‌گیرد،
 *  فهرست محصولاتِ نهاییِ آن‌ها را می‌سازد، بعد کل محصولات ووکامرس یا
 *  باسلام را می‌خواند و سه چیز را گزارش می‌کند:
 *    • در مقصد هست ولی در هیچ پروفایلی نیست  → حذف/بازنشستگی
 *    • قیمتش با قیمت پروفایل فرق دارد         → به‌روزرسانی قیمت
 *    • یکسان است                              → دست نخورده
 *
 *  ⚠️ حذف خطرناک است، پس همان محافظ بازنشستگی اینجا هم اعمال می‌شود و
 *  حالت پیش‌فرض «فقط گزارش» است.
 * ===================================================================== */

/** عنوان را برای مقایسه یکدست می‌کند */
/**
 * v8.64: نرمال‌سازی عنوان برای مقایسه با مقصد.
 *
 * نسخهٔ قبلی فقط فاصله‌ها را جمع می‌کرد و کوچک می‌نوشت. نتیجه این بود که
 * محصولی که در پروفایل «کیف چرم & کفش» بود، در ووکامرس با «&amp;» ذخیره
 * شده و «در هیچ پروفایلی نیست» گزارش می‌شد. همین اتفاق برای ی/ک عربی
 * (که خیلی از فروشگاه‌ها موقع ذخیره تبدیل می‌کنند)، نیم‌فاصله و فاصلهٔ
 * سخت (NBSP) هم می‌افتاد. یعنی مغایرت‌گیری روی داده‌های واقعی تقریباً
 * همه‌چیز را «اضافی» می‌دید و اگر کاربر «حذف» می‌زد فاجعه بود.
 *
 * حالا قبل از مقایسه: انتیتی‌های HTML باز می‌شوند، ارقام فارسی/عربی به
 * لاتین، حروف عربی به فارسی، نیم‌فاصله و فاصله‌های نامرئی به فاصلهٔ
 * ساده، و علائم نگارشی حذف می‌شوند.
 */
/* =====================================================================
 *  v8.65: دفترچهٔ شناسهٔ مقصد
 *
 *  تا اینجا مغایرت‌گیری، آمار پسوند و عکس‌دار کردن، محصول را با «عنوان»
 *  در مقصد پیدا می‌کردند. مشکل این است که عنوان تغییر می‌کند: یک ویرایش
 *  دستی در پنل ووکامرس، یا پسوندی که بعداً عوض شود، و آن محصول ناگهان
 *  «در هیچ پروفایلی نیست» گزارش می‌شود. اگر کاربر روی چنین گزارشی حذف
 *  بزند، محصول سالم پاک می‌شود.
 *
 *  هر بار که چیزی با موفقیت ارسال یا آپدیت می‌شود، شناسهٔ مقصد کنار
 *  کلید محصول ثبت می‌شود. کلید محصول از روی آدرس صفحهٔ مبدأ ساخته شده و
 *  با تغییر عنوان عوض نمی‌شود. از آن به بعد تطبیق اول با شناسه انجام
 *  می‌شود و عنوان فقط راه دوم است.
 * ===================================================================== */

function remoteMapLoad(): array {
    if (!is_file(REMOTEMAP_FILE)) return ['woo' => [], 'bsl' => []];
    $d = json_decode((string)@file_get_contents(REMOTEMAP_FILE), true);
    if (!is_array($d)) return ['woo' => [], 'bsl' => []];
    $d['woo'] = is_array($d['woo'] ?? null) ? $d['woo'] : [];
    $d['bsl'] = is_array($d['bsl'] ?? null) ? $d['bsl'] : [];
    return $d;
}

function remoteMapSave(array $m): bool {
    return @file_put_contents(REMOTEMAP_FILE, json_encode($m, JSON_UNESCAPED_UNICODE), LOCK_EX) !== false;
}

/**
 * فهرست «کلید → شناسه» را برای یک مقصد ثبت می‌کند.
 * $rows همان sent_details/updated_details است: هر ردیف key و remote_id دارد.
 */
function remoteMapRecord(string $target, array $rows, string $profileKey = ''): int {
    if ($target !== 'woo' && $target !== 'bsl') return 0;
    $add = [];
    foreach ($rows as $r) {
        if (!is_array($r)) continue;
        $k = trim((string)($r['key'] ?? ''));
        $id = (int)($r['remote_id'] ?? 0);
        if ($k === '' || $id <= 0) continue;
        $add[$k] = ['id' => $id, 'title' => mb_substr((string)($r['title'] ?? ''), 0, 120),
                    'profile' => $profileKey, 'at' => time()];
    }
    if (!$add) return 0;
    $m = remoteMapLoad();
    foreach ($add as $k => $v) $m[$target][$k] = $v;
    // سقف منطقی تا فایل بی‌نهایت رشد نکند
    if (count($m[$target]) > 20000) {
        uasort($m[$target], fn($a, $b) => ((int)($b['at'] ?? 0)) <=> ((int)($a['at'] ?? 0)));
        $m[$target] = array_slice($m[$target], 0, 20000, true);
    }
    remoteMapSave($m);
    return count($add);
}

/** نگاشت معکوس: شناسهٔ مقصد → کلید محصول */
function remoteMapById(string $target): array {
    $out = [];
    foreach ((remoteMapLoad()[$target] ?? []) as $k => $v) {
        $id = (int)($v['id'] ?? 0);
        if ($id > 0) $out[$id] = $k;
    }
    return $out;
}

function reconNormTitle(string $t): string {
    $t = html_entity_decode($t, ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $t = persianToEnglish($t);
    $t = str_replace(['ي', 'ك', 'ة', 'ۀ', 'أ', 'إ', 'ؤ'],
                     ['ی', 'ک', 'ه', 'ه', 'ا', 'ا', 'و'], $t);
    // نیم‌فاصله، فاصلهٔ سخت و نشانه‌های جهت‌دهی → فاصلهٔ ساده
    $t = preg_replace('~[\x{200c}\x{200d}\x{200e}\x{200f}\x{00a0}\x{feff}]~u', ' ', $t);
    // اعراب
    $t = preg_replace('~[\x{064B}-\x{065F}\x{0670}]~u', '', $t);
    // v8.73: پسوند کد محصول «(کد: ۱)» قبل از حذف علائم برداشته شود،
    // وگرنه فقط پرانتزش می‌رود و «کد 1» توی عنوان می‌ماند.
    $t = stripProductCode($t);
    // علائم نگارشی و جداکننده‌ها — «&» و «-» و «—» نباید تفاوت بسازند
    $t = preg_replace('~[^\p{L}\p{N}\s]~u', ' ', $t);
    $t = preg_replace('~\s+~u', ' ', $t);
    $t = trim($t);
    return function_exists('mb_strtolower') ? mb_strtolower($t, 'UTF-8') : strtolower($t);
}

/* =====================================================================
 *  v8.53: آمار محصولات بر اساس پسوند یکتای هر پروفایل
 *
 *  هر پروفایل یک پسوند دارد که به انتهای عنوان محصول اضافه می‌شود.
 *  همین پسوند اجازه می‌دهد در فهرست مقصد بفهمیم هر محصول مال کدام
 *  پروفایل است، بدون اینکه چیزی جداگانه ذخیره کرده باشیم.
 * ===================================================================== */

/** پسوند هر پروفایل، فقط آن‌هایی که پسوند دارند */
function suffixProfiles(): array {
    $out = [];
    foreach (loadProfiles() as $key => $p) {
        $sfx = trim((string)($p['titleSuffix'] ?? ''));
        if ($sfx === '') continue;
        $out[] = ['key' => $key, 'name' => (string)($p['name'] ?? $key),
                  'suffix' => $sfx, 'target' => (string)($p['syncConfig']['target'] ?? 'woo')];
    }
    return $out;
}

/* =====================================================================
 *  v8.62: ویرایش گروهی و تکی محصولات مقصد — سمت سرور
 *
 *  همه‌چیز پس‌زمینه اجرا می‌شود: مرورگر بسته شود هم ادامه دارد، پیشرفت
 *  در فایل نوشته می‌شود و در پایان گزارش به پیام‌رسان‌ها می‌رود.
 * ===================================================================== */

function bulkProgress(array $patch): void {
    $cur = [];
    if (is_file(BULKEDIT_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(BULKEDIT_PROGRESS_FILE), true);
        if (is_array($d)) $cur = $d;
    }
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 300) $log = array_slice($log, -300);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    $cur['log'] = $log; $cur['ts'] = time();
    @file_put_contents(BULKEDIT_PROGRESS_FILE, json_encode($cur, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/**
 * اجرای ویرایش گروهی.
 *
 * $target  woo | bsl
 * $ids     فهرست شناسه‌های محصول در مقصد
 * $ops     ['price'=>['op'=>'inc','val'=>'10%'], 'stock'=>5, 'status'=>'draft',
 *           'desc'=>'...', 'short_desc'=>'...', 'delete'=>true, 'force'=>false]
 * $dry     فقط پیش‌نمایش، بدون تغییر واقعی
 */
function bulkEditRun(array $cn, string $target, array $ids, array $ops, bool $dry = false): array {
    $out = ['ok' => true, 'target' => $target, 'total' => count($ids), 'changed' => 0,
            'deleted' => 0, 'skipped' => 0, 'failed' => 0, 'dry' => $dry, 'items' => [],
            'started_at' => time()];
    $ids = array_values(array_filter(array_map('intval', $ids), fn($v) => $v > 0));
    if (empty($ids)) { $out['ok'] = false; $out['error'] = 'محصولی انتخاب نشده'; return $out; }

    $w  = $cn['woocommerce'] ?? [];
    $bs = $cn['basalam'] ?? [];
    $tk = (string)($bs['token'] ?? ''); $vid = (int)($bs['vendor_id'] ?? 0);
    if ($target === 'woo' && empty($w['store_url'])) { $out['ok'] = false; $out['error'] = 'تنظیمات ووکامرس ناقص'; return $out; }
    if ($target === 'bsl' && ($tk === '' || $vid <= 0)) { $out['ok'] = false; $out['error'] = 'تنظیمات باسلام ناقص'; return $out; }

    $wantDelete = !empty($ops['delete']);
    $n = 0;
    foreach ($ids as $pid) {
        $n++;
        if ($n % 5 === 1 || $n === count($ids)) {
            bulkProgress(['current' => $n, 'total' => count($ids),
                'changed' => $out['changed'], 'deleted' => $out['deleted'],
                'failed' => $out['failed'], 'skipped' => $out['skipped']]);
        }
        $row = ['id' => $pid];

        // ---- وضعیت فعلی محصول را بگیر تا درصد قیمت درست حساب شود ----
        $curPrice = 0; $title = '';
        if ($target === 'woo') {
            $g = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET', 'products/' . $pid);
            if (empty($g['ok'])) { $out['failed']++; $row['error'] = 'یافت نشد (' . (int)$g['code'] . ')'; $out['items'][] = $row; continue; }
            $gb = $g['body'] ?? [];
            $curPrice = (int)preg_replace('~[^0-9]~', '', (string)($gb['regular_price'] ?? '0'));
            $title = (string)($gb['name'] ?? '');
        } else {
            $g = bslReq($tk, 'GET', 'products/' . $pid);
            $gb = $g['body'] ?? [];
            $curPrice = (int)($gb['price'] ?? $gb['primary_price'] ?? 0);
            // باسلام ریالی است و کاربر تومانی فکر می‌کند
            if ($curPrice > 0) $curPrice = (int)round($curPrice / 10);
            $title = (string)($gb['title'] ?? $gb['name'] ?? '');
        }
        $row['title'] = mb_substr($title, 0, 60);
        $row['old_price'] = $curPrice;

        // ---- حذف ----
        if ($wantDelete) {
            if ($dry) {
                $row['action'] = $target === 'bsl' ? 'بایگانی می‌شود' : 'حذف می‌شود';
                $out['items'][] = $row; $out['deleted']++; continue;
            }
            if ($target === 'woo') {
                $r = wooDeleteProduct($w, $pid, !empty($ops['force']));
                $row['action'] = !empty($ops['force']) ? 'حذف همیشگی' : 'به زباله‌دان';
            } else {
                $r = bslArchiveProduct($tk, $vid, $pid);
                $row['action'] = 'بایگانی (باسلام حذف همیشگی ندارد)';
            }
            if (!empty($r['ok'])) { $out['deleted']++; }
            else { $out['failed']++; $row['error'] = 'خطا ' . (int)($r['code'] ?? 0); }
            $out['items'][] = $row;
            usleep(250000);
            continue;
        }

        // ---- ساخت فیلدهای تغییر ----
        $fields = [];
        if (!empty($ops['price']) && is_array($ops['price'])) {
            $np = editApplyPrice((string)($ops['price']['op'] ?? ''), (string)($ops['price']['val'] ?? ''), $curPrice);
            if ($np !== null && $np !== $curPrice) {
                $row['new_price'] = $np;
                $row['pct'] = $curPrice > 0 ? round(($np - $curPrice) / $curPrice * 100, 1) : 0;
                if ($target === 'woo') $fields['regular_price'] = (string)$np;
                else $fields['primary_price'] = $np * 10;   // باسلام ریالی
            }
        }
        if (isset($ops['stock']) && $ops['stock'] !== '') {
            $st = (int)$ops['stock'];
            if ($target === 'woo') { $fields['manage_stock'] = true; $fields['stock_quantity'] = $st;
                                     $fields['stock_status'] = $st > 0 ? 'instock' : 'outofstock'; }
            else $fields['stock'] = $st;
            $row['stock'] = $st;
        }
        if (!empty($ops['status'])) {
            $s = (string)$ops['status'];
            if ($target === 'woo') { $fields['status'] = in_array($s, ['publish','draft','private','pending'], true) ? $s : 'draft'; }
            else { $sm = bslStatusMap(); $si = (int)$s; if (isset($sm[$si])) $fields['status'] = $si; }
            $row['status'] = $s;
        }
        if (isset($ops['desc']) && $ops['desc'] !== '') {
            if ($target === 'woo') $fields['description'] = (string)$ops['desc'];
            else $fields['description'] = (string)$ops['desc'];
            $row['desc'] = true;
        }
        if (isset($ops['short_desc']) && $ops['short_desc'] !== '') {
            if ($target === 'woo') $fields['short_description'] = (string)$ops['short_desc'];
            else $fields['brief'] = mb_substr((string)$ops['short_desc'], 0, 250);
            $row['short_desc'] = true;
        }
        if (!empty($ops['title_prefix']) || !empty($ops['title_suffix'])) {
            $nt = (string)($ops['title_prefix'] ?? '') . $title . (string)($ops['title_suffix'] ?? '');
            $nt = trim($nt);
            if ($nt !== '' && $nt !== $title) {
                if ($target === 'woo') $fields['name'] = $nt; else $fields['name'] = mb_substr($nt, 0, 120);
                $row['new_title'] = mb_substr($nt, 0, 60);
            }
        }

        if (empty($fields)) { $out['skipped']++; $row['action'] = 'تغییری لازم نبود'; $out['items'][] = $row; continue; }
        if ($dry) { $row['action'] = 'آماده: ' . implode('، ', array_keys($fields)); $out['items'][] = $row; $out['changed']++; continue; }

        $r = $target === 'woo' ? wooEditProduct($w, $pid, $fields) : bslEditProduct($tk, $vid, $pid, $fields);
        if (!empty($r['ok'])) { $out['changed']++; $row['action'] = 'انجام شد'; }
        else { $out['failed']++; $row['error'] = 'خطا ' . (int)($r['code'] ?? 0) . ' ' . mb_substr((string)($r['body']['message'] ?? ''), 0, 60); }
        $out['items'][] = $row;
        usleep(250000);
    }
    $out['finished_at'] = time();
    return $out;
}

/** پیام گزارش ویرایش گروهی برای پیام‌رسان */
function bulkEditMsg(array $r): string {
    $t = ($r['target'] ?? '') === 'woo' ? 'ووکامرس' : 'باسلام';
    $m = "✏️ ویرایش گروهی — {$t}\n";
    if (!empty($r['dry'])) $m .= "(پیش‌نمایش — چیزی تغییر نکرد)\n";
    $m .= "───────────────\n";
    $m .= "کل: " . (int)($r['total'] ?? 0) . "\n";
    if ((int)($r['changed'] ?? 0) > 0) $m .= "✅ ویرایش شد: " . (int)$r['changed'] . "\n";
    if ((int)($r['deleted'] ?? 0) > 0) {
        $m .= (($r['target'] ?? '') === 'bsl' ? "🗄 بایگانی شد: " : "🗑 حذف شد: ") . (int)$r['deleted'] . "\n";
    }
    if ((int)($r['skipped'] ?? 0) > 0) $m .= "⏭ بدون تغییر: " . (int)$r['skipped'] . "\n";
    if ((int)($r['failed'] ?? 0) > 0)  $m .= "❌ خطا: " . (int)$r['failed'] . "\n";
    $priced = array_values(array_filter($r['items'] ?? [], fn($i) => isset($i['new_price'])));
    if ($priced) {
        $m .= "\n💰 نمونهٔ تغییر قیمت:\n";
        foreach (array_slice($priced, 0, 5) as $i) {
            $sign = ($i['pct'] ?? 0) >= 0 ? '+' : '';
            $m .= '• ' . mb_substr((string)$i['title'], 0, 34) . ' — '
                . number_format((int)$i['old_price']) . ' → ' . number_format((int)$i['new_price'])
                . ' (' . $sign . $i['pct'] . "٪)\n";
        }
    }
    return $m;
}

/* =====================================================================
 *  v8.62: عکس‌دار کردن محصولات ووکامرس از روی پروفایل‌ها
 *
 *  محصولاتی که بی‌تصویر در ووکامرس نشسته‌اند (چه به‌خاطر باگ‌های قدیمی
 *  آپلود، چه به‌خاطر تصویر نگرفتنی) با تطبیق عنوان به تصویرِ همان محصول
 *  در پروفایل وصل می‌شوند. از همان مسیر wooImagePayload استفاده می‌کند،
 *  پس اگر آپلود مستقیم نشد، آدرس به خود ووکامرس سپرده می‌شود.
 * ===================================================================== */

function photoFixProgress(array $patch): void {
    $cur = [];
    if (is_file(PHOTOFIX_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(PHOTOFIX_PROGRESS_FILE), true);
        if (is_array($d)) $cur = $d;
    }
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 300) $log = array_slice($log, -300);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    $cur['log'] = $log; $cur['ts'] = time();
    @file_put_contents(PHOTOFIX_PROGRESS_FILE, json_encode($cur, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/** نگاشت «عنوان نرمال‌شده → تصویر» از روی همهٔ پروفایل‌ها */
function photoFixIndex(?string $onlyProfile = null, ?array &$byKey = null): array {
    $idx = [];
    $byKey = [];   // v8.65: همان تصویرها، این بار با کلید محصول
    foreach (loadProfiles() as $key => $p) {
        if ($onlyProfile !== null && $onlyProfile !== '' && $key !== $onlyProfile) continue;
        $suffix = trim((string)($p['titleSuffix'] ?? ''));
        foreach (profileOrderedProducts($p, null, false) as $prod) {
            if (!is_array($prod)) continue;
            $img = trim((string)($prod['image'] ?? ''));
            if ($img === '') continue;
            $rec = ['image' => $img, 'profile' => $p['name'] ?? $key,
                    'images' => productImageList($prod)];
            $pk = trim((string)($prod['key'] ?? ''));
            if ($pk !== '' && !isset($byKey[$pk])) $byKey[$pk] = $rec;
            $t = trim((string)($prod['title'] ?? $prod['name'] ?? ''));
            if ($t === '') continue;
            foreach ([$t, ($suffix !== '' ? trim($t . ' ' . $suffix) : $t)] as $variant) {
                $k = bslNormalizeTitle($variant);
                if ($k !== '' && !isset($idx[$k])) $idx[$k] = $rec;
            }
        }
    }
    return $idx;
}

/**
 * محصولات بی‌تصویر ووکامرس را پیدا و از روی پروفایل عکس‌دار می‌کند.
 * $dry فقط گزارش می‌دهد.
 */
function photoFixRun(array $cn, bool $dry = false, string $onlyProfile = '', int $maxItems = 2000): array {
    $w = $cn['woocommerce'] ?? [];
    $out = ['ok' => true, 'scanned' => 0, 'missing' => 0, 'matched' => 0, 'fixed' => 0,
            'failed' => 0, 'unmatched' => 0, 'dry' => $dry, 'items' => [], 'started_at' => time()];
    if (empty($w['store_url'])) { $out['ok'] = false; $out['error'] = 'تنظیمات ووکامرس ناقص'; return $out; }

    $pfByKey = null;
    $idx = photoFixIndex($onlyProfile !== '' ? $onlyProfile : null, $pfByKey);
    $out['index_size'] = count($idx);
    if (empty($idx)) { $out['ok'] = false; $out['error'] = 'در پروفایل‌ها تصویری پیدا نشد'; return $out; }
    // v8.65: تطبیق با شناسهٔ ثبت‌شده، برای محصولی که در ووکامرس تغییر نام داده
    $pfIdMap = remoteMapById('woo');
    $out['by_id'] = 0;
    photoFixProgress(['log_add' => ['🗂 ' . count($idx) . ' تصویر از پروفایل‌ها فهرست شد'
        . (count($pfIdMap) ? ' · ' . count($pfIdMap) . ' شناسهٔ ثبت‌شده' : '')]]);

    $page = 1;
    while ($page <= 100 && $out['scanned'] < $maxItems) {
        $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET',
                    'products?per_page=100&page=' . $page . '&status=any');
        if (empty($r['ok']) || !is_array($r['body'] ?? null) || empty($r['body'])) break;
        foreach ($r['body'] as $p) {
            $out['scanned']++;
            $imgs = $p['images'] ?? [];
            if (!empty($imgs) && is_array($imgs)) continue;    // تصویر دارد
            $out['missing']++;
            $pid = (int)($p['id'] ?? 0);
            $name = trim((string)($p['name'] ?? ''));
            $hit = $idx[bslNormalizeTitle($name)] ?? null;
            if ($hit === null && $pid > 0 && isset($pfIdMap[$pid])
                && isset($pfByKey[$pfIdMap[$pid]])) {
                $hit = $pfByKey[$pfIdMap[$pid]];   // عنوان عوض شده، شناسه نه
                $out['by_id']++;
            }
            if ($hit === null) {
                $out['unmatched']++;
                if (count($out['items']) < 200) $out['items'][] = ['id' => $pid, 'title' => mb_substr($name, 0, 60), 'status' => 'در پروفایل‌ها نبود'];
                continue;
            }
            $out['matched']++;
            if ($dry) {
                if (count($out['items']) < 200) $out['items'][] = ['id' => $pid, 'title' => mb_substr($name, 0, 60),
                    'status' => 'آماده', 'profile' => $hit['profile'], 'image' => $hit['image']];
                continue;
            }
            $note = null;
            $GLOBALS['_currentProductLink'] = '';
            $imgsHit = !empty($hit['images']) && is_array($hit['images'])
                     ? $hit['images'] : [(string)$hit['image']];
            $payload = wooGalleryPayload($w, $imgsHit, $note);
            if (empty($payload)) {
                $out['failed']++;
                if (count($out['items']) < 200) $out['items'][] = ['id' => $pid, 'title' => mb_substr($name, 0, 60), 'status' => 'تصویر آماده نشد: ' . (string)$note];
                continue;
            }
            $u = wooEditProduct($w, $pid, ['images' => $payload]);
            if (empty($u['ok']) && wooIsImageError($u)) {
                $out['failed']++;
                if (count($out['items']) < 200) $out['items'][] = ['id' => $pid, 'title' => mb_substr($name, 0, 60), 'status' => 'ووکامرس تصویر را نگرفت'];
                continue;
            }
            if (!empty($u['ok'])) { $out['fixed']++;
                if (count($out['items']) < 200) $out['items'][] = ['id' => $pid, 'title' => mb_substr($name, 0, 60), 'status' => '✅ عکس‌دار شد', 'profile' => $hit['profile']]; }
            else { $out['failed']++;
                if (count($out['items']) < 200) $out['items'][] = ['id' => $pid, 'title' => mb_substr($name, 0, 60), 'status' => 'خطا ' . (int)$u['code']]; }
            usleep(200000);
        }
        photoFixProgress(['scanned' => $out['scanned'], 'missing' => $out['missing'],
            'fixed' => $out['fixed'], 'failed' => $out['failed'], 'unmatched' => $out['unmatched'],
            'log_add' => ['📄 صفحهٔ ' . $page . ' — بررسی‌شده ' . $out['scanned'] . '، بی‌تصویر ' . $out['missing'] . '، درست‌شده ' . $out['fixed']]]);
        if (count($r['body']) < 100) break;
        $page++;
    }
    $out['finished_at'] = time();
    return $out;
}

function photoFixMsg(array $r): string {
    $m = "🖼 عکس‌دار کردن محصولات ووکامرس\n";
    if (!empty($r['dry'])) $m .= "(پیش‌نمایش — چیزی تغییر نکرد)\n";
    $m .= "───────────────\n";
    $m .= "بررسی‌شده: " . (int)($r['scanned'] ?? 0) . "\n";
    $m .= "بی‌تصویر: " . (int)($r['missing'] ?? 0) . "\n";
    $m .= "✅ عکس‌دار شد: " . (int)($r['fixed'] ?? 0) . "\n";
    if ((int)($r['unmatched'] ?? 0) > 0) $m .= "❓ در پروفایل‌ها نبود: " . (int)$r['unmatched'] . "\n";
    if ((int)($r['failed'] ?? 0) > 0)    $m .= "❌ ناموفق: " . (int)$r['failed'] . "\n";
    return $m;
}

/* =====================================================================
 *  v8.62: گزارش شبانهٔ تفصیلی (پیش‌فرض ساعت ۲۳)
 *
 *  از گزارش‌های استخراج هر پروفایل، محصولات اضافه‌شده، تغییر قیمت‌داده و
 *  حذف‌شده را جمع می‌کند و با میزان و درصد تغییر می‌فرستد. وضعیت ارسال
 *  به ووکامرس و باسلام هم از صف‌ها خوانده می‌شود.
 *
 *  کران‌جاب هر پنج دقیقه اجرا می‌شود، پس اینجا فقط تصمیم می‌گیریم که
 *  «آیا الان وقتش هست و امروز فرستاده‌ایم یا نه».
 * ===================================================================== */

function digestLoadState(): array {
    if (!is_file(DIGEST_STATE_FILE)) return [];
    $d = json_decode((string)@file_get_contents(DIGEST_STATE_FILE), true);
    return is_array($d) ? $d : [];
}
function digestSaveState(array $s): void {
    @file_put_contents(DIGEST_STATE_FILE, json_encode($s, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/** آیا الان باید گزارش شبانه برود؟ */
function digestDue(array $cn, int $now): bool {
    if (empty($cn['digest_enabled'])) return false;
    $hour = max(0, min(23, (int)($cn['digest_hour'] ?? 23)));
    // ساعت محلی سرور؛ اگر منطقهٔ زمانی تنظیم شده باشد همان اعمال می‌شود
    $tz = trim((string)($cn['digest_tz'] ?? ''));
    if ($tz !== '') { $old = @date_default_timezone_get(); @date_default_timezone_set($tz); }
    $h = (int)date('G', $now);
    $today = date('Y-m-d', $now);
    if ($tz !== '' && isset($old)) @date_default_timezone_set($old);

    if ($h < $hour) return false;                    // هنوز نرسیده
    $st = digestLoadState();
    if (($st['last_date'] ?? '') === $today) return false;   // امروز فرستاده شده
    return true;
}

/**
 * جمع‌آوری آمار همهٔ پروفایل‌ها از گزارش‌های استخراج امروز.
 * $sinceHours بازهٔ زمانی که گزارش‌ها را از آن می‌خوانیم.
 */
function digestBuild(array $cn, int $sinceHours = 24): array {
    $since = time() - $sinceHours * 3600;
    $profiles = loadProfiles();
    $out = ['ok' => true, 'since' => $since, 'hours' => $sinceHours,
            'profiles' => [], 'tot_new' => 0, 'tot_changed' => 0, 'tot_removed' => 0,
            'tot_up' => 0, 'tot_down' => 0, 'sum_pct' => 0.0, 'n_pct' => 0];

    // آخرین گزارش هر پروفایل در بازه
    $byProfile = [];
    foreach (glob(__DIR__ . '/extract_report_*.json') ?: [] as $f) {
        $ts = (int)@filemtime($f);
        if ($ts < $since) continue;
        $d = json_decode((string)@file_get_contents($f), true);
        if (!is_array($d)) continue;
        $pk = (string)($d['profile_key'] ?? '');
        $pn = (string)($d['profile_name'] ?? $pk);
        $key = $pk !== '' ? $pk : $pn;
        if ($key === '') continue;
        if (!isset($byProfile[$key]) || $ts > $byProfile[$key]['_ts']) {
            $d['_ts'] = $ts; $d['_name'] = $pn !== '' ? $pn : $key;
            $byProfile[$key] = $d;
        }
    }

    foreach ($byProfile as $key => $d) {
        $new = (array)($d['new_items'] ?? []);
        $chg = (array)($d['changed_items'] ?? []);
        $rem = (array)($d['removed_items'] ?? []);
        $up = 0; $down = 0; $pctSum = 0.0; $pctN = 0;
        foreach ($chg as $c) {
            if (($c['dir'] ?? '') === 'up') $up++; else $down++;
            if (isset($c['pct'])) { $pctSum += (float)$c['pct']; $pctN++; }
        }
        $row = [
            'name' => (string)$d['_name'],
            'at' => (int)$d['_ts'],
            'extracted' => (int)($d['extracted'] ?? 0),
            'new' => count($new), 'changed' => count($chg), 'removed' => count($rem),
            'up' => $up, 'down' => $down,
            'avg_pct' => $pctN > 0 ? round($pctSum / $pctN, 1) : 0,
            'new_items' => array_slice($new, 0, 5),
            'changed_items' => array_slice($chg, 0, 5),
            'removed_items' => array_slice($rem, 0, 5),
        ];
        $out['profiles'][] = $row;
        $out['tot_new'] += $row['new']; $out['tot_changed'] += $row['changed'];
        $out['tot_removed'] += $row['removed'];
        $out['tot_up'] += $up; $out['tot_down'] += $down;
        $out['sum_pct'] += $pctSum; $out['n_pct'] += $pctN;
    }
    $out['avg_pct'] = $out['n_pct'] > 0 ? round($out['sum_pct'] / $out['n_pct'], 1) : 0;

    // وضعیت ارسال به مقصدها در همین بازه
    foreach ([['woo', wooReadQueue()], ['bsl', bslReadQueue()]] as [$k, $q]) {
        $sent = 0; $upd = 0; $skip = 0; $fail = 0; $rows = 0;
        foreach ((array)($q['entries'] ?? []) as $e) {
            $at = (int)($e['done_at'] ?? $e['started_at'] ?? 0);
            if ($at < $since) continue;
            $rows++;
            $sent += (int)($e['sent'] ?? 0); $upd += (int)($e['updated'] ?? 0);
            $skip += (int)($e['skipped'] ?? 0); $fail += (int)($e['failed'] ?? 0);
        }
        $out[$k] = ['rows' => $rows, 'sent' => $sent, 'updated' => $upd,
                    'skipped' => $skip, 'failed' => $fail];
    }
    return $out;
}

/** متن گزارش شبانه */
function digestMsg(array $d): string {
    $m = "🌙 گزارش شبانهٔ محصولات\n";
    $m .= '🗓 ' . date('Y-m-d H:i') . ' · ' . (int)($d['hours'] ?? 24) . " ساعت گذشته\n";
    $m .= "═══════════════\n";
    $m .= "📊 مجموع همهٔ پروفایل‌ها\n";
    $m .= '🆕 اضافه‌شده: ' . (int)$d['tot_new'] . "\n";
    $m .= '💰 تغییر قیمت: ' . (int)$d['tot_changed']
        . ' (↑' . (int)$d['tot_up'] . ' ↓' . (int)$d['tot_down'] . ")\n";
    if ((int)$d['tot_changed'] > 0) {
        $s = $d['avg_pct'] >= 0 ? '+' : '';
        $m .= '   میانگین تغییر: ' . $s . $d['avg_pct'] . "٪\n";
    }
    $m .= '❌ حذف‌شده از مبدأ: ' . (int)$d['tot_removed'] . "\n";

    $wo = $d['woo'] ?? []; $bs = $d['bsl'] ?? [];
    if ((int)($wo['rows'] ?? 0) > 0 || (int)($bs['rows'] ?? 0) > 0) {
        $m .= "\n📤 ارسال به مقصد\n";
        if ((int)($wo['rows'] ?? 0) > 0) {
            $m .= '🛒 ووکامرس: ' . (int)$wo['sent'] . ' جدید · ' . (int)$wo['updated'] . ' آپدیت'
                . ((int)$wo['failed'] > 0 ? ' · ❌' . (int)$wo['failed'] : '') . "\n";
        }
        if ((int)($bs['rows'] ?? 0) > 0) {
            $m .= '🏪 باسلام: ' . (int)$bs['sent'] . ' جدید · ' . (int)$bs['updated'] . ' آپدیت'
                . ((int)$bs['failed'] > 0 ? ' · ❌' . (int)$bs['failed'] : '') . "\n";
        }
    }

    foreach ((array)$d['profiles'] as $p) {
        if ((int)$p['new'] === 0 && (int)$p['changed'] === 0 && (int)$p['removed'] === 0) continue;
        $m .= "\n───────────────\n📁 " . $p['name'] . "\n";
        $m .= '   🆕 ' . (int)$p['new'] . '  💰 ' . (int)$p['changed']
            . ' (↑' . (int)$p['up'] . ' ↓' . (int)$p['down'] . ')  ❌ ' . (int)$p['removed'] . "\n";
        foreach ((array)$p['changed_items'] as $c) {
            $sign = ($c['dir'] ?? '') === 'up' ? '📈' : '📉';
            $pc = isset($c['pct']) ? (((float)$c['pct'] >= 0 ? '+' : '') . $c['pct'] . '٪') : '';
            $m .= '   ' . $sign . ' ' . mb_substr((string)($c['title'] ?? ''), 0, 30)
                . ' ' . (string)($c['old_price'] ?? '') . '→' . (string)($c['new_price'] ?? '')
                . ' ' . $pc . "\n";
        }
        foreach ((array)$p['new_items'] as $c) {
            $m .= '   🆕 ' . mb_substr((string)($c['title'] ?? ''), 0, 34) . "\n";
        }
        foreach ((array)$p['removed_items'] as $c) {
            $m .= '   ❌ ' . mb_substr((string)($c['title'] ?? ''), 0, 34) . "\n";
        }
    }
    if (empty($d['profiles'])) $m .= "\n(در این بازه گزارش استخراجی ثبت نشده)\n";
    return $m;
}

/** اگر وقتش باشد، گزارش شبانه را می‌فرستد */
function digestMaybeSend(array $cn, int $now): array {
    if (!digestDue($cn, $now)) return ['sent' => false, 'skipped' => 'not_due'];
    $why = notifPrereq($cn);
    if ($why !== null) return ['sent' => false, 'skipped' => $why];
    $d = digestBuild($cn, max(1, min(168, (int)($cn['digest_hours'] ?? 24))));
    $res = notifSend($cn, digestMsg($d));
    $st = digestLoadState();
    $st['last_date'] = date('Y-m-d', $now);
    $st['last_at'] = $now;
    $st['last_totals'] = ['new' => $d['tot_new'], 'changed' => $d['tot_changed'], 'removed' => $d['tot_removed']];
    digestSaveState($st);
    return ['sent' => true, 'delivery' => $res, 'totals' => $st['last_totals']];
}

function suffixProgress(array $patch): void {
    $cur = [];
    if (is_file(SUFFIX_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(SUFFIX_PROGRESS_FILE), true);
        if (is_array($d)) $cur = $d;
    }
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 200) $log = array_slice($log, -200);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    $cur['log'] = $log; $cur['ts'] = time();
    @file_put_contents(SUFFIX_PROGRESS_FILE, json_encode($cur, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/**
 * همهٔ محصولات باسلام با وضعیتشان.
 * برخلاف reconFetchBsl که فقط فعال و غیرفعال را می‌گیرد، اینجا وضعیت
 * تأیید نشده و در انتظار هم لازم است.
 */
function suffixFetchBsl(string $tk, int $vid, int $maxPages = 80): array {
    $rows = [];
    $statuses = '&statuses=2976&statuses=3790&statuses=3567&statuses=3568&statuses=4184';
    for ($page = 1; $page <= $maxPages; $page++) {
        $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?page=' . $page
             . '&per_page=100' . $statuses);
        if (empty($r['ok'])) break;
        $batch = $r['body']['data'] ?? [];
        if (!$batch) break;
        foreach ($batch as $pr) {
            if (!is_array($pr)) continue;
            $rev  = $pr['revision']['data'] ?? [];
            $name = trim((string)($pr['title'] ?? ($pr['name'] ?? ($rev['title'] ?? ''))));
            if ($name === '') continue;
            $st = $pr['status'] ?? null;
            $rows[] = ['id' => (int)($pr['id'] ?? 0), 'title' => $name,
                       'status' => (int)(is_array($st) ? ($st['value'] ?? 0) : $st)];
        }
        suffixProgress(['log_add' => ['📄 باسلام صفحهٔ ' . $page . ': ' . count($batch)
            . ' محصول (مجموع ' . count($rows) . ')'], 'fetched' => count($rows)]);
        if (count($batch) < 100) break;
        usleep(150000);
    }
    return $rows;
}

/** همهٔ محصولات ووکامرس با وضعیتشان */
function suffixFetchWoo(array $w, int $maxPages = 80): array {
    $rows = [];
    for ($page = 1; $page <= $maxPages; $page++) {
        $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET',
            'products?per_page=100&status=any&page=' . $page);
        if (empty($r['ok']) || !is_array($r['body'])) break;
        $batch = $r['body'];
        if (!$batch) break;
        foreach ($batch as $pr) {
            $name = trim((string)($pr['name'] ?? ''));
            if ($name === '') continue;
            $rows[] = ['id' => (int)($pr['id'] ?? 0), 'title' => $name,
                       'wstatus' => (string)($pr['status'] ?? '')];
        }
        suffixProgress(['log_add' => ['📄 ووکامرس صفحهٔ ' . $page . ': ' . count($batch)
            . ' محصول (مجموع ' . count($rows) . ')'], 'fetched' => count($rows)]);
        if (count($batch) < 100) break;
        usleep(150000);
    }
    return $rows;
}

/** آیا عنوان با این پسوند تمام می‌شود؟ */
function suffixMatches(string $title, string $suffix): bool {
    $t = trim($title); $x = trim($suffix);
    if ($x === '') return false;
    if (function_exists('mb_strtolower')) { $t = mb_strtolower($t, 'UTF-8'); $x = mb_strtolower($x, 'UTF-8'); }
    return mb_strpos($t, $x) !== false;
}

/**
 * آمار هر پسوند را می‌سازد.
 * وضعیت‌های باسلام: 2976 فعال/تأییدشده · 3567 تأیید نشده ·
 * 3568 در انتظار · 3790 غیرفعال · 4184 بایگانی
 */
function suffixReport(array $cn, string $target): array {
    $profs = suffixProfiles();
    if (!$profs) return ['ok' => false, 'error' => 'هیچ پروفایلی پسوند عنوان ندارد'];

    $wanted = [];
    foreach ($profs as $p) {
        if ($target === 'both' || $p['target'] === 'both' || $p['target'] === $target) $wanted[] = $p;
    }
    if (!$wanted) return ['ok' => false, 'error' => 'هیچ پروفایلی با پسوند برای این مقصد نیست'];

    suffixProgress(['log_add' => ['🔎 ' . count($wanted) . ' پروفایل با پسوند پیدا شد']]);

    if ($target === 'bsl') {
        $tk = (string)($cn['basalam']['token'] ?? '');
        $vid = (int)($cn['basalam']['vendor_id'] ?? 0);
        if ($tk === '' || $vid <= 0) return ['ok' => false, 'error' => 'تنظیمات باسلام ناقص'];
        $rows = suffixFetchBsl($tk, $vid);
    } else {
        $w = $cn['woocommerce'] ?? [];
        if (empty($w['store_url'])) return ['ok' => false, 'error' => 'تنظیمات ووکامرس ناقص'];
        $rows = suffixFetchWoo($w);
    }
    if (!$rows) return ['ok' => false, 'error' => 'هیچ محصولی از مقصد دریافت نشد'];

    suffixProgress(['log_add' => ['⚖️ تفکیک بر اساس پسوند...'], 'remote' => count($rows)]);

    // v8.65: محصولی که در مقصد تغییر نام داده پسوند پروفایل را ندارد و در
    // آمار گم می‌شد. شناسهٔ ثبت‌شده می‌گوید مال کدام پروفایل است.
    $sfxIdMap = remoteMapById($target === 'bsl' ? 'bsl' : 'woo');
    $sfxKeyOwner = [];
    foreach (loadProfiles() as $pk => $pv) {
        foreach (profileOrderedProducts($pv, null, false) as $pp) {
            $kk = trim((string)($pp['key'] ?? ''));
            if ($kk !== '') $sfxKeyOwner[$kk] = $pk;
        }
    }
    $out = []; $claimed = []; $byIdTotal = 0;
    foreach ($wanted as $p) {
        $c = ['approved' => 0, 'rejected' => 0, 'pending' => 0, 'inactive' => 0, 'archived' => 0];
        foreach ($rows as $i => $r) {
            $ok = suffixMatches($r['title'], $p['suffix']);
            if (!$ok) {
                $rid = (int)($r['id'] ?? 0);
                if ($rid > 0 && isset($sfxIdMap[$rid])
                    && ($sfxKeyOwner[$sfxIdMap[$rid]] ?? '') === $p['key']) {
                    $ok = true; $byIdTotal++;
                }
            }
            if (!$ok) continue;
            $claimed[$i] = true;
            if ($target === 'bsl') {
                $st = (int)($r['status'] ?? 0);
                if ($st === 2976)      $c['approved']++;
                elseif ($st === 3567)  $c['rejected']++;
                elseif ($st === 3568)  $c['pending']++;
                elseif ($st === 4184)  $c['archived']++;
                else                   $c['inactive']++;
            } else {
                $ws = (string)($r['wstatus'] ?? '');
                if ($ws === 'publish')      $c['approved']++;
                elseif ($ws === 'pending')  $c['pending']++;
                elseif ($ws === 'draft')    $c['inactive']++;
                elseif ($ws === 'trash')    $c['archived']++;
                else                        $c['inactive']++;
            }
        }
        $total = array_sum($c);
        $pct = [];
        foreach ($c as $k => $v) $pct[$k] = $total > 0 ? round($v / $total * 100, 1) : 0.0;
        $out[] = ['key' => $p['key'], 'name' => $p['name'], 'suffix' => $p['suffix'],
                  'total' => $total, 'counts' => $c, 'pct' => $pct];
        suffixProgress(['log_add' => ['• ' . $p['name'] . ' («' . $p['suffix'] . '»): ' . $total . ' محصول']]);
    }
    $unmatched = count($rows) - count($claimed);
    if ($byIdTotal > 0) suffixProgress(['log_add' => ['🔗 ' . $byIdTotal
        . ' محصول با شناسهٔ ثبت‌شده به پروفایلش وصل شد (پسوند در عنوانشان نبود)']]);
    return ['ok' => true, 'target' => $target, 'remote_total' => count($rows),
            'unmatched' => $unmatched, 'matched_by_id' => $byIdTotal, 'profiles' => $out];
}

/** متن گزارش برای پیام‌رسان‌ها */
function suffixReportMsg(array $rep): string {
    $lbl = ($rep['target'] ?? '') === 'bsl' ? 'باسلام' : 'ووکامرس';
    $lines = ['📊 گزارش محصولات بر اساس پروفایل — ' . $lbl,
              'کل محصولات مقصد: ' . (int)($rep['remote_total'] ?? 0)];
    foreach (($rep['profiles'] ?? []) as $p) {
        $c = $p['counts']; $q = $p['pct'];
        $lines[] = '━━━━━━━━━━';
        $lines[] = '🏷 ' . $p['name'] . '  («' . $p['suffix'] . '»)';
        $lines[] = 'ثبت‌شده: ' . $p['total'];
        if ($p['total'] > 0) {
            $lines[] = '✅ تأیید شده: ' . $c['approved'] . ' (' . $q['approved'] . '٪)';
            if ($c['rejected'] > 0) $lines[] = '❌ تأیید نشده: ' . $c['rejected'] . ' (' . $q['rejected'] . '٪)';
            if ($c['pending']  > 0) $lines[] = '⏳ در انتظار: ' . $c['pending'] . ' (' . $q['pending'] . '٪)';
            if ($c['inactive'] > 0) $lines[] = '⏸ غیرفعال: ' . $c['inactive'] . ' (' . $q['inactive'] . '٪)';
            if ($c['archived'] > 0) $lines[] = '🗑 بایگانی: ' . $c['archived'] . ' (' . $q['archived'] . '٪)';
        }
    }
    if ((int)($rep['unmatched'] ?? 0) > 0) {
        $lines[] = '━━━━━━━━━━';
        $lines[] = '❔ بدون پسوند شناخته‌شده: ' . (int)$rep['unmatched'];
    }
    return implode("\n", $lines);
}

/* v8.49: گزارش زندهٔ مغایرت‌گیری */
function reconProgress(array $patch): void {
    $cur = [];
    if (is_file(RECON_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(RECON_PROGRESS_FILE), true);
        if (is_array($d)) $cur = $d;
    }
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $line) {
            $log[] = ['t' => time(), 'm' => (string)$line];
        }
        if (count($log) > 300) $log = array_slice($log, -300);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    $cur['log'] = $log;
    $cur['ts'] = time();
    @file_put_contents(RECON_PROGRESS_FILE, json_encode($cur, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

function reconProgressRead(): array {
    if (!is_file(RECON_PROGRESS_FILE)) return ['running' => false, 'done' => false, 'log' => []];
    $d = json_decode((string)@file_get_contents(RECON_PROGRESS_FILE), true);
    return is_array($d) ? $d : ['running' => false, 'done' => false, 'log' => []];
}

/**
 * فهرست محصولات نهاییِ پروفایل‌ها برای مقایسه با مقصد.
 *
 * v8.64: تا اینجا فقط پروفایل‌هایی خوانده می‌شدند که «همگام‌سازی دوره‌ای»
 * آن‌ها روشن بود. کسی که محصولاتش را دستی می‌فرستد هیچ‌وقت این تیک را
 * نمی‌زند، پس مغایرت‌گیری برایش با پیام «هیچ پروفایلی پیدا نشد» تمام
 * می‌شد — دقیقاً همان «کار نمی‌کند». حالا $allProfiles=true همهٔ
 * پروفایل‌ها را می‌خواند.
 *
 * $stats اگر داده شود، شرح تفکیکی هر پروفایل داخلش نوشته می‌شود تا در
 * گزارش زنده دیده شود.
 */
function reconExpected(string $target, bool $allProfiles = false, ?array &$stats = null): array {
    $out = [];
    $stats = ['profiles' => [], 'used' => 0, 'skipped' => 0, 'no_products' => 0, 'by_key' => []];
    foreach (loadProfiles() as $key => $profile) {
        $sc = $profile['syncConfig'] ?? [];
        $name = (string)($profile['name'] ?? $key);
        $syncOn = !empty($sc['enabled']);
        $t = (string)($sc['target'] ?? 'woo');
        $targetOk = ($t === 'both' || $t === $target);
        if (!$allProfiles) {
            if (!$syncOn)    { $stats['skipped']++; $stats['profiles'][] = ['name' => $name, 'n' => 0, 'why' => 'همگام‌سازی دوره‌ای خاموش']; continue; }
            if (!$targetOk)  { $stats['skipped']++; $stats['profiles'][] = ['name' => $name, 'n' => 0, 'why' => 'مقصدش این نیست']; continue; }
        }
        $n = 0; $noPrice = 0;
        foreach (profileOrderedProducts($profile) as $p) {
            // v8.65: همان رکورد، این بار با کلید محصول — برای تطبیق با شناسهٔ مقصد
            $pk = trim((string)($p['key'] ?? ''));
            if ($pk !== '' && !isset($stats['by_key'][$pk])) {
                $stats['by_key'][$pk] = ['price' => (int)($p['final_price'] ?? 0),
                                         'profile' => $name, 'key' => $pk];
            }
            $title = reconNormTitle((string)($p['title'] ?? ''));
            if ($title === '') continue;
            $price = (int)($p['final_price'] ?? 0);
            if ($price <= 0) $noPrice++;
            $n++;
            if (isset($out[$title]) && (int)$out[$title]['price'] > 0) continue;
            $out[$title] = ['price' => $price, 'profile' => $name,
                            'key' => (string)($p['key'] ?? '')];
        }
        if ($n === 0) { $stats['no_products']++; $stats['profiles'][] = ['name' => $name, 'n' => 0, 'why' => 'محصولی ندارد']; continue; }
        $stats['used']++;
        $stats['profiles'][] = ['name' => $name, 'n' => $n, 'no_price' => $noPrice,
                                'why' => $syncOn ? '' : 'بدون همگام‌سازی دوره‌ای'];
    }
    return $out;
}

/** همهٔ محصولات ووکامرس */
function reconFetchWoo(array $w, int $maxPages = 60): array {
    $rows = [];
    for ($page = 1; $page <= $maxPages; $page++) {
        $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET',
            'products?per_page=100&status=any&page=' . $page);
        if (empty($r['ok']) || !is_array($r['body'])) break;
        $batch = $r['body'];
        if (!$batch) break;
        foreach ($batch as $pr) {
            $name = trim((string)($pr['name'] ?? ''));
            if ($name === '') continue;
            $rows[] = ['id' => (int)($pr['id'] ?? 0), 'title' => $name,
                       'price' => (int)preg_replace('~[^\d]~', '', (string)($pr['regular_price'] ?? '0')),
                       'status' => (string)($pr['status'] ?? '')];
        }
        // v8.64: نمونهٔ واقعی از عنوان‌های مقصد — برای وقتی تطبیق نمی‌خورد
        $fLog = ['📄 صفحهٔ ' . $page . ': ' . count($batch) . ' محصول (مجموع ' . count($rows) . ')'];
        if ($page === 1) {
            foreach (array_slice($rows, 0, 3) as $s) $fLog[] = '  • ' . mb_substr($s['title'], 0, 50);
        }
        reconProgress(['phase' => 'fetch', 'fetched' => count($rows), 'page' => $page,
            'log_add' => $fLog]);
        if (count($batch) < 100) break;
        usleep(150000);
    }
    return $rows;
}

/** همهٔ محصولات فعال باسلام. قیمت باسلام به ریال است. */
function reconFetchBsl(string $tk, int $vid, int $maxPages = 60): array {
    $rows = [];
    for ($page = 1; $page <= $maxPages; $page++) {
        $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?page=' . $page
             . '&per_page=100&statuses=2976&statuses=3790');
        if (empty($r['ok'])) break;
        $batch = $r['body']['data'] ?? [];
        if (!$batch) break;
        foreach ($batch as $pr) {
            if (!is_array($pr)) continue;
            $rev  = $pr['revision']['data'] ?? [];
            $name = trim((string)($pr['title'] ?? ($pr['name'] ?? ($rev['title'] ?? ''))));
            if ($name === '') continue;
            $rial = (int)($rev['primary_price'] ?? ($pr['primary_price'] ?? 0));
            $rows[] = ['id' => (int)($pr['id'] ?? 0), 'title' => $name,
                       'price' => $rial, 'price_toman' => (int)round($rial / 10),
                       'status' => (int)(is_array($pr['status'] ?? null)
                                   ? ($pr['status']['value'] ?? 0) : ($pr['status'] ?? 0))];
        }
        $fLog = ['📄 صفحهٔ ' . $page . ': ' . count($batch) . ' محصول (مجموع ' . count($rows) . ')'];
        if ($page === 1) {
            foreach (array_slice($rows, 0, 3) as $s) $fLog[] = '  • ' . mb_substr($s['title'], 0, 50);
        }
        reconProgress(['phase' => 'fetch', 'fetched' => count($rows), 'page' => $page,
            'log_add' => $fLog]);
        if (count($batch) < 100) break;
        usleep(150000);
    }
    return $rows;
}

/**
 * مقایسه و در صورت درخواست، اعمال تغییرات.
 * $mode برای موارد اضافی: off | draft | outofstock | delete
 */
function reconRun(array $cn, string $target, bool $apply = false,
                  string $mode = 'off', bool $fixPrice = true, bool $allProfiles = false): array {
    $out = ['ok' => true, 'target' => $target, 'apply' => $apply, 'mode' => $mode,
            'all_profiles' => $allProfiles,
            'expected' => 0, 'remote' => 0, 'extra' => [], 'price_diff' => [],
            'matched' => 0, 'matched_items' => [], 'deleted' => 0, 'repriced' => 0, 'failed' => 0];

    reconProgress(['phase' => 'profiles', 'log_add' => [$allProfiles
        ? '🔎 خواندن همهٔ پروفایل‌ها...'
        : '🔎 خواندن پروفایل‌های دارای همگام‌سازی دوره‌ای...']]);
    $pstats = null;
    $expected = reconExpected($target, $allProfiles, $pstats);
    $out['expected'] = count($expected);
    $out['profile_stats'] = $pstats;

    // v8.64: شرح تفکیکی هر پروفایل در گزارش زنده — تا معلوم باشد چرا
    // عددها این‌طور شده‌اند و کدام پروفایل کنار گذاشته شد.
    $plog = [];
    foreach (($pstats['profiles'] ?? []) as $ps) {
        $plog[] = ($ps['n'] > 0 ? '  ✓ ' : '  ⏭ ') . $ps['name']
            . ($ps['n'] > 0 ? (' — ' . $ps['n'] . ' محصول'
                . (!empty($ps['no_price']) ? ' (' . $ps['no_price'] . ' بدون قیمت)' : '')
                . (!empty($ps['why']) ? ' · ' . $ps['why'] : ''))
              : ' — ' . ($ps['why'] ?? ''));
    }
    $plog[] = '✅ ' . count($expected) . ' عنوان یکتا از '
            . (int)($pstats['used'] ?? 0) . ' پروفایل جمع شد'
            . ((int)($pstats['skipped'] ?? 0) > 0 ? ' · ' . (int)$pstats['skipped'] . ' پروفایل کنار گذاشته شد' : '');
    reconProgress(['phase' => 'profiles', 'expected' => count($expected), 'log_add' => $plog]);

    if (!$expected) {
        $out['ok'] = false;
        $out['error'] = $allProfiles
            ? 'هیچ پروفایلی محصولی برای مقایسه ندارد — اول استخراج کنید'
            : 'هیچ پروفایلی با همگام‌سازی دوره‌ای برای این مقصد پیدا نشد — گزینهٔ «همهٔ پروفایل‌ها» را بزنید';
        $out['hint_all_profiles'] = !$allProfiles && (int)($pstats['skipped'] ?? 0) > 0;
        return $out;
    }

    reconProgress(['phase' => 'fetch', 'log_add' => ['📥 دریافت محصولات '
        . ($target === 'woo' ? 'ووکامرس' : 'باسلام') . '...']]);
    if ($target === 'woo') {
        $w = $cn['woocommerce'] ?? [];
        if (empty($w['store_url'])) { $out['ok'] = false; $out['error'] = 'تنظیمات ووکامرس ناقص'; return $out; }
        $remote = reconFetchWoo($w);
    } else {
        $tk = (string)($cn['basalam']['token'] ?? '');
        $vid = (int)($cn['basalam']['vendor_id'] ?? 0);
        if ($tk === '' || $vid <= 0) { $out['ok'] = false; $out['error'] = 'تنظیمات باسلام ناقص'; return $out; }
        $remote = reconFetchBsl($tk, $vid);
    }
    $out['remote'] = count($remote);
    reconProgress(['phase' => 'compare', 'remote' => count($remote),
        'log_add' => ['✅ ' . count($remote) . ' محصول از مقصد دریافت شد', '⚖️ مقایسه...']]);
    if (!$remote) {
        $out['ok'] = false;
        $out['error'] = 'هیچ محصولی از مقصد دریافت نشد — برای احتیاط کاری انجام نشد';
        return $out;
    }

    // دسته‌بندی
    // v8.64: مقایسه هم گزارش زنده دارد — هر ۲۵ محصول یک به‌روزرسانی، و
    // چند نمونهٔ واقعی از هر دسته، تا کاربر ببیند دقیقاً چه اتفاقی می‌افتد.
    // v8.65: اول با شناسهٔ ثبت‌شده تطبیق بده، بعد با عنوان.
    // محصولی که در مقصد تغییر نام داده، با عنوان پیدا نمی‌شود ولی شناسه‌اش
    // همان است — بدون این، «اضافی» گزارش می‌شد و با حذف از بین می‌رفت.
    $idMap  = remoteMapById($target);
    $byKey  = is_array($pstats['by_key'] ?? null) ? $pstats['by_key'] : [];
    $byIdN  = 0;
    $cmpN = 0; $sampleExtra = []; $sampleDiff = []; $noPriceN = 0;
    foreach ($remote as $r) {
        $cmpN++;
        $rid = (int)($r['id'] ?? 0);
        $key = reconNormTitle($r['title']);
        $hit = $expected[$key] ?? null;
        if ($hit === null && $rid > 0 && isset($idMap[$rid]) && isset($byKey[$idMap[$rid]])) {
            $hit = $byKey[$idMap[$rid]];
            $byIdN++;
        }
        if ($hit === null) {
            $out['extra'][] = ['id' => $r['id'], 'title' => $r['title'], 'price' => $r['price']];
            if (count($sampleExtra) < 5) $sampleExtra[] = '  🗑 ' . mb_substr($r['title'], 0, 45);
        } else {
            $want = (int)$hit['price'];
            $have = $target === 'bsl' ? (int)($r['price_toman'] ?? 0) : (int)$r['price'];
            if ($want <= 0) {
                // قیمت مبدأ صفر است — مغایرت حساب نمی‌شود، وگرنه همه‌چیز صفر می‌شد
                $noPriceN++;
                $out['matched']++;
                if (count($out['matched_items']) < 500) {
                    $out['matched_items'][] = ['id' => $r['id'], 'title' => $r['title'], 'price' => $have];
                }
            } elseif ($have !== $want) {
                $out['price_diff'][] = ['id' => $r['id'], 'title' => $r['title'],
                    'from' => $have, 'to' => $want, 'profile' => (string)($hit['profile'] ?? '')];
                if (count($sampleDiff) < 5) $sampleDiff[] = '  💰 ' . mb_substr($r['title'], 0, 38)
                    . ' — ' . number_format($have) . ' → ' . number_format($want);
            } else {
                $out['matched']++;
                // v8.50: فهرست یکسان‌ها هم نگه داشته می‌شود تا شمارندهٔ آن قابل کلیک باشد
                if (count($out['matched_items']) < 500) {
                    $out['matched_items'][] = ['id' => $r['id'], 'title' => $r['title'], 'price' => $have];
                }
            }
        }
        if ($cmpN % 25 === 0) {
            reconProgress(['phase' => 'compare', 'cur' => $cmpN, 'cur_total' => count($remote),
                'extra' => count($out['extra']), 'diff' => count($out['price_diff']),
                'matched' => $out['matched'],
                'log_add' => ['⚖️ مقایسه ' . $cmpN . '/' . count($remote)
                    . ' — اضافی ' . count($out['extra'])
                    . '، مغایرت ' . count($out['price_diff'])
                    . '، یکسان ' . $out['matched']]]);
        }
    }
    $out['no_src_price'] = $noPriceN;
    $out['matched_by_id'] = $byIdN;
    $out['id_map_size'] = count($idMap);

    $doneLog = ['📊 اضافی: ' . count($out['extra'])
        . ' · مغایرت قیمت: ' . count($out['price_diff'])
        . ' · یکسان: ' . $out['matched']];
    if ($byIdN > 0) $doneLog[] = '🔗 ' . $byIdN . ' محصول با شناسهٔ ثبت‌شده تطبیق خورد '
        . '(عنوانشان در مقصد عوض شده بود)';
    if ($noPriceN > 0) $doneLog[] = 'ℹ️ ' . $noPriceN . ' محصول در مبدأ قیمت ندارد — قیمتشان مقایسه نشد';
    if ($sampleDiff)  { $doneLog[] = 'نمونهٔ مغایرت قیمت:';  foreach ($sampleDiff as $l) $doneLog[] = $l; }
    if ($sampleExtra) { $doneLog[] = 'نمونهٔ «در هیچ پروفایلی نیست»:'; foreach ($sampleExtra as $l) $doneLog[] = $l; }
    if (count($out['extra']) > 0 && count($out['extra']) === count($remote)) {
        $doneLog[] = '⚠️ هیچ محصولی تطبیق نخورد — احتمالاً عنوان‌های مقصد با پروفایل فرق دارند '
                   . '(پسوند پروفایل یا تغییر نام). قبل از «حذف»، فهرست را ببینید.';
    }
    reconProgress(['phase' => $apply ? 'apply' : 'done',
        'extra' => count($out['extra']), 'diff' => count($out['price_diff']),
        'matched' => $out['matched'], 'cur' => 0, 'cur_total' => 0,
        'log_add' => $doneLog]);

    if (!$apply) return $out;

    // --- اصلاح قیمت ---
    if ($fixPrice && $out['price_diff']) {
        foreach ($out['price_diff'] as $i => $d) {
            $okRow = false;
            if ($target === 'woo') {
                $r = wooReq($cn['woocommerce']['store_url'], $cn['woocommerce']['consumer_key'],
                    $cn['woocommerce']['consumer_secret'], 'PUT', 'products/' . $d['id'],
                    ['regular_price' => (string)$d['to']]);
                $okRow = !empty($r['ok']);
            } else {
                $tk = (string)$cn['basalam']['token']; $vid = (int)$cn['basalam']['vendor_id'];
                $bu = ['primary_price' => $d['to'] * 10];      // باسلام ریال می‌خواهد
                $r = bslReq($tk, 'PATCH', 'products/' . $d['id'], $bu);
                if ((int)($r['code'] ?? 0) === 404)
                    $r = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $d['id'], $bu);
                $okRow = !empty($r['ok']);
            }
            if ($okRow) $out['repriced']++; else $out['failed']++;
            $out['price_diff'][$i]['done'] = $okRow;
            reconProgress(['phase' => 'apply', 'step' => 'price',
                'repriced' => $out['repriced'], 'failed' => $out['failed'],
                'cur' => $i + 1, 'cur_total' => count($out['price_diff']),
                'log_add' => [($okRow ? '💰 ' : '❌ ') . mb_substr($d['title'], 0, 40)
                    . ' — ' . number_format($d['from']) . ' → ' . number_format($d['to'])]]);
            usleep(200000);
        }
    }

    // --- حذف/بازنشستگی موارد اضافی ---
    if ($mode !== 'off' && $out['extra']) {
        // v8.47: مبنای درصد باید کل محصولات مقصد باشد. retireGuard خودش
        // removed را به مخرج اضافه می‌کند، پس «باقی‌مانده» را می‌دهیم.
        $kept = max(0, count($remote) - count($out['extra']));
        $guard = retireGuard(count($out['extra']), $kept, $cn);
        $out['guard'] = $guard;
        if (empty($guard['allow'])) {
            $out['skipped_delete'] = $guard['reason'];
            reconProgress(['log_add' => ['🛑 حذف انجام نشد: ' . $guard['reason']]]);
            return $out;
        }
        foreach ($out['extra'] as $i => $d) {
            $okRow = false;
            if ($target === 'woo') {
                $w = $cn['woocommerce'];
                if ($mode === 'delete') {
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'DELETE', 'products/' . $d['id'] . '?force=false');
                } elseif ($mode === 'outofstock') {
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'PUT', 'products/' . $d['id'], ['stock_status' => 'outofstock', 'stock_quantity' => 0]);
                } else {
                    $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                        'PUT', 'products/' . $d['id'], ['status' => 'draft']);
                }
                $okRow = !empty($r['ok']);
            } else {
                $tk = (string)$cn['basalam']['token']; $vid = (int)$cn['basalam']['vendor_id'];
                if ($mode === 'delete') {
                    // v8.62: باسلام حذف واقعی ندارد؛ بایگانی می‌کنیم
                    $r = bslArchiveProduct($tk, $vid, (int)$d['id']);
                } elseif ($mode === 'outofstock') {
                    $r = bslEditProduct($tk, $vid, (int)$d['id'], ['stock' => 0]);
                } else {
                    $r = bslReq($tk, 'PATCH', 'products/' . $d['id'], ['status' => 3790]);
                    if ((int)($r['code'] ?? 0) === 404) $r = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $d['id'], ['status' => 3790]);
                }
                $okRow = !empty($r['ok']);
            }
            if ($okRow) $out['deleted']++; else $out['failed']++;
            $out['extra'][$i]['done'] = $okRow;
            reconProgress(['phase' => 'apply', 'step' => 'extra',
                'deleted' => $out['deleted'], 'failed' => $out['failed'],
                'cur' => $i + 1, 'cur_total' => count($out['extra']),
                'log_add' => [($okRow ? '🗑 ' : '❌ ') . mb_substr($d['title'], 0, 45)]]);
            usleep(200000);
        }
    }
    return $out;
}

/** اعلان نتیجهٔ بازنشستگی به پیام‌رسان‌ها */
function notifRetire(array $cn, array $res, string $profileName = ''): array {
    if (empty($cn['notif_events']['retire'])) return ['ok' => true, 'skipped' => 'disabled'];
    if (notifPrereq($cn) !== null) return ['ok' => false];
    $modeLbl = retireModes()[$res['mode'] ?? 'off'] ?? '';
    if (!empty($res['guard']['blocked'])) {
        return ['ok' => true, 'delivery' => notifSend($cn,
            "🛑 بازنشستگی خودکار متوقف شد" . ($profileName !== '' ? "\nپروفایل: {$profileName}" : '')
            . "\nعلت: " . ($res['guard']['reason'] ?? '')
            . "\nهیچ محصولی تغییر نکرد — اگر درست است، دستی اجرا کنید.")];
    }
    if ((int)($res['retired'] ?? 0) <= 0) return ['ok' => true, 'skipped' => 'nothing'];
    $lines = ["🗂 بازنشستگی محصولات رفته از مبدأ" . ($profileName !== '' ? " — {$profileName}" : ''),
              'اقدام: ' . $modeLbl,
              'انجام‌شده: ' . (int)$res['retired']
              . ' · یافت‌نشده: ' . (int)($res['not_found'] ?? 0)
              . ' · ناموفق: ' . (int)($res['failed'] ?? 0)];
    foreach (array_slice($res['items'] ?? [], 0, 8) as $it) {
        $lines[] = '• ' . ($it['title'] ?? '') . ' — ' . ($it['reason'] ?? '');
    }
    return ['ok' => true, 'delivery' => notifSend($cn, implode("\n", $lines))];
}

/**
 * v8.30: اعلان تغییرات سایت مبدأ.
 * نتیجهٔ استخراج را می‌گیرد و گران/ارزان شدن و موجود/ناموجود شدن را
 * به پیام‌رسان‌ها گزارش می‌کند. برای جلوگیری از هرزنامه، به‌جای یک پیام
 * برای هر محصول، یک خلاصهٔ فشرده با نمونه‌ها فرستاده می‌شود.
 */
function notifSourceChanges(array $cn, array $res, string $profileName = '', int $sampleLimit = 5): array {
    $ne = $cn['notif_events'] ?? [];
    $wantPrice = !empty($ne['src_price']);
    $wantStock = !empty($ne['src_stock']);
    if (!$wantPrice && !$wantStock) return ['ok' => true, 'skipped' => 'disabled'];
    if (notifPrereq($cn) !== null) return ['ok' => false, 'error' => notifPrereq($cn)];

    $up = (int)($res['price_up'] ?? 0);
    $down = (int)($res['price_down'] ?? 0);
    $noPrice = (int)($res['no_price'] ?? 0);
    $gone = (int)($res['gone_from_site'] ?? 0);
    $back = 0;
    foreach (($res['new_items'] ?? []) as $it) {
        if (($it['reason'] ?? '') === 'دوباره موجود شد') $back++;
    }

    $blocks = [];

    if ($wantPrice && ($up > 0 || $down > 0)) {
        $lines = ["💰 تغییر قیمت در سایت مبدأ" . ($profileName !== '' ? " — {$profileName}" : '')];
        $lines[] = "▲ گران شد: {$up}   ▼ ارزان شد: {$down}";
        $n = 0;
        foreach (($res['changed_items'] ?? []) as $it) {
            if ($n >= $sampleLimit) break;
            $arrow = ($it['dir'] ?? '') === 'up' ? '▲' : '▼';
            $pct = isset($it['pct']) ? (($it['pct'] > 0 ? '+' : '') . $it['pct'] . '٪') : '';
            $lines[] = $arrow . ' ' . mb_substr((string)($it['title'] ?? ''), 0, 40)
                     . "\n   " . ($it['old_price'] ?? '') . ' ← ' . ($it['new_price'] ?? '') . ' ' . $pct;
            $n++;
        }
        $rest = ($up + $down) - $n;
        if ($rest > 0) $lines[] = "... و {$rest} مورد دیگر";
        $blocks[] = implode("\n", $lines);
    }

    if ($wantStock && ($noPrice > 0 || $gone > 0 || $back > 0)) {
        $lines = ["📦 تغییر موجودی در سایت مبدأ" . ($profileName !== '' ? " — {$profileName}" : '')];
        if ($noPrice > 0) $lines[] = "🚫 ناموجود شد: {$noPrice}";
        if ($gone > 0)    $lines[] = "❌ از سایت حذف شد: {$gone}";
        if ($back > 0)    $lines[] = "✅ دوباره موجود شد: {$back}";
        $n = 0;
        foreach (($res['removed_items'] ?? []) as $it) {
            if ($n >= $sampleLimit) break;
            $why = $it['reason'] ?? '';
            if ($why === 'بدون قیمت') continue;   // محصول تازه‌ای که هیچ‌وقت قیمت نداشته
            $lines[] = '• ' . mb_substr((string)($it['title'] ?? ''), 0, 45) . ' — ' . $why;
            $n++;
        }
        $blocks[] = implode("\n", $lines);
    }

    if (!$blocks) return ['ok' => true, 'sent' => 0, 'nothing' => true];

    $sentCount = 0; $last = [];
    foreach ($blocks as $b) { $last = notifSend($cn, $b); $sentCount++; }
    return ['ok' => true, 'sent' => $sentCount, 'price_up' => $up, 'price_down' => $down,
            'no_price' => $noPrice, 'gone' => $gone, 'back' => $back, 'delivery' => $last];
}

/**
 * v8.30: اعلان شکست یک اجرا. سکوت بدترین حالت است — اگر کران‌جاب
 * خراب شود باید خبردار شوید، نه اینکه روزها بی‌صدا بماند.
 */
function notifRunFailure(array $cn, string $stage, string $profileName, string $error): array {
    if (empty($cn['notif_events']['run_fail'])) return ['ok' => true, 'skipped' => 'disabled'];
    if (notifPrereq($cn) !== null) return ['ok' => false];
    $msg = "⚠️ خطا در اجرای خودکار\nمرحله: {$stage}"
         . ($profileName !== '' ? "\nپروفایل: {$profileName}" : '')
         . "\nعلت: " . mb_substr($error, 0, 200);
    return ['ok' => true, 'delivery' => notifSend($cn, $msg)];
}

/**
 * اجرای همهٔ بررسی‌های فعال — همان چیزی که کران‌جاب صدا می‌زند.
 * ترتیب عمدی: سفارش (پول)، پیام (مشتری منتظر است)، محصول (اطلاعی).
 */
function bslCheckNotifications(array $cn): array {
    $why = notifPrereq($cn);
    if ($why !== null) return [];
    $ne = $cn['notif_events'] ?? [];
    $out = [];
    if (!empty($ne['order_new']) || !empty($ne['order_status'])) {
        $r = notifCheckOrders($cn);
        if (!empty($r['found'])) $out['orders'] = $r['found'];
    }
    if (!empty($ne['chat_msg'])) {
        $r = notifCheckChats($cn);
        if (!empty($r['found'])) $out['chats'] = $r['found'];
    }
    if (!empty($ne['product_status']) || !empty($ne['product_new'])) {
        $r = notifCheckProducts($cn);
        if (!empty($r['found'])) $out['products'] = $r['found'];
    }
    return $out;
}

/* دکمه‌های تست — هر بررسی را جدا اجرا و نتیجه را گزارش می‌کند */
if (isset($_GET['notif_test'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $kind = $_GET['kind'] ?? '';
    $cn = loadConnections();
    $why = notifPrereq($cn);
    if ($why !== null) { echo json_encode(['ok' => false, 'error' => $why], JSON_UNESCAPED_UNICODE); exit; }

    if ($kind === 'orders')        $r = notifCheckOrders($cn, true);
    elseif ($kind === 'chats')     $r = notifCheckChats($cn, true);
    elseif ($kind === 'products')  $r = notifCheckProducts($cn, true);
    elseif ($kind === 'ping') {
        // v8.37: پینگ آزمایشی — فاصلهٔ زمانی را نادیده می‌گیرد و
        // وضعیت را ذخیره نمی‌کند تا پینگ واقعی بعدی از دست نرود
        $pr = notifCronPing($cn, ['profiles' => []], true);
        $r = ['ok' => !empty($pr['ok']), 'found' => 1, 'total_seen' => 1,
              'sent' => $pr['delivery'] ?? [], 'sample' => $pr['message'] ?? ''];
        if (!empty($pr['error'])) { $r['ok'] = false; $r['error'] = $pr['error']; }
    }
    elseif ($kind === 'source') {
        // v8.30: از آخرین گزارش استخراج استفاده می‌کند تا پیام واقعی باشد
        $rep = null;
        foreach (glob(__DIR__ . '/extract_report_*.json') ?: [] as $f) {
            $d = json_decode((string)@file_get_contents($f), true);
            if (is_array($d) && (($d['price_up'] ?? 0) || ($d['price_down'] ?? 0)
                || ($d['no_price'] ?? 0) || ($d['gone_from_site'] ?? 0))) { $rep = $d; break; }
            if ($rep === null && is_array($d)) $rep = $d;
        }
        if ($rep === null) {
            $rep = ['price_up' => 1, 'price_down' => 1, 'no_price' => 1, 'gone_from_site' => 0,
                'changed_items' => [
                    ['title' => 'نمونه — کالای گران‌شده', 'old_price' => '100,000', 'new_price' => '130,000', 'dir' => 'up', 'pct' => 30],
                    ['title' => 'نمونه — کالای ارزان‌شده', 'old_price' => '80,000', 'new_price' => '60,000', 'dir' => 'down', 'pct' => -25]],
                'removed_items' => [['title' => 'نمونه — کالای ناموجود', 'reason' => 'ناموجود شد']],
                'new_items' => []];
        }
        // در حالت تست، هر دو نوع اعلان را صرف‌نظر از تنظیمات بفرست
        $cnTest = $cn;
        $cnTest['notif_events']['src_price'] = true;
        $cnTest['notif_events']['src_stock'] = true;
        $sr = notifSourceChanges($cnTest, $rep, 'تست');
        $r = ['ok' => !empty($sr['ok']), 'found' => (int)($sr['sent'] ?? 0),
              'total_seen' => (int)($rep['extracted'] ?? 0),
              'sent' => $sr['delivery'] ?? [],
              'sample' => '▲ گران: ' . (int)($sr['price_up'] ?? 0)
                        . ' | ▼ ارزان: ' . (int)($sr['price_down'] ?? 0)
                        . ' | 🚫 ناموجود: ' . (int)($sr['no_price'] ?? 0)];
        if (!empty($sr['nothing'])) $r['sample'] = 'تغییری برای گزارش نبود';
    }
    else { echo json_encode(['ok' => false, 'error' => 'نوع تست نامعتبر']); exit; }

    echo json_encode($r, JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v8.32: اندپوینت‌های مودال استعلام
 *  دکمه‌های استعلام حالا اول لیست را نشان می‌دهند، بعد کاربر تصمیم
 *  می‌گیرد چه چیزی به پیام‌رسان‌ها برود.
 * ===================================================================== */

/** لیست سفارش‌های غرفه — برای مودال */
if (isset($_GET['bsl_orders_list'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cn = loadConnections();
    $tk = trim((string)($cn['basalam']['token'] ?? ''));
    $vid = (int)($cn['basalam']['vendor_id'] ?? 0);
    if ($tk === '' || $vid <= 0) {
        echo json_encode(['ok' => false, 'error' => 'تنظیمات باسلام ناقص است'], JSON_UNESCAPED_UNICODE); exit;
    }
    $per = min(30, max(5, (int)($_GET['per_page'] ?? 20)));   // سقف مستندات: ۳۰
    $filter = (string)($_GET['filter'] ?? 'all');
    $ep = 'vendor-parcels?items.vendor_ids=' . $vid . '&per_page=' . $per;
    if ($filter === 'unsent') $ep .= '&statuses=' . implode(',', bslUnsentStatuses());
    $cur = trim((string)($_GET['cursor'] ?? ''));
    if ($cur !== '') $ep .= '&cursor=' . rawurlencode($cur);

    $r = bslReq($tk, 'GET', $ep);
    if (!$r['ok']) {
        echo json_encode(['ok' => false,
            'error' => bslApiError($r, 'دریافت سفارش‌ها ناموفق', 'vendor-parcels', 'vendor.parcel.read')],
            JSON_UNESCAPED_UNICODE); exit;
    }
    $rows = [];
    foreach (($r['body']['data'] ?? []) as $o) { if (is_array($o)) $rows[] = bslNormalizeParcel($o); }
    $unsent = 0;
    foreach ($rows as $n) { if ($n['unsent']) $unsent++; }
    echo json_encode(['ok' => true, 'rows' => $rows, 'total' => count($rows), 'unsent' => $unsent,
        'filter' => $filter, 'next_cursor' => (string)($r['body']['next_cursor'] ?? '')],
        JSON_UNESCAPED_UNICODE);
    exit;
}

/** لیست گفتگوها — برای مودال */
if (isset($_GET['bsl_chats_list'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cn = loadConnections();
    $tk = trim((string)($cn['basalam']['token'] ?? ''));
    if ($tk === '') {
        echo json_encode(['ok' => false, 'error' => 'توکن باسلام تنظیم نشده'], JSON_UNESCAPED_UNICODE); exit;
    }
    $limit = min(50, max(5, (int)($_GET['limit'] ?? 20)));
    $filter = (string)($_GET['filter'] ?? 'all');
    $ep = 'chats?limit=' . $limit . '&order_by=updated_at';
    if ($filter === 'unseen') $ep .= '&filters=unseen';   // فیلتر رسمی مستندات

    $r = bslReq($tk, 'GET', $ep);
    if (!$r['ok']) {
        echo json_encode(['ok' => false,
            'error' => bslApiError($r, 'دریافت گفتگوها ناموفق', 'chats', 'customer.chat.read')],
            JSON_UNESCAPED_UNICODE); exit;
    }
    $raw = $r['body']['data']['chats'] ?? ($r['body']['data'] ?? []);
    $rows = [];
    foreach ($raw as $c) { if (is_array($c)) $rows[] = bslNormalizeChat($c); }
    $unseen = 0;
    foreach ($rows as $n) { if ($n['unseen'] > 0) $unseen++; }
    echo json_encode(['ok' => true, 'rows' => $rows, 'total' => count($rows), 'unseen' => $unseen,
        'filter' => $filter], JSON_UNESCAPED_UNICODE);
    exit;
}

/**
 * ارسال موارد انتخاب‌شده به پیام‌رسان‌ها.
 * kind=orders|chats و ids=فهرست شناسه‌های جداشده با کاما.
 * اگر ids خالی باشد، همهٔ موارد «اقدام‌نشده» فرستاده می‌شوند.
 */
if (isset($_GET['bsl_notify_selected'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cn = loadConnections();
    $why = notifPrereq($cn);
    if ($why !== null) { echo json_encode(['ok' => false, 'error' => $why], JSON_UNESCAPED_UNICODE); exit; }
    $tk = (string)$cn['basalam']['token'];
    $vid = (int)$cn['basalam']['vendor_id'];
    $kind = (string)($_GET['kind'] ?? '');
    $idsRaw = trim((string)($_GET['ids'] ?? ''));
    $want = $idsRaw === '' ? [] : array_filter(array_map('intval', explode(',', $idsRaw)));
    $digest = !empty($_GET['digest']);   // یک پیام خلاصه به‌جای چند پیام جدا

    if ($kind === 'orders') {
        $r = bslReq($tk, 'GET', 'vendor-parcels?items.vendor_ids=' . $vid . '&per_page=30');
        if (!$r['ok']) { echo json_encode(['ok' => false,
            'error' => bslApiError($r, 'دریافت سفارش‌ها ناموفق', 'vendor-parcels', 'vendor.parcel.read')],
            JSON_UNESCAPED_UNICODE); exit; }
        $picked = [];
        foreach (($r['body']['data'] ?? []) as $o) {
            if (!is_array($o)) continue;
            $n = bslNormalizeParcel($o);
            if ($want ? in_array($n['parcel_id'], $want, true) : $n['unsent']) $picked[] = $n;
        }
    } elseif ($kind === 'chats') {
        $r = bslReq($tk, 'GET', 'chats?limit=50&order_by=updated_at');
        if (!$r['ok']) { echo json_encode(['ok' => false,
            'error' => bslApiError($r, 'دریافت گفتگوها ناموفق', 'chats', 'customer.chat.read')],
            JSON_UNESCAPED_UNICODE); exit; }
        $raw = $r['body']['data']['chats'] ?? ($r['body']['data'] ?? []);
        $picked = [];
        foreach ($raw as $c) {
            if (!is_array($c)) continue;
            $n = bslNormalizeChat($c);
            if ($want ? in_array($n['chat_id'], $want, true) : $n['unseen'] > 0) $picked[] = $n;
        }
    } else { echo json_encode(['ok' => false, 'error' => 'نوع نامعتبر'], JSON_UNESCAPED_UNICODE); exit; }

    if (!$picked) {
        echo json_encode(['ok' => true, 'sent' => 0, 'delivery' => [],
            'note' => 'موردی برای ارسال نبود'], JSON_UNESCAPED_UNICODE); exit;
    }

    $delivery = []; $sent = 0;
    if ($digest) {
        // یک پیام فشرده — برای وقتی موارد زیاد است و نمی‌خواهیم پیام‌رسان پر شود
        if ($kind === 'orders') {
            $lines = ['📦 سفارش‌های ارسال‌نشده (' . count($picked) . ' مورد)'];
            $sum = 0;
            foreach ($picked as $n) {
                $sum += $n['amount'];
                $lines[] = '• #' . ($n['order_id'] ?: $n['parcel_id']) . ' — ' . $n['customer']
                         . ' — ' . number_format($n['amount']) . ' تومان — ' . $n['status'];
            }
            $lines[] = '━━━━━━━━━━';
            $lines[] = 'جمع: ' . number_format($sum) . ' تومان';
        } else {
            $tot = 0;
            foreach ($picked as $n) { $tot += $n['unseen']; }
            $lines = ['💬 پیام‌های خوانده‌نشده (' . count($picked) . ' گفتگو · ' . $tot . ' پیام)'];
            foreach ($picked as $n) {
                $lines[] = '• ' . $n['who'] . ($n['unseen'] > 0 ? ' (' . $n['unseen'] . ')' : '')
                         . ' — ' . mb_substr($n['text'], 0, 60);
            }
        }
        $delivery = notifSend($cn, implode("\n", $lines));
        $sent = 1;
    } else {
        foreach ($picked as $n) {
            if ($kind === 'orders') {
                $msg = bslParcelMsg($n, '📦 سفارش ارسال‌نشده');
            } else {
                // v8.33: متن کامل پیام‌های مشتری، نه فقط آخرین پیام
                $body = bslFetchChatMessages($tk, $n['chat_id'], max(1, min(10, $n['unseen'] ?: 1)));
                $msg = bslChatMsg($n, '💬 پیام خوانده‌نشده', $body);
            }
            $delivery = notifSend($cn, $msg);
            $sent++;
            if ($sent >= 20) break;   // سقف ایمنی برای جلوگیری از هرزنامه
        }
    }
    echo json_encode(['ok' => true, 'sent' => $sent, 'picked' => count($picked),
        'delivery' => $delivery, 'digest' => $digest], JSON_UNESCAPED_UNICODE);
    exit;
}

function bslSendToBaleh(string $token, string $chatId, string $text): bool {
$url = 'https://tapi.bale.ai/bot' . $token . '/sendMessage';
$ch = curl_init($url); curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_POSTFIELDS => json_encode(['chat_id' => $chatId, 'text' => $text], JSON_UNESCAPED_UNICODE), CURLOPT_HTTPHEADER => ['Content-Type: application/json'], CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 10]);
$resp = curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
return $code >= 200 && $code < 300;
}
function bslSendToRubika(string $token, string $chatId, string $text): bool {
$url = 'https://api.rubika.ir/v1/bot' . $token . '/sendMessage';
$ch = curl_init($url); curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_POSTFIELDS => json_encode(['chat_id' => $chatId, 'text' => $text], JSON_UNESCAPED_UNICODE), CURLOPT_HTTPHEADER => ['Content-Type: application/json'], CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 10]);
$resp = curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
return $code >= 200 && $code < 300;
}

function bslTryCreateWithFallback(string $tk, int $vid, array $bp, array $fallbackCatIds, string $pTitle, bool $autoCat, array $bslFlatCats, array $cData): array {
$tried = [(int)($bp['category_id'] ?? 0)];
foreach ($fallbackCatIds as $fc) {
$fc = (int)$fc; if ($fc <= 0 || in_array($fc, $tried)) continue; $tried[] = $fc;
if (!empty($cData) && is_array($cData)) $fc = findLeafCategory($fc, $cData);
$bp['category_id'] = $fc;
$r = bslReq($tk, 'POST', 'vendors/' . $vid . '/products', $bp);
if ($r['ok'] && !empty($r['body']['id'])) return ['ok' => true, 'body' => $r['body'], 'used_cat_id' => $fc, 'tried' => $tried];
$em = $r['body']['error_description'] ?? $r['body']['message'] ?? $r['body']['error'] ?? '';
if (is_array($em)) $em = json_encode($em, JSON_UNESCAPED_UNICODE);
if (mb_stripos($em, 'دسته') === false && mb_stripos($em, 'category') === false && mb_stripos($em, 'فرزند') === false) return ['ok' => false, 'error' => $em, 'tried' => $tried];
}
if ($autoCat && !empty($bslFlatCats)) {
