if($r['code']===401)$errMsg='توکن نامعتبر (۴۰۱)';
elseif($r['code']===403)$errMsg='دسترسی ممنوع (۴۰۳) — احراز هویت ناقص یا توکن بدون مجوز';
elseif($r['code']===0){
