echo json_encode(['ok'=>false,'error'=>$errMsg,'http_code'=>$r['code'],'curl_error'=>trim((string)($r['error']??'')),'mode'=>(string)($r['mode']??''),'detail'=>$r['body']['detail']??($r['raw']??'')], JSON_UNESCAPED_UNICODE);
