if ($modelId === '') { echo json_encode(['ok'=>false,'error'=>'ارائه‌دهنده مدلی ندارد'],JSON_UNESCAPED_UNICODE); exit; }
$payload=['messages'=>[['role'=>'user','content'=>'سلام']], 'temperature'=>0.1, 'max_tokens'=>300];
