/* =====================================================================
 *  v9.20: مدیریت چند-ارائه‌دهندهٔ هوش مصنوعی
 * ===================================================================== */
/* وضعیت ارائه‌دهنده‌ها (خلاصهٔ ماسک‌شده برای رابط کاربری) */
if (isset($_GET['ai_providers_status'])) {
header('Content-Type: application/json; charset=UTF-8');
echo json_encode(aiProvidersSummary(), JSON_UNESCAPED_UNICODE);
exit;
}
/* درون‌ریزی فایل JSON تنظیمات ارائه‌دهنده‌ها */
if (($_POST['action'] ?? '') === 'ai_import_providers') {
header('Content-Type: application/json; charset=UTF-8');
$jsonStr = trim((string)($_POST['providers_json'] ?? ''));
$parsed = json_decode($jsonStr, true);
if (!is_array($parsed)) { echo json_encode(['ok'=>false,'error'=>'JSON نامعتبر: '.json_last_error_msg()],JSON_UNESCAPED_UNICODE); exit; }
// اگر کل بدنه داخل کلید providers بود بازش کن
if (isset($parsed['providers']) && is_array($parsed['providers'])) $parsed = $parsed['providers'];
$providers = aiNormalizeProviders($parsed);
if (empty($providers)) { echo json_encode(['ok'=>false,'error'=>'در JSON هیچ ارائه‌دهندهٔ معتبری پیدا نشد'],JSON_UNESCAPED_UNICODE); exit; }
$totalModels = 0;
foreach ($providers as $p) $totalModels += count($p['models']);
// اگر فعلاً انتخابی نیست، اولین ارائه‌دهندهٔ روشن را فعال کن
$sel = aiSelected();
if ($sel['provider'] === '' || !isset($providers[$sel['provider']])) {
    $first = null;
    foreach ($providers as $id => $p) { if (($p['enabled'] ?? true) && !empty($p['models'])) { $first = $id; break; } }
    if ($first !== null) aiSaveSelected($first, $providers[$first]['models'][0]['id'] ?? '');
}
$ok = aiProvidersSave($providers);
echo json_encode(['ok'=>$ok, 'providers'=>count($providers), 'models'=>$totalModels,
    'message'=>count($providers).' ارائه‌دهنده با '.$totalModels.' مدل درون‌ریزی شد'], JSON_UNESCAPED_UNICODE);
exit;
}
/* انتخاب ارائه‌دهنده/مدل فعال */
if (($_POST['action'] ?? '') === 'ai_select') {
header('Content-Type: application/json; charset=UTF-8');
$pid = trim($_POST['provider_id'] ?? '');
$mid = trim($_POST['model_id'] ?? '');
$providers = aiProvidersLoad();
if (!isset($providers[$pid])) { echo json_encode(['ok'=>false,'error'=>'ارائه‌دهنده یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
if ($mid === '') $mid = $providers[$pid]['models'][0]['id'] ?? '';
aiSaveSelected($pid, $mid);
echo json_encode(['ok'=>true,'provider'=>$pid,'model'=>$mid], JSON_UNESCAPED_UNICODE);
exit;
}
/* v9.63: روشن/خاموش کردن انفرادیِ یک ارائه‌دهنده — ارائه‌دهندهٔ خاموش به‌همراهِ
   همهٔ مدل‌هایش از «تست مدل‌ها» خارج می‌شود (تست انبوه ارائه‌دهنده‌های خاموش
   را رد می‌کند) ولی داده‌ها و تنظیماتش باقی می‌ماند. */
if (($_POST['action'] ?? '') === 'ai_toggle_provider') {
header('Content-Type: application/json; charset=UTF-8');
$pid = trim($_POST['provider_id'] ?? '');
$providers = aiProvidersLoad();
if (!isset($providers[$pid])) { echo json_encode(['ok'=>false,'error'=>'ارائه‌دهنده یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
$on = !empty($_POST['enabled']);
$providers[$pid]['enabled'] = $on;
$ok = aiProvidersSave($providers);
// اگر این ارائه‌دهنده «فعال» (انتخاب اصلی اتوماسیون) بود و خاموش شد، فعال را عوض کن
if ($on === false && aiSelected()['provider'] === $pid) {
    $cfg = aiActiveConfig();
    $np = is_array($cfg['provider']) ? ($cfg['provider']['id'] ?? '') : '';
    $nm = $cfg['model'] ?? '';
    if ($np !== '' && $np !== $pid) aiSaveSelected($np, $nm);
}
echo json_encode(['ok'=>$ok,'provider'=>$pid,'enabled'=>$on], JSON_UNESCAPED_UNICODE);
exit;
}
/* تست یک مدل و ذخیرهٔ نتیجه در همان مدل */
if (($_POST['action'] ?? '') === 'ai_test_one') {
header('Content-Type: application/json; charset=UTF-8');
$pid = trim($_POST['provider_id'] ?? '');
$mid = trim($_POST['model_id'] ?? '');
$providers = aiProvidersLoad();
if (!isset($providers[$pid])) { echo json_encode(['ok'=>false,'error'=>'ارائه‌دهنده یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
$found = false;
foreach ($providers[$pid]['models'] as $i => $m) {
    if (($m['id'] ?? '') === $mid) { $found = true; break; }
}
if (!$found) { echo json_encode(['ok'=>false,'error'=>'مدل یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
// v9.52: پیام تست و دستهٔ تستِ قابل‌تنظیم (پیش‌فرض «سلام» و «ادو پرفیوم»)
$testMsg = trim((string)($_POST['msg'] ?? 'سلام'));
if ($testMsg === '') $testMsg = 'سلام';
$testCat = trim((string)($_POST['cat'] ?? 'ادو پرفیوم'));
if ($testCat === '') $testCat = 'ادو پرفیوم';
$t0 = microtime(true);
// v9.57: سقف توکن برای تست بالاتر رفت (۳۰۰) — مدل‌های reasoning (مثل gpt-oss،
// qwen، nemotron و...) اول روی «فکر کردن» توکن می‌سوزانند و اگر سقف پایین باشد
// (۳۰) هیچ‌وقت به content نمی‌رسند و پاسخِ خالی برمی‌گردد.
$payload = ['messages'=>[['role'=>'user','content'=>$testMsg]], 'temperature'=>0.3, 'max_tokens'=>300];
$r = aiProviderCall($providers[$pid], $mid, $payload, aiNetCfg());
$latency = (int)round((microtime(true) - $t0) * 1000);
$code = (int)$r['code'];
$ok = $code === 200;
$body = $r['body'] ?? [];
$response = $ok ? aiExtractText($body) : '';   // v9.54: استخراج مقاومِ متنِ پاسخ
$err = $ok ? '' : ($body['error']['message'] ?? ($body['message'] ?? ($r['error'] ?? ('HTTP '.$code))));
$rateLimited = in_array($code, [429], true);
$catResponse = aiRunTestCategory($providers[$pid], $mid, $testCat, aiTestCategoryData());
$details = ['status'=>$code, 'error'=>mb_substr((string)$err,0,300), 'response'=>mb_substr((string)$response,0,300),
            'catResponse'=>(string)$catResponse, 'testMsg'=>$testMsg, 'testCat'=>$testCat,
            'latencyMs'=>$latency, 'testedAt'=>gmdate('c')];
foreach ($providers[$pid]['models'] as $i => $m) {
    if (($m['id'] ?? '') === $mid) {
        $providers[$pid]['models'][$i]['tested'] = true;
        $providers[$pid]['models'][$i]['available'] = $ok;
        $providers[$pid]['models'][$i]['rateLimited'] = $rateLimited;
        $providers[$pid]['models'][$i]['testDetails'] = $details;
        break;
    }
}
aiProvidersSave($providers);
echo json_encode(['ok'=>true, 'model'=>$mid, 'provider'=>$pid, 'available'=>$ok,
    'rateLimited'=>$rateLimited, 'latencyMs'=>$latency, 'code'=>$code, 'error'=>$err,
    'response'=>mb_substr($response,0,200), 'catResponse'=>(string)$catResponse], JSON_UNESCAPED_UNICODE);
exit;
}
/* تست همهٔ مدل‌های فعال (SSE) — با سقف به‌ازای هر ارائه‌دهنده */
/* =====================================================================
 *  v9.24: تست مدل‌ها به‌صورت کارِ پس‌زمینهٔ سمت سرور
 *
 *  ?ai_test_start=1  → شروع تست در پس‌زمینه (جدا از مرورگر) + پاسخ فوری
 *  ?ai_test_all=1    → نامِ سازگار (همان شروع) برای نسخه‌های قبلی
 *  ?ai_test_status=1 → وضعیت فعلی کار (poll شده توسط مرورگر)
 *  ?ai_test_stop=1   → سیگنال توقف صریح
 * ===================================================================== */
if (isset($_GET['ai_test_status'])) {
header('Content-Type: application/json; charset=UTF-8');
$st = aiTestStateLoad();
/* v9.45: نگهبانِ گیرکردن. اگر پردازهٔ پس‌زمینه مرده باشد (کشته شده)،
   running تا ابد true می‌ماند و مرورگر بی‌نهایت poll می‌کند. وقتی چند دقیقه
   است هیچ به‌روزرسانی‌ای (updated_at) نیامده، یعنی پردازه دیگر زنده نیست —
   آن را «متوقف شده» علامت بزن تا رابط کاربری رها شود. همین الگو در جای‌های
   دیگر (extractProgress و... ) هم هست. */
if (!empty($st['running']) && empty($st['done'])) {
    $stAt = (int)($st['updated_at'] ?? $st['started_at'] ?? 0);
    $idle = $stAt > 0 ? (time() - $stAt) : PHP_INT_MAX;
    $stall = max(120, (int)(loadConnections()['ai_test_stall_sec'] ?? 300));
    if ($idle > $stall) {
        $st['running'] = false;
        $st['done'] = true;
        $st['stopped'] = true;
        $st['stalled'] = true;
        $st['summary'] = 'گیر کرد (پردازهٔ پس‌زمینه دیگر پاسخ نمی‌دهد) — متوقف شد';
        aiTestStateSave($st);
    }
}
echo json_encode($st, JSON_UNESCAPED_UNICODE);
exit;
}
if (isset($_GET['ai_test_stop'])) {
    /* v9.42: فایل توقف را مقاوم بنویس — writeJsonFile اول با قفل تلاش می‌کند
       و اگر قفل روی FUSE/ترموکس پشتیبانی نشد، بدون قفل می‌نویسد. قبلاً با
       LOCK_EX مستقیم اگر نوشتن بی‌صدا fail می‌شد، پردازهٔ پس‌زمینه هیچ‌وقت
       توقف را نمی‌دید. */
    writeJsonFile(AI_TEST_STOP_FILE, ['stop' => true, 'time' => time()]);
    $st = aiTestStateLoad();
    $st['stopping'] = true;
    aiTestStateSave($st);
    /* v9.45: اگر پردازهٔ پس‌زمینه دیگر زنده نباشد (کشته شده)، هیچ‌کس نمی‌آید
       running را false کند و رابط کاربری تا ابد «در حال اجراست» نشان می‌داد.
       اینجا حالت را مستقیم «متوقف شده» می‌کنیم تا poll مرورگر همان لحظه ببیند
       کار تمام شده. پردازهٔ زنده هم وقتی سیگنال توقف را می‌بیند خودش همان
       نتیجه را می‌نویسد (همان مقدار). */
    if (!empty($st['running']) && empty($st['done'])) {
        $st['running'] = false;
        $st['done'] = true;
        $st['stopped'] = true;
        $st['summary'] = 'توقف خواسته شد';
        aiTestStateSave($st);
    }
    header('Content-Type: application/json; charset=UTF-8');
    echo json_encode(['ok' => true, 'stopping' => true], JSON_UNESCAPED_UNICODE);
    exit;
}

/* v9.52: دادهٔ دسته‌بندی برای «تست دسته» — دسته‌های برگِ باسلام را یک‌بار
   می‌گیرد و برای همهٔ مدل‌ها به‌کار می‌برد تا در تستِ انبوه دوباره‌دوباره
   درخواستِ categories نرود. اگر توکن باسلام نباشد null برمی‌گردد. */
function aiTestCategoryData(): ?array {
    $cn = loadConnections(); $bs = $cn['basalam'] ?? [];
    $tk = trim((string)($bs['token'] ?? ''));
    if ($tk === '') return null;
    $cats = [];
    $cr = bslReq($tk, 'GET', 'categories');
    if ($cr['ok']) {
        $cData = $cr['body']['data'] ?? [];
        if (is_array($cData)) {
            $cFlat = function ($items, $lv = 0) use (&$cFlat) {
                $o = []; foreach ($items as $c) {
                    $t = trim($c['title'] ?? $c['name'] ?? ''); $id = (int)($c['id'] ?? 0);
                    if ($id > 0) $o[] = ['id' => $id, 'name' => $t, 'level' => $lv];
                    $ch = $c['children'] ?? []; if (is_array($ch) && count($ch) > 0) { foreach ($cFlat($ch, $lv + 1) as $s) $o[] = $s; }
                } return $o;
            };
            $cats = $cFlat($cData, 0);
        }
    }
    if (!$cats) return null;
    $catList = ''; $leafCats = [];
    foreach ($cats as $c) { if (($c['level'] ?? 0) >= 2) { $catList .= $c['id'] . ': ' . $c['name'] . "\n"; $leafCats[] = $c; } }
    if (!$leafCats) { foreach ($cats as $c) { $catList .= $c['id'] . ': ' . $c['name'] . "\n"; $leafCats[] = $c; } }
    if (strlen($catList) > 3000) { $catList = ''; $leafCats = array_slice($leafCats, 0, 200); foreach ($leafCats as $c) { $catList .= $c['id'] . ': ' . $c['name'] . "\n"; } }
    return ['cats' => $cats, 'leafCats' => $leafCats, 'catList' => $catList];
}

/* v9.52: اجرای تستِ دسته‌بندی برای یک مدل و خلاصه‌سازی نتیجه به رشتهٔ کوتاه.
   اگر catData نباشد یا عنوان خالی باشد null برمی‌گردد. */
function aiRunTestCategory(array $p, string $mid, string $testCat, ?array $catData, ?array $net = null): ?string {
    if ($testCat === '' || !$catData) return null;
    if ($net === null) $net = aiNetCfg();
    $res = aiCandidateCategory($p, $mid, $testCat, $catData['cats'], $catData['leafCats'], $catData['catList'], $net);
    if (!empty($res['ok']) && !empty($res['category_name'])) return $res['category_name'] . ' (#' . $res['category_id'] . ')';
    if (!empty($res['category_id'])) return '#' . $res['category_id'];
    if (!empty($res['error'])) return 'خطا: ' . mb_substr((string)$res['error'], 0, 80);
    if (!empty($res['ai_text'])) return mb_substr(trim((string)$res['ai_text']), 0, 80);
    return '';
}

/* هستهٔ اجرای تست — یک تابع تا هم از مسیر پس‌زمینه و هم از مسیر هم‌زمان استفاده کند */
function aiRunTestBackground(int $per, bool $onlyUntested, string $testMsg = 'سلام', string $testCat = 'ادو پرفیوم', int $delayMs = 120): array {
    @set_time_limit(0); @ignore_user_abort(true);
    @unlink(AI_TEST_STOP_FILE);
    $providers = aiProvidersLoad();
    $catData = aiTestCategoryData();
    $delayMs = max(0, min(60000, (int)$delayMs));   // v9.56: تاخیر بین هر تست (جلوگیری از ریت‌لیمیت)
    $st = ['running'=>true,'done'=>false,'stopped'=>false,'started_at'=>time(),'updated_at'=>time(),
           'per_provider'=>$per,'only_untested'=>$onlyUntested,'delay_ms'=>$delayMs,
           'total'=>0,'tested'=>0,'available'=>0,'failed'=>0,'skipped'=>0,
           'current'=>['provider'=>'','model'=>''],'items'=>[],'diag'=>[],'summary'=>''];
    // شمارش کل مدل‌های هدف
    $queue = [];
    foreach ($providers as $pid => $p) {
        if (($p['enabled'] ?? true) === false) continue;
        $n = 0;
        foreach ($p['models'] as $m) {
            $mid = (string)($m['id'] ?? '');
            if ($mid === '') continue;
            if ($onlyUntested && !empty($m['tested'])) continue;
            if ($n >= $per) { $st['skipped']++; $n++; continue; }
            $n++;
            $queue[] = ['pid'=>$pid, 'mid'=>$mid];
        }
    }
    $st['total'] = count($queue);
    aiTestStateSave($st);
    foreach ($queue as $q) {
        // توقف صریح — v9.42: کش stat را پاک کن وگرنه سیگنال توقفِ تازه دیده
        // نمی‌شود. فایل توقف را یک پردازهٔ جدا (درخواست مرورگر) می‌سازد؛ PHP
        // نتیجهٔ is_file را برای طولِ این پردازه کش می‌کند و اگر اولین بررسی
        // «فایل نیست» بود، دکمهٔ توقف تا پایان کار بی‌اثر می‌ماند. همین الگوی
        // clearstatcache در bslReq برای BSL_STOP_FILE از قبل هست.
        clearstatcache(true, AI_TEST_STOP_FILE);
        if (is_file(AI_TEST_STOP_FILE)) { $st['stopped'] = true; break; }
        $pid = $q['pid']; $mid = $q['mid'];
        $p = $providers[$pid] ?? null;
        if (!$p) continue;
        $st['current'] = ['provider'=>$pid, 'model'=>$mid];
        aiTestStateSave($st);
        $t0 = microtime(true);
        // پیام تست (پیش‌فرض «سلام») — v9.57: سقف توکن ۳۰۰ برای مدل‌های reasoning
        $r = aiProviderCall($p, $mid, ['messages'=>[['role'=>'user','content'=>$testMsg]], 'temperature'=>0.3, 'max_tokens'=>300], aiNetCfg());
        /* v9.45: اگر فراخوانی به‌خاطر توقف abort شد، همین‌جا خارج شو —
           منتظر پردازشِ نتیجهٔ «stopped» نباش. */
        if (!empty($r['stopped']) || aiTestStopRequested()) {
            $st['stopped'] = true;
            break;
        }
        $latency = (int)round((microtime(true) - $t0) * 1000);
        $code = (int)$r['code'];
        $ok = $code === 200;
        $body = $r['body'] ?? [];
        $response = $ok ? aiExtractText($body) : '';   // v9.54: استخراج مقاومِ متنِ پاسخ
        $err = $ok ? '' : ($body['error']['message'] ?? ($body['message'] ?? ($r['error'] ?? ('HTTP '.$code))));
        // تشخیص قابل‌دسترس‌نبودن اندپوینت
        $diag = aiTestNetworkFailure($r);
        $diag['label'] = $ok ? 'در دسترس' : ($diag['label'] !== '' ? $diag['label'] : ('HTTP '.$code));
        $diag['ok'] = $ok;
        $diag['latencyMs'] = $latency;
        if (!isset($st['diag'][$pid])) $st['diag'][$pid] = ['reachable'=>true,'categories'=>[],'samples'=>0];
        $st['diag'][$pid]['samples']++;
        /* v9.29: اگر با «روش اتصال فعلی» fail شد ولی با «مستقیم» روی همان مدل
           موفق شد، یعنی خودِ هاست به اندپوینت دسترسی دارد و مشکل از روش اتصال
           (مثلاً DoH که روی این شبکه به سرور DNS هم وصل نمی‌شود) است. آن را
           «مشکل روش» علامت بزن تا پیام گمراه‌کنندهٔ «هاست دسترسی ندارد» نیاید. */
        $netIssue = false;
        if (!$ok) {
            if (aiTestStopRequested()) {   // v9.45
                $st['stopped'] = true;
                break;
            }
            $netCfg = aiNetCfg();
            $dnet = $netCfg; $dnet['mode'] = 'direct';
            $rd = aiProviderCall($p, $mid, ['messages'=>[['role'=>'user','content'=>$testMsg]], 'temperature'=>0.3, 'max_tokens'=>300], $dnet);   // v9.57
            if (aiTestStopRequested()) { $st['stopped'] = true; break; }
            if ((int)$rd['code'] === 200) $netIssue = true;
        }
        if ($netIssue) {
            $st['diag'][$pid]['net_issue'] = true;
            $st['diag'][$pid]['mode'] = (string)(aiNetCfg()['mode'] ?? 'direct');
            $st['diag'][$pid]['net_hint'] = 'روش اتصال فعلی روی این شبکه کار نمی‌کند ولی «مستقیم» جواب می‌دهد — روش را روی «مستقیم» بگذارید یا یک Worker/پروکسی سالم اضافه کنید';
            // روش اتصال را موقتاً مستقیم کن تا خودِ مدل رد نشود
            $r = $rd; $ok = true; $code = (int)$rd['code']; $response = aiExtractText($rd['body'] ?? []);   // v9.54
        } else {
            $st['diag'][$pid]['net_issue'] = false;
        }
        if (!$ok) {
            $st['diag'][$pid]['categories'][$diag['cat']] = ($st['diag'][$pid]['categories'][$diag['cat']] ?? 0) + 1;
            if ($diag['cat'] === 'dns' || $diag['cat'] === 'timeout' || $diag['cat'] === 'refused'
                || $diag['cat'] === 'connect' || $diag['cat'] === 'ssl' || $diag['cat'] === 'network') {
                $st['diag'][$pid]['reachable'] = false;
                $st['diag'][$pid]['first_error'] = $diag['error'];
            }
        }
        $st['diag'][$pid]['last_label'] = $diag['label'];
        // v9.52: تستِ دسته‌بندی برای همین مدل (پیش‌فرض «ادو پرفیوم»)
        $catResponse = aiRunTestCategory($p, $mid, $testCat, $catData);
        // ذخیرهٔ نتیجه در provider
        if (isset($providers[$pid]['models'])) {
            foreach ($providers[$pid]['models'] as $i => $m) {
                if (($m['id'] ?? '') === $mid) {
                    $providers[$pid]['models'][$i]['tested'] = true;
                    $providers[$pid]['models'][$i]['available'] = $ok;
                    $providers[$pid]['models'][$i]['rateLimited'] = in_array($code, [429], true);
                    $providers[$pid]['models'][$i]['testDetails'] = ['status'=>$code, 'error'=>mb_substr((string)$err,0,300),
                        'response'=>mb_substr((string)$response,0,300), 'catResponse'=>(string)$catResponse,
                        'testMsg'=>$testMsg, 'testCat'=>$testCat, 'latencyMs'=>$latency, 'testedAt'=>gmdate('c')];
                    break;
                }
            }
        }
        $st['tested']++;
        if ($ok) $st['available']++; else $st['failed']++;
        $st['items'][] = ['provider'=>$pid, 'providerName'=>$p['name']??$pid, 'model'=>$mid,
            'ok'=>$ok, 'latencyMs'=>$latency, 'error'=>mb_substr((string)$err,0,120),
            'cat'=>$diag['cat'], 'label'=>$diag['label'],
            'msgResponse'=>mb_substr($response,0,150), 'catResponse'=>mb_substr((string)$catResponse,0,150)];
        if (count($st['items']) > 1000) $st['items'] = array_slice($st['items'], -1000);
        $st['current'] = ['provider'=>'', 'model'=>''];
        // هر ۳ مدل ذخیره کن تا اگر پردازه کشته شد کار حفظ شود
        if ($st['tested'] % 3 === 0) { aiProvidersSave($providers); aiTestStateSave($st); }
        // v9.56: تاخیر قابل‌تنظیم بین هر تست برای جلوگیری از ریت‌لیمیت
        if ($delayMs > 0) usleep($delayMs * 1000);
    }
    aiProvidersSave($providers);
    $st['running'] = false;
    $st['done'] = true;
    $st['summary'] = $st['stopped']
        ? 'توقف خواسته شد — '.$st['tested'].' تست انجام شد'
        : 'تمام شد — '.$st['tested'].' تست · 🟢 '.$st['available'].' · 🔴 '.$st['failed'];
    aiTestStateSave($st);
    @unlink(AI_TEST_STOP_FILE);
    return $st;
}

if (isset($_GET['ai_test_start']) || isset($_GET['ai_test_all'])) {
header('Content-Type: application/json; charset=UTF-8');
$per = max(1, min(500, (int)($_GET['per_provider'] ?? 50)));
$onlyUntested = !empty($_GET['only_untested']);
// v9.52: پیام تست و دستهٔ تستِ قابل‌تنظیم (پیش‌فرض «سلام» و «ادو پرفیوم»)
$testMsg = trim((string)($_GET['msg'] ?? 'سلام'));
if ($testMsg === '') $testMsg = 'سلام';
$testCat = trim((string)($_GET['cat'] ?? 'ادو پرفیوم'));
if ($testCat === '') $testCat = 'ادو پرفیوم';
// v9.56: تاخیر بین هر تست (میلی‌ثانیه) — برای جلوگیری از ریت‌لیمیت
$delayMs = max(0, min(60000, (int)($_GET['delay'] ?? 120)));
// اگر کاری در حال اجراست، دوباره شروع نکن
$cur = aiTestStateLoad();
if (!empty($cur['running'])) {
    echo json_encode(['ok'=>false,'running'=>true,'error'=>'تست مدل‌ها در حال اجراست — برای شروع تازه اول متوقفش کنید (?)'], JSON_UNESCAPED_UNICODE);
    exit;
}
$detach = !isset($_GET['sync']);
finishRequestNow(json_encode(['ok'=>true,'started'=>true,'background'=>$detach,
    'note'=>'تست در پس‌زمینهٔ سرور ادامه دارد — می‌توانید صفحه را ببندید'], JSON_UNESCAPED_UNICODE));
if (!$detach) {
    // حالت هم‌زمان برای تست/عیب‌یابی
    aiRunTestBackground($per, $onlyUntested, $testMsg, $testCat, $delayMs);
    exit;
}
// پس از جدا شدن از مرورگر، اجرای واقعی ادامه می‌یابد
aiRunTestBackground($per, $onlyUntested, $testMsg, $testCat, $delayMs);
exit;
}

/* =====================================================================
 *  v9.38: مدل‌های کاندید + مدل مستر — مدیریت، آزمون چند-مدلی و رأی
 * ===================================================================== */
/* وضعیت کاندیدها + امتیازات + مستر */
if (isset($_GET['ai_candidates'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cands = aiCandidates();
    $v = aiVotesLoad();
    $master = aiMasterKey();
    $providers = aiProvidersLoad();
    $items = [];
    foreach ($cands as $c) {
        $mn = $c['model'];
        if (isset($providers[$c['provider']])) {
            foreach ($providers[$c['provider']]['models'] as $mm) {
                if (($mm['id'] ?? '') === $c['model']) { $mn = $mm['name'] ?? $c['model']; break; }
            }
        }
        $s = $v['scores'][$c['key']] ?? ['wins' => 0, 'losses' => 0, 'votes' => 0];
        $items[] = ['provider' => $c['provider'], 'model' => $c['model'], 'key' => $c['key'],
                    'providerName' => $c['providerName'], 'modelName' => $mn,
                    'wins' => (int)($s['wins'] ?? 0), 'losses' => (int)($s['losses'] ?? 0),
                    'votes' => (int)($s['votes'] ?? 0), 'score' => aiScoreOf($s)];
    }
    usort($items, fn($a, $b) => $b['score'] <=> $a['score']);
    echo json_encode(['ok' => true, 'candidates' => $items, 'master' => $master,
        'pin' => $v['pin'], 'history' => array_slice(array_reverse($v['history']), 0, 50)],
        JSON_UNESCAPED_UNICODE);
    exit;
}
/* ذخیرهٔ کاندیدها + سنجاقِ مستر */
if (($_POST['action'] ?? '') === 'ai_candidates_save') {
    header('Content-Type: application/json; charset=UTF-8');
    $list = json_decode((string)($_POST['candidates'] ?? '[]'), true);
    $ok = is_array($list) && aiCandidatesSave($list);
    // سنجاقِ مستر فقط وقتی به‌روزرسانی شود که صریحاً همراه درخواست آمده باشد
    // (افزودن/حذف یک کاندید نباید سنجاقِ دستیِ مستر را پاک کند)
    $pinProvided = isset($_POST['pin']);
    $pin = $pinProvided ? trim((string)$_POST['pin']) : '';
    if ($ok && $pinProvided) {
        $v = aiVotesLoad();
        $valid = false;
        foreach (aiCandidates() as $c) { if ($c['key'] === $pin) { $valid = true; break; } }
        $v['pin'] = $valid ? $pin : '';
        $v['master'] = aiMasterKey();
        aiVotesSave($v);
    }
    echo json_encode(['ok' => $ok, 'error' => $ok ? '' : 'خطا در ذخیرهٔ کاندیدها'], JSON_UNESCAPED_UNICODE);
    exit;
}
/* ثبت رأی برای یک آزمون */
if (($_POST['action'] ?? '') === 'ai_vote') {
    header('Content-Type: application/json; charset=UTF-8');
    $task = in_array((string)($_POST['task'] ?? ''), ['category', 'autoreply'], true) ? $_POST['task'] : 'category';
    $input = (string)($_POST['input'] ?? '');
    $winner = trim((string)($_POST['winner'] ?? ''));
    $cands = json_decode((string)($_POST['candidates'] ?? '[]'), true);
    if ($winner === '' || !is_array($cands)) { echo json_encode(['ok' => false, 'error' => 'رأی نامعتبر'], JSON_UNESCAPED_UNICODE); exit; }
    $v = aiVoteRecord($task, $input, $winner, array_map('strval', $cands));
    // v9.49: اگر رأیِ دسته‌بندی است و دستهٔ برنده هم داده شد، همان را در
    // حافظهٔ یادگیری ثبت کن تا «اصلاح بقیه با مستر» و مسیرهای بعدی از آن
    // استفاده کنند. (برندهٔ واقعی جایی است که کاربر برگزیده؛ مستر فقط مرجع است.)
    if ($task === 'category' && $input !== '') {
        $catId = (int)($_POST['cat_id'] ?? 0);
        if ($catId > 0) {
            $v['learned'] = catLearnRecord($input, $catId, trim((string)($_POST['cat_name'] ?? '')));
            $v['learn_word'] = catFirstWord($input);
        }
    }
    echo json_encode(['ok' => true, 'master' => $v['master'], 'pin' => $v['pin'],
        'scores' => $v['scores'], 'learned' => $v['learned'] ?? false,
        'learn_word' => $v['learn_word'] ?? ''], JSON_UNESCAPED_UNICODE);
    exit;
}
/* آزمون دسته‌بندی با همهٔ کاندیدها — پاسخ هر مدل جدا می‌آید */
if (isset($_GET['ai_candidates_category'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(180);
    $title = trim((string)($_GET['title'] ?? ''));
    if ($title === '') { echo json_encode(['ok' => false, 'error' => 'عنوان محصول خالی'], JSON_UNESCAPED_UNICODE); exit; }
    $cands = aiCandidates();
    if (!$cands) { echo json_encode(['ok' => false, 'error' => 'هیچ مدل کاندیدی انتخاب نشده — اول در بخش 🤖 چند مدل کاندید اضافه کنید'], JSON_UNESCAPED_UNICODE); exit; }
    $cn = loadConnections(); $tk = (string)($cn['basalam']['token'] ?? '');
    $cats = [];
    if (!empty($tk)) {
        $cr = bslReq($tk, 'GET', 'categories');
        if ($cr['ok']) {
            $cData = $cr['body']['data'] ?? [];
            if (is_array($cData)) {
                $cFlat = function ($items, $lv = 0) use (&$cFlat) {
                    $o = []; foreach ($items as $c) {
                        $t = trim($c['title'] ?? $c['name'] ?? ''); $id = (int)($c['id'] ?? 0);
                        if ($id > 0) $o[] = ['id' => $id, 'name' => $t, 'level' => $lv];
                        $ch = $c['children'] ?? []; if (is_array($ch) && count($ch) > 0) { foreach ($cFlat($ch, $lv + 1) as $s) $o[] = $s; }
                    } return $o;
                };
                $cats = $cFlat($cData, 0);
            }
        }
    }
    if (!$cats) { echo json_encode(['ok' => false, 'error' => 'دسته‌بندی‌های باسلام در دسترس نیست'], JSON_UNESCAPED_UNICODE); exit; }
    $catList = ''; $leafCats = [];
    foreach ($cats as $c) { if (($c['level'] ?? 0) >= 2) { $catList .= $c['id'] . ': ' . $c['name'] . "\n"; $leafCats[] = $c; } }
    if (!$leafCats) { foreach ($cats as $c) { $catList .= $c['id'] . ': ' . $c['name'] . "\n"; $leafCats[] = $c; } }
    if (strlen($catList) > 3000) { $catList = ''; $leafCats = array_slice($leafCats, 0, 200); foreach ($leafCats as $c) { $catList .= $c['id'] . ': ' . $c['name'] . "\n"; } }
    $providers = aiProvidersLoad();
    $net = aiNetCfg();
    $items = [];
    foreach ($cands as $c) {
        $p = $providers[$c['provider']] ?? null;
        if (!$p) continue;
        $res = aiCandidateCategory($p, $c['model'], $title, $cats, $leafCats, $catList, $net);
        $res['key'] = $c['key'];
        $res['providerName'] = $c['providerName'];
        $items[] = $res;
    }
    echo json_encode(['ok' => true, 'title' => $title, 'master' => aiMasterKey(), 'items' => $items], JSON_UNESCAPED_UNICODE);
    exit;
}
/* آزمون پاسخ خودکار با همهٔ کاندیدها */
if (isset($_GET['ai_candidates_reply'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(180);
    $msg = trim((string)($_GET['msg'] ?? ($_GET['text'] ?? '')));
    if ($msg === '') { echo json_encode(['ok' => false, 'error' => 'پیام خالی است'], JSON_UNESCAPED_UNICODE); exit; }
    $cands = aiCandidates();
    if (!$cands) { echo json_encode(['ok' => false, 'error' => 'هیچ مدل کاندیدی انتخاب نشده'], JSON_UNESCAPED_UNICODE); exit; }
    $providers = aiProvidersLoad();
    $items = [];
    foreach ($cands as $c) {
        $p = $providers[$c['provider']] ?? null;
        if (!$p) continue;
        $res = aiCandidateReply($p, $c['model'], $msg, 8);
        $res['key'] = $c['key'];
        $res['providerName'] = $c['providerName'];
        $items[] = $res;
    }
    echo json_encode(['ok' => true, 'master' => aiMasterKey(), 'items' => $items], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['ai_category'])) {
header('Content-Type: application/json; charset=UTF-8');
$cn=loadConnections();$bs=$cn['basalam']??[];
// v9.20: از ارائه‌دهندهٔ فعال استفاده می‌شود
$_aiCfg=aiActiveConfig();
$aiModel = $_aiCfg['model'] ?? '';
if (empty($_aiCfg['provider'])) { echo json_encode(['ok'=>false,'error'=>'هیچ ارائه‌دهندهٔ هوش مصنوعی فعالی تنظیم نشده — در بخش 🤖 هوش مصنوعی JSON را درون‌ریزی کنید','category_id'=>0],JSON_UNESCAPED_UNICODE);exit; }
$temperature=(float)0.1;
$productTitle=trim($_GET['title']??'');
if(empty($productTitle)){echo json_encode(['ok'=>false,'error'=>'عنوان محصول خالی','category_id'=>0],JSON_UNESCAPED_UNICODE);exit;}

$tk=$bs['token']??'';$cats=[];
if(!empty($tk)){
$cr=bslReq($tk,'GET','categories');
if($cr['ok']){$cData=$cr['body']['data']??[];if(is_array($cData)){$cFlat=function($items,$lv=0)use(&$cFlat){$o=[];foreach($items as $c){$t=trim($c['title']??$c['name']??'');$id=(int)($c['id']??0);if($id>0)$o[]=['id'=>$id,'name'=>$t,'level'=>$lv];$ch=$c['children']??[];if(is_array($ch)&&count($ch)>0){foreach($cFlat($ch,$lv+1)as $s)$o[]=$s;}}return $o;};$cats=$cFlat($cData,0);}}
}
if(empty($cats)){echo json_encode(['ok'=>false,'error'=>'دسته‌بندی‌های باسلام در دسترس نیست','category_id'=>0],JSON_UNESCAPED_UNICODE);exit;}

$catList='';$leafCats=[];
