$wooTitleSuffix='';
$wooQueueCatId=-1;
$wooQueueProfileKey='';   // v8.65: برای ثبت در دفترچهٔ شناسه‌ها
$wooContentSync=contentSyncOn($cn);   // v8.69: آپدیت محتوای تازه
$wooQueue=wooReadQueue();
foreach($wooQueue['entries'] as $qe){
if(($qe['status']??'')!=='running')continue;
if(!empty($qe['config']['title_suffix']))$wooTitleSuffix=trim($qe['config']['title_suffix']);
if(isset($qe['config']['category_id']))$wooQueueCatId=(int)$qe['config']['category_id'];
$wooQueueProfileKey=(string)($qe['profile_key']??'');
break;
}
if($wooTitleSuffix===''){$wooTitleSuffix=trim($cn['basalam']['title_suffix']??'');}
// v8.87: تعدیل قیمت مخصوص ووکامرس (جدا از تنظیم قیمت پروفایل)
$wooPriceCfg=destPriceCfg($cn,'woocommerce');
if($wooPriceCfg['mode']!=='none'){
wooBackendProgress(0,0,0,0,0,0,'','💰 تعدیل قیمت ووکامرس: '
  .($wooPriceCfg['mode']==='percent'?(($wooPriceCfg['val']>=0?'+':'').$wooPriceCfg['val'].'%'):('×'.$wooPriceCfg['val']))
  .($wooPriceCfg['round']>0?(' · گرد به '.$wooPriceCfg['round']):''));
}
// دستهٔ مؤثر: دستهٔ صف (پروفایل) و در نبودش دستهٔ پیش‌فرض تنظیمات عمومی
$wooSendCatId=$wooQueueCatId>=0?$wooQueueCatId:(int)($w['default_category']??0);
$GLOBALS['_currentProductLink']='';

wooBackendProgress(0,0,0,0,$total,0,'',['✅ [v8.22 woo_backend] شروع — '.$total.' محصول']);

foreach($pd as $i=>$p){
if(file_exists(WOO_STOP_FILE)){
@unlink(WOO_STOP_FILE);
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$i,'',['❌ متوقف شد']);
writeProgress(WOO_PROGRESS_FILE,['running'=>false,'done'=>true,'cancelled'=>true,'sent'=>$sent,'updated'=>$updated,'skipped'=>$skipped,'failed'=>$fail,'total'=>$total,'current'=>$i,'started_at'=>$startedAt,'recent_log'=>['❌ متوقف شد'],'total_log_count'=>1,'sent_details'=>$wooSentList,'updated_details'=>$wooUpdatedList,'skipped_details'=>$wooSkippedList,'failed_details'=>$wooFailedList]);
exit;
}

$pTitle=trim($p['title']??$p['name']??'');
$pPrice=(string)($p['final_price']??'0');
/* v8.87: درصد/ضریب مخصوص ووکامرس روی قیمت نهایی اعمال می‌شود.
   تنظیم قیمت پروفایل سر جایش می‌ماند؛ این فقط تفاوت مقصد را می‌گذارد. */
if($wooPriceCfg['mode']!=='none'){
$_pb=(int)preg_replace('/[^0-9]/','',$pPrice);
if($_pb>0)$pPrice=(string)destAdjustPrice($_pb,$wooPriceCfg);
}
$pKey=$p['key']??'';
$n=$i+1;
$GLOBALS['_currentProductLink']=$p['link']??'';
// v8.21: Apply title suffix if not already present in the title
if($wooTitleSuffix!==''&&$pTitle!==''&&strpos($pTitle,$wooTitleSuffix)===false){$pTitle=$pTitle.$wooTitleSuffix;}

$card=['title'=>$pTitle,'image'=>$p['image']??'','price'=>$pPrice,'category'=>'','link'=>$p['link']??''];

if($pTitle===''){wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ❌ عنوان خالی");$fail++;$wooFailedList[]=array_merge(['title'=>'','key'=>$pKey,'error'=>'عنوان خالی'],$card);continue;}

// v8.56: محصول بدون قیمت نباید ارسال شود.
// باسلام از قدیم این محافظ را داشت ولی ووکامرس نداشت؛ نتیجه این بود که
// محصول ناموجود با قیمت صفر ساخته می‌شد و بدتر: روی محصول موجود در
// ووکامرس هم PUT با regular_price=0 می‌رفت و قیمت درست را پاک می‌کرد.
$pPriceNum=(int)preg_replace('/[^0-9]/','',$pPrice);
if($pPriceNum<=0){
$skipped++;
$wooSkippedList[]=array_merge(['title'=>$pTitle,'key'=>$pKey,'reason'=>'بدون قیمت — ارسال نشد تا قیمت مقصد خراب نشود'],$card);
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ⏭ بدون قیمت — رد شد: $pTitle");
continue;
}

$wp=['name'=>$pTitle,'type'=>'simple','regular_price'=>$pPrice,'status'=>$w['default_status']??'draft','manage_stock'=>!empty($w['manage_stock']),'stock_quantity'=>(int)($w['stock_quantity']??10)];
if(!empty($p['short_desc']))$wp['short_description']=$p['short_desc'];
if(!empty($p['long_desc']))$wp['description']=$p['long_desc'];
if(!empty($p['sku']))$wp['sku']=$p['sku'];
// v8.56: دستهٔ همین پروفایل، نه فقط دستهٔ سراسری
if($wooSendCatId>0)$wp['categories']=[['id'=>$wooSendCatId]];
// v8.85: تنوع‌ها موقع ساخت محصول (نه فقط آپدیت)
$_atNew=wooVariationAttributes($p);
if($_atNew)$wp['attributes']=$_atNew;
// v8.85: دستهٔ استخراج‌شده بر دستهٔ ثابت پروفایل ارجح است
$_catNew=wooCategoryIds($w,$p['category']??'');
if($_catNew)$wp['categories']=array_map(fn($i)=>['id'=>$i],$_catNew);

$existing=null;
if($pTitle!==''){
$sep='products?search='.urlencode($pTitle).'&status=any&per_page=10';
$sr=wooReq($w['store_url'],$w['consumer_key'],$w['consumer_secret'],'GET',$sep);
if($sr['ok']&&is_array($sr['body'])){
// v8.71: تطبیق دقیق، بعد نرمال‌شده (&amp;، ی/ک عربی، نیم‌فاصله)
$baseTitle=$wooTitleSuffix!==''?trim(str_replace($wooTitleSuffix,'',$pTitle)):'';
$how='';
$existing=findRemoteByTitle($sr['body'],$pTitle,$baseTitle,'name',$how);
if($existing&&$how==='normalized')wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ✓ یافت شد با تطبیق نرمال‌شده (عنوان مقصد کمی فرق دارد)");
elseif($existing&&$baseTitle!==''&&trim((string)($existing['name']??''))===$baseTitle)wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ✓ یافت شد با عنوان بدون پسوند");
// v8.71: اگر باز پیدا نشد، شناسهٔ ثبت‌شده را امتحان کن — عنوان مقصد عوض شده
if(!$existing){
$byId=findRemoteById($sr['body'],'woo',(string)$pKey);
if($byId){$existing=$byId;wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ✓ یافت شد با شناسهٔ ثبت‌شده (عنوان مقصد عوض شده)");}
}
}
// v8.71: جست‌وجوی دوم بدون پسوند — وقتی موتور جست‌وجوی مقصد با عنوان کامل چیزی نیافت
if(!$existing&&$wooTitleSuffix!==''){
$bt=trim(str_replace($wooTitleSuffix,'',$pTitle));
if($bt!==''&&$bt!==$pTitle){
$sr2=wooReq($w['store_url'],$w['consumer_key'],$w['consumer_secret'],'GET','products?search='.urlencode($bt).'&status=any&per_page=10');
if($sr2['ok']&&is_array($sr2['body'])){
$h2='';
$existing=findRemoteByTitle($sr2['body'],$pTitle,$bt,'name',$h2);
if($existing)wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ✓ یافت شد با جستجوی بدون پسوند");
}
}
}
}

if($existing){
$exId=$existing['id']??'?';
$exPrice=trim((string)($existing['regular_price']??''));
$exStock=(int)($existing['stock_quantity']??0);
$newStock=(int)($w['stock_quantity']??10);
$editUrl=rtrim($w['store_url'],'/').'/wp-admin/post.php?post='.$exId.'&action=edit';

// v8.58: «تکراری» فقط وقتی که تصویر هم سر جایش باشد.
// قبلاً محصولی که قیمت و موجودی‌اش یکی بود ولی در ووکامرس تصویر نداشت،
// رد می‌شد و برای همیشه بی‌تصویر می‌ماند — این همان «هنوز بدون تصویر است».
$exHasImg=!empty($existing['images'])&&is_array($existing['images']);
$needImg=!$exHasImg&&!empty($p['image']);
// v8.69: محتوای تازه (توضیحات، گالری، تنوع، SKU) هم دلیل آپدیت است
$contentDiff=$wooContentSync?contentChanges($p,wooRemoteContent($existing)):[];
if($exPrice===$pPrice&&$exStock===$newStock&&!$needImg&&!$contentDiff){
$skipped++;$wooSkippedList[]=array_merge(['title'=>$pTitle,'key'=>$pKey,'remote_id'=>$exId,'reason'=>'تکرار: نام+قیمت+موجودی+محتوا یکسان','edit_url'=>$editUrl],$card);
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ⏭ تکرار: $pTitle");
continue;
}
if($contentDiff)wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] 🔄 محتوای تازه: ".implode('، ',$contentDiff));
if($needImg&&$exPrice===$pPrice&&$exStock===$newStock){
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] 🖼 تکراری ولی بدون تصویر — تصویر اضافه می‌شود");
}

// v8.57: اگر محصول مقصد از قبل تصویر دارد، دست نزن. فقط وقتی تصویر
// ندارد یا ما تصویر تازه داریم، تصویر را می‌فرستیم — و اگر آپلود مستقیم
// نشد، آدرس را به خود ووکامرس می‌سپاریم.
// v8.69: گالریِ تازه هم فرستاده می‌شود، نه فقط وقتی مقصد بی‌عکس است
$galGrew=false;
foreach($contentDiff as $_cd){ if(mb_strpos($_cd,'گالری')===0){$galGrew=true;break;} }
$wooUpdImgs=[];
if($needImg||$galGrew){
$imgNote=null;
// v8.64: همهٔ عکس‌های محصول
$wooUpdImgs=wooGalleryPayload($w,productImageList($p),$imgNote);
if($imgNote)wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] 🖼 ".$imgNote);
}

$wpUpdate=['regular_price'=>$pPrice,'stock_quantity'=>$newStock];
if(!empty($p['short_desc']))$wpUpdate['short_description']=$p['short_desc'];
if(!empty($p['long_desc']))$wpUpdate['description']=$p['long_desc'];
if(!empty($wooUpdImgs))$wpUpdate['images']=$wooUpdImgs;
if(!empty($p['sku']))$wpUpdate['sku']=$p['sku'];
// v8.69: تنوع‌ها به‌صورت ویژگی محصول ووکامرس
$wooAttrs=wooVariationAttributes($p);
if($wooAttrs)$wpUpdate['attributes']=$wooAttrs;
// v8.85: دستهٔ استخراج‌شده در آپدیت هم اعمال شود
$_catUpd=wooCategoryIds($w,$p['category']??'');
if($_catUpd)$wpUpdate['categories']=array_map(fn($i)=>['id'=>$i],$_catUpd);
$r=wooReq($w['store_url'],$w['consumer_key'],$w['consumer_secret'],'PUT','products/'.$exId,$wpUpdate);
// v8.58: اگر فقط تصویر مقصر بود، بدون تصویر دوباره تلاش کن تا بقیهٔ
// تغییرات (قیمت/موجودی) از دست نرود.
if(!$r['ok']&&!empty($wpUpdate['images'])&&wooIsImageError($r)){
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ⚠️ ووکامرس تصویر را نگرفت — آپدیت بدون تصویر");
unset($wpUpdate['images']);
$r=wooReq($w['store_url'],$w['consumer_key'],$w['consumer_secret'],'PUT','products/'.$exId,$wpUpdate);
}
if($r['ok']&&!empty($r['body']['id'])){
$updated++;$wooUpdatedList[]=array_merge(['title'=>$pTitle,'key'=>$pKey,'remote_id'=>$r['body']['id'],'edit_url'=>$editUrl,'changes'=>'قیمت '.$exPrice.'→'.$pPrice,'update_reason'=>'تغییر قیمت: '.$exPrice.' → '.$pPrice],$card);
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ⚡ آپدیت: ID#{$r['body']['id']}");
}else{
$errMsg=mb_substr($r['body']['message']??($r['body']['error']??$r['error']??'?'),0,120);
$fail++;$wooFailedList[]=array_merge(['title'=>$pTitle,'key'=>$pKey,'error'=>'خطای آپدیت: '.$errMsg,'edit_url'=>$editUrl],$card);
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ❌ آپدیت: $errMsg");
}
}else{

// v8.57: آپلود مستقیم و در نبودش سپردن آدرس به ووکامرس
// v8.63: تصویر دیگر همراه خودِ POST نمی‌رود.
//
// چرا عوض شد: ساختن محصول با images[] داخل همان درخواست، مسیر دیگری در
// ووکامرس است و روی خیلی از فروشگاه‌ها رد می‌شود — و بدتر، کل محصول را
// می‌اندازد. همان تصویر اگر بعد از ساخته‌شدن محصول با یک PUT جدا وصل
// شود، قبول می‌شود. این دقیقاً همان روشی است که «عکس‌دار کردن محصولات»
// استفاده می‌کند و کار می‌کند، پس اینجا هم همان را به کار می‌بریم.
// v8.64: همهٔ عکس‌های محصول، نه فقط اولی
$imgNote=null;
$wooNewImgs=wooGalleryPayload($w,productImageList($p),$imgNote);
if($imgNote)wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] 🖼 ".$imgNote);

// محصول اول بدون تصویر ساخته می‌شود تا هیچ‌وقت به‌خاطر تصویر رد نشود
$r=wooReq($w['store_url'],$w['consumer_key'],$w['consumer_secret'],'POST','products',$wp);
if($r['ok']&&!empty($r['body']['id'])){
$newId=(int)$r['body']['id'];
$editUrl=rtrim($w['store_url'],'/').'/wp-admin/post.php?post='.$newId.'&action=edit';
// حالا تصویر را جداگانه وصل کن — همان کاری که «عکس‌دار کردن» می‌کند
$imgDone='';
if(!empty($wooNewImgs)){
$iu=wooEditProduct($w,$newId,['images'=>$wooNewImgs]);
if(!empty($iu['ok'])){
$imgDone=' + تصویر';
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] 🖼 تصویر وصل شد");
}else{
// محصول سر جایش می‌ماند؛ «عکس‌دار کردن» بعداً دوباره تلاش می‌کند
$imgDone=' (بدون تصویر)';
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ⚠️ تصویر وصل نشد (HTTP ".(int)($iu['code']??0).") — با «🖼 عکس‌دار کردن» قابل تکمیل است");
}
}
$sent++;$wooSentList[]=array_merge(['title'=>$pTitle,'key'=>$pKey,'remote_id'=>$newId,'edit_url'=>$editUrl,'price'=>$pPrice],$card);
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ✅ ایجاد: ID#".$newId.$imgDone);
}else{
$errBody=$r['body']??[];
$errMsg=mb_substr($errBody['message']??($errBody['error']??($r['error']??json_encode($errBody,JSON_UNESCAPED_UNICODE))),0,150);
// v8.71: اگر ووکامرس گفت «از قبل هست»، یعنی جست‌وجو پیدایش نکرده بود.
// به‌جای شکست، همان محصول را پیدا کن و آپدیتش کن.
if(wooIsDuplicateError($r)){
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] 🔁 مقصد گفت تکراری — جستجوی محصول موجود برای آپدیت...");
$dupRow=wooFindExisting($w,$pTitle,$wooTitleSuffix,(string)$pKey);
if($dupRow){
$dupId=(int)($dupRow['id']??0);
$wpFix=['regular_price'=>$pPrice,'stock_quantity'=>(int)($w['stock_quantity']??10)];
if(!empty($p['short_desc']))$wpFix['short_description']=$p['short_desc'];
if(!empty($p['long_desc']))$wpFix['description']=$p['long_desc'];
if(!empty($wooNewImgs))$wpFix['images']=$wooNewImgs;
$_at=wooVariationAttributes($p); if($_at)$wpFix['attributes']=$_at;
$rf=wooReq($w['store_url'],$w['consumer_key'],$w['consumer_secret'],'PUT','products/'.$dupId,$wpFix);
if(empty($rf['ok'])&&!empty($wpFix['images'])&&wooIsImageError($rf)){unset($wpFix['images']);$rf=wooReq($w['store_url'],$w['consumer_key'],$w['consumer_secret'],'PUT','products/'.$dupId,$wpFix);}
if(!empty($rf['ok'])&&!empty($rf['body']['id'])){
$updated++;$wooUpdatedList[]=array_merge(['title'=>$pTitle,'key'=>$pKey,'remote_id'=>$dupId,'edit_url'=>rtrim($w['store_url'],'/').'/wp-admin/post.php?post='.$dupId.'&action=edit','changes'=>'آپدیت پس از خطای تکراری','update_reason'=>'محصول از قبل موجود بود'],$card);
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ✅ آپدیت شد به‌جای ایجاد: ID#".$dupId);
usleep(max(100000,$bslDelayMs*1000));continue;
}
}
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ⚠️ تکراری بود ولی محصول موجود پیدا نشد");
}
$fail++;$wooFailedList[]=array_merge(['title'=>$pTitle,'key'=>$pKey,'error'=>'خطای ایجاد: '.$errMsg],$card);
wooBackendProgress($sent,$updated,$skipped,$fail,$total,$n,mb_substr($pTitle,0,30),"[{$n}] ❌ ایجاد: $errMsg");
}
}
usleep(max(100000,$bslDelayMs*1000));
}

$finalLog='پایان: '.$sent.' جدید, '.$updated.' آپدیت, '.$skipped.' تکراری, '.$fail.' خطا';
// v8.65: شناسهٔ مقصد را کنار کلید محصول نگه دار تا تطبیق بعدی به عنوان وابسته نباشد
remoteMapRecord('woo',array_merge($wooSentList,$wooUpdatedList),(string)($wooQueueProfileKey??''));
writeProgress(WOO_PROGRESS_FILE,['running'=>false,'done'=>true,'sent'=>$sent,'updated'=>$updated,'skipped'=>$skipped,'failed'=>$fail,'total'=>$total,'current'=>$total,'started_at'=>$startedAt,'last_progress_ts'=>time(),'recent_log'=>[$finalLog],'total_log_count'=>count($wooLog)+1,'sent_details'=>$wooSentList,'updated_details'=>$wooUpdatedList,'skipped_details'=>$wooSkippedList,'failed_details'=>$wooFailedList]);

$queue=wooReadQueue();
foreach($queue['entries'] as &$e){
if($e['status']==='running'){
$e['status']='done';
$e['sent']=$sent;$e['updated']=$updated;$e['skipped']=$skipped;$e['failed']=$fail;$e['done_at']=time();
}
}
unset($e);
wooWriteQueue($queue);

exit;
}

if(isset($_GET['bsl_stop'])){
header('Content-Type: application/json; charset=UTF-8');
@file_put_contents(BSL_STOP_FILE,json_encode(['stop'=>true,'time'=>time()],LOCK_EX));

$prevProgress=readProgress(BSL_PROGRESS_FILE);
writeProgress(BSL_PROGRESS_FILE,['running'=>false,'done'=>true,'cancelled'=>true,'sent'=>$prevProgress['sent']??0,'updated'=>$prevProgress['updated']??0,'skipped'=>$prevProgress['skipped']??0,'failed'=>$prevProgress['failed']??0,'total'=>$prevProgress['total']??0,'current'=>$prevProgress['current']??0,'last_title'=>'','started_at'=>$prevProgress['started_at']??0,'recent_log'=>['❌ ارسال توسط کاربر متوقف شد'],'total_log_count'=>($prevProgress['total_log_count']??0)+1,'sent_details'=>$prevProgress['sent_details']??[],'updated_details'=>$prevProgress['updated_details']??[],'skipped_details'=>$prevProgress['skipped_details']??[],'failed_details'=>$prevProgress['failed_details']??[]]);

// v8.57: «توقف» یعنی همه چیز بایستد. قبلاً فقط ردیف در حال اجرا بسته
// می‌شد و ردیف‌های منتظر سر جایشان می‌ماندند، پس اولین پینگ بعدی صف را
// دوباره راه می‌انداخت و کاربر می‌دید ارسال متوقف نشده.
$queue=bslReadQueue();
$stopPaused=0;
foreach($queue['entries'] as &$e){
if($e['status']==='running'){
$e['status']='failed';
$e['sent']=$prevProgress['sent']??0;$e['updated']=$prevProgress['updated']??0;$e['skipped']=$prevProgress['skipped']??0;$e['failed']=$prevProgress['failed']??0;$e['current']=$prevProgress['current']??0;
}elseif($e['status']==='waiting'){
$e['status']='paused';
$e['paused_at']=time();
$stopPaused++;
}
}
unset($e);
bslWriteQueue($queue);
echo json_encode(['ok'=>true,'paused'=>$stopPaused,
'msg'=>$stopPaused>0
?('فرآیند متوقف شد — '.$stopPaused.' ردیف صف هم موقتاً نگه داشته شد')
:'فرآیند متوقف شد'],JSON_UNESCAPED_UNICODE);
exit;
}

if (isset($_GET['poll_bsl'])) {
