];

foreach($queue['entries'] as $e){
$st=$e['status']??'unknown';
if(!isset($diag['queue_statuses'][$st]))$diag['queue_statuses'][$st]=0;
$diag['queue_statuses'][$st]++;
}

foreach($profiles as $key=>$p){
$sc=$p['syncConfig']??[];
