            }
            if($__pf['price']<=0)continue;
            $__found=bslFindExisting($sTk,$sVid,$__pt,(string)($p['key']??''));
            if(!$__found||(int)($__found['id']??0)<=0) continue;
            $__exId=(int)$__found['id'];
            $__np=$__pf['price'];
