/**
 * v8.29: تست استعلام باسلام — واقعاً درخواست می‌فرستد، نه شبیه‌سازی.
 * حالت تست وضعیت را ذخیره نمی‌کند تا اعلان واقعی بعدی از دست نرود.
 */
function notifTest(kind){
  const labels={orders:'🛒 سفارش‌ها',chats:'💬 پیام‌ها',products:'📋 محصولات',source:'💰 تغییرات مبدأ',ping:'📡 پینگ کران'};
  const box=$('notifTestR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حال استعلام '+esc(labels[kind]||kind)+' از باسلام...</div>';
  fetch('?notif_test=1&kind='+encodeURIComponent(kind)).then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){
      box.innerHTML='<div style="color:#f87171;font-size:11px;background:#7f1d1d20;padding:6px 8px;border-radius:6px">✗ '+esc(d.error||'خطا')+'</div>';
      showToast(d.error||'تست ناموفق',1);
      return;
    }
    const sent=d.sent||{};
    const chips=Object.keys(sent).map(k=>{
      const okv=sent[k]==='sent';
      const nm={baleh:'بله',rubika:'روبیکا',none:'پیام‌رسان'}[k]||k;
      return '<span style="font-size:10px;padding:1px 7px;border-radius:4px;margin-left:4px;background:'
        +(okv?'#14532d':'#7f1d1d')+';color:'+(okv?'#86efac':'#fca5a5')+'">'
        +(okv?'✓ ':'✗ ')+esc(nm)+'</span>';
    }).join('');
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">';
    h+='<div style="color:#4ade80;margin-bottom:4px">✓ ارتباط با باسلام برقرار است</div>';
    h+='<div style="color:#94a3b8">بررسی‌شده: '+toFa(d.total_seen||0)+' مورد · یافت‌شده: '+toFa(d.found||0)+'</div>';
    if(chips)h+='<div style="margin-top:4px">ارسال: '+chips+'</div>';
    if(d.sample)h+='<div style="margin-top:6px;color:#cbd5e1;background:#1e293b;padding:6px;border-radius:6px;white-space:pre-wrap;font-size:10.5px">'+esc(d.sample)+'</div>';
    h+='</div>';
    box.innerHTML=h;
    showToast('✓ تست '+(labels[kind]||kind)+' انجام شد');
  }).catch(()=>{
    if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا در ارتباط</div>';
    showToast('خطا شبکه',1);
  });
}

/** v8.37: پینگ آزمایشی — همان پیامی که کران‌جاب می‌فرستد */
function testPing(){notifTest('ping');}

/* =====================================================================
 *  v8.47: مغایرت‌گیری — رابط کاربری
 * ===================================================================== */
var reconLast=null;

function reconLabel(t){return t==='woo'?'ووکامرس':'باسلام';}

/** گام ۱: فقط گزارش، بدون هیچ تغییری */
function reconScan(target){reconStart(target,false,'off',1);}

/* v8.65: دفترچهٔ شناسهٔ مقصد */
function rmapShow(){
  const box=$('rmapR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ ...</div>';
  fetch('?remote_map=1').then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#fca5a5;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    const tot=(d.woo||0)+(d.bsl||0);
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px;line-height:1.9">';
    h+='<div style="color:#67e8f9;font-weight:700">📇 شناسه‌های ثبت‌شده</div>';
    h+='<div>🛒 ووکامرس: <b style="color:'+((d.woo||0)?'#4ade80':'#94a3b8')+'">'+toFa(d.woo||0)+'</b>'
      +' · 🏪 باسلام: <b style="color:'+((d.bsl||0)?'#4ade80':'#94a3b8')+'">'+toFa(d.bsl||0)+'</b></div>';
    if(!tot){
      h+='<div style="color:#fbbf24;font-size:10.5px;margin-top:4px">'
        +'هنوز چیزی ثبت نشده. با هر ارسال خودکار پر می‌شود، یا همین حالا «بازسازی» را بزنید.</div>';
    }
    ['woo','bsl'].forEach(t=>{
      const rows=(d.sample||{})[t]||[];
      rows.forEach(s=>{h+='<div style="color:#94a3b8;font-size:10px">'
        +(t==='woo'?'🛒':'🏪')+' #'+toFa(s.id)+' — '+esc(s.title||'')+'</div>';});
    });
    h+='</div>';
    box.innerHTML=h;
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

function rmapRebuild(target){
  const box=$('rmapR');
  const lbl=target==='woo'?'ووکامرس':'باسلام';
  if(!confirm('شناسهٔ محصولات '+lbl+' از روی عنوان‌های فعلی ثبت شود؟\n\n'
    +'این کار چیزی را تغییر نمی‌دهد؛ فقط یاد می‌گیرد کدام محصول مقصد مال کدام محصول پروفایل است.\n'
    +'بهتر است قبل از تغییر نام محصولات انجام شود.'))return;
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ خواندن محصولات '+esc(lbl)+'...</div>';
  fetch('?remote_map=1&rebuild='+encodeURIComponent(target)).then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#fca5a5;font-size:11px;background:#7f1d1d20;padding:6px 8px;border-radius:6px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px;line-height:1.9">';
    h+='<div style="color:#4ade80;font-weight:700">✅ بازسازی '+esc(lbl)+'</div>';
    h+='<div>محصولات مقصد: <b>'+toFa(d.remote_seen||0)+'</b> · عنوان‌های پروفایل: <b>'+toFa(d.profile_titles||0)+'</b></div>';
    h+='<div>🔗 شناسهٔ ثبت‌شده: <b style="color:#4ade80">'+toFa(d.recorded||0)+'</b></div>';
    if(!(d.recorded||0))h+='<div style="color:#fbbf24;font-size:10.5px">هیچ عنوانی تطبیق نخورد — یعنی عنوان‌های مقصد با پروفایل فرق دارند.</div>';
    h+='</div>';
    box.innerHTML=h;
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

/** v8.49: شروع در پس‌زمینه و سپس دنبال کردن گزارش زنده */
function reconStart(target,apply,mode,fixPrice){
  const box=$('reconR');
  let q='?recon=1&target='+encodeURIComponent(target);
  // v8.64: همهٔ پروفایل‌ها یا فقط همگام‌شونده‌ها
  if(($('reconAllProfiles')||{}).checked)q+='&all_profiles=1';
  if(apply)q+='&apply=1&mode='+encodeURIComponent(mode||'off')+'&fix_price='+(fixPrice?1:0);
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حال شروع...</div>';
  fetch(q).then(r=>r.json()).then(d=>{
    if(!d.ok){
      if(box)box.innerHTML='<div style="color:#fca5a5;font-size:11px;background:#7f1d1d20;'
        +'padding:6px 8px;border-radius:6px">✗ '+esc(d.error||'خطا')
        +(d.running?'<div style="color:#94a3b8;margin-top:4px">اگر گیر کرده، تا ۳ دقیقه دیگر خودش آزاد می‌شود.</div>':'')
        +'</div>';
      return;
    }
    reconWatch(target);
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

var reconTimer=null, reconSeen=0;

function reconWatch(target){
  if(reconTimer)clearInterval(reconTimer);
  reconSeen=0;
  const box=$('reconR');
  if(box)box.innerHTML=
    '<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px">'
    +'<div id="reconHead" style="color:#93c5fd;margin-bottom:5px">⏳ در حال اجرا...</div>'
    +'<div id="reconCounts" style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:5px"></div>'
    +'<div id="reconLog" style="max-height:190px;overflow:auto;font-family:ui-monospace,monospace;'
    +'font-size:10.5px;line-height:1.8;direction:rtl;background:#111c31;border-radius:6px;padding:6px"></div>'
    +'</div>';
      const tick=()=>{
    fetch('?recon_status=1&since='+reconSeen).then(r=>r.json()).then(st=>{
      const logEl=$('reconLog');
      if(logEl&&st.log&&st.log.length){
        st.log.forEach(l=>{
          const d=document.createElement('div');
          // v8.64: رنگ سطر بر اساس محتوا، تا گزارش زنده خوانا باشد
          const m=l.m||'';
          d.style.color = /^⛔|❌|🛑|⚠️/.test(m) ? '#fca5a5'
                        : /^✅|^💰|^🗑/.test(m)  ? '#86efac'
                        : /^\s+[•✓⏭🗑💰]/.test(m) ? '#94a3b8'
                        : /^📊|^⚖️/.test(m)      ? '#93c5fd'
                        : '#cbd5e1';
          if(/^\s/.test(m))d.style.paddingRight='10px';
          d.textContent=m;
          logEl.appendChild(d);
        });
        logEl.scrollTop=logEl.scrollHeight;
      }
      reconSeen=st.log_total||reconSeen;
      const c=$('reconCounts');
      if(c){
        const cell=(lbl,v,col)=>v===undefined?'':
          '<span style="color:#94a3b8">'+lbl+': <b style="color:'+col+'">'+toFa(v)+'</b></span>';
        c.innerHTML=cell('پروفایل',st.expected,'#e2e8f0')+cell('مقصد',st.remote,'#e2e8f0')
          +cell('یکسان',st.matched,'#86efac')+cell('اضافی',st.extra,'#fca5a5')
          +cell('مغایرت',st.diff,'#fbbf24')
          +(st.repriced?cell('اصلاح‌شده',st.repriced,'#4ade80'):'')
          +(st.deleted?cell('حذف‌شده',st.deleted,'#4ade80'):'')
          +(st.cur&&st.cur_total?'<span style="color:#93c5fd">'+toFa(st.cur)+'/'+toFa(st.cur_total)+'</span>':'');
      }
      const h=$('reconHead');
      if(st.done){
        clearInterval(reconTimer);reconTimer=null;
        if(h)h.innerHTML=st.result_ok===false
          ?'<span style="color:#fca5a5">✗ '+esc(st.error||'ناموفق')+'</span>'
          :'<span style="color:#4ade80">✅ پایان</span>';
        fetch('?recon_result=1').then(r=>r.json()).then(res=>{
          reconLast=res;
          if(!res.ok){
            // v8.64: وقتی نتیجه‌ای نیست، بگو چرا و چه کاری می‌شود کرد
            const b=$('reconR');
            if(b&&res.hint_all_profiles){
              b.insertAdjacentHTML('beforeend',
                '<div style="background:#78350f30;border:1px solid #f59e0b;border-radius:8px;'
                +'padding:8px;margin-top:6px;font-size:11px;color:#fcd34d;line-height:1.8">'
                +'💡 پروفایل‌هایی هست ولی «همگام‌سازی دوره‌ای» ندارند. تیک '
                +'<b>«همهٔ پروفایل‌ها»</b> را بزنید و دوباره بررسی کنید.</div>');
            }
            return;
          }
          res.applied=!!st.apply;
          const b=$('reconR');
          if(b)b.innerHTML=reconReport(res,target)
            +'<div style="margin-top:6px"><button class="btn btn-gray" onclick="reconWatch(\''+target+'\')" '
            +'style="font-size:10px;padding:3px 8px">📜 نمایش گزارش</button></div>';
        }).catch(()=>{});
      }else if(h){
        const ph={start:'شروع',profiles:'خواندن پروفایل‌ها',fetch:'دریافت از مقصد',
                  compare:'مقایسه',apply:'اعمال تغییرات'}[st.phase]||'در حال اجرا';
        // v8.64: جزئیات زندهٔ همان لحظه، نه فقط نام مرحله
        let extra='';
        if(st.phase==='fetch'&&st.fetched)extra=' — '+toFa(st.fetched)+' محصول از صفحهٔ '+toFa(st.page||1);
        else if(st.cur&&st.cur_total)extra=' — '+toFa(st.cur)+' از '+toFa(st.cur_total);
        const secs=st.started_at?Math.max(0,Math.floor(Date.now()/1000)-st.started_at):0;
        h.innerHTML='⏳ '+esc(ph)+esc(extra)
          +(secs?'<span style="color:#64748b;font-size:10px"> · '+toFa(secs)+' ثانیه</span>':'');
      }
    }).catch(()=>{});
  };
  tick();
  reconTimer=setInterval(tick,1200);
}

function reconReport(d,target){
  // v8.50: هر شمارنده قابل کلیک است و فهرست محصولاتش را باز می‌کند
  reconLast=d; reconLastTarget=target;
  const nExtra=d.extra_total||0, nDiff=d.price_diff_total||0;
  const nMatch=d.matched||0, nExp=d.expected||0, nRem=d.remote||0;
  const cell=(icon,label,val,color,kind,enabled)=>
    '<div class="rc-cell'+(enabled?' rc-on':'')+'"'
    +(enabled?' onclick="reconList(\''+kind+'\')" title="کلیک برای دیدن فهرست"':'')
    +'><b style="color:'+color+'">'+toFa(val)+'</b><span>'+icon+' '+label+'</span></div>';
  let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px">';
  h+='<div class="rc-grid">'
   +cell('📋','در پروفایل‌ها',nExp,'#e2e8f0','',false)
   +cell('🏪','در '+reconLabel(target),nRem,'#e2e8f0','',false)
   +cell('✓','یکسان',nMatch,'#86efac','matched',nMatch>0)
   +cell('🗑','اضافی',nExtra,nExtra?'#fca5a5':'#64748b','extra',nExtra>0)
   +cell('💰','مغایرت قیمت',nDiff,nDiff?'#fbbf24':'#64748b','diff',nDiff>0)
   +'</div>';
  if(d.applied){
    h+='<div style="color:#4ade80;margin:6px 0">✅ اعمال شد — '
      +toFa(d.repriced||0)+' قیمت اصلاح، '+toFa(d.deleted||0)+' مورد اضافی'
      +((d.failed||0)?' · <span style="color:#fca5a5">'+toFa(d.failed)+' ناموفق</span>':'')+'</div>';
  }
  if(d.skipped_delete){
    h+='<div style="color:#fca5a5;background:#7f1d1d20;padding:5px 7px;border-radius:6px;margin:4px 0">'
      +'🛑 حذف انجام نشد: '+esc(d.skipped_delete)+'</div>';
  }
  // v8.64: شرح تفکیکی پروفایل‌ها و هشدار «هیچ‌چیز تطبیق نخورد»
  const ps=d.profile_stats||{};
  if(ps.profiles&&ps.profiles.length){
    h+='<details style="margin-top:6px"><summary style="cursor:pointer;color:#94a3b8;font-size:10.5px">'
      +'📋 '+toFa(ps.used||0)+' پروفایل استفاده شد'
      +((ps.skipped||0)?(' · '+toFa(ps.skipped)+' کنار گذاشته شد'):'')+'</summary>'
      +'<div style="padding:5px 8px 0;font-size:10px;line-height:1.9">';
    ps.profiles.forEach(p=>{
      h+='<div style="color:'+(p.n>0?'#cbd5e1':'#64748b')+'">'+(p.n>0?'✓ ':'⏭ ')+esc(p.name||'')
        +(p.n>0?(' — '+toFa(p.n)+' محصول'+(p.no_price?(' ('+toFa(p.no_price)+' بدون قیمت)'):'')):'')
        +(p.why?' <span style="color:#64748b">· '+esc(p.why)+'</span>':'')+'</div>';
    });
    h+='</div></details>';
  }
  if(d.matched_by_id>0){
    h+='<div style="color:#86efac;font-size:10.5px;margin-top:4px">🔗 '+toFa(d.matched_by_id)
      +' محصول با شناسهٔ ثبت‌شده تطبیق خورد — عنوانشان در مقصد عوض شده بود</div>';
  }
  if(d.no_src_price>0){
    h+='<div style="color:#94a3b8;font-size:10.5px;margin-top:4px">ℹ️ '+toFa(d.no_src_price)
      +' محصول در مبدأ قیمت ندارد — قیمتشان مقایسه نشد</div>';
  }
  if(nExtra>0&&nRem>0&&nExtra===nRem){
    h+='<div style="background:#7f1d1d30;border:1px solid #ef4444;border-radius:8px;padding:7px;'
      +'margin-top:5px;font-size:10.5px;color:#fca5a5;line-height:1.8">'
      +'⚠️ <b>هیچ محصولی تطبیق نخورد.</b> یعنی عنوان‌های مقصد با پروفایل یکی نیستند '
      +'(پسوند پروفایل، تغییر نام دستی، یا پروفایل اشتباه). '
      +'قبل از هر اقدامی روی «اضافی» بزنید و فهرست را ببینید.</div>';
  }
  if(!nExtra&&!nDiff)h+='<div style="color:#4ade80;margin-top:4px">✓ همه‌چیز هماهنگ است</div>';
  if(!d.applied&&(nExtra||nDiff)){
    h+='<div style="margin-top:8px;padding-top:8px;border-top:1px solid #334155">';
    h+='<div style="color:#94a3b8;margin-bottom:5px">اقدام برای موارد اضافی:</div>';
    h+='<select id="reconMode" style="width:100%;margin-bottom:6px;padding:5px;font-size:11px">'
      +'<option value="off">کاری نکن (فقط قیمت‌ها اصلاح شود)</option>'
      +'<option value="draft">پیش‌نویس/غیرفعال کن</option>'
      +'<option value="outofstock">ناموجود کن</option>'
      +'<option value="delete">حذف کن (زباله‌دان)</option></select>';
    h+='<label style="display:flex;align-items:center;gap:6px;color:#cbd5e1;margin-bottom:6px;cursor:pointer">'
      +'<input type="checkbox" id="reconFixPrice" checked style="width:14px;height:14px">'
      +'<span>قیمت‌های مغایر اصلاح شوند ('+toFa(nDiff)+')</span></label>';
    h+='<button class="btn btn-green" onclick="reconApply(\''+target+'\')" style="width:100%;font-size:11px">'
      +'✅ اعمال تغییرات</button>';
    h+='</div>';
  }
  return h+'</div>';
}

var reconLastTarget='';

/** v8.50: فهرست محصولات یک شمارنده */
function reconList(kind){
  const d=reconLast||{};
  const map={
    extra:{rows:d.extra||[],total:d.extra_total||0,title:'🗑 در هیچ پروفایلی نیست',color:'#fca5a5'},
    diff:{rows:d.price_diff||[],total:d.price_diff_total||0,title:'💰 مغایرت قیمت',color:'#fbbf24'},
    matched:{rows:d.matched_items||[],total:d.matched_items_total||d.matched||0,
             title:'✓ یکسان',color:'#86efac'}
  }[kind];
  if(!map){showToast('فهرستی نیست',1);return;}
  let h='<div class="bsl-modal-overlay" onclick="if(event.target===this)reconCloseList()">';
  h+='<div class="bsl-modal" style="max-width:760px">';
  h+='<div class="bsl-modal-head"><h2 style="color:'+map.color+'">'+map.title
    +' ('+toFa(map.total)+')</h2>'
    +'<button class="btn btn-gray" onclick="reconCloseList()">✕</button></div>';
  h+='<div style="padding:6px 12px;background:#111c31;border-bottom:1px solid #334155">'
    +'<input type="text" id="reconFilter" placeholder="جستجو در فهرست..." oninput="reconFilterRows()" '
    +'style="width:100%;padding:5px 8px;border:1px solid #475569;border-radius:6px;'
    +'background:#0f172a;color:#e2e8f0;font-size:11px;direction:rtl"></div>';
  h+='<div class="bsl-modal-body" style="max-height:60vh;overflow:auto">';
  if(!map.rows.length){
    h+='<div style="padding:24px;text-align:center;color:#64748b">موردی نیست</div>';
  }else{
    h+='<table class="bsl-modal-table"><thead><tr>'
      +'<th style="width:34px">#</th><th>عنوان</th>'
      +(kind==='diff'?'<th>فعلی</th><th>جدید</th>':'<th>قیمت</th>')
      +'<th style="width:52px">شناسه</th>'
      +(kind!=='matched'?'<th style="width:40px">وضعیت</th>':'')
      +'</tr></thead><tbody id="reconRows">';
    map.rows.forEach((it,n)=>{
      const money=v=>toFa(Number(v||0).toLocaleString('en-US'));
      h+='<tr class="rc-row" data-t="'+esc(String(it.title||'').toLowerCase())+'">'
        +'<td style="color:#64748b">'+toFa(n+1)+'</td>'
        +'<td>'+esc(String(it.title||''))+'</td>';
      h+=kind==='diff'
        ? '<td style="color:#94a3b8;white-space:nowrap">'+money(it.from)+'</td>'
          +'<td style="color:#e2e8f0;white-space:nowrap"><b>'+money(it.to)+'</b></td>'
        : '<td style="white-space:nowrap">'+money(it.price)+'</td>';
      h+='<td style="font-family:ui-monospace,monospace;color:#64748b">'+toFa(it.id||0)+'</td>';
      if(kind!=='matched'){
        h+='<td style="text-align:center">'+(it.done===true?'<span style="color:#4ade80">✓</span>'
          :(it.done===false?'<span style="color:#fca5a5">✗</span>':'<span style="color:#475569">—</span>'))+'</td>';
      }
      h+='</tr>';
    });
    h+='</tbody></table>';
    if(map.total>map.rows.length){
      h+='<div style="padding:8px;text-align:center;color:#64748b;font-size:10.5px">'
        +'نمایش '+toFa(map.rows.length)+' مورد از '+toFa(map.total)+'</div>';
    }
  }
  h+='</div></div></div>';
  const old=document.getElementById('reconListBox');if(old)old.remove();
  const div=document.createElement('div');div.id='reconListBox';div.innerHTML=h;
  document.body.appendChild(div);
}

function reconCloseList(){const m=document.getElementById('reconListBox');if(m)m.remove();}

function reconFilterRows(){
  const q=((document.getElementById('reconFilter')||{}).value||'').toLowerCase().trim();
  document.querySelectorAll('#reconRows .rc-row').forEach(tr=>{
    tr.style.display=(!q||(tr.dataset.t||'').includes(q))?'':'none';
  });
}

/** گام ۲: اعمال، با تأیید صریح — سمت سرور با گزارش زنده */
function reconApply(target){
  const mode=($('reconMode')||{}).value||'off';
  const fix=($('reconFixPrice')||{}).checked?1:0;
  const d=reconLast||{};
  const nExtra=d.extra_total||0, nDiff=d.price_diff_total||0;
  const modeTxt={off:'',draft:'پیش‌نویس',outofstock:'ناموجود',delete:'حذف'}[mode]||'';
  if(!fix&&mode==='off'){showToast('هیچ اقدامی انتخاب نشده',1);return;}
  let msg='تغییرات روی '+reconLabel(target)+':\n';
  if(fix&&nDiff)msg+='\n• اصلاح قیمت '+nDiff+' محصول';
  if(mode!=='off'&&nExtra)msg+='\n• '+modeTxt+' کردن '+nExtra+' محصول اضافی';
  msg+='\n\nادامه می‌دهید؟';
  if(!confirm(msg))return;
  reconStart(target,true,mode,fix);
}

/* =====================================================================
 *  v8.64: پاسخ خودکار به پیام مشتریان — رابط کاربری
 * ===================================================================== */
var arRules=[], arLoaded=false;

const AR_MATCH={contains:'شامل کلمه',exact:'دقیقاً همین',starts:'شروع با',regex:'الگوی regex',always:'همیشه (پیش‌فرض)'};

function arCollectCfg(){
  const g=id=>$(id)||{};
  return {
    enabled:      !!g('arEnabled').checked,
    grace_min:    parseInt(g('arGrace').value||'10')||0,
    per_chat_min: parseInt(g('arPerChat').value||'180')||0,
    max_per_run:  parseInt(g('arMaxRun').value||'5')||5,
    scan_limit:   parseInt(g('arScan').value||'20')||20,
    only_offhours:!!g('arOffHours').checked,
    work_from:    parseInt(g('arFrom').value||'9')||0,
    work_to:      parseInt(g('arTo').value||'21')||0,
    sign:         (g('arSign').value||'').trim(),
    notify:       !!g('arNotify').checked,
    ai_system_mode:(g('arAiSysMode').value||'default'),
    ai_system_text:(g('arAiSysText').value||'').trim(),
    reply_order:(g('arOrder').value||'rules_first')
  };
}

function arApplyCfg(c){
  c=c||{};
  const set=(id,v)=>{const e=$(id);if(e)e.value=v;};
  const chk=(id,v)=>{const e=$(id);if(e)e.checked=!!v;};
  // ساعت‌ها یک بار پر می‌شوند
  ['arFrom','arTo'].forEach(id=>{
    const e=$(id); if(!e||e.options.length)return;
    let h=''; for(let i=0;i<24;i++)h+='<option value="'+i+'">'+toFa(String(i).padStart(2,'0'))+':۰۰</option>';
    e.innerHTML=h;
  });
  chk('arEnabled',c.enabled);
  set('arGrace',c.grace_min!==undefined?c.grace_min:10);
  set('arPerChat',c.per_chat_min!==undefined?c.per_chat_min:180);
  set('arMaxRun',c.max_per_run!==undefined?c.max_per_run:5);
  set('arScan',c.scan_limit!==undefined?c.scan_limit:20);
  chk('arOffHours',c.only_offhours);
  set('arFrom',String(c.work_from!==undefined?c.work_from:9));
  set('arTo',String(c.work_to!==undefined?c.work_to:21));
  set('arSign',c.sign||'');
  chk('arNotify',c.notify);
  set('arAiSysMode',c.ai_system_mode||'default');
  set('arAiSysText',c.ai_system_text||'');
  set('arOrder',c.reply_order||'rules_first');
  arAiSysToggle();
  arOrderHint();
  arToggleHours();
  arBadge();
}
function arAiSysToggle(){
  const v=($('arAiSysMode')||{}).value||'default';
  const tr=$('arAiSysTextRow');
  const dh=$('arAiSysDefaultHint');
  if(tr)tr.style.display=(v==='custom')?'':'none';
  if(dh)dh.style.display=(v==='default')?'':'none';
}
/* v9.38: شرح هر حالتِ ترتیب اولویت پاسخ‌دهی */
function arOrderHint(){
  const h=$('arOrderHint'); if(!h)return;
  const v=($('arOrder')||{}).value||'rules_first';
  const map={
    'rules_first':'⭐ پیشنهادی: «سلام» و سؤال‌های ساده را همان قواعدِ آماده جواب می‌دهند (سریع و مطمئن). فقط وقتی هیچ قاعده‌ای نخورد — مثلاً «سلام، وقتتون بخیر، این کالا موجوده؟» — هوش مصنوعی پاسخ می‌دهد.',
    'ai_first':'🤖 اول از هوش مصنوعی پاسخ گرفته می‌شود؛ اگر خطا یا پاسخ خالی بدهد، قواعدِ آماده امتحان می‌شوند.',
    'rules_only':'📋 فقط از قواعدِ آماده استفاده می‌شود؛ هوش مصنوعی اصلاً صدا زده نمی‌شود.',
    'ai_only':'🧠 فقط از هوش مصنوعی استفاده می‌شود؛ قواعدِ آماده نادیده گرفته می‌شوند.'
  };
  h.textContent=map[v]||'';
}

function arToggleHours(){
  const r=$('arHoursRow');
  if(r)r.classList.toggle('hidden',!($('arOffHours')||{}).checked);
}
/* v9.37: تغییر تب‌های بخش پاسخ خودکار */
function arTab(btn){
  if(!btn)return;
  const tab=btn.getAttribute('data-ar-tab');
  document.querySelectorAll('.ar-tab').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  document.querySelectorAll('.ar-pane').forEach(p=>{
    p.style.display=(p.getAttribute('data-ar-pane')===tab)?'':'none';
  });
}

function arBadge(){
  const b=$('arS'); if(!b)return;
  const on=($('arEnabled')||{}).checked;
  const nOn=arRules.filter(r=>r.on).length;
  b.textContent=on?('فعال · '+toFa(nOn)+' قاعده'):'خاموش';
  b.className='cst '+(on?'on':'off');
}

function arSaveCfg(){arBadge();saveConn();}

/** قواعد و تنظیمات را از سرور می‌گیرد */
function arLoad(force){
  if(arLoaded&&!force)return Promise.resolve();
  return fetch('?ar_rules=1').then(r=>r.json()).then(d=>{
    if(!d.ok)return;
    arRules=d.rules||[];
    arLoaded=true;
    arApplyCfg(d.cfg||{});
    arRenderRules();
  }).catch(()=>{});
}

function arRenderRules(){
  const box=$('arRules'); if(!box)return;
  if(!arRules.length){box.innerHTML='<div style="color:#64748b;font-size:11px;padding:8px;text-align:center">قاعده‌ای نیست — «قاعدهٔ جدید» را بزنید</div>';arBadge();return;}
  const sorted=arRules.map((r,i)=>({r,i})).sort((a,b)=>(a.r.priority||50)-(b.r.priority||50));
  let h='';
  sorted.forEach(({r,i})=>{
    const isAlways=r.match==='always';
    h+='<div style="background:#0f172a;border:1px solid '+(r.on?'#22c55e55':'#334155')+';border-radius:8px;padding:8px;margin-bottom:7px">';
    h+='<div style="display:flex;gap:6px;align-items:center;margin-bottom:5px">';
    h+='<label class="switch" style="flex:0 0 auto"><input type="checkbox" '+(r.on?'checked':'')
      +' onchange="arSetRule('+i+',\'on\',this.checked)"><span class="slider"></span></label>';
    h+='<select onchange="arSetRule('+i+',\'match\',this.value)" style="flex:1;font-size:10.5px;padding:3px">';
    for(const k in AR_MATCH)h+='<option value="'+k+'"'+(r.match===k?' selected':'')+'>'+AR_MATCH[k]+'</option>';
    h+='</select>';
    h+='<input type="number" value="'+(r.priority||50)+'" min="1" max="999" title="اولویت — کمتر یعنی زودتر بررسی می‌شود" '
      +'onchange="arSetRule('+i+',\'priority\',this.value)" style="flex:0 0 52px;font-size:10.5px;padding:3px">';
    h+='<button class="btn btn-red" onclick="arDelRule('+i+')" style="flex:0 0 auto;font-size:10px;padding:3px 7px">🗑</button>';
    h+='</div>';
    if(!isAlways){
      h+='<textarea rows="2" placeholder="محرک‌ها — هر کدام در یک خط" oninput="arSetRule('+i+',\'triggers\',this.value)" '
        +'style="width:100%;background:#111c31;border:1px solid #475569;color:#e2e8f0;padding:5px;border-radius:6px;font-size:11px;direction:rtl;margin-bottom:4px">'
        +esc(r.triggers||'')+'</textarea>';
    }else{
      h+='<div style="font-size:10px;color:#fbbf24;margin-bottom:4px">این قاعده وقتی هیچ قاعدهٔ دیگری نخورد اجرا می‌شود — اولویتش را بالا (عدد بزرگ) بگذارید.</div>';
    }
    h+='<textarea rows="2" placeholder="پاسخ خودکار" oninput="arSetRule('+i+',\'reply\',this.value)" '
      +'style="width:100%;background:#111c31;border:1px solid #a855f7;color:#e9d5ff;padding:5px;border-radius:6px;font-size:11px;direction:rtl">'
      +esc(r.reply||'')+'</textarea>';
    h+='<div style="display:flex;gap:6px;align-items:center;margin-top:4px;font-size:10px;color:#64748b">'
      +'<span>سقف روزانه:</span><input type="number" value="'+(r.daily_max!==undefined?r.daily_max:50)+'" min="0" max="1000" '
      +'onchange="arSetRule('+i+',\'daily_max\',this.value)" style="width:64px;font-size:10px;padding:2px">'
      +'<span style="color:#475569">۰ = بی‌نهایت</span></div>';
    h+='</div>';
  });
  box.innerHTML=h;
  arBadge();
}

function arSetRule(i,field,val){
  if(!arRules[i])return;
  if(field==='priority'||field==='daily_max')val=parseInt(val)||0;
  arRules[i][field]=val;
  if(field==='on'||field==='match')arRenderRules();
  else arBadge();
}

function arAddRule(){
  arRules.push({id:'r'+Date.now().toString(36),on:true,match:'contains',
                triggers:'',reply:'',priority:50,daily_max:50});
  arRenderRules();
}

function arDelRule(i){
  if(!arRules[i])return;
  if(!confirm('این قاعده حذف شود؟'))return;
  arRules.splice(i,1);
  arRenderRules();
}

function arResetRules(){
  if(!confirm('همهٔ قواعد به حالت پیش‌فرض برگردند؟ (تغییرات ذخیره‌نشده از بین می‌رود)'))return;
  fetch('?ar_rules=1&defaults=1').then(r=>r.json()).then(d=>{
    if(!d.ok){showToast('خطا',true);return;}
    arRules=d.rules||[];
    arRenderRules();
    showToast('✓ پیش‌فرض‌ها بارگذاری شد — برای ثبت، «ذخیرهٔ قواعد» را بزنید');
  }).catch(()=>showToast('خطا در ارتباط',true));
}

function arSaveRules(){
  const bad=arRules.filter(r=>r.on&&!(r.reply||'').trim());
  if(bad.length){showToast('قاعدهٔ فعال بدون پاسخ وجود دارد',true);return;}
  const fd=new FormData();
  fd.append('action','ar_save_rules');
  fd.append('rules',JSON.stringify(arRules));
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    showToast(d.ok?('✓ '+toFa(d.count)+' قاعده ذخیره شد'):('خطا: '+(d.error||'')),!d.ok);
    if(d.ok)arSaveCfg();
  }).catch(()=>showToast('خطا در ارتباط',true));
}

function arTest(){
  const t=($('arTestText')||{}).value||'';
  const box=$('arR');
  if(!t.trim()){showToast('یک متن بنویسید',true);return;}
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ بررسی طبق ترتیبِ انتخابی...</div>';
  fetch('?ar_test=1&text='+encodeURIComponent(t)).then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#fca5a5;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    const ord=d.order||'rules_first';
    const rulesFirst=(ord==='rules_first'||ord==='rules_only');
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px;line-height:1.9">';
    if(d.source==='ai'){
      h+='<div style="color:#67e8f9;font-weight:700">🤖 پاسخ با هوش مصنوعی</div>';
      h+='<div style="background:#111c31;border-right:3px solid #3b82f6;padding:6px 8px;border-radius:6px;margin-top:5px;color:#bfdbfe;white-space:pre-wrap">'+esc(d.reply)+'</div>';
    }else if(d.source==='rule'){
      const why=rulesFirst
        ? 'قاعدهٔ «'+esc(d.rule)+'» جواب داد'
        : ('هوش مصنوعی نتوانست ('+esc(d.ai_error||'خطا')+') → قاعدهٔ «'+esc(d.rule)+'» جواب داد');
      h+='<div style="color:#fbbf24;font-weight:700">📋 '+why+'</div>';
      h+='<div style="background:#111c31;border-right:3px solid #a855f7;padding:6px 8px;border-radius:6px;margin-top:5px;color:#e9d5ff;white-space:pre-wrap">'+esc(d.reply)+'</div>';
    }else{
      let why;
      if(ord==='rules_only')why='هیچ قاعده‌ای نخورد — پاسخی فرستاده نمی‌شود';
      else if(ord==='ai_only')why='هوش مصنوعی نتوانست ('+esc(d.ai_error||'خطا')+') — پاسخی فرستاده نمی‌شود';
      else why='هوش مصنوعی نتوانست ('+esc(d.ai_error||'خطا')+') و هیچ قاعده‌ای هم نخورد — پاسخی فرستاده نمی‌شود';
      h+='<div style="color:#f87171">✖ '+why+'</div>';
    }
    h+='<div style="color:#64748b;font-size:10px;margin-top:5px">متن نرمال‌شده: '+esc(d.normalized||'')+'</div>';
    h+='</div>';
    box.innerHTML=h;
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

/* ============ v9.36: محیط چتِ آزمایش پاسخ خودکار (مودال) ============ */
let arChatBusy=false;
function arOpenChatTest(){
  let m=document.getElementById('arChatModal');if(m)m.remove();
  m=document.createElement('div');
  m.id='arChatModal';
  m.className='bsl-modal-overlay';
  m.innerHTML='<div class="bsl-modal" style="width:820px">'
    +'<div class="bsl-modal-head"><h2>💬 آزمایش پاسخ خودکار</h2>'
    +'<div style="display:flex;gap:6px;align-items:center">'
    +'<span id="arChatStat" style="font-size:11px;color:#64748b"></span>'
    +'<button class="btn btn-red" onclick="arChatClear()" style="font-size:11px;padding:4px 9px">🗑 پاک کردن</button>'
    +'<button class="btn btn-gray" onclick="arCloseChatTest()" style="font-size:11px;padding:4px 9px">✕</button>'
    +'</div></div>'
    +'<div class="bsl-modal-body" id="arChatBody" style="min-height:380px;max-height:55vh;overflow:auto;padding:14px;display:flex;flex-direction:column;gap:10px"></div>'
    +'<div style="padding:10px 14px;background:#1e293b;border-top:1px solid #334155">'
    +'<div style="display:flex;gap:8px;align-items:center">'
    +'<input type="text" id="arChatInput" placeholder="پیام مشتری را بنویسید و Enter بزنید…" '
    +'onkeydown="if(event.key===\'Enter\')arChatSend()" style="flex:1;background:#0f172a;color:#e2e8f0;border:1px solid #334155;border-radius:8px;padding:9px 12px;font-size:13px">'
    +'<button class="btn btn-green" onclick="arChatSend()" style="font-size:12px;padding:9px 16px">➤ ارسال</button>'
    +'</div>'
    +'<div style="display:flex;gap:6px;margin-top:6px;align-items:center;flex-wrap:wrap">'
    +'<span style="font-size:10px;color:#64748b">الگوی پاسخ:</span>'
    +'<button class="btn btn-gray" onclick="arChatFill(\'سلام، این محصول موجوده؟\')" style="font-size:10px;padding:3px 8px">سلام</button>'
    +'<button class="btn btn-gray" onclick="arChatFill(\'قیمت این چنده؟\')" style="font-size:10px;padding:3px 8px">قیمت</button>'
    +'<button class="btn btn-gray" onclick="arChatFill(\'ممنونم\')" style="font-size:10px;padding:3px 8px">تشکر</button>'
    +'<button class="btn btn-gray" onclick="arChatFill(\'ارسال چند روزه است؟\')" style="font-size:10px;padding:3px 8px">ارسال</button>'
    +'<button class="btn btn-gray" onclick="arChatFill(\'یک سوال کاملاً جدید و بی‌ربط\')" style="font-size:10px;padding:3px 8px">بی‌ربط</button>'
    +'</div></div></div>';
  m.addEventListener('click',function(e){if(e.target===m)arCloseChatTest();});
  document.body.appendChild(m);
  const body=$('arChatBody');
  if(body)body.innerHTML='<div style="color:#64748b;font-size:11px;text-align:center;padding:30px">یک پیام بنویسید تا ببینید پاسخ‌خودکار چگونه جواب می‌دهد.</div>';
  setTimeout(()=>{const i=$('arChatInput');if(i)i.focus();},50);
}
function arCloseChatTest(){const m=document.getElementById('arChatModal');if(m)m.remove();}
function arChatFill(t){const i=$('arChatInput');if(i){i.value=t;i.focus();}}
function arChatClear(){
  const body=$('arChatBody');if(body)body.innerHTML='<div style="color:#64748b;font-size:11px;text-align:center;padding:30px">یک پیام بنویسید تا ببینید پاسخ‌خودکار چگونه جواب می‌دهد.</div>';
  if($('arChatStat'))$('arChatStat').textContent='';
}
function arChatBubble(role,html,meta){
  const body=$('arChatBody');if(!body)return;
  const d=document.createElement('div');
  d.style.cssText='max-width:80%;padding:9px 12px;border-radius:12px;font-size:13px;line-height:1.7;white-space:pre-wrap;word-break:break-word;align-self:'+(role==='user'?'flex-end':'flex-start');
  d.style.background=role==='user'?'#1e3a5f':'#1e293b';
  d.style.border=role==='user'?'1px solid #2563eb':'1px solid #334155';
  d.style.color=role==='user'?'#bfdbfe':'#e2e8f0';
  if(meta)d.style.borderTop=(role==='user'?'2px':'0')+' solid transparent';
  d.innerHTML=html;
  if(meta){
    const mt=document.createElement('div');
    mt.style.cssText='font-size:10px;color:#64748b;margin-top:6px;display:flex;gap:8px;flex-wrap:wrap;align-items:center';
    mt.innerHTML=meta;
    d.appendChild(mt);
  }
  body.appendChild(d);
  body.scrollTop=body.scrollHeight;
}
function arChatTyping(){
  const body=$('arChatBody');if(!body)return;
  const d=document.createElement('div');
  d.id='arChatTyping';
  d.style.cssText='max-width:60%;padding:9px 14px;border-radius:12px;font-size:12px;background:#111c31;border:1px solid #334155;color:#94a3b8;align-self:flex-start';
  d.textContent='⏳ در حال بررسی...';
  body.appendChild(d);
  body.scrollTop=body.scrollHeight;
}
function arChatSend(){
  if(arChatBusy)return;
  const inp=$('arChatInput');if(!inp)return;
  const t=inp.value.trim();if(!t){inp.focus();return;}
  inp.value='';
  arChatBubble('user',esc(t),'<span style="color:#93c5fd">👤 مشتری</span>');
  arChatTyping();
  arChatBusy=true;
  if($('arChatStat'))$('arChatStat').textContent='⏳ در حال پاسخ...';
  fetch('?ar_chat=1&msg='+encodeURIComponent(t)).then(r=>r.json()).then(d=>{
    const ty=$('arChatTyping');if(ty)ty.remove();
    arChatBusy=false;
    if($('arChatStat'))$('arChatStat').textContent='';
    if(!d.ok){arChatBubble('bot','<span style="color:#f87171">✗ '+esc(d.error||'خطا')+'</span>');return;}
    const src=d.source||'none';
    const ord=d.order||'rules_first';
    let icon,color,label;
    if(src==='ai'){icon='🤖';color='#67e8f9';label='هوش مصنوعی'+(d.model?' · <span dir="ltr">'+esc(d.model)+'</span>':'');}
    else if(src==='rule'){
      icon='📋';color='#fbbf24';
      label=(ord==='rules_first'||ord==='rules_only')
        ? 'قاعدهٔ «'+esc(d.rule)+'» جواب داد'
        : 'قاعدهٔ «'+esc(d.rule)+'» (هوش مصنوعی خطا داد)';
    }
    else{
      icon='🚫';color='#f87171';
      label=(ord==='rules_only')
        ? 'بدون پاسخ — هیچ قاعده‌ای نخورد'
        : ((ord==='ai_only')
          ? 'بدون پاسخ — هوش مصنوعی پاسخ نداد'
          : 'بدون پاسخ — هوش مصنوعی خطا داد و قاعده‌ای نخورد');
    }
    const replyHtml = d.reply ? esc(d.reply)
        : '<span style="color:#f87171">پاسخی ارسال نشد — '+esc(d.ai_error||'')+'</span>';
    arChatBubble('bot','<div style="font-weight:700;color:'+color+';font-size:12px;margin-bottom:4px">'+icon+' '+label+'</div>'+replyHtml,
      '<span style="color:#64748b">⏱ '+toFa(d.latency_ms||0)+'ms</span>'
      +(d.ai_error?'<span style="color:#f87171" title="'+esc(d.ai_error)+'">⚠️ خطای AI</span>':''));
  }).catch(e=>{
    const ty=$('arChatTyping');if(ty)ty.remove();
    arChatBusy=false;
    if($('arChatStat'))$('arChatStat').textContent='';
    arChatBubble('bot','<span style="color:#f87171">✗ خطای شبکه: '+esc(e.message)+'</span>');
  });
}

function arRun(dry){
  const box=$('arR');
  if(!dry&&!confirm('پاسخ خودکار همین حالا روی گفتگوهای واقعی اجرا شود؟\nپیام‌ها واقعاً ارسال می‌شوند.'))return;
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ '+(dry?'پیش‌نمایش':'اجرا')+'...</div>';
  fetch('?ar_run=1'+(dry?'&dry=1':'&now=1')).then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#fca5a5;font-size:11px;background:#7f1d1d20;padding:6px 8px;border-radius:6px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px;line-height:1.9">';
    h+='<div style="color:#67e8f9;font-weight:700">🤖 '+(d.dry?'پیش‌نمایش — چیزی ارسال نشد':'اجرا شد')+'</div>';
    h+='<div>بررسی‌شده: <b>'+toFa(d.checked||0)+'</b>'
      +' · '+(d.dry?'ارسال می‌شد':'پاسخ داده شد')+': <b style="color:#4ade80">'+toFa(d.replied||0)+'</b>'
      +' · رد شد: <b style="color:#94a3b8">'+toFa(d.skipped||0)+'</b>'
      +((d.failed||0)?' · خطا: <b style="color:#f87171">'+toFa(d.failed)+'</b>':'')+'</div>';
    if(d.skipped_all)h+='<div style="color:#fbbf24">⏸ '+esc(d.skipped_all)+'</div>';
    (d.items||[]).slice(0,20).forEach(it=>{
      h+='<div style="border-top:1px solid #1e293b;padding-top:4px;margin-top:4px">'
        +'<div style="color:#e2e8f0">👤 '+esc(it.who||'')+' <span style="color:#64748b;font-size:10px">#'+toFa(it.chat_id||0)+'</span></div>'
        +'<div style="color:#94a3b8;font-size:10px">💬 '+esc(it.text||'')+'</div>';
      if(it.rule)h+='<div style="color:#a78bfa;font-size:10px">↳ «'+esc(it.rule)+'» — '+esc(it.status||'')+'</div>';
      else if(it.skip)h+='<div style="color:#64748b;font-size:10px">⏭ '+esc(it.skip)+'</div>';
      h+='</div>';
    });
    h+='</div>';
    box.innerHTML=h;
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

function arShowLog(){
  const box=$('arR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ ...</div>';
  fetch('?ar_log=1').then(r=>r.json()).then(d=>{
    if(!box)return;
    const rows=d.log||[];
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px;line-height:1.9">';
    h+='<div style="color:#67e8f9;font-weight:700">📜 پاسخ‌های خودکار اخیر ('+toFa(rows.length)+')</div>';
    if(d.last_run)h+='<div style="color:#64748b;font-size:10px">آخرین اجرا: '+esc(new Date(d.last_run*1000).toLocaleString('fa-IR'))+'</div>';
    if(!rows.length)h+='<div style="color:#64748b;padding:8px 0">هنوز پاسخ خودکاری فرستاده نشده</div>';
    rows.forEach(l=>{
      h+='<div style="border-top:1px solid #1e293b;padding-top:4px;margin-top:4px">'
        +'<div style="color:#e2e8f0">👤 '+esc(l.who||'')+' <span style="color:#64748b;font-size:10px">'
        +esc(new Date((l.at||0)*1000).toLocaleString('fa-IR'))+'</span></div>'
        +'<div style="color:#94a3b8;font-size:10px">💬 '+esc(l.in||'')+'</div>'
        +'<div style="color:#a78bfa;font-size:10px">↳ '+esc(l.out||'')+' <span style="color:#475569">«'+esc(l.rule||'')+'»</span></div>'
        +'</div>';
    });
    h+='</div>';
    box.innerHTML=h;
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

/* =====================================================================
 *  v8.53: آمار محصولات هر پروفایل بر اساس پسوند
 * ===================================================================== */
var sfxTimer=null, sfxSeen=0, sfxLast=null;

const SFX_SLICES=[
  {k:'approved',label:'تأیید شده',color:'#22c55e'},
  {k:'rejected',label:'تأیید نشده',color:'#ef4444'},
  {k:'pending', label:'در انتظار', color:'#f59e0b'},
  {k:'inactive',label:'غیرفعال',   color:'#64748b'},
  {k:'archived',label:'بایگانی',   color:'#7c3aed'}
];

function sfxRun(target){
  const notify=($('sfxNotify')||{}).checked?1:0;
  const box=$('sfxR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ شروع...</div>';
  fetch('?suffix_report=1&target='+encodeURIComponent(target)+'&notify='+notify)
    .then(r=>r.json()).then(d=>{
      if(!d.ok){
        if(box)box.innerHTML='<div style="color:#fca5a5;font-size:11px;background:#7f1d1d20;'
          +'padding:6px 8px;border-radius:6px">✗ '+esc(d.error||'خطا')+'</div>';
        return;
      }
      sfxWatch(target);
    }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

function sfxWatch(target){
  if(sfxTimer)clearInterval(sfxTimer);
  sfxSeen=0;
  const box=$('sfxR');
  if(box)box.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px">'
    +'<div id="sfxHead" style="color:#93c5fd;margin-bottom:5px">⏳ در حال اجرا...</div>'
    +'<div id="sfxLog" style="max-height:150px;overflow:auto;font-family:ui-monospace,monospace;'
    +'font-size:10.5px;line-height:1.8;background:#111c31;border-radius:6px;padding:6px"></div></div>';
  const tick=()=>{
    fetch('?suffix_status=1&since='+sfxSeen).then(r=>r.json()).then(st=>{
      const lg=$('sfxLog');
      if(lg&&st.log&&st.log.length){
        st.log.forEach(l=>{const d=document.createElement('div');d.style.color='#cbd5e1';
          d.textContent=l.m;lg.appendChild(d);});
        lg.scrollTop=lg.scrollHeight;
      }
      sfxSeen=st.log_total||sfxSeen;
      if(st.done){
        clearInterval(sfxTimer);sfxTimer=null;
        fetch('?suffix_result=1').then(r=>r.json()).then(rep=>{
          sfxLast=rep;
          const b=$('sfxR');
          if(!b)return;
          if(!rep.ok){b.innerHTML='<div style="color:#fca5a5;font-size:11px">✗ '+esc(rep.error||'خطا')+'</div>';return;}
          b.innerHTML=sfxRender(rep,target);
        }).catch(()=>{});
      }
    }).catch(()=>{});
  };
  tick();
  sfxTimer=setInterval(tick,1000);
}

/** نمودار دایره‌ای با SVG — بدون کتابخانهٔ بیرونی */
function sfxPie(counts,total,size){
  const R=size/2, r=R-2;
  if(!total)return '<svg width="'+size+'" height="'+size+'"><circle cx="'+R+'" cy="'+R+'" r="'+r
    +'" fill="none" stroke="#334155" stroke-width="3"/></svg>';
  let a=-Math.PI/2, out='';
  SFX_SLICES.forEach(s=>{
    const v=counts[s.k]||0;
    if(!v)return;
    const frac=v/total, ang=frac*Math.PI*2;
    if(frac>=0.999){
      out+='<circle cx="'+R+'" cy="'+R+'" r="'+r+'" fill="'+s.color+'"/>';
      return;
    }
    const x1=R+r*Math.cos(a), y1=R+r*Math.sin(a);
    a+=ang;
    const x2=R+r*Math.cos(a), y2=R+r*Math.sin(a);
    out+='<path d="M '+R+' '+R+' L '+x1.toFixed(2)+' '+y1.toFixed(2)
      +' A '+r+' '+r+' 0 '+(ang>Math.PI?1:0)+' 1 '+x2.toFixed(2)+' '+y2.toFixed(2)
      +' Z" fill="'+s.color+'"/>';
  });
  return '<svg width="'+size+'" height="'+size+'" viewBox="0 0 '+size+' '+size+'">'+out+'</svg>';
}

function sfxRender(rep,target){
  const lbl=target==='woo'?'ووکامرس':'باسلام';
  let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px;font-size:11px">';
  h+='<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px">'
   +'<b style="color:#e2e8f0">📊 آمار '+esc(lbl)+'</b>'
   +'<span style="color:#94a3b8">کل مقصد: '+toFa(rep.remote_total||0)+'</span>'
   +((rep.unmatched||0)>0?'<span style="color:#fbbf24">بدون پسوند: '+toFa(rep.unmatched)+'</span>':'')
   +'<span style="flex:1"></span>'
   +'<button class="btn btn-gray" onclick="sfxSend()" style="font-size:10px;padding:3px 8px">📤 ارسال به پیام‌رسان</button>'
   +'</div>';
  if(rep.delivery)h+='<div style="color:#4ade80;margin-bottom:6px">✅ گزارش فرستاده شد</div>';
  if(rep.notify_error)h+='<div style="color:#fca5a5;margin-bottom:6px">⚠️ '+esc(rep.notify_error)+'</div>';
  (rep.profiles||[]).forEach(p=>{
    const c=p.counts||{}, q=p.pct||{};
    h+='<div class="sfx-card">';
    h+='<div class="sfx-pie">'+sfxPie(c,p.total||0,86)+'</div>';
    h+='<div class="sfx-info">';
    h+='<div class="sfx-name">🏷 '+esc(p.name)+' <span class="sfx-sfx">«'+esc(p.suffix)+'»</span></div>';
    h+='<div class="sfx-total">ثبت‌شده: <b>'+toFa(p.total||0)+'</b></div>';
    if(p.total>0){
      SFX_SLICES.forEach(s=>{
        const v=c[s.k]||0; if(!v)return;
        h+='<div class="sfx-row"><i style="background:'+s.color+'"></i>'
          +'<span>'+s.label+'</span><b>'+toFa(v)+'</b>'
          +'<span class="sfx-pct">'+toFa(q[s.k]||0)+'٪</span></div>';
      });
    }else{
      h+='<div style="color:#64748b">هیچ محصولی با این پسوند پیدا نشد</div>';
    }
    h+='</div></div>';
  });
  if(!(rep.profiles||[]).length)h+='<div style="color:#64748b">پروفایلی با پسوند نبود</div>';
  return h+'</div>';
}

function sfxSend(){
  fetch('?suffix_notify=1').then(r=>r.json()).then(d=>{
    if(!d.ok){showToast(d.error||'ارسال ناموفق',1);return;}
    const bad=Object.keys(d.delivery||{}).filter(k=>d.delivery[k]!=='sent');
    showToast(bad.length?('⚠ ناموفق: '+bad.join('، ')):'✓ گزارش فرستاده شد',bad.length?1:0);
  }).catch(()=>showToast('خطا شبکه',1));
}

