/* v8.70: بررسی امنیت نصب — آیا فایل‌های داده از وب خوانده می‌شوند؟ */
function secCheck(){
  const box=$('genR')||$('watchdogR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ بررسی دسترسی به فایل‌های داده...</div>';
  fetch('?sec_check=1').then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#fca5a5;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    const bad=(d.exposed||0)>0;
    let h='<div style="background:#0f172a;border:1px solid '+(bad?'#ef4444':'#22c55e')
      +';border-radius:8px;padding:9px;font-size:11px;line-height:1.9">';
    h+='<div style="color:'+(bad?'#fca5a5':'#4ade80')+';font-weight:700">'
      +(bad?('🔴 '+toFa(d.exposed)+' فایل داده از اینترنت قابل خواندن است'):'🟢 فایل‌های داده محافظت شده‌اند')+'</div>';
    (d.checks||[]).forEach(c=>{
      const ico=c.state==='open'?'🔴':(c.state==='protected'?'🟢':'⚪');
      const txt=c.state==='open'?'قابل خواندن از وب!':(c.state==='protected'?'محافظت‌شده':'وجود ندارد');
      h+='<div style="color:'+(c.state==='open'?'#fca5a5':'#94a3b8')+'">'+ico+' '+esc(c.file)+' — '+txt+'</div>';
    });
    h+='<div style="color:#94a3b8;margin-top:5px">'+esc(d.advice||'')+'</div>';
    if(bad){
      h+='<div style="color:#fbbf24;font-size:10.5px;margin-top:5px;line-height:1.8">'
        +'⚠️ <b>connections.json</b> شامل توکن باسلام و کلید ووکامرس شماست. '
        +'فایل <code>htaccess-sample.txt</code> را از مخزن بردارید، نامش را به <code>.htaccess</code> '
        +'تغییر دهید و کنار همین فایل آپلود کنید.</div>';
    }
    h+='<div style="color:#475569;font-size:10px;margin-top:4px">htaccess موجود: '+(d.htaccess?'بله':'خیر')+'</div>';
    h+='</div>';
    box.innerHTML=h;
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

function genQueueStatus(){
  const box=$('genR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ ...</div>';
  fetch('?queues_overview=1').then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا</div>';return;}
    const nm={extract:'استخراج',bsl:'باسلام',woo:'ووکامرس'};
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">';
    ['extract','bsl','woo'].forEach(k=>{
      const q=d.queues[k]||{};
      h+='<div style="border-top:1px solid #1e293b;padding:4px 0">'
        +'<b style="color:#e2e8f0">'+nm[k]+'</b> '
        +'<span style="color:#94a3b8">فعال: '+toFa(q.active||0)+' · کل: '+toFa(q.total||0)+'</span>';
      (q.profiles||[]).forEach(p=>{
        h+='<div style="color:#cbd5e1;padding-right:10px">• '+esc(p.name||p.key||'—')
          +' <span style="color:#64748b">('+esc(p.status)+')</span></div>';
      });
      h+='</div>';
    });
    h+='</div>';
    box.innerHTML=h;
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا</div>';});
}

/* v8.48: رابط حافظهٔ یادگیری دسته‌بندی */
/* ============ v8.62: ویرایشگر محصولات مقصد ============ */
let edTarget='woo', edPage=1, edRows=[], edSel=new Set(), edTimer=null;

function editorOpen(target){
  edTarget=target; edPage=1; edSel=new Set(); edRows=[];
  let m=document.getElementById('edModal');
  if(!m){
    m=document.createElement('div');
    m.id='edModal';
    m.className='bsl-modal-overlay';
    m.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.72);z-index:100000;display:flex;align-items:center;justify-content:center;padding:12px';
    m.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:12px;width:min(1000px,96vw);max-height:92vh;display:flex;flex-direction:column;overflow:hidden">'
      +'<div style="padding:12px 16px;background:#1e293b;border-bottom:1px solid #334155;display:flex;justify-content:space-between;align-items:center">'
      +'<h2 id="edTitle" style="margin:0;font-size:15px;color:#e2e8f0">✏️ ویرایش محصولات</h2>'
      +'<button class="btn btn-gray" onclick="editorClose()" style="padding:4px 10px">✕</button></div>'
      +'<div id="edBody" style="padding:12px 16px;overflow-y:auto;flex:1"></div></div>';
    document.body.appendChild(m);
  }
  m.style.display='flex';
  $('edTitle').textContent=target==='woo'?'✏️ ویرایش محصولات ووکامرس':'✏️ ویرایش محصولات باسلام';
  editorRender();
  editorLoad();
}
function editorClose(){
  const m=document.getElementById('edModal');if(m)m.style.display='none';
  if(edTimer){clearInterval(edTimer);edTimer=null;}
}
function editorRender(){
  const b=$('edBody');if(!b)return;
  const isBsl=edTarget==='bsl';
  b.innerHTML=
   '<div class="row" style="align-items:center;gap:6px">'
   +'<input type="text" id="edQ" placeholder="جستجوی عنوان..." style="flex:1" onkeydown="if(event.key===\'Enter\'){edPage=1;editorLoad();}">'
   +'<button class="btn btn-blue" onclick="edPage=1;editorLoad()">🔍 جستجو</button>'
   +'<button class="btn btn-gray" onclick="editorPage(-1)">‹</button>'
   +'<span id="edPageN" style="color:#94a3b8;font-size:12px">۱</span>'
   +'<button class="btn btn-gray" onclick="editorPage(1)">›</button></div>'
   +'<div id="edList" style="max-height:38vh;overflow-y:auto;border:1px solid #334155;border-radius:8px;padding:6px;background:#111c31;margin-bottom:10px">در حال بارگذاری...</div>'
   +'<div style="display:flex;gap:8px;align-items:center;margin-bottom:8px;flex-wrap:wrap">'
   +'<button class="btn btn-gray" onclick="editorSelAll(1)" style="font-size:11px;padding:4px 10px">انتخاب همه</button>'
   +'<button class="btn btn-gray" onclick="editorSelAll(0)" style="font-size:11px;padding:4px 10px">لغو انتخاب</button>'
   +'<span id="edSelN" style="color:#67e8f9;font-size:12px;font-weight:700">۰ انتخاب‌شده</span></div>'
   +'<div style="border-top:1px solid #334155;padding-top:10px">'
   +'<div style="color:#fbbf24;font-weight:700;font-size:12px;margin-bottom:8px">تغییرات روی انتخاب‌شده‌ها</div>'
   +'<div class="row" style="align-items:center"><label style="min-width:70px">💰 قیمت:</label>'
   +'<select id="edPriceOp" style="flex:0;min-width:130px"><option value="">بدون تغییر</option>'
   +'<option value="set">مقدار ثابت</option><option value="inc">افزایش</option><option value="dec">کاهش</option></select>'
   +'<input type="text" id="edPriceVal" placeholder="مثلاً 10% یا 5000" dir="ltr" style="flex:1"></div>'
   +'<div class="row" style="align-items:center"><label style="min-width:70px">📦 موجودی:</label>'
   +'<input type="number" id="edStock" placeholder="خالی = بدون تغییر" dir="ltr" style="flex:1"></div>'
   +'<div class="row" style="align-items:center"><label style="min-width:70px">🏷 وضعیت:</label>'
   +'<select id="edStatus" style="flex:1"><option value="">بدون تغییر</option>'
   +(isBsl
      ?'<option value="2976">فعال</option><option value="3790">غیرفعال</option><option value="4184">بایگانی</option>'
      :'<option value="publish">منتشر</option><option value="draft">پیش‌نویس</option><option value="private">خصوصی</option>')
   +'</select></div>'
   +'<div class="row" style="align-items:center"><label style="min-width:70px">📝 توضیح کوتاه:</label>'
   +'<input type="text" id="edShort" placeholder="خالی = بدون تغییر" style="flex:1"></div>'
   +'<div class="row" style="align-items:flex-start"><label style="min-width:70px">📄 توضیحات:</label>'
   +'<textarea id="edDesc" placeholder="خالی = بدون تغییر" style="flex:1;height:60px"></textarea></div>'
   +'<div class="row" style="align-items:center"><label style="min-width:70px">🔤 عنوان:</label>'
   +'<input type="text" id="edPrefix" placeholder="پیشوند" style="flex:1">'
   +'<input type="text" id="edSuffix" placeholder="پسوند" style="flex:1"></div>'
   +'<div style="border-top:1px solid #7f1d1d;margin-top:8px;padding-top:8px">'
   +'<label style="display:flex;align-items:center;gap:6px;font-size:12px;color:#fca5a5;cursor:pointer">'
   +'<input type="checkbox" id="edDelete" onchange="editorDelToggle()" style="width:16px;height:16px">'
   +(isBsl?'🗄 بایگانی کردن (باسلام حذف همیشگی ندارد)':'🗑 حذف محصولات')+'</label>'
   +(isBsl?'':'<label id="edForceWrap" style="display:none;align-items:center;gap:6px;font-size:11px;color:#f87171;margin-top:4px;cursor:pointer">'
      +'<input type="checkbox" id="edForce" style="width:14px;height:14px"> حذف همیشگی (برگشت‌ناپذیر)</label>')
   +'</div>'
   +'<label style="display:flex;align-items:center;gap:6px;font-size:11px;color:#cbd5e1;margin-top:8px;cursor:pointer">'
   +'<input type="checkbox" id="edNotify" style="width:14px;height:14px"> ارسال گزارش به پیام‌رسان</label>'
   +'<div class="cact" style="margin-top:10px">'
   +'<button class="btn btn-gray" onclick="editorRun(1)" style="flex:1">👁 پیش‌نمایش</button>'
   +'<button class="btn btn-green" onclick="editorRun(0)" style="flex:1">✓ اعمال</button></div>'
   +'<div id="edResult" style="margin-top:10px"></div></div>';
}
function editorDelToggle(){
  const w=$('edForceWrap');
  if(w)w.style.display=($('edDelete')&&$('edDelete').checked)?'flex':'none';
}
function editorPage(d){
  const n=edPage+d; if(n<1)return; edPage=n; editorLoad();
}
function editorLoad(){
  const l=$('edList');if(!l)return;
  l.innerHTML='در حال بارگذاری...';
  const q=new URLSearchParams({dest_list:'1',target:edTarget,page:String(edPage)});
  const s=($('edQ')||{}).value||''; if(s.trim())q.set('q',s.trim());
  fetch('?'+q.toString()).then(r=>r.json()).then(d=>{
    if(!d.ok){l.innerHTML='<div style="color:#fca5a5">✗ '+esc(d.error||'خطا')+'</div>';return;}
    edRows=d.products||[];
    if($('edPageN'))$('edPageN').textContent=toFa(edPage);
    if(!edRows.length){l.innerHTML='<div style="color:#64748b">محصولی نیست</div>';return;}
    let h='';
    edRows.forEach(p=>{
      const on=edSel.has(p.id);
      h+='<label style="display:flex;align-items:center;gap:8px;padding:5px 6px;border-bottom:1px solid #1e293b;cursor:pointer;font-size:11.5px">'
        +'<input type="checkbox" '+(on?'checked':'')+' onchange="editorPick('+p.id+',this.checked)" style="width:15px;height:15px">'
        +'<span style="flex:1;color:#e2e8f0">'+esc(p.title||'')+'</span>'
        +'<span style="color:#fbbf24;font-family:ui-monospace,monospace">'+toFa(Number(p.price||0).toLocaleString('en-US'))+'</span>'
        +'<span style="color:#94a3b8;min-width:46px;text-align:center">'+(p.stock===null||p.stock===undefined?'—':toFa(p.stock))+'</span>'
        +'<span style="color:#64748b;min-width:60px">'+esc(String(p.status||''))+'</span>'
        +(p.has_image?'':'<span title="بدون تصویر">🖼️❌</span>')
        +'</label>';
    });
    l.innerHTML=h;
    editorCount();
  }).catch(()=>{l.innerHTML='<div style="color:#fca5a5">✗ خطا شبکه</div>';});
}
function editorPick(id,on){ if(on)edSel.add(id); else edSel.delete(id); editorCount(); }
function editorSelAll(on){
  edRows.forEach(p=>{ if(on)edSel.add(p.id); else edSel.delete(p.id); });
  editorLoad();
}
function editorCount(){ if($('edSelN'))$('edSelN').textContent=toFa(edSel.size)+' انتخاب‌شده'; }
function editorRun(dry){
  if(edSel.size===0){showToast('محصولی انتخاب نشده',1);return;}
  const ops={};
  const po=($('edPriceOp')||{}).value||'';
  const pv=(($('edPriceVal')||{}).value||'').trim();
  if(po&&pv)ops.price={op:po,val:pv};
  const st=(($('edStock')||{}).value||'').trim();
  if(st!=='')ops.stock=parseInt(st)||0;
  const su=($('edStatus')||{}).value||''; if(su)ops.status=su;
  const sd=(($('edShort')||{}).value||'').trim(); if(sd)ops.short_desc=sd;
  const dd=(($('edDesc')||{}).value||'').trim(); if(dd)ops.desc=dd;
  const pf=(($('edPrefix')||{}).value||'').trim(); if(pf)ops.title_prefix=pf+' ';
  const sf=(($('edSuffix')||{}).value||'').trim(); if(sf)ops.title_suffix=' '+sf;
  const del=$('edDelete')&&$('edDelete').checked;
  if(del){ops.delete=true; if($('edForce')&&$('edForce').checked)ops.force=true;}
  if(!del&&Object.keys(ops).length===0){showToast('هیچ تغییری تعیین نشده',1);return;}
  if(!dry){
    const what=del?(edTarget==='bsl'?'بایگانی':'حذف'):'ویرایش';
    if(!confirm(what+' '+edSel.size+' محصول؟ این کار روی مقصد اعمال می‌شود.'))return;
  }
  const fd=new FormData();
  fd.append('target',edTarget);
  fd.append('ids',JSON.stringify(Array.from(edSel)));
  fd.append('ops',JSON.stringify(ops));
  if(dry)fd.append('dry','1');
  if(!dry&&$('edNotify')&&$('edNotify').checked)fd.append('notify','1');
  $('edResult').innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">در حال اجرا...</div>';
  fetch('?bulk_edit=1',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    if(!d.ok){$('edResult').innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    if(edTimer)clearInterval(edTimer);
    edTimer=setInterval(editorPoll,1500);
    editorPoll();
  }).catch(()=>{$('edResult').innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا شبکه</div>';});
}
function editorPoll(){
  fetch('?bulk_status=1').then(r=>r.json()).then(d=>{
    const st=d.status||{},box=$('edResult');if(!box)return;
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px;font-size:11px;line-height:1.9">';
    h+='<div style="color:#67e8f9;font-weight:700">'+(st.running?'⏳ در حال اجرا':'✅ پایان')+(st.dry?' (پیش‌نمایش)':'')+'</div>';
    h+='<div>'+toFa(st.current||0)+'/'+toFa(st.total||0)
      +' · ویرایش: <b style="color:#4ade80">'+toFa(st.changed||0)+'</b>'
      +' · حذف/بایگانی: <b style="color:#fb923c">'+toFa(st.deleted||0)+'</b>'
      +' · بدون تغییر: '+toFa(st.skipped||0)
      +(st.failed?' · خطا: <b style="color:#f87171">'+toFa(st.failed)+'</b>':'')+'</div>';
    (st.log||[]).slice(-4).forEach(l=>{h+='<div style="color:#94a3b8;font-size:10px">'+esc(l.m||'')+'</div>';});
    h+='</div>';
    box.innerHTML=h;
    if(!st.running){
      if(edTimer){clearInterval(edTimer);edTimer=null;}
      fetch('?bulk_result=1').then(r=>r.json()).then(rr=>{
        const res=rr.result;if(!res||!res.items)return;
        let t='<div style="margin-top:6px;max-height:220px;overflow-y:auto;border:1px solid #334155;border-radius:8px;padding:6px;background:#111c31">';
        res.items.slice(0,120).forEach(i=>{
          const bad=i.error?'#fca5a5':'#cbd5e1';
          t+='<div style="font-size:10.5px;color:'+bad+'">• #'+i.id+' '+esc(i.title||'')
            +(i.new_price!==undefined?(' — '+toFa(Number(i.old_price).toLocaleString('en-US'))+'→'+toFa(Number(i.new_price).toLocaleString('en-US'))+' ('+(i.pct>=0?'+':'')+i.pct+'٪)'):'')
            +(i.action?(' — '+esc(i.action)):'')+(i.error?(' — '+esc(i.error)):'')+'</div>';
        });
        t+='</div>';
        box.innerHTML+=t;
        if(!res.dry)editorLoad();
      }).catch(()=>{});
    }
  }).catch(()=>{});
}

/* ============ v8.62: پشتیبان‌گیری آموخته‌ها ============ */
function catLearnExport(){
  const r=$('catLearnR');
  r.innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">در حال آماده‌سازی...</div>';
  fetch('?catlearn=1&export=1').then(x=>x.json()).then(d=>{
    if(!d.ok){r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    const txt=JSON.stringify(d.data);
    r.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px">'
      +'<div style="color:#67e8f9;font-weight:700;font-size:11px;margin-bottom:6px">💾 پشتیبان '+toFa(d.count)+' کلمه</div>'
      +'<textarea id="catLearnBak" readonly style="width:100%;height:120px;font-family:ui-monospace,monospace;font-size:10px;direction:ltr;text-align:left;background:#111c31;color:#e2e8f0;border:1px solid #334155;border-radius:6px;padding:8px"></textarea>'
      +'<div style="font-size:10px;color:#64748b;margin-top:6px">این متن را جایی نگه دارید. بعد از نصب با نام جدید، با «⬆️ بازیابی» برگردانید.</div>'
      +'<button class="btn btn-cyan" style="margin-top:6px;font-size:11px;padding:5px 10px" onclick="catLearnCopyBak()">📋 کپی</button></div>';
    $('catLearnBak').value=txt;
  }).catch(()=>{r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا شبکه</div>';});
}
function catLearnCopyBak(){
  const t=$('catLearnBak');if(!t)return;t.select();
  try{document.execCommand('copy');showToast('✓ کپی شد');}
  catch(e){if(navigator.clipboard){navigator.clipboard.writeText(t.value);showToast('✓ کپی شد');}}
}
function catLearnImportPrompt(){
  const r=$('catLearnR');
  r.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px">'
    +'<div style="color:#4ade80;font-weight:700;font-size:11px;margin-bottom:6px">⬆️ بازیابی آموخته‌ها</div>'
    +'<textarea id="catLearnIn" placeholder=\'{"کفش":{...}}\' style="width:100%;height:110px;font-family:ui-monospace,monospace;font-size:10px;direction:ltr;text-align:left;background:#111c31;color:#e2e8f0;border:1px solid #334155;border-radius:6px;padding:8px"></textarea>'
    +'<label style="display:flex;align-items:center;gap:6px;font-size:11px;color:#cbd5e1;margin:6px 0;cursor:pointer">'
    +'<input type="checkbox" id="catLearnReplace" style="width:14px;height:14px"> جایگزینی کامل (به‌جای ادغام)</label>'
    +'<button class="btn btn-green" style="font-size:11px;padding:5px 10px" onclick="catLearnImport()">✓ بازیابی</button></div>';
}
function catLearnImport(){
  const t=$('catLearnIn');if(!t||!t.value.trim()){showToast('چیزی وارد نشده',1);return;}
  let parsed;try{parsed=JSON.parse(t.value.trim());}catch(e){showToast('JSON نامعتبر',1);return;}
  const fd=new FormData();
  fd.append('action','catlearn_import');
  fd.append('data',JSON.stringify(parsed));
  if($('catLearnReplace')&&$('catLearnReplace').checked)fd.append('replace','1');
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    if(d.ok){showToast('✓ '+toFa(d.added)+' تازه، '+toFa(d.merged)+' ادغام — کل '+toFa(d.total));catLearnShow();}
    else showToast('خطا: '+(d.error||''),1);
  }).catch(()=>showToast('خطا شبکه',1));
}

/* ============ v8.62: عکس‌دار کردن محصولات ووکامرس ============ */
let photoTimer=null;
function photoRun(dry){
  const r=$('photoR');
  const q=new URLSearchParams({photo_fix:'1'});
  if(dry)q.set('dry','1');
  const pf=($('photoProfile')||{}).value||'';
  if(pf)q.set('profile',pf);
  if(!dry&&$('photoNotify')&&$('photoNotify').checked)q.set('notify','1');
  if(!dry&&!confirm('تصویر محصولات بی‌عکس ووکامرس از روی پروفایل‌ها تکمیل شود؟'))return;
  r.innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">🖼 شروع شد — پیشرفت زنده...</div>';
  fetch('?'+q.toString()).then(x=>x.json()).then(d=>{
    if(!d.ok){r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    if(photoTimer)clearInterval(photoTimer);
    photoTimer=setInterval(photoPoll,2000);
    photoPoll();
  }).catch(()=>{r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا شبکه</div>';});
}
function photoPoll(){
  fetch('?photo_status=1').then(x=>x.json()).then(d=>{
    const st=d.status||{},res=d.result||null,r=$('photoR');
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px;font-size:11px;line-height:1.9">';
    h+='<div style="color:#67e8f9;font-weight:700">🖼 '+(st.running?'در حال اجرا...':'پایان')+(st.dry?' (پیش‌نمایش)':'')+'</div>';
    h+='<div>بررسی‌شده: <b>'+toFa(st.scanned||0)+'</b> · بی‌تصویر: <b style="color:#fbbf24">'+toFa(st.missing||0)+'</b>'
      +' · عکس‌دار شد: <b style="color:#4ade80">'+toFa(st.fixed||0)+'</b>'
      +(st.unmatched?' · بی‌تطبیق: <b style="color:#94a3b8">'+toFa(st.unmatched)+'</b>':'')
      +(st.failed?' · خطا: <b style="color:#f87171">'+toFa(st.failed)+'</b>':'')+'</div>';
    (st.log||[]).slice(-6).forEach(l=>{h+='<div style="color:#94a3b8;font-size:10px">'+esc(l.m||'')+'</div>';});
    if(res&&res.items&&res.items.length){
      h+='<div style="margin-top:6px;max-height:200px;overflow-y:auto;border-top:1px solid #334155;padding-top:6px">';
      res.items.slice(0,60).forEach(i=>{h+='<div style="font-size:10px;color:#cbd5e1">• '+esc(i.title||'')+' — <span style="color:#94a3b8">'+esc(i.status||'')+'</span></div>';});
      h+='</div>';
    }
    h+='</div>';
    r.innerHTML=h;
    if($('photoS')){$('photoS').textContent=st.running?'در حال اجرا':(st.fixed?toFa(st.fixed)+' عکس‌دار':'—');
      $('photoS').className='cst '+(st.running?'tg':(st.fixed?'on':'off'));}
    if(!st.running&&photoTimer){clearInterval(photoTimer);photoTimer=null;}
  }).catch(()=>{});
}

/* ============ v8.62: گزارش شبانه ============ */
function updateDigestBadge(){
  const el=$('digestS'),en=$('digestEnabled'),h=$('digestHour');
  if(!el||!en)return;
  el.textContent=en.checked?('ساعت '+toFa((h&&h.value)||23)):'خاموش';
  el.className='cst '+(en.checked?'on':'off');
}
function digestPreview(){
  const r=$('digestR');
  r.innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">در حال ساخت گزارش...</div>';
  fetch('?digest=1').then(x=>x.json()).then(d=>{
    if(!d.ok){r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا</div>';return;}
    r.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px">'
      +'<div style="color:#67e8f9;font-weight:700;font-size:11px;margin-bottom:6px">👁 پیش‌نمایش گزارش</div>'
      +'<pre style="white-space:pre-wrap;font-size:10.5px;color:#e2e8f0;max-height:320px;overflow-y:auto;margin:0">'+esc(d.message||'')+'</pre>'
      +(d.state&&d.state.last_date?'<div style="font-size:10px;color:#64748b;margin-top:6px">آخرین ارسال: '+esc(d.state.last_date)+'</div>':'')
      +'</div>';
  }).catch(()=>{r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا شبکه</div>';});
}
function digestSendNow(){
  if(!confirm('گزارش همین حالا به پیام‌رسان‌ها فرستاده شود؟'))return;
  const r=$('digestR');
  r.innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">در حال ارسال...</div>';
  fetch('?digest=1&send=1').then(x=>x.json()).then(d=>{
    if(d.sent){r.innerHTML='<div class="alert alert-success" style="padding:8px;font-size:11px">✓ گزارش فرستاده شد</div>';showToast('✓ ارسال شد');}
    else r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'ارسال نشد')+'</div>';
  }).catch(()=>{r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا شبکه</div>';});
}

function catLearnShow(){
  const box=$('catLearnR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ ...</div>';
  fetch('?catlearn=1').then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا</div>';return;}
    if(!d.count){box.innerHTML='<div style="color:#64748b;font-size:11px">هنوز چیزی آموخته نشده — '
      +'یک دسته را دستی اصلاح کنید.</div>';return;}
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">';
    h+='<div style="display:flex;align-items:center;margin-bottom:5px">'
      +'<span style="color:#93c5fd">🧠 '+toFa(d.count)+' کلمه آموخته شده</span>'
      +'<span style="flex:1"></span>'
      +'<button class="btn btn-red" onclick="catLearnClear()" style="font-size:10px;padding:3px 8px">پاک کردن همه</button></div>';
    d.rows.slice(0,40).forEach(r=>{
      h+='<div style="display:flex;gap:6px;align-items:center;border-top:1px solid #1e293b;padding:3px 0">'
        +'<b style="color:#e2e8f0;min-width:70px">'+esc(r.word)+'</b>'
        +'<span style="color:#94a3b8;flex:1">→ '+esc(r.cat_name||('#'+r.cat_id))+'</span>'
        +'<span style="color:#64748b;font-size:10px">'+toFa(r.times)+'×</span>'
        +(r.variants>1?'<span style="color:#fbbf24;font-size:10px" title="چند دستهٔ مختلف">⚠'+toFa(r.variants)+'</span>':'')
        +'<button class="btn btn-gray" onclick="catLearnForget(\''+encodeURIComponent(r.word)+'\')" '
        +'style="font-size:9px;padding:2px 6px">✕</button></div>';
    });
    if(d.count>40)h+='<div style="color:#64748b;padding-top:4px">… و '+toFa(d.count-40)+' مورد دیگر</div>';
    box.innerHTML=h+'</div>';
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا</div>';});
}
function catLearnForget(w){
  fetch('?catlearn=1&forget='+w).then(r=>r.json()).then(()=>{showToast('فراموش شد');catLearnShow();});
}
function catLearnClear(){
  if(!confirm('همهٔ آموخته‌ها پاک شوند؟'))return;
  fetch('?catlearn=1&clear=1').then(r=>r.json()).then(()=>{showToast('پاک شد');catLearnShow();});
}
function catLearnTest(){
  const t=prompt('عنوان محصول را بنویسید:');
  if(!t)return;
  const box=$('catLearnR');
  fetch('?catlearn=1&test='+encodeURIComponent(t)).then(r=>r.json()).then(d=>{
    if(!box)return;
    box.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">'
      +'<div style="color:#cbd5e1">عنوان: '+esc(d.title||'')+'</div>'
      +'<div style="color:#93c5fd">کلمهٔ اول: <b>'+esc(d.first_word||'—')+'</b></div>'
      +'<div style="color:'+(d.learned_cat?'#4ade80':'#64748b')+'">'
      +(d.learned_cat?('✓ دستهٔ آموخته‌شده: #'+d.learned_cat):'— هنوز برای این کلمه چیزی آموخته نشده')
      +'</div></div>';
  }).catch(()=>{});
}

/** v8.36: نشانگر کنار عنوان بخش «محصولات رفته از مبدأ» */
function updateRetireBadge(){
  const el=$('retireS'),sel=$('retireMode');
  if(!el||!sel)return;
  const lbl={off:'خاموش',draft:'پیش‌نویس',outofstock:'ناموجود',delete:'حذف'}[sel.value]||'خاموش';
  el.textContent=lbl;
  el.className='cst '+(sel.value==='off'?'off':'on');
}

/** v8.36: نشانگر کنار عنوان بخش «نگهبان صف» */
function updateStallBadge(){
  const el=$('stallS'),cb=$('stallWatchdog');
  if(!el||!cb)return;
  el.textContent=cb.checked?'فعال':'خاموش';
  el.className='cst '+(cb.checked?'on':'off');
}

/**
 * v8.34: پیش‌نمایش بازنشستگی — هیچ تغییری اعمال نمی‌کند، فقط نشان می‌دهد
 * چه محصولاتی روی مقصد پیدا می‌شوند و چه بلایی سرشان می‌آید.
 */
function retirePreview(){
  const box=$('retireR');
  const key=$('profileSelect')?$('profileSelect').value:'';
  if(!key){if(box)box.innerHTML='<div style="color:#fca5a5;font-size:11px">اول یک پروفایل انتخاب کنید</div>';return;}
  const mode=$('retireMode')?$('retireMode').value:'draft';
  if(mode==='off'){if(box)box.innerHTML='<div style="color:#94a3b8;font-size:11px">اقدام روی «کاری نکن» است</div>';return;}
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حال بررسی...</div>';
  fetch('?retire_run=1&dry=1&profile='+encodeURIComponent(key)+'&mode='+encodeURIComponent(mode))
   .then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#f87171;font-size:11px;background:#7f1d1d20;padding:6px 8px;border-radius:6px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    if(d.skipped){
      const blocked=d.guard&&d.guard.blocked;
      box.innerHTML='<div style="color:'+(blocked?'#fca5a5':'#94a3b8')+';font-size:11px;background:'+(blocked?'#7f1d1d20':'#0f172a')+';padding:6px 8px;border-radius:6px">'
        +(blocked?'🛑 ':'ℹ️ ')+esc(d.skipped)+'</div>';return;
    }
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">';
    h+='<div style="color:#fbbf24;margin-bottom:4px">پیش‌نمایش — هیچ تغییری اعمال نشد</div>';
    h+='<div style="color:#94a3b8">بررسی‌شده: '+toFa(d.checked||0)+' · یافت‌نشده: '+toFa(d.not_found||0)+'</div>';
    (d.items||[]).slice(0,12).forEach(it=>{
      h+='<div style="border-top:1px solid #1e293b;padding:3px 0;color:#cbd5e1">• '+esc(it.title||'')
        +' <span style="color:#64748b">'+esc(it.reason||'')+'</span>'
        +(it.woo?' <span style="color:#67e8f9">woo: '+esc(it.woo)+'</span>':'')
        +(it.bsl?' <span style="color:#c4b5fd">bsl: '+esc(it.bsl)+'</span>':'')+'</div>';
    });
    h+='<div style="margin-top:6px;color:#94a3b8">برای اجرای واقعی، «اقدام» را ذخیره کنید تا در اجرای خودکار بعدی انجام شود.</div>';
    h+='</div>';
    box.innerHTML=h;
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا در ارتباط</div>';});
}

/** v8.34: بررسی دستی وضعیت گیر کردن صف */
function watchdogCheck(){
  const box=$('watchdogR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حال بررسی...</div>';
  const after=$('stallAfter')?$('stallAfter').value:300;
  fetch('?queue_watchdog=1&dry=1&after='+encodeURIComponent(after)).then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا</div>';return;}
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">';
    (d.checks||[]).forEach(c=>{
      const nm=c.which==='bsl'?'باسلام':'ووکامرس';
      if(c.stalled){
        h+='<div style="color:#fca5a5">⚠️ '+esc(nm)+' گیر کرده — '+toFa(c.idle||0)+' ثانیه بی‌حرکت'
          +' ('+toFa(c.current||0)+'/'+toFa(c.total||0)+')</div>';
      }else{
        h+='<div style="color:#86efac">✓ '+esc(nm)+' — '+esc(c.reason||'سالم')+'</div>';
      }
    });
    h+='<div style="margin-top:4px;color:#64748b">در اجرای خودکار بعدی، موارد گیرکرده ادامه داده می‌شوند.</div>';
    h+='</div>';
    box.innerHTML=h;
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا در ارتباط</div>';});
}

/* =====================================================================
 *  v8.32: مودال‌های استعلام — سفارش‌ها و گفتگوها
 *  اول لیست را نشان می‌دهد، بعد کاربر انتخاب می‌کند چه چیزی
 *  به پیام‌رسان‌ها فرستاده شود. هر دو مودال از یک اسکلت مشترک می‌آیند.
 * ===================================================================== */
let inqState={kind:'',filter:'',rows:[],sel:{},loading:false};

function inqClose(){
  const m=document.getElementById('inqModalContainer');
  if(m)m.remove();
  inqState={kind:'',filter:'',rows:[],sel:{},loading:false};
}

/** تاریخ ISO را به شکل خوانا و کوتاه فارسی درمی‌آورد */
function inqDate(s){
  if(!s)return '—';
  const d=new Date(s);
  if(isNaN(d))return '—';
  try{
    return new Intl.DateTimeFormat('fa-IR',{month:'short',day:'numeric',
      hour:'2-digit',minute:'2-digit'}).format(d);
  }catch(e){return d.toLocaleString();}
}

function inqMoney(n){return toFa(Number(n||0).toLocaleString('en-US'))+' تومان';}

/** کلید یکتای هر ردیف بسته به نوع */
function inqId(r){return inqState.kind==='orders'?r.parcel_id:r.chat_id;}

/** ردیف‌هایی که به‌طور پیش‌فرض «اقدام‌نشده» شمرده می‌شوند */
function inqIsPending(r){return inqState.kind==='orders'?!!r.unsent:(r.unseen>0);}

function inqSelectedIds(){
  return Object.keys(inqState.sel).filter(k=>inqState.sel[k]);
}

function inqToggle(id){
  inqState.sel[id]=!inqState.sel[id];
  inqRenderFoot();
  const cb=document.getElementById('inqCb_'+id);
  if(cb)cb.checked=!!inqState.sel[id];
  const tr=document.getElementById('inqRow_'+id);
  if(tr)tr.style.background=inqState.sel[id]?'#1e3a5f':'';
}

function inqSelectAll(on){
  inqState.rows.forEach(r=>{inqState.sel[inqId(r)]=on;});
  inqRenderBody();inqRenderFoot();
}

/** فقط موارد اقدام‌نشده را تیک می‌زند */
function inqSelectPending(){
  inqState.rows.forEach(r=>{inqState.sel[inqId(r)]=inqIsPending(r);});
  inqRenderBody();inqRenderFoot();
}

function openOrdersModal(filter){inqOpen('orders',filter||'all');}
function openChatsModal(filter){inqOpen('chats',filter||'all');}

function inqOpen(kind,filter){
  inqState.kind=kind;inqState.filter=filter;inqState.sel={};inqState.loading=true;
  const isOrd=kind==='orders';
  const title=isOrd?'🛒 سفارش‌های باسلام':'💬 گفتگوهای باسلام';
  let html='<div class="bsl-modal-overlay" onclick="if(event.target===this)inqClose()">';
  html+='<div class="bsl-modal" style="max-width:920px">';
  html+='<div class="bsl-modal-head"><h2 id="inqTitle">'+title+'</h2>'
      +'<button class="btn btn-gray" onclick="inqClose()">✕</button></div>';
  // نوار فیلتر
  html+='<div style="display:flex;gap:6px;padding:8px 12px;background:#111c31;border-bottom:1px solid #334155;flex-wrap:wrap;align-items:center">';
  if(isOrd){
    html+='<button class="btn btn-gray" id="inqF_all" onclick="inqSetFilter(\'all\')" style="font-size:11px;padding:5px 10px">همه</button>';
    html+='<button class="btn btn-gray" id="inqF_unsent" onclick="inqSetFilter(\'unsent\')" style="font-size:11px;padding:5px 10px">📦 ارسال‌نشده</button>';
  }else{
    html+='<button class="btn btn-gray" id="inqF_all" onclick="inqSetFilter(\'all\')" style="font-size:11px;padding:5px 10px">همه</button>';
    html+='<button class="btn btn-gray" id="inqF_unseen" onclick="inqSetFilter(\'unseen\')" style="font-size:11px;padding:5px 10px">💬 خوانده‌نشده</button>';
  }
  html+='<span style="flex:1"></span>';
  html+='<span id="inqSummary" style="font-size:11px;color:#94a3b8"></span>';
  html+='<button class="btn btn-gray" onclick="inqReload()" style="font-size:11px;padding:5px 10px">🔄 تازه‌سازی</button>';
  html+='</div>';
  html+='<div class="bsl-modal-body" id="inqBody" style="min-height:180px"></div>';
  html+='<div class="bsl-modal-pager" id="inqFoot" style="justify-content:space-between;flex-wrap:wrap;gap:6px"></div>';
  html+='</div></div>';
  const old=document.getElementById('inqModalContainer');if(old)old.remove();
  const div=document.createElement('div');div.id='inqModalContainer';div.innerHTML=html;
  document.body.appendChild(div);
  inqReload();
}

function inqSetFilter(f){inqState.filter=f;inqState.sel={};inqReload();}

function inqReload(){
  const body=document.getElementById('inqBody');
  if(body)body.innerHTML='<div style="padding:26px;text-align:center;color:#93c5fd;font-size:12px">⏳ در حال استعلام از باسلام...</div>';
  inqRenderFoot();
  const isOrd=inqState.kind==='orders';
  const url=isOrd
    ?('?bsl_orders_list=1&per_page=30&filter='+encodeURIComponent(inqState.filter))
    :('?bsl_chats_list=1&limit=50&filter='+encodeURIComponent(inqState.filter));
  fetch(url).then(r=>r.json()).then(d=>{
    inqState.loading=false;
    if(!d||!d.ok){
      if(body)body.innerHTML='<div style="padding:20px;color:#fca5a5;font-size:12px;background:#7f1d1d20;border-radius:8px;margin:8px">✗ '+esc(d&&d.error?d.error:'خطا در دریافت')+'</div>';
      inqRenderFoot();return;
    }
    inqState.rows=d.rows||[];
    // پیش‌فرض: موارد اقدام‌نشده تیک خورده باشند تا کار کاربر کم شود
    inqState.rows.forEach(r=>{if(inqState.sel[inqId(r)]===undefined)inqState.sel[inqId(r)]=inqIsPending(r);});
    const sm=document.getElementById('inqSummary');
    if(sm){
      sm.innerHTML=isOrd
        ?(toFa(d.total||0)+' سفارش · <b style="color:#fbbf24">'+toFa(d.unsent||0)+'</b> ارسال‌نشده')
        :(toFa(d.total||0)+' گفتگو · <b style="color:#fbbf24">'+toFa(d.unseen||0)+'</b> خوانده‌نشده');
    }
    ['all','unsent','unseen'].forEach(f=>{
      const b=document.getElementById('inqF_'+f);
      if(b){b.className='btn '+(inqState.filter===f?'btn-cyan':'btn-gray');}
    });
    inqRenderBody();inqRenderFoot();
  }).catch(e=>{
    inqState.loading=false;
    if(body)body.innerHTML='<div style="padding:20px;color:#fca5a5;font-size:12px">✗ خطا در ارتباط: '+esc(e.message)+'</div>';
    inqRenderFoot();
  });
}

function inqRenderBody(){
  const body=document.getElementById('inqBody');
  if(!body)return;
  const rows=inqState.rows;
  if(!rows.length){
    body.innerHTML='<div style="padding:30px;text-align:center;color:#64748b;font-size:12px">موردی یافت نشد</div>';
    return;
  }
  const isOrd=inqState.kind==='orders';
  let h='<table class="bsl-modal-table"><thead><tr>'
    +'<th style="width:34px"><input type="checkbox" onclick="inqSelectAll(this.checked)" style="width:15px;height:15px;cursor:pointer"></th>';
  h+=isOrd
    ?'<th>شماره</th><th>مشتری</th><th>مبلغ</th><th>وضعیت</th><th>تاریخ</th>'
    :'<th>مشتری</th><th>آخرین پیام</th><th>خوانده‌نشده</th><th>زمان</th>';
  h+='</tr></thead><tbody>';
  rows.forEach(r=>{
    const id=inqId(r);
    const pend=inqIsPending(r);
    const on=!!inqState.sel[id];
    h+='<tr id="inqRow_'+id+'" style="border-bottom:1px solid #1e293b;'+(on?'background:#1e3a5f':'')+'">';
    h+='<td style="text-align:center"><input type="checkbox" id="inqCb_'+id+'" '+(on?'checked':'')
      +' onclick="inqToggle('+id+')" style="width:15px;height:15px;cursor:pointer"></td>';
    if(isOrd){
      h+='<td style="font-family:ui-monospace,monospace;direction:ltr;text-align:right">#'+toFa(r.order_id||r.parcel_id)+'</td>';
      h+='<td>'+esc(r.customer||'—')+(r.items_count>0?'<div style="font-size:9.5px;color:#64748b">'+toFa(r.items_count)+' قلم</div>':'')+'</td>';
      h+='<td style="white-space:nowrap">'+inqMoney(r.amount)+'</td>';
      h+='<td><span style="font-size:10px;padding:2px 7px;border-radius:4px;background:'
        +(pend?'#7c2d12':'#14532d')+';color:'+(pend?'#fdba74':'#86efac')+'">'+esc(r.status||'—')+'</span></td>';
      h+='<td style="font-size:10px;color:#94a3b8;white-space:nowrap">'+esc(inqDate(r.created_at))+'</td>';
    }else{
      h+='<td>'+esc(r.who||'—')+'</td>';
      h+='<td style="max-width:340px;color:#cbd5e1">'+esc((r.text||'').slice(0,90))+'</td>';
      h+='<td style="text-align:center">'+(r.unseen>0
        ?'<span style="font-size:10px;padding:2px 7px;border-radius:10px;background:#7f1d1d;color:#fca5a5">'+toFa(r.unseen)+'</span>'
        :'<span style="color:#475569">—</span>')+'</td>';
      h+='<td style="font-size:10px;color:#94a3b8;white-space:nowrap">'+esc(inqDate(r.updated_at))+'</td>';
    }
    h+='</tr>';
  });
  h+='</tbody></table>';
  body.innerHTML=h;
}

function inqRenderFoot(){
  const foot=document.getElementById('inqFoot');
  if(!foot)return;
  const n=inqSelectedIds().length;
  const isOrd=inqState.kind==='orders';
  const lbl=isOrd?'سفارش':'گفتگو';
  let h='<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">';
  h+='<button class="btn btn-gray" onclick="inqSelectPending()" style="font-size:11px;padding:5px 10px">'
    +(isOrd?'انتخاب ارسال‌نشده‌ها':'انتخاب خوانده‌نشده‌ها')+'</button>';
  h+='<button class="btn btn-gray" onclick="inqSelectAll(false)" style="font-size:11px;padding:5px 10px">هیچ‌کدام</button>';
  h+='<span style="font-size:11px;color:'+(n?'#4ade80':'#64748b')+'">'+toFa(n)+' '+lbl+' انتخاب شده</span>';
  h+='</div>';
  h+='<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">';
  h+='<button class="btn btn-purple" id="inqSendDigest" '+(n?'':'disabled')
    +' onclick="inqSend(1)" style="font-size:11px;padding:6px 11px">📋 ارسال خلاصه (یک پیام)</button>';
  h+='<button class="btn btn-green" id="inqSendEach" '+(n?'':'disabled')
    +' onclick="inqSend(0)" style="font-size:11px;padding:6px 11px">📨 ارسال جداگانه</button>';
  h+='</div>';
  foot.innerHTML=h;
}

function inqSend(digest){
  const ids=inqSelectedIds();
  if(!ids.length){showToast('موردی انتخاب نشده',1);return;}
  if(!digest&&ids.length>5&&!confirm('می‌خواهید '+ids.length+' پیام جداگانه فرستاده شود؟\nبرای شلوغ نشدن پیام‌رسان، «ارسال خلاصه» بهتر است.'))return;
  ['inqSendDigest','inqSendEach'].forEach(k=>{const b=document.getElementById(k);if(b){b.disabled=true;}});
  const b2=document.getElementById(digest?'inqSendDigest':'inqSendEach');
  const oldTxt=b2?b2.textContent:'';
  if(b2)b2.textContent='⏳ در حال ارسال...';
  fetch('?bsl_notify_selected=1&kind='+encodeURIComponent(inqState.kind)
    +'&digest='+(digest?1:0)+'&ids='+encodeURIComponent(ids.join(',')))
    .then(r=>r.json()).then(d=>{
      if(b2)b2.textContent=oldTxt;
      inqRenderFoot();
      if(!d||!d.ok){showToast((d&&d.error)?d.error:'ارسال ناموفق',1);return;}
      if(d.note){showToast(d.note,1);return;}
      const dl=d.delivery||{};
      const bad=Object.keys(dl).filter(k=>dl[k]!=='sent');
      if(bad.length)showToast('⚠ ارسال به '+bad.join('، ')+' ناموفق بود',1);
      else showToast('✓ '+toFa(d.sent||0)+' پیام فرستاده شد');
    }).catch(()=>{
      if(b2)b2.textContent=oldTxt;
      inqRenderFoot();showToast('خطا شبکه',1);
    });
}

/* ===== v9.16: بکاپ و بازیابی ===== */
function bkSet(msg,color){const s=$('bkStatus');if(s){s.innerHTML=msg;s.style.color=color||'#94a3b8';}}
function bkRefresh(){
    fetch('?backup_status=1').then(r=>r.json()).then(d=>{
        if(!d||!d.ok)return;
        const c=d.cfg||{};
        /* v9.18: مقادیر ارث‌بری‌شده از «منبع و نصب‌کننده» */
        const vc=c.vc||{};
        if($('bkVcRepo'))$('bkVcRepo').textContent=vc.repo||'— تنظیم نشده';
        if($('bkVcBranch'))$('bkVcBranch').textContent=vc.branch||'main';
        if($('bkVcToken')){
            $('bkVcToken').innerHTML=vc.has_token
                ?'<span style="color:#4ade80">ذخیره شده ✓</span>'
                :'<span style="color:#fbbf24">تنظیم نشده — برای مخزن خصوصی لازم است</span>';
        }
        if($('bkOwnRepo'))$('bkOwnRepo').checked=!!c.own_repo;
        bkToggleOwn();
        if($('bkRepo')&&!$('bkRepo').value&&c.own_repo)$('bkRepo').value=c.repo||'';
        if($('bkBranch')&&!$('bkBranch').value&&c.own_repo)$('bkBranch').value=c.branch||'main';
        if($('bkPath')&&!$('bkPath').value)$('bkPath').value=c.path||'backups';
        if($('bkToken'))$('bkToken').placeholder=(c.own_repo&&c.token)?('ذخیره شده '+c.token):'ghp_...';
        if($('bkIncData'))$('bkIncData').checked=!!c.include_data;
        if($('bkIncCode'))$('bkIncCode').checked=!!c.include_code;
        if($('bkAuto'))$('bkAuto').checked=!!c.auto;
        if($('bkEvery'))$('bkEvery').value=c.auto_every_h||24;
        if($('bkKeep'))$('bkKeep').value=c.keep||20;
        const b=$('bkBadge');
        if(b){
            const has=(d.local||[]).length;
            b.textContent=has?(toFa(has)+' نسخه'):'بدون بکاپ';
            b.className='cst '+(has?'on':'off');
        }
        // فهرست بکاپ‌های محلی
        let h='';
        (d.local||[]).forEach(f=>{
            h+='<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;'
              +'background:#0f172a;border:1px solid #334155;border-radius:7px;padding:6px 8px;margin-bottom:4px">'
              +'<div><code style="direction:ltr;font-size:10px">'+esc(f.name)+'</code>'
              +'<br><span style="color:#64748b;font-size:9.5px">'+esc(f.at_h)+' · '+toFa(Math.round(f.size/1024))+'KB</span></div>'
              +'<div style="display:flex;gap:4px">'
              +'<button class="btn" style="font-size:9.5px;padding:3px 7px;background:#334155;color:#cbd5e1;border:none;border-radius:4px" onclick="bkPeek(\''+esc(f.name)+'\')">👁</button>'
              +'<button class="btn" style="font-size:9.5px;padding:3px 7px;background:#0e7490;color:#fff;border:none;border-radius:4px" onclick="bkDownload(\''+esc(f.name)+'\')">⬇</button>'
              +'<button class="btn" style="font-size:9.5px;padding:3px 7px;background:#c2410c;color:#fff;border:none;border-radius:4px" onclick="bkRestore(\'local\',\''+esc(f.name)+'\')">♻️</button>'
              +'</div></div>';
        });
        if($('bkList'))$('bkList').innerHTML=h||'<span style="color:#64748b">هنوز بکاپی گرفته نشده</span>';
        // گزارش
        let lg='';
        (d.log||[]).forEach(l=>{
            const okc=l.ok?'#4ade80':'#f87171';
            lg+='<div style="border-right:2px solid '+okc+';padding:2px 8px;margin-bottom:4px">'
              +'<span style="color:'+okc+'">'+(l.ok?'✅':'❌')+'</span> '
              +'<span style="color:#64748b">'+esc(l.at_h||'')+'</span> '
              +(l.files!==undefined?('<span style="color:#94a3b8">'+toFa(l.files)+' فایل</span> '):'')
              +(l.github?('<span style="color:#67e8f9">گیت‌هاب: '+esc(l.github)+'</span>'):'')
              +(l.restore?('<span style="color:#fbbf24">بازیابی '+toFa((l.restore||[]).length)+' فایل</span>'):'')
              +(l.error?('<br><span style="color:#f87171;font-size:10px">'+esc(l.error)+'</span>'):'')
              +'</div>';
        });
        if($('bkLog'))$('bkLog').innerHTML=lg||'<span style="color:#64748b">—</span>';
    }).catch(()=>{});
}
/* v9.18: فیلدهای مخزن فقط وقتی معنا دارند که «مخزن جدا» روشن باشد */
function bkToggleOwn(){
    const on=!!(($('bkOwnRepo')||{}).checked);
    const box=$('bkOwnBox'), inh=$('bkInherit');
    if(box)box.style.display=on?'block':'none';
    if(inh)inh.style.opacity=on?'0.45':'1';
}
function bkSaveCfg(){
    const fd=new FormData();
    fd.append('action','backup_save_cfg');
    const own=!!(($('bkOwnRepo')||{}).checked);
    if(own){
        fd.append('own_repo','1');
        fd.append('repo',($('bkRepo')||{}).value||'');
        fd.append('branch',($('bkBranch')||{}).value||'main');
        const t=($('bkToken')||{}).value||'';
        if(t)fd.append('token',t);
    }
    fd.append('path',($('bkPath')||{}).value||'backups');
    if(($('bkIncData')||{}).checked)fd.append('include_data','1');
    if(($('bkIncCode')||{}).checked)fd.append('include_code','1');
    if(($('bkAuto')||{}).checked)fd.append('auto','1');
    fd.append('auto_every_h',($('bkEvery')||{}).value||24);
    fd.append('keep',($('bkKeep')||{}).value||20);
    bkSet('در حال ذخیره...','#67e8f9');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(d&&d.ok){bkSet('✅ ذخیره شد','#4ade80');if($('bkToken'))$('bkToken').value='';bkRefresh();}
        else bkSet('❌ ذخیره نشد','#f87171');
    }).catch(()=>bkSet('❌ خطای شبکه','#f87171'));
}
function bkRunNow(){
    bkSet('⏳ در حال گرفتن بکاپ...','#67e8f9');
    fetch('?backup_run=1').then(r=>r.json()).then(d=>{
        if(!d){bkSet('❌ پاسخ نامعتبر','#f87171');return;}
        let m=(d.ok?'✅':'⚠️')+' '+toFa(d.files||0)+' فایل ('+toFa(Math.round((d.bytes||0)/1024))+'KB)';
        if(d.github)m+=' · گیت‌هاب: '+esc(d.github);
        if(d.error)m+='<br><span style="color:#f87171">'+esc(d.error)+'</span>';
        bkSet(m,d.ok?'#4ade80':'#fbbf24');
        bkRefresh();
    }).catch(()=>bkSet('❌ خطای شبکه','#f87171'));
}
function bkDownload(n){window.open('?backup_download='+encodeURIComponent(n),'_blank');}
function bkPeek(n){
    fetch('?backup_peek='+encodeURIComponent(n)).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){showToast('خوانده نشد',1);return;}
        let m='📦 '+n+'\n'+(d.created_at_h||'')+' · v'+(d.version||'')+'\n\n';
        (d.files||[]).forEach(f=>{
            m+='• '+f.name+' ('+Math.round(f.size/1024)+'KB)';
            if(f.profiles!==undefined)m+=' — '+f.profiles+' پروفایل: '+(f.names||[]).join('، ');
            m+='\n';
        });
        alert(m);
    }).catch(()=>showToast('خطا',1));
}
function bkRemoteList(){
    bkSet('⏳ خواندن از گیت‌هاب...','#67e8f9');
    fetch('?backup_remote_list=1').then(r=>r.json()).then(d=>{
