}
/* v8.61: روش عبور از محدودیت شبکه برای سرویس‌های هوش مصنوعی */
function aiNetToggle(){
    const m=($('aiNetMode')||{}).value||'direct';
    const show=(id,on)=>{const e=$(id);if(e)e.style.display=on?'':'none';};
    show('aiNetDoh',m==='doh');
    show('aiNetDns',m==='dns');
    show('aiNetWorker',m==='worker');
    show('aiNetGateway',m==='gateway');
    show('aiNetProxy',m==='proxy');
    updateAiNetBadge();
}
/* v9.60: تب‌بندیِ بخش هوش مصنوعی — هر تب یک پنل را نشان می‌دهد تا همه‌چیز
   منظم و قابل‌دسترس باشد (قبلاً یک ستونِ بلند بود و بخش‌های پایین مثل «روش
   اتصال» یا «تست دسته» بریده می‌شدند). */
function aiTab(tab){
    const btns=document.querySelectorAll('.ai-tab-btn');
    btns.forEach(b=>{b.classList.toggle('active', b.getAttribute('data-ai-tab')===tab);});
    const panels=document.querySelectorAll('.ai-tab-panel');
    // v9.61: قبلاً اینجا برای تبِ انتخاب‌شده display='' می‌گذاشتیم که یعنی
    // «استایل درون‌خطی را بردار». ولی فقط تبِ «ارائه‌دهنده‌ها» کلاس .active را
    // دارد (CSS آن را display:block می‌کند)؛ بقیهٔ تب‌ها چنین کلاسی ندارند و با
    // CSS پایه display:none می‌ماندند. نتیجه: با کلیک روی «تست/مدل‌ها/کاندید/
    // اتصال» هیچ محتوایی دیده نمی‌شد (تب‌ها خالی). حالا برای تبِ انتخاب‌شده
    // صریحاً display:block می‌گذاریم تا حتی تب‌های بدون کلاس .active هم باز شوند.
    panels.forEach(p=>{p.style.display=(p.getAttribute('data-ai-panel')===tab)?'block':'none';});
}
function updateAiNetBadge(){
    const el=$('aiS'),m=($('aiNetMode')||{}).value||'direct';
    if(!el)return;
    if(el.textContent==='✓'||el.textContent==='✗')return;   // نتیجهٔ تست را پاک نکن
    const names={direct:'مستقیم',doh:'DoH',dns:'IP دستی',worker:'Worker',gateway:'درگاه',proxy:'پروکسی'};
    el.textContent=names[m]||m;
}
function getAiNet(){
    return {
        mode:($('aiNetMode')||{}).value||'direct',
        resolve_ip:(($('aiNetResolveIp')||{}).value||'').trim(),
        doh_url:($('aiNetDohUrl')||{}).value||'https://cloudflare-dns.com/dns-query',
        worker_url:(($('aiNetWorkerUrl')||{}).value||'').trim(),
        proxy:(($('aiNetProxyUrl')||{}).value||'').trim(),
        proxy_type:($('aiNetProxyType')||{}).value||'http',
        proxy_auth:(($('aiNetProxyAuth')||{}).value||'').trim(),
        timeout:parseInt(($('aiNetTimeout')||{}).value)||25,
        ipv4:1,
        fallback:($('aiNetFallback')||{}).checked?1:0
    };
}
function applyAiNet(n){
    n=n||{};
    if($('aiNetMode'))$('aiNetMode').value=n.mode||'direct';
    if($('aiNetResolveIp'))$('aiNetResolveIp').value=n.resolve_ip||'';
    if($('aiNetDohUrl')&&n.doh_url)$('aiNetDohUrl').value=n.doh_url;
    if($('aiNetWorkerUrl'))$('aiNetWorkerUrl').value=n.worker_url||'';
    if($('aiNetProxyUrl'))$('aiNetProxyUrl').value=n.proxy||'';
    if($('aiNetProxyType'))$('aiNetProxyType').value=n.proxy_type||'http';
    if($('aiNetProxyAuth'))$('aiNetProxyAuth').value=n.proxy_auth||'';
    if($('aiNetTimeout'))$('aiNetTimeout').value=n.timeout||25;
    if($('aiNetFallback'))$('aiNetFallback').checked=!!n.fallback;
    aiNetToggle();
}
/* عیب‌یابی: همهٔ روش‌ها را می‌سنجد و می‌گوید کدام کار می‌کند */
function aiProbe(){
    const r=$('aiTR');
    r.innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">🩺 در حال سنجش روش‌ها... (تا یک دقیقه)</div>';
    const n=getAiNet();
    // v9.27: base_url دیگر از فیلد حذف‌شده فرستاده نمی‌شود؛ سمت سرور از ارائه‌دهندهٔ فعال می‌گیرد
    const q=new URLSearchParams({ai_probe:'1',
        net_mode:n.mode,net_resolve_ip:n.resolve_ip,net_doh_url:n.doh_url,
        net_worker_url:n.worker_url,net_proxy:n.proxy,net_proxy_type:n.proxy_type,net_proxy_auth:n.proxy_auth});
    fetch('?'+q.toString()).then(x=>x.json()).then(d=>{
        if(!d.ok){r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
        let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px;font-size:11px;line-height:2">';
        h+='<div style="color:#67e8f9;font-weight:700;margin-bottom:6px">🩺 نتیجهٔ عیب‌یابی — '+esc(d.host||'')+'</div>';
        if(d.provider_name)h+='<div style="color:#94a3b8;margin-bottom:6px">ارائه‌دهنده: '+esc(d.provider_name)+' · مدل: <span dir="ltr">'+esc(d.model||'')+'</span></div>';
        (d.steps||[]).forEach(st=>{
            h+='<div>'+(st.ok?'🟢':'🔴')+' '+esc(st.name)+' — <span style="color:#94a3b8">'+esc(st.detail||'')+'</span>'
              +(st.ms!==undefined?' <span style="color:#64748b">('+toFa(st.ms)+'ms)</span>':'')+'</div>';
        });
        if((d.modes||[]).length){
            h+='<div style="color:#fbbf24;font-weight:700;margin:8px 0 4px">روش‌های عبور:</div>';
            const names={direct:'مستقیم',doh:'DoH',dns:'IP دستی',worker:'Worker',gateway:'درگاه',proxy:'پروکسی'};
            d.modes.forEach(m=>{
                h+='<div>'+(m.reached?'🟢':'🔴')+' <b>'+esc(names[m.mode]||m.mode)+'</b> — '+esc(m.note||'')
                  +' <span style="color:#64748b">('+toFa(m.ms)+'ms)</span></div>';
            });
        }
        h+='<div style="margin-top:8px;padding-top:6px;border-top:1px solid #334155;color:'+((d.working||[]).length?'#4ade80':'#fca5a5')+'">'+esc(d.summary||'')+'</div>';
        if(d.recommended){
            h+='<button class="btn btn-green" style="margin-top:8px;font-size:11px;padding:5px 10px" onclick="aiUseMode(\''+d.recommended+'\')">✓ استفاده از روش پیشنهادی</button>';
        }
        h+='</div>';
        r.innerHTML=h;
    }).catch(()=>{r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا شبکه</div>';});
}
function aiUseMode(m){
    if($('aiNetMode')){$('aiNetMode').value=m;aiNetToggle();}
    saveConn();
    showToast('✓ روش «'+m+'» انتخاب و ذخیره شد');
}
/* کد آمادهٔ Cloudflare Worker — کاربر کپی می‌کند و در حساب رایگان خودش می‌گذارد */
function aiShowWorkerCode(){
    const code=[
"// Cloudflare Worker — واسط رساندن درخواست به سرویس هوش مصنوعی",
"// ۱) وارد dash.cloudflare.com شوید → Workers → Create Worker",
"// ۲) این کد را جایگزین کنید → Deploy",
"// ۳) آدرس xxx.workers.dev را در تنظیمات این برنامه بگذارید",
"export default {",
"  async fetch(request) {",
"    const cors = {",
"      'Access-Control-Allow-Origin': '*',",
"      'Access-Control-Allow-Headers': '*',",
"      'Access-Control-Allow-Methods': 'GET,POST,OPTIONS'",
"    };",
"    if (request.method === 'OPTIONS') return new Response(null, { headers: cors });",
"",
"    // آدرس مقصد: از هدر X-Target-URL یا از مسیر بعد از /",
"    let target = request.headers.get('X-Target-URL');",
"    if (!target) {",
"      const u = new URL(request.url);",
"      target = u.pathname.slice(1) + u.search;",
"      if (target.startsWith('https:/') && !target.startsWith('https://'))",
"        target = target.replace('https:/', 'https://');",
"      if (target.startsWith('http:/') && !target.startsWith('http://'))",
"        target = target.replace('http:/', 'http://');",
"    }",
"    if (!/^https?:\\/\\//.test(target))",
"      return new Response('bad target', { status: 400, headers: cors });",
"",
"    const h = new Headers(request.headers);",
"    h.delete('X-Target-URL');",
"    h.delete('Host');",
"",
"    const resp = await fetch(target, {",
"      method: request.method,",
"      headers: h,",
"      body: ['GET','HEAD'].includes(request.method) ? undefined : await request.arrayBuffer()",
"    });",
"    const out = new Headers(resp.headers);",
"    Object.entries(cors).forEach(([k,v]) => out.set(k,v));",
"    return new Response(resp.body, { status: resp.status, headers: out });",
"  }",
"};"
    ].join('\n');
    const r=$('aiTR');
    r.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px">'
      +'<div style="color:#67e8f9;font-weight:700;font-size:11px;margin-bottom:6px">📄 کد Cloudflare Worker</div>'
      +'<textarea id="aiWorkerCode" readonly style="width:100%;height:220px;font-family:ui-monospace,monospace;font-size:10px;direction:ltr;text-align:left;background:#111c31;color:#e2e8f0;border:1px solid #334155;border-radius:6px;padding:8px"></textarea>'
      +'<button class="btn btn-cyan" style="margin-top:6px;font-size:11px;padding:5px 10px" onclick="aiCopyWorkerCode()">📋 کپی</button>'
      +'<div style="font-size:10px;color:#64748b;margin-top:6px;line-height:1.8">حساب رایگان Cloudflare روزانه ۱۰۰٬۰۰۰ درخواست می‌دهد که برای این کار کافی است.</div>'
      +'</div>';
    $('aiWorkerCode').value=code;
}
function aiCopyWorkerCode(){
    const t=$('aiWorkerCode');if(!t)return;
    t.select();
    try{document.execCommand('copy');showToast('✓ کد کپی شد');}
    catch(e){if(navigator.clipboard){navigator.clipboard.writeText(t.value);showToast('✓ کد کپی شد');}}
}
function testAi(){const s=$('aiS'),r=$('aiTR');const pid=$('aiProviderSel')?$('aiProviderSel').value:'',mid=$('aiModelSel')?$('aiModelSel').value:'';if(!pid||!mid){r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ ابتدا یک ارائه‌دهنده و مدل فعال انتخاب کنید</div>';return;}s.textContent='تست...';s.className='cst tg';r.innerHTML='';const fd=new FormData();fd.append('action','test_ai');fd.append('provider_id',pid);fd.append('model_id',mid);const _n=getAiNet();fd.append('net_mode',_n.mode);fd.append('net_resolve_ip',_n.resolve_ip);fd.append('net_doh_url',_n.doh_url);fd.append('net_worker_url',_n.worker_url);fd.append('net_proxy',_n.proxy);fd.append('net_proxy_type',_n.proxy_type);fd.append('net_proxy_auth',_n.proxy_auth);fd.append('net_fallback',_n.fallback);fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{if(d.ok){s.textContent='✓';s.className='cst on';r.innerHTML='<div class="alert alert-success" style="padding:8px;font-size:11px">✓ '+esc(d.message)+' | مدل: '+esc(d.model)+' | پاسخ: '+esc(d.response||'')+(d.via?' | مسیر: <b>'+esc(d.via)+'</b>':'')+'</div>';aiTestOne(pid,mid);}else{s.textContent='✗';s.className='cst off';let _t='';if(d.tried&&d.tried.length>1){_t='<div style="margin-top:4px;font-size:10px;color:#fca5a5">تلاش‌ها: '+d.tried.map(x=>esc(x.mode)+'='+(x.code||'✗')).join(' · ')+'</div>';}
r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'خطا')+_t+(d.cf_detail?'<div style="margin-top:4px;font-size:10px;color:#fbbf24;direction:ltr;text-align:left">'+esc(d.cf_detail)+'</div>':'')+'<div style="margin-top:6px"><button class="btn btn-orange" style="font-size:10px;padding:4px 8px" onclick="aiProbe()">🩺 عیب‌یابی روش‌ها</button></div></div>';}}).catch(()=>{s.textContent='✗';s.className='cst off';});}
/* ============ v9.20: مدیریت چند-ارائه‌دهندهٔ هوش مصنوعی ============ */
let aiProvData={providers:[],selected:{provider:'',model:''}};
function aiLoadProviders(){fetch('?ai_providers_status=1').then(r=>r.json()).then(d=>{if(d&&d.ok){aiProvData=d;aiRenderProviders();}else{if(d&&d.error)showToast('خطا: '+d.error,1);}}).catch(()=>{});aiCandRender();}
/* ============ v9.38: مدل‌های کاندید + مدل مستر + پایگاه رای ============ */
var aiCandData=null;
var aiCandCtx={task:'category',input:'',keys:[],items:[]};
function aiCandLoad(cb){
  fetch('?ai_candidates=1').then(r=>r.json()).then(d=>{aiCandData=d||{candidates:[],master:'',pin:'',history:[]};if(cb)cb(aiCandData);}).catch(()=>{});
}
function aiCandSave(addKey,removeKey,isPin,removeKeys){
  fetch('?ai_candidates=1').then(r=>r.json()).then(d=>{
    let list=((d&&d.candidates)||[]).map(c=>({provider:c.provider,model:c.model}));
    if(addKey){
      const i=addKey.indexOf('::');
      if(i>0){const pp=addKey.slice(0,i),mm=addKey.slice(i+2);if(!list.find(x=>x.provider===pp&&x.model===mm))list.push({provider:pp,model:mm});}
    }
    const rmKeys=removeKeys&&removeKeys.length?removeKeys:(removeKey?[removeKey]:[]);
    if(rmKeys.length){
      const rmSet=new Set(rmKeys);
      list=list.filter(x=>!rmSet.has(x.provider+'::'+x.model));
    }
    const fd=new FormData();
    fd.append('action','ai_candidates_save');
    fd.append('candidates',JSON.stringify(list));
    if(isPin)fd.append('pin',($('aiMasterPin')||{}).value||'');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(res=>{
      if(res&&res.ok){showToast(isPin?'✓ مدل مستر ثبت شد':'✓ کاندیدها ذخیره شد');aiCandRender();}
      else showToast('خطا: '+((res&&res.error)||'نامشخص'),true);
    }).catch(()=>showToast('خطا در ارتباط',true));
  }).catch(()=>showToast('خطا در ارتباط',true));
}
function aiCandAddFromSel(){
  const pid=($('aiProviderSel')||{}).value||'';
  const mid=($('aiModelSel')||{}).value||'';
  if(!pid||!mid){showToast('اول از بالای همین بخش یک ارائه‌دهنده و مدل فعال انتخاب کنید',1);return;}
  aiCandSave(pid+'::'+mid,null,false);
}
/* v9.55: همهٔ مدل‌هایی که تیک سبز (available/در دسترس) گرفته‌اند را یک‌جا
   به فهرست کاندیدها اضافه می‌کند. */
function aiCandAddAvailable(){
  const add=[];
  ((aiProvData&&aiProvData.providers)||[]).forEach(p=>{
    (p.models||[]).forEach(m=>{
      if(m&&m.available && m.id && p.id) add.push(p.id+'::'+m.id);
    });
  });
  if(!add.length){showToast('هیچ مدلِ در دسترسی نیست — اول مدل‌ها را تست کنید',1);return;}
  fetch('?ai_candidates=1').then(r=>r.json()).then(d=>{
    let list=((d&&d.candidates)||[]).map(c=>({provider:c.provider,model:c.model}));
    let added=0;
    add.forEach(k=>{
      const i=k.indexOf('::');
      if(i<=0)return;
      const pp=k.slice(0,i), mm=k.slice(i+2);
      if(!list.find(x=>x.provider===pp&&x.model===mm)){list.push({provider:pp,model:mm});added++;}
    });
    if(!added){showToast('همهٔ مدل‌های در دسترس از قبل کاندید هستند',0);return;}
    const fd=new FormData();
    fd.append('action','ai_candidates_save');
    fd.append('candidates',JSON.stringify(list));
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(res=>{
      showToast(res&&res.ok?('✓ '+added+' مدلِ در دسترس به کاندیدها اضافه شد'):('خطا: '+((res&&res.error)||'نامشخص')),!(res&&res.ok));
      aiCandRender();
    }).catch(()=>showToast('خطا در ارتباط',1));
  }).catch(()=>showToast('خطا در ارتباط',1));
}
/* v9.38: دراپ‌داون‌های اختصاصی افزودن کاندید (ارائه‌دهنده + مدل) */
function aiCandFillSel(){
  const ps=$('aiCandProvSel'); if(!ps)return;
  const cur=ps.value||((aiProvData&&aiProvData.selected&&aiProvData.selected.provider)||'');
  ps.innerHTML='<option value="">— انتخاب —</option>';
  ((aiProvData&&aiProvData.providers)||[]).forEach(p=>{
    const n=(p.models||[]).length;
    ps.add(new Option(esc(p.name)+(n?' ('+toFa(n)+' مدل)':''),esc(p.id)));
  });
  if(cur&&[...ps.options].some(o=>o.value===cur))ps.value=cur;
  aiCandFillModels();
}
function aiCandFillModels(){
  const ms=$('aiCandModelSel'); if(!ms)return;
  const pid=($('aiCandProvSel')||{}).value||'';
  const p=((aiProvData&&aiProvData.providers)||[]).find(x=>x.id===pid);
  ms.innerHTML='<option value="">—</option>';
  if(!p)return;
  (p.models||[]).forEach(m=>ms.add(new Option(esc(m.name||m.id),esc(m.id))));
  // مدل فعالِ همین ارائه‌دهنده را پیش‌فرض بگذار
  if(aiProvData&&aiProvData.selected&&aiProvData.selected.provider===pid&&aiProvData.selected.model)
    ms.value=aiProvData.selected.model;
}
function aiCandProvChange(){aiCandFillModels();}
function aiCandAddSel(){
  const pid=($('aiCandProvSel')||{}).value||'';
  const mid=($('aiCandModelSel')||{}).value||'';
  if(!pid||!mid){showToast('ارائه‌دهنده و مدل کاندید را انتخاب کنید',1);return;}
  aiCandSave(pid+'::'+mid,null,false);
}
function aiCandRemove(key){if(confirm('این مدل از کاندیدها حذف شود؟'))aiCandSave(null,key,false);}
function aiCandSetPin(){aiCandSave(null,null,true);}
/* v9.55: تیک زدن/برداشتن همهٔ کاندیدها + حذف کاندیدهایِ تیک‌خورده */
let aiCandSelectedKeys=new Set();
function aiCandToggleSelAll(checked){
  aiCandSelectedKeys.clear();
  const rows=document.querySelectorAll('.aiCandRow');
  rows.forEach(r=>{
    const key=r.getAttribute('data-key');
    const cb=r.querySelector('.aiCandCb');
    if(!key||!cb)return;
    cb.checked=checked;
    if(checked)aiCandSelectedKeys.add(key);
  });
  aiCandUpdateSelUI();
}
function aiCandRowCheck(cb,key){
  if(!key)return;
  if(cb.checked)aiCandSelectedKeys.add(key); else aiCandSelectedKeys.delete(key);
  const all=$('aiCandSelAll');
  const rows=document.querySelectorAll('.aiCandRow');
  if(all){all.checked=aiCandSelectedKeys.size>0&&aiCandSelectedKeys.size===rows.length;}
  aiCandUpdateSelUI();
}
function aiCandUpdateSelUI(){
  const cnt=$('aiCandSelCount');
  if(cnt)cnt.textContent=toFa(aiCandSelectedKeys.size)+' انتخاب';
}
function aiCandRemoveSelected(){
  if(!aiCandSelectedKeys.size){showToast('هیچ کاندیدی انتخاب نشده',1);return;}
  const keys=[...aiCandSelectedKeys];
  if(!confirm(keys.length+' کاندید انتخاب‌شده حذف شود؟'))return;
  aiCandSave(null,null,false,keys);
}
function aiCandRender(){
  aiCandLoad(d=>{
    aiCandFillSel();
    const box=$('aiCandList'); if(!box)return;
    const c=d.candidates||[];
    aiCandSelectedKeys.clear();
    if(!c.length){box.innerHTML='<div style="padding:8px;color:#64748b;font-size:11px">کاندیدی نیست — مدل فعال را انتخاب و «➕ افزودن» بزنید.</div>';}
    else{
      let h='';
      c.forEach(x=>{
        const isM=(x.key===d.master);
        h+='<div class="aiCandRow" data-key="'+esc(x.key)+'" style="display:flex;gap:6px;align-items:center;padding:6px 8px;border-bottom:1px solid #1e293b;font-size:11px">'
          +'<input type="checkbox" class="aiCandCb" style="width:14px;height:14px;flex:0 0 auto" onchange="aiCandRowCheck(this,\''+esc(x.key)+'\')">'
          +'<span style="flex:1;color:'+(isM?'#4ade80':'#e2e8f0')+'">'+esc(x.providerName)+' · <span dir="ltr">'+esc(x.modelName||x.model)+'</span>'
          +(isM?' <span style="color:#fbbf24;font-size:9px">⭐ مستر</span>':'')
          +'<span style="color:#64748b;font-size:9px"> | '+(x.votes?('🏅 '+toFa(x.wins)+'/'+toFa(x.votes)+' ('+Math.round(x.score*100)+'٪)'):'بدون رای')+'</span></span>'
          +'<button class="btn btn-red" onclick="aiCandRemove(\''+esc(x.key)+'\')" style="font-size:10px;padding:2px 6px">🗑</button></div>';
      });
      box.innerHTML=h;
    }
    const all=$('aiCandSelAll'); if(all)all.checked=false;
    aiCandUpdateSelUI();
    const ms=$('aiMasterPin');
    if(ms){
      let o='<option value="">خودکار (بهترین آمار)</option>';
      c.forEach(x=>{o+='<option value="'+esc(x.key)+'"'+(d.pin===x.key?' selected':'')+'>'+esc(x.providerName+' / '+(x.modelName||x.model))+'</option>';});
      ms.innerHTML=o;
    }
    const mi=$('aiMasterInfo');
    if(mi){
      if(d.master){
        const m=c.find(x=>x.key===d.master);
        mi.innerHTML='⭐ مدل مستر: <b>'+esc(m?(m.providerName+' / '+(m.modelName||m.model)):d.master)+'</b>'
          +(d.pin?' (سنجاق دستی)':' — به‌صورت خودکار از بهترین آمار')
          +' — در آزمون‌ها، پاسخِ مستر به‌عنوان مرجعِ مقایسه نشان داده می‌شود.';
      }else{mi.innerHTML='هنوز مستری نیست — با آزمون‌ها به‌صورت خودکار مشخص می‌شود.';}
    }
  });
}
function aiCandVote(task,idx){
  const it=(aiCandCtx.items||[])[idx];
  if(!it)return;
  const fd=new FormData();
  fd.append('action','ai_vote');
  fd.append('task',task);
  fd.append('input',aiCandCtx.input||'');
  fd.append('winner',it.key);
  fd.append('candidates',JSON.stringify(aiCandCtx.keys||[]));
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    showToast(d&&d.ok?('✓ رأی ثبت شد — مستر: '+((d.master||'').split('::')[1]||d.master||'?')):('خطا: '+((d&&d.error)||'نامشخص')),!d||!d.ok);
    if(d&&d.ok)aiCandRender();
  }).catch(()=>showToast('خطا در ثبت رأی',true));
}
/* v9.49: نتیجهٔ «تست دستهٔ همهٔ کاندیدها» حالا در یک مودال نشان داده می‌شود
   (نه داخل همان بخش که در موبایل جایی نداشت). برگزیدنِ هر پاسخ هم رأیِ مدل
   مستر را ثبت می‌کند و هم دسته را در حافظهٔ یادگیری می‌نشاند. */
function aiCandCategoryTest(){
  let m=document.getElementById('aiCandCatModal');if(m)m.remove();
  m=document.createElement('div');m.id='aiCandCatModal';m.className='bsl-modal-overlay';
  m.innerHTML='<div class="bsl-modal" style="width:880px">'
    +'<div class="bsl-modal-head"><h2>🏷️ تست دسته‌بندی همهٔ کاندیدها</h2>'
    +'<button class="btn btn-gray" onclick="aiCandCatClose()" style="font-size:11px;padding:4px 9px">✕</button></div>'
    +'<div style="padding:10px 14px;background:#1e293b;border-bottom:1px solid #334155;display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
    +'<input type="text" id="aiCandCatInput" placeholder="عنوان محصول را بنویسید... (مثلاً: کفش ورزشی مردانه)" '
    +'onkeydown="if(event.key===\'Enter\')aiCandCatRun()" style="flex:1;min-width:220px;background:#0f172a;color:#e2e8f0;border:1px solid #334155;border-radius:8px;padding:9px 12px;font-size:13px;direction:rtl">'
    +'<button class="btn btn-green" onclick="aiCandCatRun()" style="font-size:12px;padding:9px 16px">➤ مقایسه</button></div>'
    +'<div class="bsl-modal-body" id="aiCandCatBody" style="min-height:300px;max-height:62vh;overflow:auto;padding:12px"></div></div>';
  m.addEventListener('click',function(e){if(e.target===m)aiCandCatClose();});
  document.body.appendChild(m);
  setTimeout(()=>{const i=$('aiCandCatInput');if(i)i.focus();},50);
}
function aiCandCatClose(){const m=document.getElementById('aiCandCatModal');if(m)m.remove();}
function aiCandCatRun(){
  const inp=$('aiCandCatInput');const title=(inp?inp.value:'').trim();if(!title){if(inp)inp.focus();return;}
  const body=$('aiCandCatBody'); if(!body)return;
  body.innerHTML='<div style="color:#93c5fd;font-size:11px">🔄 در حال تحلیل «'+esc(title)+'» با همهٔ کاندیدها...</div>';
  fetch('?ai_candidates_category=1&title='+encodeURIComponent(title)).then(rr=>rr.json()).then(d=>{
    if(!body)return;
    if(!d||!d.ok){body.innerHTML='<div style="color:#fca5a5;font-size:11px">✗ '+esc((d&&d.error)||'خطا')+'</div>';return;}
    const items=d.items||[];
    aiCandCtx={task:'category',input:title,keys:items.map(x=>x.key),items:items};
    let h='<div style="color:#67e8f9;font-weight:700;font-size:12px;margin-bottom:6px">🏷️ دسته‌بندی «'+esc(d.title)+'» توسط '+toFa(items.length)+' کاندید</div>'
      +'<div style="color:#94a3b8;font-size:10px;margin-bottom:8px">پاسخی که دسته‌اش درست‌تر بود را «برگزیدن + یادگیری» بزنید؛ هم رأیِ مستر ثبت می‌شود و هم این دسته برای محصولات هم‌کلمه آموخته می‌شود.</div>';
    items.forEach((it,idx)=>{
      const isM=(it.key===d.master);
      h+='<div style="border:1px solid '+(isM?'#fbbf24':'#334155')+';border-radius:8px;padding:7px;margin-bottom:6px;background:#111c31">'
        +'<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;flex-wrap:wrap">'
        +'<span style="color:'+(isM?'#fbbf24':'#e2e8f0')+';font-weight:700">'+(idx+1)+'. '+esc(it.providerName)+(isM?' <span style="color:#fbbf24;font-size:9px">⭐ مستر</span>':'')+'</span>'
        +'<span style="color:#64748b;font-size:9px" dir="ltr">'+esc(it.model)+' · '+toFa(it.latency||0)+'ms</span></div>'
        +'<div style="margin-top:4px">'+((it.ok&&it.category_name)
            ? '✅ دسته: <b style="color:#4ade80">'+esc(it.category_name)+'</b> (#'+it.category_id+')'
            : '<span style="color:#f87171">✗ '+(it.error||'پاسخ نامعتبر')+'</span>')+'</div>'
        +(it.ai_text?'<div style="color:#94a3b8;font-size:10px;direction:ltr;text-align:left;white-space:pre-wrap;margin-top:3px">'+esc(it.ai_text)+'</div>':'')
        +'<button class="btn btn-green" style="margin-top:6px;font-size:10px;padding:3px 10px" onclick="aiCandCatVote('+idx+')">✓ برگزیدن + یادگیری</button>'
        +'</div>';
    });
    h+='<div style="color:#64748b;font-size:10px;margin-top:6px">⭐ = مدل مستر (مرجع مقایسه). انتخاب شما همان رایِ مستر را به‌روز می‌کند.</div>';
    body.innerHTML=h;
  }).catch(()=>{if(body)body.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا شبکه</div>';});
}
function aiCandCatVote(idx){
  const it=(aiCandCtx.items||[])[idx];
  if(!it){showToast('نتیجهٔ کاندید یافت نشد',1);return;}
  const fd=new FormData();
  fd.append('action','ai_vote');
  fd.append('task','category');
  fd.append('input',aiCandCtx.input||'');
  fd.append('winner',it.key);
  fd.append('candidates',JSON.stringify(aiCandCtx.keys||[]));
  fd.append('cat_id',String(it.category_id||0));
  fd.append('cat_name',it.category_name||'');
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    showToast(d&&d.ok?('✓ رأی ثبت شد — مستر: '+((d.master||'').split('::')[1]||d.master||'?')):('خطا: '+((d&&d.error)||'نامشخص')),!d||!d.ok);
    if(d&&d.ok)aiCandRender();
  }).catch(()=>showToast('خطا در ثبت رأی',true));
}
function aiCandReplyTest(){
  let m=document.getElementById('aiCandReplyModal');if(m)m.remove();
  m=document.createElement('div');m.id='aiCandReplyModal';m.className='bsl-modal-overlay';
  m.innerHTML='<div class="bsl-modal" style="width:860px">'
    +'<div class="bsl-modal-head"><h2>💬 تست پاسخ همهٔ کاندیدها</h2>'
    +'<button class="btn btn-gray" onclick="aiCandReplyClose()" style="font-size:11px;padding:4px 9px">✕</button></div>'
    +'<div style="padding:10px 14px;background:#1e293b;border-bottom:1px solid #334155;display:flex;gap:8px;align-items:center">'
    +'<input type="text" id="aiCandReplyInput" placeholder="پیام مشتری را بنویسید…" '
    +'onkeydown="if(event.key===\'Enter\')aiCandReplyRun()" style="flex:1;background:#0f172a;color:#e2e8f0;border:1px solid #334155;border-radius:8px;padding:9px 12px;font-size:13px">'
    +'<button class="btn btn-green" onclick="aiCandReplyRun()" style="font-size:12px;padding:9px 16px">➤ مقایسه</button></div>'
    +'<div class="bsl-modal-body" id="aiCandReplyBody" style="min-height:300px;max-height:60vh;overflow:auto;padding:12px"></div></div>';
  m.addEventListener('click',function(e){if(e.target===m)aiCandReplyClose();});
  document.body.appendChild(m);
  setTimeout(()=>{const i=$('aiCandReplyInput');if(i)i.focus();},50);
}
function aiCandReplyClose(){const m=document.getElementById('aiCandReplyModal');if(m)m.remove();}
function aiCandReplyRun(){
  const inp=$('aiCandReplyInput');const t=(inp?inp.value:'').trim();if(!t){if(inp)inp.focus();return;}
  const body=$('aiCandReplyBody'); if(!body)return;
  body.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حال پرسیدن از همهٔ کاندیدها...</div>';
  fetch('?ai_candidates_reply=1&msg='+encodeURIComponent(t)).then(r=>r.json()).then(d=>{
    if(!body)return;
    if(!d.ok){body.innerHTML='<div style="color:#fca5a5;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    const items=d.items||[];
    aiCandCtx={task:'autoreply',input:t,keys:items.map(x=>x.key),items:items};
    let h='<div style="font-size:11px;color:#67e8f9;font-weight:700;margin-bottom:8px">💬 «'+esc(t)+'» — پاسخ '+toFa(items.length)+' کاندید (مستر ⭐ مرجعِ مقایسه)</div>';
    items.forEach((it,idx)=>{
      const isM=(it.key===d.master);
      h+='<div style="border:1px solid '+(isM?'#fbbf24':'#334155')+';border-radius:8px;padding:8px;margin-bottom:8px;background:#111c31">'
        +'<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;flex-wrap:wrap">'
        +'<span style="color:'+(isM?'#fbbf24':'#e2e8f0')+';font-weight:700">'+esc(it.providerName)+(isM?' <span style="font-size:9px;color:#fbbf24">⭐ مستر</span>':'')+'</span>'
        +'<span style="color:#64748b;font-size:9px" dir="ltr">'+esc(it.model||'')+' · '+toFa(it.latency||0)+'ms</span></div>'
        +'<div style="margin-top:5px;color:'+(it.ok?'#e9d5ff':'#f87171')+';white-space:pre-wrap;font-size:12px">'+esc(it.ok?it.text:(it.error||'پاسخی نیامد'))+'</div>'
        +'<button class="btn btn-green" style="margin-top:6px;font-size:10px;padding:3px 10px" onclick="aiCandVote(\'autoreply\','+idx+')">✓ این بهتر بود (رای)</button>'
        +'</div>';
    });
    body.innerHTML=h;
  }).catch(()=>{if(body)body.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا شبکه</div>';});
}
function aiCandLeaderboard(){
  aiCandLoad(d=>{
    const r=$('aiCandR'); if(!r)return;
    const c=d.candidates||[];
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px;line-height:1.8">'
      +'<div style="color:#67e8f9;font-weight:700">📊 جدول امتیازات مدل‌های کاندید</div>';
    if(!c.length){h+='<div style="color:#64748b;padding:8px 0">کاندیدی نیست.</div>';}
    else{
      h+='<table style="width:100%;border-collapse:collapse;margin-top:6px;font-size:11px">'
        +'<tr style="background:#1e293b;color:#94a3b8"><th style="padding:5px;text-align:right">مدل</th><th>برد</th><th>شرکت</th><th>درصد برد</th><th>مستر</th></tr>';
      c.forEach(x=>{
        const pct=x.votes?Math.round(x.score*100)+'٪':'—';
        h+='<tr style="border-bottom:1px solid #1e293b"><td style="padding:5px;color:#e2e8f0">'+esc(x.providerName)+' · <span dir="ltr">'+esc(x.modelName||x.model)+'</span></td>'
          +'<td style="padding:5px;text-align:center;color:#4ade80">'+toFa(x.wins)+'</td>'
          +'<td style="padding:5px;text-align:center;color:#94a3b8">'+toFa(x.votes)+'</td>'
          +'<td style="padding:5px;text-align:center;color:#fbbf24">'+pct+'</td>'
          +'<td style="padding:5px;text-align:center">'+(x.key===d.master?'⭐':'')+'</td></tr>';
      });
      h+='</table>';
    }
    h+='<div style="color:#94a3b8;font-size:10px;margin-top:6px">آخرین رأی‌ها:</div>';
    (d.history||[]).slice(0,10).forEach(hi=>{
      h+='<div style="color:#64748b;font-size:10px;border-top:1px solid #1e293b;padding-top:3px;margin-top:3px">'
        +(hi.task==='category'?'🏷️':'💬')+' «'+esc(hi.input)+'» → برنده: <span dir="ltr">'+esc(hi.winner)+'</span></div>';
    });
    h+='</div>';
    r.innerHTML=h;
  });
}
function aiRenderProviders(){
    const sel=$('aiProviderSel');if(!sel)return;
    const cur=sel.value||aiProvData.selected.provider||'';
    sel.innerHTML='<option value="">— انتخاب —</option>';
    (aiProvData.providers||[]).forEach(p=>{
        const ok=p.enabled?'':' ⛔';
        sel.add(new Option(esc(p.name)+ok+' ('+(p.models||[]).length+' مدل)',esc(p.id)));
    });
    let target=cur;
    if(!target||![...(sel.options)].some(o=>o.value===target))target=aiProvData.selected.provider||'';
    if(target)sel.value=target;
    aiRenderModels();
    aiCandFillSel();
    aiRenderProviderToggles();
}
// v9.63: فهرست ارائه‌دهنده‌ها با تیکِ روشن/خاموش انفرادی. خاموش کردن یعنی
// ارائه‌دهنده و همهٔ مدل‌هایش از «تست مدل‌ها» کنار می‌روند (تست انبوه فقط
// ارائه‌دهنده‌های روشن را می‌شمارد) ولی داده‌ها و کلیدها حفظ می‌شوند.
function aiRenderProviderToggles(){
    const list=document.getElementById('aiProviderToggleList');if(!list)return;
    const provs=aiProvData.providers||[];
    if(!provs.length){list.innerHTML='<div style="padding:8px;color:#64748b;font-size:11px">ارائه‌دهنده‌ای درون‌ریزی نشده.</div>';const c=document.getElementById('aiProvOnCount');if(c)c.textContent='';return;}
    let html='';
    let onCount=0;
    provs.forEach(p=>{
        const on=p.enabled!==false;
        if(on)onCount++;
        const mc=(p.models||[]).length;
        html+='<label style="display:flex;align-items:center;gap:8px;padding:7px 10px;border-bottom:1px solid #1e293b;cursor:pointer;'+(on?'':'opacity:.55')+'" title="خاموش: ارائه‌دهنده و مدل‌هایش در تست مدل‌ها شرکت نمی‌کنند">'
           +'<input type="checkbox" style="width:15px;height:15px;flex:0 0 auto" '+(on?'checked':'')+' onchange="aiToggleProvider(\''+jsAttr(p.id)+'\',this.checked)">'
           +'<span style="flex:1;min-width:0">'+esc(p.name||p.id)+'</span>'
           +'<span style="color:#94a3b8;font-size:10px;white-space:nowrap" dir="ltr">'+toFa(mc)+' مدل</span>'
           +'<span style="font-size:10px;'+(on?'color:#4ade80':'color:#f87171')+'" id="aiProvStat-'+esc(p.id)+'">'+(on?'✓ روشن':'✕ خاموش')+'</span>'
           +'</label>';
    });
    list.innerHTML=html||'<div style="padding:8px;color:#64748b;font-size:11px">ارائه‌دهنده‌ای نیست.</div>';
    const c=document.getElementById('aiProvOnCount');
    if(c)c.textContent=onCount+' روشن از '+provs.length;
}
function aiToggleProvider(pid,on){
    const fd=new FormData();
    fd.append('action','ai_toggle_provider');
    fd.append('provider_id',pid);
    fd.append('enabled',on?'1':'0');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){showToast('خطا در ذخیرهٔ وضعیت: '+((d&&d.error)||'؟'),1);}
        else{showToast((on?'✓ «':'✕ «')+pid+'» '+(on?'روشن':'خاموش')+' شد');}
        aiLoadProviders();   // برای به‌روزرسانی فهرست و شمارنده
    }).catch(()=>{showToast('❌ خطا شبکه',1);});
}
function aiCurrentProvider(){
    const sel=$('aiProviderSel');const id=sel?sel.value:'';
    return (aiProvData.providers||[]).find(p=>p.id===id)||null;
}
function aiUpdateUseInfo(){
    const el=$('aiUseInfo');if(!el)return;
    const sel=aiProvData.selected||{};
    const p=(aiProvData.providers||[]).find(x=>x.id===sel.provider);
    if(!p){el.innerHTML='<span style="color:#94a3b8">هیچ مدل فعالی انتخاب نشده — از این مدل‌ها برای دسته‌بندی خودکار و پاسخ به مشتریان استفاده می‌شود.</span>';return;}
    el.innerHTML='<span style="color:#67e8f9">⚡ مدل فعال:</span> <b dir="ltr">'+esc(sel.model||'')+'</b> <span style="color:#64748b">('+esc(p.name||p.id)+')</span>'
      +'<div style="margin-top:2px">از این مدل برای <b style="color:#c4b5fd">دسته‌بندی خودکار</b> و <b style="color:#c4b5fd">پاسخ به مشتریان</b> استفاده می‌شود.'
      +' اگر خطا بدهد، خودکار به مدل رایگان <b style="color:#4ade80">Bonsai</b> برمی‌گردد.</div>';
}
function aiRenderModels(){
    const msel=$('aiModelSel');if(!msel)return;
    const p=aiCurrentProvider();
    msel.innerHTML='<option value="">—</option>';
    aiUpdateUseInfo();
    if(!p){const box=$('aiModelsList');if(box)box.innerHTML='<div style="padding:8px;color:#64748b;font-size:11px">ارائه‌دهنده‌ای انتخاب نشده.</div>';return;}
    (p.models||[]).forEach(m=>msel.add(new Option(esc(m.name||m.id),esc(m.id))));
    if(aiProvData.selected.provider===p.id&&aiProvData.selected.model)msel.value=aiProvData.selected.model;
    const list=$('aiModelsList');
    if(list){
        const models=(p.models||[]);
        if(!models.length){list.innerHTML='<div style="padding:8px;color:#64748b;font-size:11px">این ارائه‌دهنده مدلی ندارد.</div>';return;}
        let h='';
        models.forEach((m,i)=>{
            const st=m.available?'🟢':(m.tested?'🔴':'⚪');
            const lat=m.latency?' · '+toFa(m.latency)+'ms':'';
            const tool=m.toolCalling?' 🔧':'';
            h+='<div style="display:flex;align-items:center;gap:6px;padding:5px 8px;border-bottom:1px solid #1e293b;font-size:10.5px">'
              +'<span title="'+(m.available?'در دسترس':(m.tested?'ناموفق':'تست نشده'))+'">'+st+'</span>'
              +'<span style="flex:1;color:#e2e8f0;direction:ltr;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(m.name||m.id)+'</span>'
              +'<span style="color:#64748b">'+lat+'</span>'+tool
              +'<button class="btn btn-gray" style="font-size:9px;padding:2px 6px" data-p="'+esc(p.id)+'" data-m="'+esc(m.id)+'" onclick="aiTestOneFrom(this)">🧪</button>'
              +'</div>';
        });
        list.innerHTML=h;
    }
}
function aiTestOneFrom(btn){if(btn&&btn.dataset)aiTestOne(btn.dataset.p,btn.dataset.m);}

function aiSelectProvider(){
    const p=aiCurrentProvider();
    aiRenderModels();
    if(p){const m=$('aiModelSel');const mid=m&&m.value?m.value:(p.models[0]&&p.models[0].id||'');aiSaveSel(p.id,mid);}
}
function aiSaveSel(pid,mid){if(!pid)return;const fd=new FormData();fd.append('action','ai_select');fd.append('provider_id',pid);fd.append('model_id',mid||'');fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(()=>aiLoadProviders()).catch(()=>{});}
function aiSelectModel(){const sel=$('aiModelSel');if(sel)aiSaveSel($('aiProviderSel').value,sel.value);}
function aiShowImportBox(){const w=$('aiImportBoxWrap');if(w)w.style.display=w.style.display==='none'?'':'none';}
function aiPickImportFile(){const f=$('aiImportFile');if(f)f.click();}
function aiImportFromFile(input){const file=input.files&&input.files[0];if(!file)return;const reader=new FileReader();reader.onload=e=>aiImportText(e.target.result);reader.readAsText(file);input.value='';}
function aiImportText(txt){
    if(!txt||!txt.trim()){showToast('JSON خالی است',1);return;}
    const r=$('aiTR');
    if(r)r.innerHTML='<div style="color:#67e8f9;font-size:11px">🔄 در حال درون‌ریزی ارائه‌دهنده‌ها...</div>';
    const fd=new FormData();fd.append('action','ai_import_providers');fd.append('providers_json',txt);
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(d&&d.ok){showToast('✓ '+d.message);if(r)r.innerHTML='<div class="alert alert-success" style="padding:8px;font-size:11px">✓ '+esc(d.message)+'</div>';aiLoadProviders();}
        else{if(r)r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d&&d.error||'خطا')+'</div>';showToast('✗ '+(d&&d.error||'خطا'),1);}
    }).catch(()=>{showToast('✗ خطا شبکه',1);});
}
function aiImportFromText(){const t=$('aiImportBox');if(t)aiImportText(t.value);}
function aiTestOne(pid,mid){
    // v9.52: پیام و دستهٔ تست را از فیلدهای جاری می‌گیرد (مودال یا بخش بیرونی)
    const msg=($('aiTestMsg')&&$('aiTestMsg').value.trim())||'سلام';
    const cat=($('aiTestCat')&&$('aiTestCat').value.trim())||'ادو پرفیوم';
    const fd=new FormData();fd.append('action','ai_test_one');fd.append('provider_id',pid);fd.append('model_id',mid);
    fd.append('msg',msg);fd.append('cat',cat);
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        const r=$('aiTR');if(r){
            const ok=d&&d.available;
            r.innerHTML='<div style="background:'+(ok?'#14532d':'#7f1d1d')+';color:'+(ok?'#86efac':'#fca5a5')+';padding:8px;font-size:11px">'
              +(ok?'✓':'✗')+' <b dir="ltr">'+esc(mid)+'</b> — '+(ok?('پاسخ پیام: '+esc(d.response||'')):esc(d.error||'خطا'))
              +(d.catResponse?'<div style="margin-top:3px;color:#c4b5fd">🏷️ دسته: '+esc(d.catResponse)+'</div>':'')
              +' <span style="color:#94a3b8">('+toFa(d.latencyMs||0)+'ms)</span></div>';
        }
        aiLoadProviders();
    }).catch(()=>{});
}
/* v9.23: مودال جدولِ زندهٔ «تست همهٔ مدل‌ها» — با ارسال پیام «سلام».
   هر ردیف = یک مدل؛ ستون‌ها: وضعیت، ارائه‌دهنده، مدل، تأخیر، پاسخ/خطا. */
function aiOpenTestModal(){
    let m=document.getElementById('aiTestModal');if(m)m.remove();
    m=document.createElement('div');
    m.id='aiTestModal';
    m.style.cssText='position:fixed;inset:0;background:rgba(2,6,23,.72);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px';
    m.innerHTML='<style>'
      // v9.64: سوییچِ اسلایدری «فقط سبزها» — نمایش فقط مدل‌های دارای چراغ سبز
      +'.ai-switch{width:34px;height:20px;border-radius:20px;background:#334155;position:relative;display:inline-block;transition:background .2s;flex:0 0 auto;vertical-align:middle}'
      +'.ai-switch::after{content:"";position:absolute;top:2px;left:2px;width:16px;height:16px;border-radius:50%;background:#e2e8f0;transition:transform .2s}'
      +'.ai-switch-wrap input:checked + .ai-switch{background:#22c55e}'
      +'.ai-switch-wrap input:checked + .ai-switch::after{transform:translateX(14px)}'
      +'</style>'
      +'<div style="background:#0f172a;border:1px solid #334155;border-radius:12px;width:min(1100px,96vw);max-height:92vh;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.5)">'
      +'<div style="display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid #334155;flex:0 0 auto">'
      +'<span style="font-size:14px">🧪</span><b style="color:#67e8f9;flex:1">نتایج زندهٔ تست همهٔ مدل‌ها</b>'
      +'<span id="aiTestCur" style="color:#fbbf24;font-size:11px"></span>'
      +'<button class="btn btn-red" onclick="aiTestStop()" style="font-size:11px;padding:4px 10px">⏹ توقف</button>'
      +'<button class="btn btn-gray" onclick="aiCloseTestModal()" style="font-size:11px;padding:4px 10px">✕ بستن</button></div>'
      +'<div style="display:flex;gap:16px;padding:8px 16px;border-bottom:1px solid #1e293b;flex:0 0 auto;font-size:11px;color:#94a3b8;flex-wrap:wrap;align-items:center">'
      +'<span>کل: <b id="aiTestTot" style="color:#e2e8f0">۰</b></span>'
      +'<span>🟢 در دسترس: <b id="aiTestOk" style="color:#4ade80">۰</b></span>'
      +'<span>🔴 ناموفق: <b id="aiTestFail" style="color:#f87171">۰</b></span>'
      +'<span>⏳ در انتظار: <b id="aiTestWait" style="color:#fbbf24">۰</b></span>'
      // v9.64: سوییچِ اسلایدریِ «فقط سبزها»
      +'<label class="ai-switch-wrap" style="display:flex;align-items:center;gap:7px;cursor:pointer;margin-inline-start:auto;margin-left:auto">'
      +'<span style="font-size:11px;color:#94a3b8">فقط سبزها</span>'
      +'<input type="checkbox" id="aiTestOnlyGreen" onchange="aiTestToggleOnlyGreen(this.checked)" style="display:none">'
      +'<span class="ai-switch"></span></label></div>'
      // v9.52: دو فیلد قابل ویرایش برای پیام و دستهٔ تست در مودال
      +'<div style="display:flex;gap:10px;padding:8px 16px;border-bottom:1px solid #1e293b;flex:0 0 auto;font-size:11px;flex-wrap:wrap;align-items:center">'
      +'<span style="color:#94a3b8">پیام تست:</span>'
      +'<input id="aiTestMsg" value="'+esc(aiTestMsgVal||'سلام')+'" dir="rtl" style="flex:1;min-width:140px;padding:4px 8px;border:1px solid #475569;border-radius:6px;background:#0f172a;color:#e2e8f0;font-size:12px">'
      +'<span style="color:#94a3b8">دستهٔ تست:</span>'
      +'<input id="aiTestCat" value="'+esc(aiTestCatVal||'ادو پرفیوم')+'" dir="rtl" style="flex:1;min-width:140px;padding:4px 8px;border:1px solid #475569;border-radius:6px;background:#0f172a;color:#e2e8f0;font-size:12px">'
      +'<span style="color:#94a3b8">تاخیر (ms):</span>'
      +'<input id="aiTestDelay" type="number" value="'+esc(aiTestDelayVal||120)+'" min="0" max="60000" step="50" dir="ltr" style="width:90px;padding:4px 8px;border:1px solid #475569;border-radius:6px;background:#0f172a;color:#e2e8f0;font-size:12px" title="مکث بین هر تست (میلی‌ثانیه) برای جلوگیری از ریت‌لیمیت">'
      +'</div>'
      +'<div style="flex:1;overflow:auto;padding:0">'
      +'<table style="width:100%;border-collapse:collapse;font-size:11px">'
      +'<thead><tr style="background:#1e293b;position:sticky;top:0;color:#94a3b8">'
      +'<th style="padding:8px;text-align:center;width:34px">#</th>'
      +'<th style="padding:8px;text-align:center;width:44px">وضعیت</th>'
      +'<th style="padding:8px;text-align:right">ارائه‌دهنده</th>'
      +'<th style="padding:8px;text-align:left;direction:ltr">مدل</th>'
      +'<th style="padding:8px;text-align:center;width:70px">تأخیر</th>'
      +'<th style="padding:8px;text-align:right">پاسخ پیام</th>'
      +'<th style="padding:8px;text-align:right">پاسخ دسته</th>'
      +'</tr></thead><tbody id="aiTestTbody"></tbody></table></div>'
      +'<div id="aiTestDiag" style="flex:0 0 auto;padding:0 16px 10px"></div>'
      +'</div>';
    m.addEventListener('click',function(e){if(e.target===m)aiCloseTestModal();});
    document.body.appendChild(m);
}
function aiCloseTestModal(){
    // فقط poll را قطع می‌کنیم؛ کارِ سرور به‌صورت پس‌زمینه ادامه دارد
    if(window._aiPollTimer){clearInterval(window._aiPollTimer);window._aiPollTimer=null;}
    const m=document.getElementById('aiTestModal');if(m)m.remove();
    aiLoadProviders();
}
function aiTestStop(){
    fetch('?ai_test_stop=1').then(r=>r.json()).then(()=>{
        if($('aiTestCur'))$('aiTestCur').textContent='⏹ در حال توقف...';
    }).catch(()=>{});
}
/* v9.24: وضعیت کارِ پس‌زمینه را poll می‌کند و جدول را به‌روز می‌کند */
function aiPollTest(){
    if(window._aiPollTimer)return;
    window._aiPollTimer=setInterval(()=>{
        fetch('?ai_test_status=1').then(r=>r.json()).then(st=>{
            aiRenderTestState(st);
            if(!st.running&&st.done){
                if(window._aiPollTimer){clearInterval(window._aiPollTimer);window._aiPollTimer=null;}
                aiLoadProviders();
            }
        }).catch(()=>{});
    },1200);
}
let aiTestRows={},aiTestTotCount=0,aiTestOkCount=0,aiTestFailCount=0,aiTestWaitCount=0;
let aiTestMsgVal='سلام',aiTestCatVal='ادو پرفیوم',aiTestDelayVal=120;
// v9.64: فیلترِ «فقط سبزها» در جدولِ نتایجِ تست مدل‌ها
let aiTestOnlyGreen=false;
function aiTestRenderCounters(){
    if($('aiTestTot'))$('aiTestTot').textContent=toFa(aiTestTotCount);
    if($('aiTestOk'))$('aiTestOk').textContent=toFa(aiTestOkCount);
    if($('aiTestFail'))$('aiTestFail').textContent=toFa(aiTestFailCount);
    if($('aiTestWait'))$('aiTestWait').textContent=toFa(aiTestWaitCount);
}
/* v9.64: سوییچِ «فقط سبزها» — فقط ردیف‌های دارای چراغ سبز (موفق) را نشان بده */
function aiTestToggleOnlyGreen(on){
    aiTestOnlyGreen=!!on;
    aiTestApplyGreenFilter();
}
function aiTestApplyGreenFilter(){
    if(!aiTestOnlyGreen){ Object.values(aiTestRows).forEach(r=>{ if(r&&r.tr)r.tr.style.display=''; }); return; }
    Object.values(aiTestRows).forEach(r=>{
        if(!r||!r.tr)return;
        const st=r.tr.querySelector('.aiSt');
        const txt=st?st.textContent:'';
        r.tr.style.display=(txt==='🟢')?'':'none';
    });
}
function aiEnsureTestRow(d){
    const tbody=$('aiTestTbody');if(!tbody)return null;
    const key=(d.provider||'')+'::'+(d.model||'');
    if(aiTestRows[key])return aiTestRows[key];
    aiTestTotCount++;aiTestWaitCount++;
    const tr=document.createElement('tr');
    tr.style.borderBottom='1px solid #1e293b';
    tr.innerHTML='<td style="padding:6px;text-align:center;color:#64748b">'+toFa(aiTestTotCount)+'</td>'
      +'<td style="padding:6px;text-align:center"><span class="aiSt">⏳</span></td>'
      +'<td style="padding:6px;text-align:right;color:#94a3b8">'+esc(d.providerName||d.provider||'')+'</td>'
      +'<td style="padding:6px;text-align:left;direction:ltr;color:#e2e8f0;word-break:break-all">'+esc(d.model||'')+'</td>'
      +'<td style="padding:6px;text-align:center;color:#64748b" class="aiLat">—</td>'
      +'<td style="padding:6px;text-align:right;color:#94a3b8" class="aiMsgRes">…</td>'
      +'<td style="padding:6px;text-align:right;color:#94a3b8" class="aiCatRes">…</td>';
    tbody.appendChild(tr);
    aiTestRenderCounters();
    return aiTestRows[key]={tr:tr};
}
function aiSetTestRow(d){
    const r=aiEnsureTestRow(d);
    if(!r)return;
    if(d.ok!==undefined){ if(aiTestWaitCount>0)aiTestWaitCount--; if(d.ok)aiTestOkCount++; else aiTestFailCount++; }
    r.tr.querySelector('.aiSt').textContent=d.ok?'🟢':'🔴';
    r.tr.querySelector('.aiSt').style.color=d.ok?'#4ade80':'#f87171';
    const lat=r.tr.querySelector('.aiLat');if(lat)lat.textContent=(d.latencyMs>0)?(toFa(d.latencyMs)+'ms'):'—';
    // v9.52: پاسخِ پیام و پاسخِ دستهٔ هر مدل در دو ستونِ جدا
    const mr=r.tr.querySelector('.aiMsgRes');
    if(mr){
        if(d.ok){
            // v9.57: اگر پاسخِ متن خالی بود (مدل ۲۰۰ داد ولی content نداشت)،
            // به‌جای «✓ پاسخ گرفت» بی‌محتوا، هشدارِ «بدون پاسخ» نشان بده.
            if((d.msgResponse||'').trim())
                mr.innerHTML='<span style="color:#4ade80" title="'+esc(d.msgResponse)+'">'+esc(d.msgResponse)+'</span>';
            else
                mr.innerHTML='<span style="color:#fbbf24" title="اتصال برقرار بود ولی مدل محتوایی برنگرداند (معمولاً مدل reasoning و سقفِ توکن)">⚠️ بدون پاسخ</span>';
        }
        else mr.innerHTML='<span style="color:#f87171" title="'+esc(d.label||'')+'">'+esc(d.error||d.label||'خطا')+'</span>';
    }
    const cr=r.tr.querySelector('.aiCatRes');
    if(cr){
        if(d.catResponse)cr.innerHTML='<span style="color:#a78bfa">'+esc(d.catResponse)+'</span>';
        else cr.innerHTML='<span style="color:#64748b">—</span>';
    }
    aiTestRenderCounters();
    aiTestApplyGreenFilter();   // v9.64: با فعال بودن «فقط سبزها»، وضعیتِ این ردیف را هم اعمال کن
}
function aiRenderTestState(st){
    if(!st)return;
    if(st.current&&st.current.model&&$('aiTestCur'))$('aiTestCur').textContent='در حال تست: '+esc(st.current.model);
    else if(st.done&&$('aiTestCur'))$('aiTestCur').textContent='🏁 '+esc(st.summary||'تمام شد');
    else if(st.stopping&&$('aiTestCur'))$('aiTestCur').textContent='⏹ در حال توقف...';
    // اگر هنوز ردیفی ساخته نشده و آیتم‌هایی هست، ابتدا کل ردیف‌ها را از روی total بساز
    if(aiTestTotCount===0&&st.total>0){
        const tbody=$('aiTestTbody');if(tbody)tbody.innerHTML='';
        aiTestTotCount=0;aiTestWaitCount=0;aiTestOkCount=0;aiTestFailCount=0;aiTestRows={};
        if(st.total>0)aiTestWaitCount=st.total;
        aiTestRenderCounters();
    }
    (st.items||[]).forEach(it=>aiSetTestRow(it));
    if(st.done){ if($('aiTestCur'))$('aiTestCur').textContent='🏁 '+esc(st.summary||'تمام شد'); }
    // خلاصهٔ عیب‌یابی (قابل‌دسترس‌نبودن اندپوینت‌ها / مشکل روش اتصال)
    const db=$('aiTestDiag');
    if(db&&st.diag){
        const netIssues=Object.entries(st.diag).filter(([,d])=>d&&d.net_issue===true);
        const unreach=Object.entries(st.diag).filter(([,d])=>d&&d.reachable===false&&d.net_issue!==true);
        if(netIssues.length){
            db.innerHTML='<div style="margin-top:8px;padding:8px;background:#422006;border:1px solid #f59e0b;border-radius:6px;font-size:11px;color:#fcd34d">'
              +'<b>⚠️ روش اتصال فعلی روی این شبکه کار نمی‌کند:</b><br>'
              +netIssues.map(([id,d])=>'• <b dir="ltr">'+esc(id)+'</b>: '+esc(d.net_hint||d.first_error||'')).join('<br>')
              +'<br><span style="color:#fbbf24">خودِ هاست به اندپوینت دسترسی دارد (مستقیم جواب می‌دهد). روش اتصال را روی «مستقیم» بگذارید، یا یک Worker/پروکسی سالم اضافه کنید.</span></div>';
        } else if(unreach.length){
            db.innerHTML='<div style="margin-top:8px;padding:8px;background:#3b1e1e;border:1px solid #ef4444;border-radius:6px;font-size:11px;color:#fca5a5">'
              +'<b>⚠️ هاست به این ارائه‌دهنده‌ها دسترسی ندارد:</b><br>'
              +unreach.map(([id,d])=>'• <b dir="ltr">'+esc(id)+'</b>: '+esc(d.first_error||d.last_label||'')).join('<br>')
              +'<br><span style="color:#fbbf24">این معمولاً DNS بسته/مسموم، تایم‌اوت یا بلاک IP هاست است. روش اتصال (DoH/پروکسی/Worker) را عوض کنید.</span></div>';
        } else {
            db.innerHTML='';
        }
    }
}
function aiTestAll(){
    const per=$('aiTestPerProvider')?parseInt($('aiTestPerProvider').value)||50:50;
    const only=$('aiTestOnlyUntested')&&$('aiTestOnlyUntested').checked?1:0;
    // v9.52: پیام و دستهٔ تستِ قابل‌تنظیم — برای نمایش در مودال هم نگه می‌داریم
    aiTestMsgVal=($('aiTestMsg')&&$('aiTestMsg').value.trim())||'سلام';
    aiTestCatVal=($('aiTestCat')&&$('aiTestCat').value.trim())||'ادو پرفیوم';
    // v9.56: تاخیر بین تست‌ها (میلی‌ثانیه)
    aiTestDelayVal=Math.max(0,parseInt(($('aiTestDelay')&&$('aiTestDelay').value)||'120',10)||120);
    aiOpenTestModal();
    const tbody=$('aiTestTbody');if(!tbody)return;
    tbody.innerHTML='';
    aiTestTotCount=0;aiTestOkCount=0;aiTestFailCount=0;aiTestWaitCount=0;aiTestRows={};
    fetch('?ai_test_start=1&per_provider='+per+'&only_untested='+only
        +'&msg='+encodeURIComponent(aiTestMsgVal)+'&cat='+encodeURIComponent(aiTestCatVal)
        +'&delay='+aiTestDelayVal).then(r=>r.json()).then(d=>{
        if(d&&d.running&&!d.ok){ if($('aiTestCur'))$('aiTestCur').textContent='در حال اجراست — ادامهٔ آن را نشان می‌دهم'; }
        else if($('aiTestCur'))$('aiTestCur').textContent='شروع تست در پس‌زمینهٔ سرور...';
        aiPollTest();
    }).catch(()=>{ if($('aiTestCur'))$('aiTestCur').textContent='خطا در شروع تست'; });
}
/* v9.58: «نمایش جدول» — مودالِ نتایج را باز می‌کند و نتایجِ ذخیره‌شدهٔ آخر را
   نشان می‌دهد، بدون شروعِ تستِ تازه. اگر تستی در حال اجراست، همان‌جا ادامه را
   پایش می‌کند. */
function aiShowTestTable(){
    aiOpenTestModal();
    // مقادیرِ جاری را از فیلدها تازه کن (در صورت تغییر)
    aiTestMsgVal=($('aiTestMsg')&&$('aiTestMsg').value.trim())||'سلام';
    aiTestCatVal=($('aiTestCat')&&$('aiTestCat').value.trim())||'ادو پرفیوم';
    aiTestDelayVal=Math.max(0,parseInt(($('aiTestDelay')&&$('aiTestDelay').value)||'120',10)||120);
    fetch('?ai_test_status=1').then(r=>r.json()).then(st=>{
        // نتایجِ ذخیره‌شده را (اگر هست) رندر کن
        if(st){
            if(st.items&&st.items.length){
                const tbody=$('aiTestTbody'); if(tbody)tbody.innerHTML='';
                aiTestTotCount=0;aiTestOkCount=0;aiTestFailCount=0;aiTestWaitCount=0;aiTestRows={};
                aiRenderTestState(st);
            }
            if(st.running){
                if($('aiTestCur'))$('aiTestCur').textContent='در حال اجراست — نتایج زنده به‌روز می‌شوند';
                aiPollTest();
            }else if(st.done&&$('aiTestCur')){
                $('aiTestCur').textContent='🏁 '+esc(st.summary||'پایان تست');
            }else{
                if($('aiTestCur'))$('aiTestCur').textContent='هنوز تستی اجرا نشده — دکمهٔ «▶ شروع / ادامه» را بزنید';
            }
        }
    }).catch(()=>{ if($('aiTestCur'))$('aiTestCur').textContent='خطا در خواندن وضعیت'; });
}
/* v9.24: بعد از ریفرش، اگر کاری در حال اجراست مودال را باز کن و ادامه بده */
function aiResumeTestModalOnLoad(){
    fetch('?ai_test_status=1').then(r=>r.json()).then(st=>{
        if(st&&st.running){ aiOpenTestModal(); aiPollTest(); }
    }).catch(()=>{});
}
/* v9.53: دکمهٔ «شروع / ادامه» — اگر تستی در حال اجراست آن را ادامه می‌دهد
   (مودالِ زنده را باز می‌کند و poll را ادامه می‌دهد، بدون شروعِ تازه)، و اگر
   نه، یک تستِ تازه با مقادیرِ جاریِ پیام/دسته شروع می‌کند. */
function aiTestStartContinue(){
    const btn=document.getElementById('aiTestStartContinue');
    if(btn){btn.disabled=true;const t=btn.textContent;btn.textContent='⏳ ...';setTimeout(()=>{btn.disabled=false;btn.textContent=t;},1500);}
    fetch('?ai_test_status=1').then(r=>r.json()).then(st=>{
        if(st&&st.running){
            // در حال اجراست → ادامه بده
            aiOpenTestModal();
            aiPollTest();
            if($('aiTestCur'))$('aiTestCur').textContent='ادامهٔ تست در حال اجرا...';
        }else{
            // نه → شروعِ تازه
            aiTestAll();
        }
    }).catch(()=>{ aiTestAll(); });
}
// v8.06: Test AI category selection with a sample product title
function testAiCategory(){
  /* v9.38: اگر مدل کاندید داریم، همهٔ آن‌ها را با هم تست می‌کنیم تا بهترین را
     برگزینیم؛ وگرنه همان تست تک‌مدلیِ قدیمی انجام می‌شود. */
  aiCandLoad(d=>{
    if((d.candidates||[]).length>0){aiCandCategoryTest();return;}
    const r=$('aiTR');const title=prompt('عنوان محصول برای تست دسته‌بندی:','کفش ورزشی مردانه نایک');if(!title)return;
    r.innerHTML='<div style="color:#67e8f9;font-size:11px">🔄 در حال تحلیل «'+esc(title)+'» با AI...</div>';
    fetch('?ai_category=1&title='+encodeURIComponent(title)).then(rr=>rr.json()).then(dd=>{
      if(dd.ok){r.innerHTML='<div class="alert alert-success" style="padding:8px;font-size:11px">✓ دسته: <b>'+esc(dd.category_name)+'</b> ('+dd.category_id+') | مدل: '+esc(dd.ai_model||'')+' | پاسخ AI: '+esc(dd.ai_raw||'')+'</div>';}
      else{r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(dd.error||'خطا')+'</div>';}
    }).catch(()=>{r.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا شبکه</div>';});
  });
}

function testBsl(){const s=$('bsS'),r=$('bsTR');s.textContent='تست...';s.className='cst tg';r.innerHTML='';const fd=new FormData();fd.append('action','test_basalam');fd.append('token',$('bsTk').value.trim());if($('bsIndirect'))fd.append('net_indirect',$('bsIndirect').checked?'1':'0');fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
if(d.ok){s.textContent='✓';s.className='cst on';r.innerHTML='<div class="alert alert-success" style="padding:8px;font-size:11px">✓ '+esc(d.message)+' | '+esc(d.vendor_title||'')+'</div>';if(d.vendor_id&&!$('bsVid').value)$('bsVid').value=d.vendor_id;saveConn();
showBslVendorModal(d);
}else{s.textContent='✗';s.className='cst off';
let ext='';
if(d.http_code===0){
ext='<div style="margin-top:6px;background:#0f172a;padding:8px;border-radius:6px;font-size:10px;color:#94a3b8;line-height:1.7">';
if(d.curl_error)ext+='<div>جزئیات: <span dir="ltr" style="font-family:monospace">'+esc(d.curl_error)+'</span></div>';
if(d.mode)ext+='<div>روش اتصال: '+esc(d.mode)+'</div>';
ext+='<div style="margin-top:4px;color:#fbbf24">💡 اگر IP هاست توسط باسلام بلاک شده است، تیک «اتصال غیرمستقیم» را فعال کنید و در بخش «اتصال به سایت مبدأ» یک روش (پروکسی، Worker یا DoH) تنظیم و ذخیره کنید.</div>';
ext+='</div>';
}
r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>'+ext;
if(d.http_code===403||d.http_code===401){showBslVendorModal(d);}
}
}).catch(()=>{s.textContent='✗';s.className='cst off';});}
